      <Row>
        <Badge>pill (default)</Badge>
        <Badge shape="square">square</Badge>
        <Badge color="accent" shape="square">v2.4.0</Badge>
        <Badge color="neutral" shape="square" leftSection={<IconGitBranch {...DEMO_ICON} />}>main</Badge>
