      <VirtariCodeBlock renderer="static" language="tsx" code={`<Badge asChild>
  <a href="/changelog">Latest release</a>
</Badge>

// React Router
<Badge asChild variant="outline">
  <RouterLink to="/settings">Beta settings</RouterLink>
