      <div dir="rtl" lang="fa" style={{ width: "14rem", maxWidth: "100%" }}><Badge color="success" leftSection={<IconCheck {...DEMO_ICON} />}>تغییرات پروژه برای بررسی و تأیید آماده است</Badge></div>
