/* ─────────────────────────────── Dataset ─────────────────────────────── */

interface Person {
  id: number;
  firstName: string;
  lastName: string;
  email: string;
  status: "active" | "pending" | "suspended";
  role: "admin" | "editor" | "viewer";
  salary: number;
  joined: string;
}

const STATUS: Person["status"][] = ["active", "pending", "suspended"];
const ROLE: Person["role"][] = ["admin", "editor", "viewer"];

function makePeople(n: number): Person[] {
  const out: Person[] = [];
  for (let i = 0; i < n; i++) {
    out.push({
      id: i + 1,
      firstName: `User${i + 1}`,
      lastName: `Doe${i + 1}`,
      email: `user${i + 1}@virtari.dev`,
      status: STATUS[i % 3]!,
      role: ROLE[(i * 7) % 3]!,
      salary: 30000 + ((i * 137) % 120000),
      joined: new Date(2020, (i * 5) % 12, ((i * 3) % 28) + 1)
        .toISOString()
        .slice(0, 10),
    });
  }
  return out;
}

