        cell: (i) => `$${i.getValue<number>().toLocaleString()}`,
      }),
      ch.accessor("joined", {
        header: "Joined",
        size: 200,
        filterFn: (row, id, value: [string, string]) => {
          const v = row.getValue<string>(id);
          const [from, to] = value;
          if (from && v < from) return false;
