            {user && (
              <Avatar
                fallback={initials(user.firstName, user.lastName)}
                size="md"
                color="auto"
                colorKey={`${user.firstName} ${user.lastName}`}
              />
            )}
            <div>
              <DrawerTitle>Quick edit</DrawerTitle>
              {user && (
                <div
                  style={{
                    fontSize: "var(--vds-text-xs, 0.75rem)",
                    color: "var(--vds-color-text-muted, #9ca3af)",
                  }}
                >
                  ID #{user.id}
                </div>
              )}
            </div>
          </div>
        </DrawerHeader>
        <DrawerBody>
          <div style={fieldStackStyle}>
            <Field label="First name">
              <Input
                inputSize="md"
                value={first}
                onChange={(e) => setFirst(e.target.value)}
              />
            </Field>
            <Field label="Last name">
              <Input
                inputSize="md"
                value={last}
                onChange={(e) => setLast(e.target.value)}
              />
            </Field>
            <Field label="Email">
              <Input
                inputSize="md"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </Field>
            <Field label="Role">
              <Select value={role} onValueChange={(v) => setRole(v as Role)}>
                <SelectTrigger size="md">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {ROLES.map((r) => (
                    <SelectItem key={r} value={r}>
                      {r}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>
            <Field label="Status">
              <ToggleRow
                label={active ? "Active" : "Inactive"}
                checked={active}
                onChange={setActive}
              />
            </Field>
            <Field label="2F Authentication">
              <ToggleRow
                label={twoFA ? "Enabled" : "Disabled"}
                checked={twoFA}
                onChange={setTwoFA}
              />
            </Field>
          </div>
        </DrawerBody>
        <DrawerFooter>
          <div style={drawerFooterStyle}>
            <Button
              variant="ghost"
              size="md"
              onClick={() => onOpenChange(false)}
            >
              Cancel
            </Button>
            <Button
              variant="solid"
              color="primary"
              size="md"
              onClick={() => {
                if (!user) return;
                onSave({
                  ...user,
                  firstName: first.trim(),
                  lastName: last.trim(),
                  email: email.trim(),
                  role,
                  status: active ? "active" : "inactive",
                  twoFA,
                });
              }}
            >
              Save changes
            </Button>
          </div>
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  );
}

