function CustomListView({
  onQuickEdit,
  onDelete,
}: {
  onQuickEdit: (u: User) => void;
  onDelete: (ids: number[]) => void;
}) {
  const { table } = useDataTableContext();
  const rows = table.getRowModel().rows;

  if (rows.length === 0) {
    return (
      <div className="vds-data-table-list vds-data-table-list-empty">
        No users match your filters.
      </div>
    );
  }

  return (
    <div role="list" className="vds-data-table-list">
      {rows.map((row) => {
        const u = row.original as User;
        const full = `${u.firstName} ${u.lastName}`;
        return (
          <div
            key={row.id}
            role="listitem"
            data-selected={row.getIsSelected() ? "" : undefined}
            className="vds-data-table-list-item"
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              gap: "var(--vds-space-3, 0.75rem)",
            }}
          >
            <Checkbox
              checked={row.getIsSelected()}
              onCheckedChange={(c) => row.toggleSelected(Boolean(c))}
              aria-label={`Select ${full}`}
            />
            <Avatar
              fallback={initials(u.firstName, u.lastName)}
              size="sm"
              color="auto"
              colorKey={full}
            />
            <div style={{ flex: 1, minInlineSize: 0 }}>
              <div className="vds-data-table-list-primary">{full}</div>
              <div
                className="vds-data-table-list-secondary"
                style={{
                  display: "flex",
                  alignItems: "center",
                  flexWrap: "nowrap",
                  gap: "var(--vds-space-3, 0.75rem)",
                  minInlineSize: 0,
                  overflow: "hidden",
                }}
              >
                <span>{u.email}</span>
                <span>{u.role}</span>
                <Badge
                  color={u.status === "active" ? "success" : "danger"}
                  variant="soft"
                  size="xs"
                  dot
                >
                  {u.status === "active" ? "Active" : "Inactive"}
                </Badge>
                <Badge
                  color={u.twoFA ? "success" : "neutral"}
                  variant="soft"
                  size="xs"
                  shape="square"
                >
                  2FA {u.twoFA ? "on" : "off"}
                </Badge>
                <span style={{ fontVariantNumeric: "tabular-nums" }}>
                  {formatJoined(u.joinedAt)}
                </span>
              </div>
            </div>
            <div
              className="vds-data-table-row-actions"
              style={{ flexShrink: 0 }}
            >
              <DataTable.RowAction
                size="xs"
                icon={<IconPencil size={12} stroke={1.75} aria-hidden />}
                onClick={() => onQuickEdit(u)}
              >
                Edit
              </DataTable.RowAction>
              <DataTable.RowAction
                size="xs"
                intent="danger"
                icon={<IconTrash size={12} stroke={1.75} aria-hidden />}
                onClick={() => onDelete([u.id])}
              >
                Delete
              </DataTable.RowAction>
            </div>
          </div>
        );
      })}
    </div>
  );
}

