/* ─────────────────────────────── Helpers ─────────────────────────────── */

/** Tracks a CSS media query. Inline here so examples stay self-contained. */
function useMediaQuery(query: string): boolean {
  const [matches, setMatches] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return window.matchMedia(query).matches;
  });
  useEffect(() => {
    if (typeof window === "undefined") return;
    const mql = window.matchMedia(query);
    const onChange = () => setMatches(mql.matches);
    onChange();
    mql.addEventListener("change", onChange);
    return () => mql.removeEventListener("change", onChange);
  }, [query]);
  return matches;
}

/** Labeled form field — small column with a label on top. */
function Field({
  label,
  hint,
  htmlFor,
  children,
}: {
  label: string;
  hint?: string;
  htmlFor?: string;
  children: React.ReactNode;
}) {
  return (
    <label
      htmlFor={htmlFor}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--vds-space-1-5)",
        fontSize: "var(--vds-text-sm)",
        color: "var(--vds-color-text)",
      }}
    >
      <span style={{ fontWeight: "var(--vds-font-weight-medium)" }}>{label}</span>
      {children}
      {hint && (
        <span
          style={{
            fontSize: "var(--vds-text-xs)",
            color: "var(--vds-color-text-muted)",
          }}
        >
          {hint}
        </span>
      )}
    </label>
  );
}

function FormStack({ children }: { children: React.ReactNode }) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--vds-space-4)",
      }}
    >
      {children}
    </div>
  );
}

function InlineRow({
  children,
  gap = "3",
  align = "center",
}: {
  children: React.ReactNode;
  gap?: "2" | "3" | "4";
  align?: "center" | "start";
}) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: align === "start" ? "flex-start" : "center",
        gap: `var(--vds-space-${gap})`,
      }}
    >
      {children}
    </div>
  );
}

/** Switch-on-label pattern. Label left, switch right, keeps label clickable. */
function SwitchRow({
  title,
  hint,
  defaultChecked,
}: {
  title: string;
  hint?: string;
  defaultChecked?: boolean;
}) {
  return (
    <label
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: "var(--vds-space-4)",
        fontSize: "var(--vds-text-sm)",
        cursor: "pointer",
      }}
    >
      <span style={{ display: "flex", flexDirection: "column", gap: 2 }}>
        <span style={{ fontWeight: "var(--vds-font-weight-medium)" }}>{title}</span>
        {hint && (
          <span
            style={{
              fontSize: "var(--vds-text-xs)",
              color: "var(--vds-color-text-muted)",
            }}
          >
            {hint}
          </span>
        )}
      </span>
      <Switch defaultChecked={defaultChecked} />
    </label>
  );
}

/* ──────────────────────────── Demo Drawer (options) ──────────────────────────── */

type DemoDrawerProps = {
  label: string;
  title?: string;
  description?: string;
  body?: React.ReactNode;
  direction?: Direction;
  sizeMode?: DrawerSizeMode;
  size?: string | number;
  offset?: number;
  indicator?: DrawerIndicatorPlacement;
  headerVariant?: DrawerHeaderVariant;
  dragHandleOnly?: boolean;
  dismissible?: boolean;
  scaleBackground?: boolean;
  stretch?: boolean;
};

function DemoDrawer({
  label,
  title = "Drawer",
  description = "Drag the handle or dismiss with Cancel.",
  body,
  scaleBackground = true,
  dismissible = true,
  ...drawerProps
}: DemoDrawerProps) {
  const [open, setOpen] = useState(false);
  return (
    <Drawer open={open} onOpenChange={setOpen} dismissible={dismissible} scaleBackground={scaleBackground} {...drawerProps}>
      <DrawerTrigger asChild>
        <Button variant="outline">{label}</Button>
      </DrawerTrigger>
      <DrawerContent>
        <DrawerHeader>
          <DrawerHandle />
          <DrawerTitle>{title}</DrawerTitle>
          <DrawerDescription>{description}</DrawerDescription>
        </DrawerHeader>
        <DrawerBody>
          {body ?? (
            <p className="docs-prose">
