/* ──────────────────────────── Example 2 — Product filters ──────────────────────────── */

const BRAND_OPTIONS = [
  "Virtari",
  "Acme",
  "Globex",
  "Umbrella",
  "Initech",
  "Hooli",
] as const;

function ProductFiltersDrawer() {
  const isDesktop = useMediaQuery("(min-width: 768px)");
  const direction: Direction = isDesktop ? "right" : "bottom";
  const [price, setPrice] = useState<number[]>([40, 320]);
  const [brands, setBrands] = useState<Set<string>>(
    new Set(["Virtari", "Acme"]),
  );
  const [condition, setCondition] = useState("any");
  const [sort, setSort] = useState("relevance");

  const activeCount = brands.size + (price[0] !== 0 || price[1] !== 500 ? 1 : 0)
    + (condition !== "any" ? 1 : 0);

  const toggleBrand = (brand: string) => {
    setBrands((prev) => {
      const next = new Set(prev);
      if (next.has(brand)) next.delete(brand);
      else next.add(brand);
      return next;
    });
  };

  const reset = () => {
    setPrice([0, 500]);
    setBrands(new Set());
    setCondition("any");
    setSort("relevance");
  };

  return (
    <Drawer
      direction={direction}
      sizeMode={isDesktop ? "fixed" : "adaptive"}
      size={isDesktop ? "24rem" : undefined}
      openStates={
        isDesktop
          ? undefined
          : [
              { id: "peek", size: 0.5, label: "Peek" },
              { id: "full", size: 1, label: "Full" },
            ]
      }
      headerVariant="bordered"
      scaleBackground
    >
      <DrawerTrigger asChild>
        <Button variant="outline" rightSection={activeCount > 0 ? <Badge>{activeCount}</Badge> : undefined}>
          Filters
        </Button>
      </DrawerTrigger>
      <DrawerContent>
        <DrawerHeader>
          <DrawerHandle />
          <DrawerTitle>Filters</DrawerTitle>
          <DrawerDescription>
            Refine the product list. Filters apply when you click Apply.
          </DrawerDescription>
        </DrawerHeader>
        <DrawerBody>
          <FormStack>
            <Field
              label={`Price — $${price[0]} to $${price[1]}`}
              hint="Drag either thumb to adjust."
            >
              <Slider
                min={0}
                max={500}
                step={10}
                value={price}
                onValueChange={setPrice}
              />
            </Field>

            <Separator />

            <div style={{ display: "flex", flexDirection: "column", gap: "var(--vds-space-2)" }}>
              <span
                style={{
                  fontSize: "var(--vds-text-sm)",
                  fontWeight: "var(--vds-font-weight-medium)",
                }}
              >
                Brand
              </span>
              <div style={{ display: "flex", flexDirection: "column", gap: "var(--vds-space-2)" }}>
                {BRAND_OPTIONS.map((brand) => (
                  <label
                    key={brand}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "var(--vds-space-3)",
                      fontSize: "var(--vds-text-sm)",
                      cursor: "pointer",
                    }}
                  >
                    <Checkbox
                      checked={brands.has(brand)}
                      onCheckedChange={() => toggleBrand(brand)}
                    />
                    {brand}
                  </label>
                ))}
              </div>
            </div>

            <Separator />

            <div style={{ display: "flex", flexDirection: "column", gap: "var(--vds-space-2)" }}>
              <span
                style={{
                  fontSize: "var(--vds-text-sm)",
                  fontWeight: "var(--vds-font-weight-medium)",
                }}
              >
                Condition
              </span>
              <RadioGroup value={condition} onValueChange={setCondition}>
                {[
                  { value: "any", label: "Any" },
                  { value: "new", label: "New" },
                  { value: "refurb", label: "Refurbished" },
                  { value: "used", label: "Used" },
                ].map((opt) => (
                  <label
                    key={opt.value}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "var(--vds-space-3)",
                      fontSize: "var(--vds-text-sm)",
                      cursor: "pointer",
                    }}
                  >
                    <RadioGroupItem value={opt.value} />
                    {opt.label}
                  </label>
                ))}
              </RadioGroup>
            </div>

            <Separator />

            <Field label="Sort">
              <Select value={sort} onValueChange={setSort}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="relevance">Relevance</SelectItem>
                  <SelectItem value="price-asc">Price — low to high</SelectItem>
                  <SelectItem value="price-desc">Price — high to low</SelectItem>
                  <SelectItem value="newest">Newest</SelectItem>
                </SelectContent>
              </Select>
            </Field>
          </FormStack>
        </DrawerBody>
        <DrawerFooter>
          <Button variant="ghost" onClick={reset}>
            Reset
          </Button>
          <DrawerClose asChild>
            <Button>Apply</Button>
          </DrawerClose>
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  );
}

/* ──────────────────────────── Example 3 — Cart summary ──────────────────────────── */

type CartItem = {
  id: string;
  name: string;
  variant: string;
  price: number;
  qty: number;
};

const INITIAL_CART: CartItem[] = [
  { id: "a", name: "Aurora Lamp", variant: "Warm · Medium", price: 129, qty: 1 },
  { id: "b", name: "Ceramic Mug Set", variant: "Bone white · 4-pack", price: 48, qty: 2 },
  { id: "c", name: "Linen Throw", variant: "Stone grey", price: 79, qty: 1 },
];

function formatUSD(n: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(n);
}

function CartDrawer() {
  const isDesktop = useMediaQuery("(min-width: 768px)");
  const direction: Direction = isDesktop ? "right" : "bottom";
  const [items, setItems] = useState<CartItem[]>(INITIAL_CART);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.qty, 0),
    [items],
  );
  const shipping = subtotal > 0 ? 12 : 0;
  const total = subtotal + shipping;
  const totalItems = items.reduce((sum, item) => sum + item.qty, 0);

  const updateQty = (id: string, delta: number) => {
    setItems((prev) =>
      prev
        .map((item) =>
          item.id === id ? { ...item, qty: Math.max(0, item.qty + delta) } : item,
        )
        .filter((item) => item.qty > 0),
    );
  };

  return (
    <Drawer
      direction={direction}
      sizeMode={isDesktop ? "fixed" : "adaptive"}
      size={isDesktop ? "28rem" : undefined}
      openStates={
        isDesktop
          ? undefined
          : [
              { id: "peek", size: 0.55, label: "Peek" },
              { id: "full", size: 1, label: "Full" },
            ]
      }
      headerVariant="bordered"
      scaleBackground
    >
      <DrawerTrigger asChild>
        <Button rightSection={totalItems > 0 ? <Badge>{totalItems}</Badge> : undefined}>
          Open cart
        </Button>
      </DrawerTrigger>
      <DrawerContent>
        <DrawerHeader>
          <DrawerHandle />
          <DrawerTitle>Your cart</DrawerTitle>
          <DrawerDescription>
            {items.length === 0
              ? "Your cart is empty."
              : `${totalItems} item${totalItems === 1 ? "" : "s"} · ${formatUSD(subtotal)}`}
          </DrawerDescription>
        </DrawerHeader>
        <DrawerBody>
          {items.length === 0 ? (
            <p className="docs-prose">Add items to the cart to see them here.</p>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "var(--vds-space-4)" }}>
              {items.map((item) => (
                <div
                  key={item.id}
                  style={{
                    display: "grid",
                    gridTemplateColumns: "3.5rem 1fr auto",
                    gap: "var(--vds-space-3)",
                    alignItems: "center",
                  }}
                >
                  <div
                    style={{
                      inlineSize: "3.5rem",
                      blockSize: "3.5rem",
                      borderRadius: "var(--vds-radius-card)",
                      background:
                        "linear-gradient(135deg, var(--vds-color-primary-100), var(--vds-color-primary-200))",
                    }}
                    aria-hidden
                  />
                  <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
                    <span style={{ fontWeight: "var(--vds-font-weight-medium)" }}>
                      {item.name}
                    </span>
                    <span
                      style={{
                        fontSize: "var(--vds-text-xs)",
                        color: "var(--vds-color-text-muted)",
                      }}
                    >
                      {item.variant}
                    </span>
                    <InlineRow gap="2">
                      <Button
                        size="2xs"
                        variant="outline"
                        onClick={() => updateQty(item.id, -1)}
                        aria-label={`Decrease ${item.name}`}
                      >
                        −
                      </Button>
                      <span
                        style={{
                          minInlineSize: "1.5rem",
                          textAlign: "center",
                          fontVariantNumeric: "tabular-nums",
                          fontSize: "var(--vds-text-sm)",
                        }}
                      >
                        {item.qty}
                      </span>
                      <Button
                        size="2xs"
                        variant="outline"
                        onClick={() => updateQty(item.id, 1)}
                        aria-label={`Increase ${item.name}`}
                      >
                        +
                      </Button>
                    </InlineRow>
                  </div>
                  <span
