          onChange={setSizeMode}
          options={SIZE_MODE_OPTIONS}
        />
        <LabeledSelect
          label="Indicator"
          value={indicator}
          onChange={setIndicator}
          options={INDICATOR_OPTIONS}
        />
        <LabeledSelect
