          { id: "peek", size: 0.4, label: "Peek" },
          { id: "full", size: 1, label: "Full" },
        ]}
      >
        <DrawerTrigger asChild>
          <Button>Open playground drawer</Button>
        </DrawerTrigger>
        <DrawerContent>
          <DrawerHeader>
            <DrawerHandle />
            <DrawerTitle>Playground</DrawerTitle>
            <DrawerDescription>
              direction={direction} · sizeMode={sizeMode} · indicator={indicator} ·
              header={headerVariant}
            </DrawerDescription>
          </DrawerHeader>
          <DrawerBody>
            <p className="docs-prose">
              Change the controls above and reopen the drawer. Each change is
              reflected in the generated snippet below.
            </p>
          </DrawerBody>
          <DrawerFooter>
            <DrawerClose asChild>
              <Button variant="outline">Close</Button>
            </DrawerClose>
          </DrawerFooter>
        </DrawerContent>
      </Drawer>

      <VirtariCodeBlock renderer="static" language="tsx" code={buildPlaygroundCode({ direction, sizeMode, indicator, headerVariant })} />
    </>
  );
}

