// typing pulse
<NumberInput typingPulse value={qty} onChange={setQty} />

<NumberInputField
  label="Seats"
  description="Used for billing."
  error="At least one seat is required"
  invalid
  counter="1-50 seats"
  metaLayout="inline"
  descriptionAlign="end"
/>`} />
      </Section>
    </>
  );
}

