        <VirtariCodeBlock renderer="static" language="tsx" code={`import { ScrollArea } from "@virtari-packages/react-scroll-area";

<ScrollArea
  orientation="horizontal"
  drag
  mask
  arrows
  arrowPlacement="inner"
  arrowAppearance="hover"
  wheelToHorizontal
  onEndReached={() => loadMore()}
  endThreshold={120}
  size="md"
  style={{ width: 480 }}
>
  {items}
</ScrollArea>

// Marquee
<ScrollArea orientation="horizontal" marquee marqueeDuration={20}>
  {logos}
</ScrollArea>`} />
      </Section>
    </>
  );
}

function ListItems({ count }: { count: number }) {
  return (
    <div style={{ padding: "var(--vds-space-4)" }}>
      {Array.from({ length: count }, (_, i) => (
        <p
          key={i}
          style={{
            margin: "0 0 var(--vds-space-2)",
