              <TableCell>گریس هاپر</TableCell>
              <TableCell><Badge size="sm" color="warning" variant="soft">در انتظار</Badge></TableCell>
              <TableCell numeric>۷۸۰٫۵۰</TableCell>
            </TableRow>
