      <TableCell>Ada Lovelace</TableCell>
      <TableCell numeric>$1,240.00</TableCell>
    </TableRow>
  </TableBody>
  <TableFooter>
    <TableRow>
      <TableCell colSpan={2}>Subtotal</TableCell>
      <TableCell numeric>$1,240.00</TableCell>
    </TableRow>
  </TableFooter>
</Table>`} />
    </Section>
  );
}

