            <div key={size}>
              <Label style={{ marginBlockEnd: "var(--vds-space-1)" }}>Size {size}</Label>
              <TagInput
                value={["one", "two"]}
                onChange={() => {}}
                size={size}
                placeholder={`${size} size…`}
              />
            </div>
          ))}
        </div>
      </Section>

      <Section title="Disabled">
        <div style={{ maxWidth: "28rem" }}>
          <TagInput
            value={["locked", "read-only"]}
            onChange={() => {}}
