apps/docs/src/shims/attrAccept.ts:
type FileLike = {
  name?: string | null;
  type?: string | null;
};

export default function attrAccept(
  file: FileLike | null | undefined,
  acceptedFiles: string | string[] | null | undefined,
): boolean {
  if (!file || !acceptedFiles) return true;

  const acceptedFilesArray = Array.isArray(acceptedFiles)
    ? acceptedFiles
    : acceptedFiles.split(",");

  if (acceptedFilesArray.length === 0) return true;

  const fileName = (file.name ?? "").toLowerCase();
  const mimeType = (file.type ?? "").toLowerCase();
  const baseMimeType = mimeType.replace(/\/.*$/, "");

  return acceptedFilesArray.some((type) => {
    const validType = type.trim().toLowerCase();

    if (!validType) return false;
    if (validType.charAt(0) === ".") {
      return fileName.endsWith(validType);
    }
    if (validType.endsWith("/*")) {
      return baseMimeType === validType.replace(/\/.*$/, "");
    }
    return mimeType === validType;
  });
}

apps/docs/src/shims/propTypes.ts:
type Validator = ((...args: unknown[]) => null) & {
  isRequired: (...args: unknown[]) => null;
};

function makeValidator(): Validator {
  const validator = ((..._args: unknown[]) => null) as Validator;
  validator.isRequired = (..._args: unknown[]) => null;
  return validator;
}

function wrapFactory(_inner?: unknown): Validator {
  return makeValidator();
}

const PropTypes = {
  any: makeValidator(),
  array: makeValidator(),
  bigint: makeValidator(),
  bool: makeValidator(),
  element: makeValidator(),
  elementType: makeValidator(),
  exact: wrapFactory,
  func: makeValidator(),
  instanceOf: wrapFactory,
  node: makeValidator(),
  number: makeValidator(),
  object: makeValidator(),
  arrayOf: wrapFactory,
  objectOf: wrapFactory,
  oneOf: wrapFactory,
  oneOfType: wrapFactory,
  shape: wrapFactory,
  string: makeValidator(),
  symbol: makeValidator(),
};

export const {
  any,
  array,
  arrayOf,
  bigint,
  bool,
  element,
  elementType,
  exact,
  func,
  instanceOf,
  node,
  number,
  object,
  objectOf,
  oneOf,
  oneOfType,
  shape,
  string,
  symbol,
} = PropTypes;

export default PropTypes;

