      min-block-size: 2.5rem;
    }
  }
}

apps/docs/src/styles/docs.css:
/* ── Section ── */
.docs-section-title {
  font-size: var(--vds-text-xl);
  font-weight: var(--vds-font-weight-semibold);
  letter-spacing: -.015em;
  margin: 0;
}

.docs-section-description {
  margin: 0;
}

/* ── Helpers ── */
.docs-row:not(.vds-cluster) {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--vds-space-3);
}

.docs-stack:not(.vds-stack) {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-3);
}
.docs-stack { max-inline-size: 24rem; }

.docs-prose {
  font-size: var(--vds-text-sm);
  line-height: var(--vds-leading-relaxed);
  max-inline-size: none;

  & strong {
    font-weight: var(--vds-font-weight-semibold);
  }

}

.docs-install-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--vds-space-5) var(--vds-space-6);
  min-inline-size: 0;
}

.docs-install-option {
  display: grid;
  align-content: start;
  gap: var(--vds-space-2);
  min-inline-size: 0;
}

.docs-install-option > .vds-badge {
  justify-self: start;
}

@media (max-width: 700px) {
  .docs-install-options {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ── DataTable demo helpers ── */
.docs-demo-hint {
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-muted);
  margin-block-start: var(--vds-space-2);
}

.docs-virtualized-frame {
  block-size: 26rem;
}

.docs-filter-header {
  display: inline-flex;
  align-items: center;
  gap: var(--vds-space-1-5);
}

.docs-row-link {
  all: unset;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: var(--vds-space-2);
  min-inline-size: 0;

  &:focus-visible {
    outline: 2px solid var(--vds-color-border-focus);
    outline-offset: 2px;
    border-radius: var(--vds-radius-control-action);
  }
}

@keyframes vds-docs-spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.docs-users-name-cell-text {
  font-weight: var(--vds-font-weight-medium);
  color: var(--vds-color-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Typography Page ── */
.docs-type-scale {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-3);
}

.docs-type-row {
  display: grid;
  grid-template-columns: 5rem 1fr 5rem;
  align-items: baseline;
  gap: var(--vds-space-4);
}

.docs-type-token {
  font-family: var(--vds-font-mono);
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-subtle);
}

.docs-type-sample {
  color: var(--vds-color-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.docs-type-meta {
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-subtle);
  text-align: end;
}

/* ── Sizing Page ── */
.docs-sizing-table {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-4);
}

.docs-sizing-row {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-2);
  padding-block-end: var(--vds-space-4);
  border-block-end: 1px solid var(--vds-color-border-muted);
}

.docs-sizing-meta {
  display: flex;
  align-items: baseline;
  gap: var(--vds-space-3);
}

.docs-sizing-px {
  font-family: var(--vds-font-mono);
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-muted);
}

.docs-sizing-wcag {
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-subtle);
}

.docs-sizing-demo {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--vds-space-2);
}

.docs-size-label {
  font-family: var(--vds-font-mono);
  font-size: var(--vds-text-xs);
  font-weight: var(--vds-font-weight-semibold);
  color: var(--vds-color-text-subtle);
  min-inline-size: 2.5rem;
  flex-shrink: 0;
}

/* ──────────────────────────────────────────────
 * Settings drawer
 * ────────────────────────────────────────────── */
.docs-settings-drawer {
  block-size: 100%;
}

.docs-settings-title {
  font-size: var(--vds-text-lg);
  font-weight: var(--vds-font-weight-semibold);
  line-height: var(--vds-leading-tight);
  margin: 0;
}

.docs-settings-body {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 0;
}
.docs-settings-scroll { flex: 1; min-block-size: 0; --scroll-area-track-inset: var(--vds-space-3); }
.docs-settings-scroll-content {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-6);
  padding: var(--vds-space-4) var(--vds-space-6);
}

.docs-settings-footer {
  justify-content: flex-end;
}

.docs-settings-section {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-2-5);
}

.docs-settings-section-header {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.docs-settings-section-title {
  font-size: var(--vds-text-xs);
  font-weight: var(--vds-font-weight-semibold);
  color: var(--vds-color-text-subtle);
  text-transform: uppercase;
  letter-spacing: var(--vds-tracking-wider, 0.05em);
  margin: 0;
}

.docs-settings-section-hint {
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-muted);
  margin: 0;
  line-height: var(--vds-leading-snug, 1.35);
}

/* ── Theme toggle ── */
.docs-settings-theme-toggle {
  display: flex;
  align-items: center;
  gap: var(--vds-space-3);
  padding: var(--vds-space-3);
  border: 1px solid var(--vds-color-border-muted);
  border-radius: var(--vds-radius-surface);
  background-color: var(--vds-color-surface);
  cursor: pointer;
}

.docs-settings-theme-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 2rem;
  block-size: 2rem;
  border-radius: var(--vds-radius-4);
  background-color: var(--vds-color-bg-muted);
  color: var(--vds-color-text);
  flex: none;
}

.docs-settings-theme-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1 1 auto;
  min-inline-size: 0;
}

.docs-settings-theme-label {
  font-size: var(--vds-text-sm);
  font-weight: var(--vds-font-weight-semibold);
  color: var(--vds-color-text);
}

.docs-settings-theme-hint {
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-muted);
}

/* ── Tabs showcase helpers ── */
.docs-stack-item {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-2);
}

.docs-subtitle {
  font-size: var(--vds-text-xs);
  font-weight: var(--vds-font-weight-semibold);
  color: var(--vds-color-text-muted);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.docs-inline-field {
  display: inline-flex;
  align-items: center;
  gap: var(--vds-space-2);
  font-size: var(--vds-text-sm);
  color: var(--vds-color-text);
}

.docs-tabs-stack {
  display: flex;
  flex-direction: column;
  gap: var(--vds-space-6);
  max-inline-size: 48rem;
}

/* ── Icons page ── */
.docs-icons-search {
  flex: 1;
  min-inline-size: 0;
  max-inline-size: 32rem;
}

.docs-icons-field {
  display: inline-flex;
  flex-direction: column;
  gap: var(--vds-space-1);
  font-size: var(--vds-text-xs);
  color: var(--vds-color-text-muted);
}

.docs-icons-field-label {
  font-weight: var(--vds-font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.docs-icons-toggle {
  display: inline-flex;
  border: 1px solid var(--vds-color-border-muted);
  border-radius: var(--vds-radius-nav-item);
  overflow: hidden;
  background-color: var(--vds-color-surface);
}

.docs-icons-toggle button {
  padding: var(--vds-space-2) var(--vds-space-3);
  font-size: var(--vds-text-sm);
  font-weight: var(--vds-font-weight-medium);
  color: var(--vds-color-text-muted);
  background: transparent;
  border: 0;
  cursor: pointer;
  transition: background-color 120ms ease, color 120ms ease;
}

.docs-icons-toggle button:hover {
  color: var(--vds-color-text);
}

.docs-icons-toggle button[data-active] {
  background-color: var(--vds-color-bg-subtle, var(--vds-color-bg));
  color: var(--vds-color-text);
}

.docs-icons-count {
  font-size: var(--vds-text-sm);
  color: var(--vds-color-text-muted);
  margin-block: var(--vds-space-2) 0;
}

.docs-icons-grid-scroll {
  block-size: 32rem;
  overflow-y: auto;
  border: 1px solid var(--vds-color-border-muted);
  border-radius: var(--vds-radius-surface);
  padding: var(--vds-space-2);
  background-color: var(--vds-color-surface);
}

.docs-icons-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--vds-space-1);
  padding: var(--vds-space-2);
  border: 1px solid transparent;
  border-radius: var(--vds-radius-nav-item);
  background: transparent;
  color: var(--vds-color-text);
  cursor: pointer;
  text-align: center;
  transition: background-color 120ms ease, border-color 120ms ease, transform 120ms ease;
  overflow: hidden;
}

.docs-icons-tile:hover {
  background-color: var(--vds-color-bg-subtle, var(--vds-color-bg));
  border-color: var(--vds-color-border-muted);
}

.docs-icons-tile:focus-visible {
  outline: 2px solid var(--vds-color-primary, currentColor);
  outline-offset: 2px;
}

.docs-icons-tile-glyph {
  display: flex;
  align-items: center;
  justify-content: center;
  block-size: 2.5rem;
  color: var(--vds-color-text);
}

.docs-icons-tile-name {
  font-size: 0.6875rem;
  font-family: var(--vds-font-mono);
  color: var(--vds-color-text-muted);
  inline-size: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.docs-icons-tile[data-copied] {
  border-color: var(--vds-color-success, var(--vds-color-primary));
  background-color: color-mix(in oklab, var(--vds-color-success, var(--vds-color-primary)) 10%, transparent);
}

.docs-icons-tile-badge {
  position: absolute;
  inset-block-start: var(--vds-space-1);
  inset-inline-end: var(--vds-space-1);
  font-size: 0.625rem;
  font-weight: var(--vds-font-weight-semibold);
  color: var(--vds-color-success, var(--vds-color-primary));
}

.docs-icons-empty {
  padding: var(--vds-space-8);
  text-align: center;
  color: var(--vds-color-text-muted);
  font-size: var(--vds-text-sm);
}
/* Introduction uses the same Card, Grid, Badge and Button primitives as consumers. */
.docs-language-hero { background: var(--vds-color-primary-container, var(--vds-color-primary-a3)); }
.docs-language-hero .vds-badge { align-self: flex-start; }
.docs-language-statement { margin: 0; white-space: pre-line; font-size: clamp(28px, 3vw, 42px); font-weight: 650; line-height: 1.25; letter-spacing: -.025em; color: var(--vds-color-on-primary-container, var(--vds-color-primary-12)); }
.docs-language-hero .docs-prose { margin: 0; max-inline-size: 38rem; }
.docs-principle-card { background: var(--vds-color-surface-container-low, var(--vds-color-bg-subtle)); }
.docs-principle-card .vds-card-content { margin-block-start: auto; }
.docs-principle-icon { display: grid; place-items: center; inline-size: 44px; block-size: 44px; background: var(--vds-color-primary-a3); color: var(--vds-color-primary-11); border-radius: var(--vds-radius-control-action); margin-block-end: 12px; }
.docs-principle-card .vds-card-description { line-height: 1.75; }
.docs-brand-preview { display: grid; place-items: center; min-block-size: 10rem; padding: var(--vds-space-6); color: var(--vds-color-text); }
.docs-brand-preview svg { max-inline-size: 100%; }

/* Source-driven color catalog. Preview scopes own their canvas and text roles. */
.docs-palette { display: grid; container-type: inline-size; gap: var(--vds-space-10); padding: var(--vds-space-4); background: var(--vds-color-bg); color: var(--vds-color-text); border-radius: var(--vds-radius-card); min-inline-size: 0; }
.docs-palette-heading { margin: 0; font-size: var(--vds-text-lg); color: var(--vds-color-text); }
.docs-palette .docs-prose { margin: 0; }
.docs-palette-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: var(--vds-space-2); }
@container (max-width: 30rem) { .docs-palette-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@container (min-width: 64rem) { .docs-palette-grid { grid-template-columns: repeat(12, minmax(0, 1fr)); } }
.docs-palette-grid[data-kind="semantic"], .docs-palette-grid[data-kind="alias"] { grid-template-columns: repeat(auto-fit, minmax(min(100%, 10rem), 1fr)); }
.docs-palette-swatch.vds-button { padding: var(--vds-space-1); block-size: auto; min-inline-size: 0; inline-size: 100%; border-radius: var(--vds-radius-sm); }
.docs-palette-swatch .vds-button-content, .docs-palette-swatch .vds-button-label { display: flex; flex-direction: column; align-items: stretch; inline-size: 100%; min-inline-size: 0; gap: var(--vds-space-2); }
.docs-palette-swatch code { font-size: 0.6875rem; line-height: 1.5; overflow-wrap: anywhere; white-space: normal; text-align: start; color: var(--vds-color-text); }
.docs-palette-checker { display: block; overflow: hidden; block-size: 3.5rem; border-radius: var(--vds-radius-xs); background: repeating-conic-gradient(var(--vds-color-neutral-5) 0% 25%, var(--vds-color-neutral-2) 0% 50%) 0 / 12px 12px; }
.docs-palette-paint { display: block; inline-size: 100%; block-size: 100%; box-shadow: inset 0 0 0 1px var(--vds-color-neutral-a3); }
.docs-palette-status { margin: 0; min-block-size: 1.5em; color: var(--vds-color-text-muted); font-size: var(--vds-text-sm); overflow-wrap: anywhere; }

