      {...scrollbarProps}
      ref={composeRefs}
      sizes={sizes}
      style={{
        top: 0,
        right: context.dir === 'ltr' ? 0 : undefined,
        left: context.dir === 'rtl' ? 0 : undefined,
        bottom: 'var(--vds-scroll-area-corner-height)',
        ['--vds-scroll-area-thumb-height' as any]: getThumbSize(sizes) + 'px',
        ...props.style,
