          '--vds-select-content-transform-origin': 'var(--vds-popper-transform-origin)',
          '--vds-select-content-available-width': 'var(--vds-popper-available-width)',
          '--vds-select-content-available-height': 'var(--vds-popper-available-height)',
          '--vds-select-trigger-width': 'var(--vds-popper-anchor-width)',
          '--vds-select-trigger-height': 'var(--vds-popper-anchor-height)',
        },
      }}
    />
