@import "./Accordion.tokens.css";

@layer design-system.components {
  /* ── Root ── */
  .vds-accordion {
    /* rendering rules declared in tokens file (display/flex/gap) */
  }

  /* ── Item ── */
  .vds-accordion-item {
    /* Positioning context for absolute-positioned icons if ever needed */
    position: relative;
  }

  /* ── Header wrapper (semantic <h2>/<h3>/... or primitive default) ── */
  .vds-accordion-header {
    display: flex;
    margin: 0;
    /* When used as a real heading, strip browser defaults so heading looks like the trigger */
    font: inherit;
    font-size: inherit;
    font-weight: inherit;
    color: inherit;
  }

  /* ── Trigger (the clickable row) ── */
  .vds-accordion-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--accordion-trigger-gap);
    inline-size: 100%;
    padding-block:  var(--accordion-trigger-padding-block);
    padding-inline: var(--accordion-trigger-padding-inline);
    font-family: var(--accordion-trigger-font-family);
    font-size:   var(--accordion-trigger-font-size);
    font-weight: var(--accordion-trigger-font-weight);
    line-height: var(--accordion-trigger-line-height);
    color: var(--accordion-text);
    background-color: var(--accordion-bg);
    border: 0;
    text-align: start;
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
    transition:
      color            var(--accordion-transition-duration) var(--accordion-transition-easing),
      background-color var(--accordion-transition-duration) var(--accordion-transition-easing);
  }

  .vds-accordion-trigger:hover:not(:disabled) {
    color: var(--accordion-text-hover);
    background-color: var(--accordion-bg-hover);
  }

  .vds-accordion-trigger:focus-visible {
    outline: var(--accordion-focus-ring-width) solid var(--accordion-focus-ring-color);
    outline-offset: var(--accordion-focus-ring-offset);
    border-radius: var(--accordion-focus-ring-radius);
  }

  .vds-accordion-trigger:disabled {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
  }

  /* ── Icon indicator (generic wrapper) ── */
  .vds-accordion-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    inline-size: var(--accordion-icon-size);
    block-size: var(--accordion-icon-size);
    color: var(--accordion-icon-color);
    transition: rotate var(--accordion-transition-duration) var(--accordion-transition-easing),
                opacity var(--accordion-transition-duration) var(--accordion-transition-easing);
  }

  .vds-accordion-icon > svg {
    inline-size: 100%;
    block-size: 100%;
  }

  /* Chevron & arrow: rotate on open */
  .vds-accordion-trigger[data-state="open"] .vds-accordion-icon[data-icon="chevron"],
  .vds-accordion-trigger[data-state="open"] .vds-accordion-icon[data-icon="arrow"],
  .vds-accordion-trigger[data-state="open"] .vds-accordion-icon[data-icon="caret"] {
    rotate: 180deg;
  }

  /* Plus/minus: swap via two stacked icons. Both fade based on state. */
  .vds-accordion-icon[data-icon="plus-minus"] {
    position: relative;
  }
  .vds-accordion-icon[data-icon="plus-minus"] > svg {
    position: absolute;
    inset: 0;
  }
  .vds-accordion-icon[data-icon="plus-minus"] > .vds-accordion-icon-plus {
    opacity: 1;
    rotate: 0deg;
  }
  .vds-accordion-icon[data-icon="plus-minus"] > .vds-accordion-icon-minus {
    opacity: 0;
    rotate: -90deg;
  }
  .vds-accordion-trigger[data-state="open"] .vds-accordion-icon[data-icon="plus-minus"] > .vds-accordion-icon-plus {
    opacity: 0;
    rotate: 90deg;
  }
  .vds-accordion-trigger[data-state="open"] .vds-accordion-icon[data-icon="plus-minus"] > .vds-accordion-icon-minus {
    opacity: 1;
    rotate: 0deg;
  }

  /* Icon at start (leading) — reverse the row */
  .vds-accordion-trigger[data-icon-position="start"] {
    flex-direction: row-reverse;
    justify-content: flex-end;
  }

  /* In RTL, arrow/caret icons should flip horizontally so they still point
   * toward the reading direction. Chevron is vertical so unaffected. */
  :dir(rtl) .vds-accordion-icon[data-icon="arrow"],
  :dir(rtl) .vds-accordion-icon[data-icon="caret"] {
    scale: -1 1;
  }

  /* ── Content ── */
  .vds-accordion-content {
    overflow: hidden;
    font-size:   var(--accordion-content-font-size);
    line-height: var(--accordion-content-line-height);
    color: var(--accordion-color-text-muted);
  }

  .vds-accordion-content[data-state="open"] {
    animation: vds-accordion-expand
      var(--accordion-transition-duration) var(--accordion-transition-easing);
  }
  .vds-accordion-content[data-state="closed"] {
    animation: vds-accordion-collapse
      var(--accordion-transition-duration) var(--accordion-transition-easing);
  }

  .vds-accordion-content-inner {
    padding-block-start: var(--accordion-content-padding-block-start);
    padding-block-end:   var(--accordion-content-padding-block-end);
    padding-inline:      var(--accordion-content-padding-inline);
  }

  /* Respect reduced motion — skip the expand/collapse animation */
  @media (prefers-reduced-motion: reduce) {
    .vds-accordion-content[data-state="open"],
    .vds-accordion-content[data-state="closed"] {
      animation: none;
    }
    .vds-accordion-icon {
      transition: none;
    }
  }

  @keyframes vds-accordion-expand {
    from { block-size: 0; }
    to   { block-size: var(--vds-accordion-content-height); }
  }

  @keyframes vds-accordion-collapse {
    from { block-size: var(--vds-accordion-content-height); }
    to   { block-size: 0; }
  }
}

packages/react-accordion/src/Accordion.t:
@layer design-system.components {
  /* =========================================================================
   * 1. Base component tokens
   *    Layout, typography, motion — orthogonal to variant/size/color.
   *    Defaults: variant=plain, size=md, color=neutral, iconType=chevron.
   *    Fallbacks keep the package usable without @virtari-packages/tokens.
   * ========================================================================= */
  .vds-accordion {
    /* ── Layout ── */
    --accordion-gap:              0;
    --accordion-item-padding:     0;
    --accordion-item-radius:      0;
    --accordion-item-border:      0;
    --accordion-item-border-color: var(--vds-color-border-muted, #e5e7eb);

    /* Trigger (header button) */
    --accordion-trigger-padding-block:  var(--vds-space-4, 1rem);
    --accordion-trigger-padding-inline: 0;
    --accordion-trigger-gap:            var(--vds-space-3, 0.75rem);
    --accordion-trigger-font-family:    var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    --accordion-trigger-font-size:      var(--vds-text-sm, 0.875rem);
    --accordion-trigger-font-weight:    var(--vds-font-weight-medium, 500);
    --accordion-trigger-line-height:    var(--vds-leading-tight, 1.25);

    /* Content body.
     * The gap between the trigger and the panel body is the panel's own, not
     * borrowed from the trigger's bottom padding — a variant that draws a
     * border or background at that seam (bordered / separated) would
     * otherwise butt the first line of content straight against it. */
    --accordion-content-padding-block-start: var(--vds-stack-gap, var(--vds-space-3, 0.75rem));
    --accordion-content-padding-block-end:   var(--vds-space-4, 1rem);
    --accordion-content-padding-inline:      0;
    --accordion-content-font-size:           var(--vds-text-sm, 0.875rem);
    --accordion-content-line-height:         var(--vds-leading-relaxed, 1.625);

    /* Icon indicator */
    --accordion-icon-size:      1rem;
    --accordion-icon-stroke:    1.5;
    --accordion-icon-color:     var(--vds-color-text-muted, #6b7280);

    /* ── Motion ── */
    --accordion-transition-duration: var(--vds-duration-normal, 200ms);
    --accordion-transition-easing:   var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* ── Focus ──
     * `--accordion-focus-ring-offset` goes negative in every variant that
     * clips its items (see §3): the trigger is full-bleed inside the frame,
     * so an outward ring lands entirely outside the clip box and vanishes.
     * `--accordion-focus-ring-radius` is what the ring traces; it is a token
     * rather than a literal so a variant that gives the trigger a corner
     * (ghost) can keep the ring on that same corner. */
    --accordion-focus-ring-color:  var(--vds-color-ring, #4f46e5);
    --accordion-focus-ring-width:  2px;
    --accordion-focus-ring-offset: 2px;
    --accordion-focus-ring-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));

    /* ── Color palette — default: neutral (orthogonal to variant) ── */
    --accordion-color-text:        var(--vds-color-text, #111827);
    --accordion-color-text-muted:  var(--vds-color-text-muted, #6b7280);
    --accordion-color-text-hover:  var(--vds-color-text, #111827);
    --accordion-color-bg:          transparent;
    --accordion-color-bg-hover:    var(--vds-color-surface-hover, rgb(0 0 0 / 0.03));
    --accordion-color-bg-active:   var(--vds-color-surface-active, rgb(0 0 0 / 0.06));
    --accordion-color-border:      var(--vds-color-border-muted, #e5e7eb);
    --accordion-color-accent:      var(--vds-color-primary-solid, #4f46e5);

    /* ── Rendering tokens ── */
    --accordion-bg:          var(--accordion-color-bg);
    --accordion-bg-hover:    var(--accordion-color-bg-hover);
    --accordion-border:      transparent;
    --accordion-text:        var(--accordion-color-text);
    --accordion-text-hover:  var(--accordion-color-text-hover);

    display: flex;
    flex-direction: column;
    gap: var(--accordion-gap);
  }

  /* =========================================================================
   * 2. Color palettes — redefine --accordion-color-* meta tokens.
   *    Apply on the root or on an item for per-row accent coloring.
   * ========================================================================= */

  .vds-accordion[data-color="primary"],
  .vds-accordion-item[data-color="primary"] {
    --accordion-color-accent:     var(--vds-color-primary-solid, #4f46e5);
    --accordion-color-bg-hover:   var(--vds-color-primary-bg, #eef2ff);
    --accordion-color-text-hover: var(--vds-color-primary-text, #3730a3);
  }
  .vds-accordion[data-color="accent"],
  .vds-accordion-item[data-color="accent"] {
    --accordion-color-accent:     var(--vds-color-accent-solid, #f97316);
    --accordion-color-bg-hover:   var(--vds-color-accent-bg, #ffedd5);
    --accordion-color-text-hover: var(--vds-color-accent-text, #7c2d12);
  }
  .vds-accordion[data-color="success"],
  .vds-accordion-item[data-color="success"] {
    --accordion-color-accent:     var(--vds-color-success-solid, #16a34a);
    --accordion-color-bg-hover:   var(--vds-color-success-bg, #dcfce7);
    --accordion-color-text-hover: var(--vds-color-success-text, #166534);
  }
  .vds-accordion[data-color="danger"],
  .vds-accordion-item[data-color="danger"] {
    --accordion-color-accent:     var(--vds-color-danger-solid, #dc2626);
    --accordion-color-bg-hover:   var(--vds-color-danger-bg, #fee2e2);
    --accordion-color-text-hover: var(--vds-color-danger-text, #991b1b);
  }
  .vds-accordion[data-color="warning"],
  .vds-accordion-item[data-color="warning"] {
    --accordion-color-accent:     var(--vds-color-warning-solid, #f59e0b);
    --accordion-color-bg-hover:   var(--vds-color-warning-bg, #fef3c7);
    --accordion-color-text-hover: var(--vds-color-warning-text, #78350f);
  }

  /* =========================================================================
   * 3. Variants — shape/frame of each item.
   *    Each variant redefines layout-only tokens; palette stays orthogonal.
   * ========================================================================= */

  /* plain — divider-based (default). Border-bottom on every item. */
  .vds-accordion[data-variant="plain"] {
    --accordion-gap: 0;
  }
  .vds-accordion[data-variant="plain"] .vds-accordion-item {
    border-block-end: 1px solid var(--accordion-color-border);
  }
  .vds-accordion[data-variant="plain"] .vds-accordion-item:last-child {
    border-block-end: 0;
  }

  /* bordered — every item framed individually, stacked with shared borders.
   * Inline padding lives on the trigger/content (not the item) so the hover
   * background paints edge-to-edge instead of leaving bare strips on the sides.
   *
   * On the `overflow: clip` and the radius-nesting channel: the clip box is
   * the padding box, whose corner radius is already `border-radius − border-
   * width` — the exact value `--vds-radius-flush` would hand the first/last
   * item. So the corners here are concentric by construction. The clip is
   * additionally load-bearing in a way corner inheritance cannot replace: the
   * surface that overflows is the *trigger's* hover background, a grandchild
   * (item > header > trigger), and the channel deliberately reaches one level
   * only. Hence: keep the clip, no channel adoption. The cost — a clipped
   * focus ring — is paid off by the inset ring offset above. */
  .vds-accordion[data-variant="bordered"] {
    --accordion-gap: 0;
    /* Clipped frame → inset ring. See --accordion-focus-ring-offset above. */
    --accordion-focus-ring-offset: calc(-1 * var(--accordion-focus-ring-width));
    --accordion-item-radius:     var(--vds-radius-card, 0.75rem);
    --accordion-trigger-padding-block:  var(--vds-space-3, 0.75rem);
    --accordion-trigger-padding-inline: var(--vds-space-4, 1rem);
    --accordion-content-padding-block-end: var(--vds-space-3, 0.75rem);
    --accordion-content-padding-inline:    var(--vds-space-4, 1rem);
    border: 1px solid var(--accordion-color-border);
    border-radius: var(--accordion-item-radius);
    overflow: clip;
  }
  .vds-accordion[data-variant="bordered"] .vds-accordion-item {
    border-block-end: 1px solid var(--accordion-color-border);
  }
  .vds-accordion[data-variant="bordered"] .vds-accordion-item:last-child {
    border-block-end: 0;
  }

  /* separated — each item a standalone card with its own frame and gap.
   * `overflow: clip` on the item keeps the trigger's hover background clipped
   * to the rounded card edge. */
  .vds-accordion[data-variant="separated"] {
    --accordion-gap: var(--vds-space-2, 0.5rem);
    /* Clipped card → inset ring. A closed item is exactly as tall as its
     * trigger, so an outward ring would have nowhere at all to draw. */
    --accordion-focus-ring-offset: calc(-1 * var(--accordion-focus-ring-width));
    --accordion-item-radius:  var(--vds-radius-card, 0.75rem);
    --accordion-trigger-padding-block:  var(--vds-space-3, 0.75rem);
    --accordion-trigger-padding-inline: var(--vds-space-4, 1rem);
    --accordion-content-padding-block-end: var(--vds-space-3, 0.75rem);
    --accordion-content-padding-inline:    var(--vds-space-4, 1rem);
  }
  .vds-accordion[data-variant="separated"] .vds-accordion-item {
    border: 1px solid var(--accordion-color-border);
    border-radius: var(--accordion-item-radius);
    background-color: var(--vds-color-surface, transparent);
    overflow: clip;
    transition: border-color var(--accordion-transition-duration) var(--accordion-transition-easing),
                box-shadow var(--accordion-transition-duration) var(--accordion-transition-easing);
  }
  .vds-accordion[data-variant="separated"] .vds-accordion-item[data-state="open"] {
    border-color: var(--accordion-color-accent);
  }

  /* filled — soft tinted background per item. Best for FAQ cards. */
  .vds-accordion[data-variant="filled"] {
    --accordion-gap: var(--vds-space-2, 0.5rem);
    /* Clipped card → inset ring. See "separated" above. */
    --accordion-focus-ring-offset: calc(-1 * var(--accordion-focus-ring-width));
    --accordion-item-radius:  var(--vds-radius-card, 0.75rem);
    --accordion-trigger-padding-block:  var(--vds-space-3, 0.75rem);
    --accordion-trigger-padding-inline: var(--vds-space-4, 1rem);
    --accordion-content-padding-block-end: var(--vds-space-3, 0.75rem);
    --accordion-content-padding-inline:    var(--vds-space-4, 1rem);
  }
  .vds-accordion[data-variant="filled"] .vds-accordion-item {
    background-color: var(--vds-color-bg-subtle, rgb(0 0 0 / 0.025));
    border-radius: var(--accordion-item-radius);
    overflow: clip;
  }
  .vds-accordion[data-variant="filled"] .vds-accordion-item[data-state="open"] {
    background-color: var(--vds-color-bg-muted, rgb(0 0 0 / 0.05));
  }

  /* ghost — no frame at all, only hover tint on the trigger. */
  .vds-accordion[data-variant="ghost"] {
    --accordion-gap: 0;
    --accordion-trigger-padding-inline: var(--vds-space-3, 0.75rem);
    --accordion-content-padding-inline: var(--vds-space-3, 0.75rem);
    /* The only variant where the trigger draws its own corner — so point the
     * ring at that same corner token instead of the generic action radius,
     * which a theme is free to move independently of --vds-radius-nav-item. */
    --accordion-focus-ring-radius: var(--vds-radius-nav-item, 0.375rem);
  }
  .vds-accordion[data-variant="ghost"] .vds-accordion-trigger {
    border-radius: var(--vds-radius-nav-item, 0.375rem);
  }

  /* contained — one outer frame with dividers inside. Best for long FAQ. */
  .vds-accordion[data-variant="contained"] {
    --accordion-gap: 0;
    /* Clipped frame → inset ring. See --accordion-focus-ring-offset above. */
    --accordion-focus-ring-offset: calc(-1 * var(--accordion-focus-ring-width));
    --accordion-item-radius:  var(--vds-radius-card, 0.75rem);
    --accordion-trigger-padding-inline: var(--vds-space-5, 1.25rem);
    --accordion-content-padding-inline: var(--vds-space-5, 1.25rem);
    border: 1px solid var(--accordion-color-border);
    border-radius: var(--accordion-item-radius);
    background-color: var(--vds-color-surface, transparent);
    overflow: clip;
  }
  .vds-accordion[data-variant="contained"] .vds-accordion-item {
    border-block-end: 1px solid var(--accordion-color-border);
  }
  .vds-accordion[data-variant="contained"] .vds-accordion-item:last-child {
    border-block-end: 0;
  }

  /* =========================================================================
   * 4. Sizes — redefine layout-only tokens.
   * ========================================================================= */

  .vds-accordion[data-size="sm"] {
    --accordion-trigger-padding-block: var(--vds-space-2-5, 0.625rem);
    --accordion-trigger-font-size:     var(--vds-text-sm, 0.875rem);
    --accordion-content-padding-block-end: var(--vds-space-2-5, 0.625rem);
    --accordion-content-font-size:     var(--vds-text-xs, 0.75rem);
    --accordion-icon-size: 0.875rem;
  }

  /* md is the base */

  .vds-accordion[data-size="lg"] {
    --accordion-trigger-padding-block: var(--vds-space-5, 1.25rem);
    --accordion-trigger-font-size:     var(--vds-text-base, 1rem);
    --accordion-content-padding-block-end: var(--vds-space-5, 1.25rem);
    --accordion-content-font-size:     var(--vds-text-base, 1rem);
    --accordion-icon-size: 1.25rem;
  }
}

import { cn } from "@virtari-packages/utils";
import {
  createContext,
  createElement,
  useContext,
  type ComponentRef,
  type ReactNode,
  type Ref,
} from "react";
import * as AccordionPrimitive from "@virtari-packages/primitives/accordion";
import {
  IconChevronDown,
  IconPlus,
  IconMinus,
  IconArrowDown,
  IconCaretDownFilled,
} from "@virtari-packages/react-icons";

/** Shape/frame variant — orthogonal to color and size. */
export type AccordionVariant =
  | "plain"
  | "bordered"
  | "separated"
  | "filled"
  | "ghost"
  | "contained";

/** Size preset — affects trigger padding, font size, icon size. */
export type AccordionSize = "sm" | "md" | "lg";

/** Intent palette — sets hover tint and open-state accent color. */
export type AccordionColor =
  | "neutral"
  | "primary"
  | "accent"
  | "success"
  | "danger"
  | "warning";

/** Indicator style placed in the trigger. */
export type AccordionIconType =
  | "chevron"
  | "plus-minus"
  | "arrow"
  | "caret"
  | "none";

/** Which side of the trigger the indicator sits on. */
export type AccordionIconPosition = "start" | "end";

/** Semantic heading level for each trigger. Default: `h3` for FAQ/SEO. */
export type AccordionHeadingLevel = "h2" | "h3" | "h4" | "h5" | "h6";

/* ──────────────────────────── Root context ────────────────────────────
 * The primitive Root takes its own props, so we wrap it and forward styling
 * config to children via context instead of drilling props. */

interface AccordionContextValue {
  iconType: AccordionIconType;
  iconPosition: AccordionIconPosition;
  headingLevel: AccordionHeadingLevel;
  size: AccordionSize;
}

const AccordionContext = createContext<AccordionContextValue>({
  iconType: "chevron",
  iconPosition: "end",
  headingLevel: "h3",
  size: "md",
});

/* ──────────────────────────── Accordion (root) ──────────────────────── */

type PrimitiveAccordionRootProps = React.ComponentPropsWithoutRef<
  typeof AccordionPrimitive.Root
>;

/** Root props. Intersection because the primitive Root is a discriminated union
 * on `type="single" | "multiple"` — `interface extends` can't widen it. */
export type AccordionProps = PrimitiveAccordionRootProps & {
  /** Shape/frame. Default: `plain`. */
  variant?: AccordionVariant;
  /** Size preset. Default: `md`. */
  size?: AccordionSize;
  /** Intent palette for hover/open accent. Default: `neutral`. */
  color?: AccordionColor;
  /** Indicator icon type. Default: `chevron`. */
  iconType?: AccordionIconType;
  /** Which side of the trigger the icon sits on. Default: `end`. */
  iconPosition?: AccordionIconPosition;
  /**
   * Heading level rendered around each trigger for SEO / a11y.
   * Default: `h3`. Pick so the hierarchy fits your page (usually h2 or h3).
   */
  headingLevel?: AccordionHeadingLevel;
  /** Optional class merged onto the root. */
  className?: string;
  ref?: Ref<ComponentRef<typeof AccordionPrimitive.Root>>;
};

export function Accordion({
  variant = "plain",
  size = "md",
  color = "neutral",
  iconType = "chevron",
  iconPosition = "end",
  headingLevel = "h3",
  className,
  ref,
  ...props
}: AccordionProps) {
  return (
    <AccordionContext.Provider
      value={{ iconType, iconPosition, headingLevel, size }}
    >
      <AccordionPrimitive.Root
        ref={ref}
        className={cn("vds-accordion", className)}
        data-variant={variant}
        data-size={size}
        data-color={color}
        {...(props as PrimitiveAccordionRootProps)}
      />
    </AccordionContext.Provider>
  );
}

/* ──────────────────────────── AccordionItem ─────────────────────────── */

export interface AccordionItemProps
  extends React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item> {
  /** Override the root color for just this item (e.g., highlight a row). */
  color?: AccordionColor;
  ref?: Ref<ComponentRef<typeof AccordionPrimitive.Item>>;
}

export function AccordionItem({
  className,
  color,
  ref,
  ...props
}: AccordionItemProps) {
  return (
    <AccordionPrimitive.Item
      ref={ref}
      className={cn("vds-accordion-item", className)}
      data-color={color}
      {...props}
    />
  );
}

/* ──────────────────────────── AccordionTrigger ──────────────────────── */

const ICON_STROKE = 1.75;

function AccordionIndicator({ type }: { type: AccordionIconType }) {
  if (type === "none") return null;

  if (type === "plus-minus") {
    return (
      <span className="vds-accordion-icon" data-icon="plus-minus" aria-hidden>
        <IconPlus
          className="vds-accordion-icon-plus"
          stroke={ICON_STROKE}
          focusable={false}
        />
        <IconMinus
          className="vds-accordion-icon-minus"
          stroke={ICON_STROKE}
          focusable={false}
        />
      </span>
    );
  }

  const Icon =
    type === "arrow"
      ? IconArrowDown
      : type === "caret"
      ? IconCaretDownFilled
      : IconChevronDown;

  return (
    <span className="vds-accordion-icon" data-icon={type} aria-hidden>
      <Icon stroke={ICON_STROKE} focusable={false} />
    </span>
  );
}

export interface AccordionTriggerProps
  extends React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger> {
  /** Override the root's icon type for this trigger only. */
  iconType?: AccordionIconType;
  /** Override the root's icon position for this trigger only. */
  iconPosition?: AccordionIconPosition;
  /** Override the root's heading level for this trigger only. */
  headingLevel?: AccordionHeadingLevel;
  ref?: Ref<ComponentRef<typeof AccordionPrimitive.Trigger>>;
}

export function AccordionTrigger({
  className,
  children,
  iconType: iconTypeProp,
  iconPosition: iconPositionProp,
  headingLevel: headingLevelProp,
  ref,
  ...props
}: AccordionTriggerProps) {
  const ctx = useContext(AccordionContext);
  const iconType = iconTypeProp ?? ctx.iconType;
  const iconPosition = iconPositionProp ?? ctx.iconPosition;
  const headingLevel = headingLevelProp ?? ctx.headingLevel;

  return (
    <AccordionPrimitive.Header asChild>
      {/* Render as a real heading for SEO + proper document outline.
       * The primitive keeps the ARIA semantics intact; the Trigger inside provides
       * aria-expanded / aria-controls. */}
      <HeadingTag className="vds-accordion-header" tag={headingLevel}>
        <AccordionPrimitive.Trigger
          ref={ref}
          className={cn("vds-accordion-trigger", className)}
          data-icon-position={iconPosition}
          {...props}
        >
          <span className="vds-accordion-trigger-label">{children}</span>
          <AccordionIndicator type={iconType} />
        </AccordionPrimitive.Trigger>
      </HeadingTag>
    </AccordionPrimitive.Header>
  );
}

/** Internal — render an arbitrary heading level without relying on the
 * global JSX namespace (absent under React 19 by default). */
function HeadingTag({
  tag,
  className,
  children,
}: {
  tag: AccordionHeadingLevel;
  className?: string;
  children: ReactNode;
}) {
  return createElement(tag, { className }, children);
}

/* ──────────────────────────── AccordionContent ──────────────────────── */

export interface AccordionContentProps
  extends React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content> {
  ref?: Ref<ComponentRef<typeof AccordionPrimitive.Content>>;
}

export function AccordionContent({
  className,
  children,
  ref,
  ...props
}: AccordionContentProps) {
  return (
    <AccordionPrimitive.Content
      ref={ref}
      className={cn("vds-accordion-content", className)}
      {...props}
    >
      <div className="vds-accordion-content-inner">{children}</div>
    </AccordionPrimitive.Content>
  );
}

