@layer design-system.components {
  /* =========================================================================
   * ButtonGroup — layout-only wrapper around a row/column of <Button>s.
   *
   * Children style themselves via their own Button tokens; this file only
   * drives spacing, orientation, segmented ("attached") geometry, and RTL.
   * Logical properties (margin-inline, border-start-start-radius, …) mean
   * LTR and RTL both work without a dedicated [dir="rtl"] branch.
   * ========================================================================= */

  .vds-button-group {
    display: inline-flex;
    align-items: stretch;
    gap: var(--button-group-gap);
    min-inline-size: 0;
  }

  .vds-button-group[data-orientation="vertical"] {
    flex-direction: column;
    align-items: stretch;
  }

  /* ── Full width — children share the container equally ── */
  .vds-button-group[data-full-width] {
    display: flex;
    inline-size: 100%;
  }
  .vds-button-group[data-full-width] > .vds-button {
    flex: 1 1 0;
    min-inline-size: 0;
  }

  /* ─────────────────────────────────────────────
   * Focus — raise an item above its neighbour so the ring
   * is not clipped by the adjacent button's box.
   * ───────────────────────────────────────────── */
  .vds-button-group > .vds-button {
    position: relative;
  }
  .vds-button-group > .vds-button:focus-visible {
    z-index: var(--button-group-focus-z);
  }

  /* =========================================================================
   * Attached mode — segmented control geometry.
   *
   * Inner radii collapse, trailing border of each non-last child is removed
   * so outlined variants read as a single bar with no doubled edges.
   * ========================================================================= */
  .vds-button-group[data-attached] {
    gap: 0;
  }

  /* ── Horizontal attached — inline axis ── */
  .vds-button-group[data-attached][data-orientation="horizontal"]
    > .vds-button:not(:last-child) {
    border-inline-end-width: 0;
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  .vds-button-group[data-attached][data-orientation="horizontal"]
    > .vds-button:not(:first-child) {
    border-start-start-radius: 0;
    border-end-start-radius: 0;
  }

  /* ── Vertical attached — block axis ── */
  .vds-button-group[data-attached][data-orientation="vertical"]
    > .vds-button:not(:last-child) {
    border-block-end-width: 0;
    border-end-start-radius: 0;
    border-end-end-radius: 0;
  }

  .vds-button-group[data-attached][data-orientation="vertical"]
    > .vds-button:not(:first-child) {
    border-start-start-radius: 0;
    border-start-end-radius: 0;
  }

  /* Ensure hovered/focused attached button sits above neighbours so that
   * its border and focus ring are fully visible. */
  .vds-button-group[data-attached] > .vds-button:hover,
  .vds-button-group[data-attached] > .vds-button:focus-visible,
  .vds-button-group[data-attached] > .vds-button[aria-pressed="true"] {
    z-index: var(--button-group-focus-z);
  }
}

@layer design-system.components {
  /* =========================================================================
   * ButtonGroup — wrapper-level layout tokens.
   *
   * Children (<Button>) keep using their own size/variant/color tokens;
   * this file only drives the group container (gap, radius when attached,
   * border-collapse between adjacent items).
   *
   * Size ramp below mirrors Button's 8-slot scale exactly so a group at
   * size "md" lines up with a Button at size "md".
   *    2xs(24) · xs(28) · sm(32) · md(36) · lg(40) · xl(44) · 2xl(52) · 3xl(64)
   * ========================================================================= */

  .vds-button-group {
    /* ── Layout (md defaults) ── */
    --button-group-height: var(--vds-size-md, 2.25rem);
    --button-group-gap: var(--vds-space-2, 0.5rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));

    /* Attached mode — shared 1px border between adjacent items. */
    --button-group-divider-width: 1px;

    /* Focus ring bump so an item's ring is not clipped by its neighbour. */
    --button-group-focus-z: 1;
  }

  /* ─────────────────────────────────────────────
   * Size ramp — synced 1:1 with Button.
   * Only gap/radius vary; height is informational for attached layouts.
   * ───────────────────────────────────────────── */

  .vds-button-group[data-size="2xs"] {
    --button-group-height: var(--vds-size-2xs, 1.5rem);
    --button-group-gap: var(--vds-space-1, 0.25rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }

  .vds-button-group[data-size="xs"] {
    --button-group-height: var(--vds-size-xs, 1.75rem);
    --button-group-gap: var(--vds-space-1, 0.25rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }

  .vds-button-group[data-size="sm"] {
    --button-group-height: var(--vds-size-sm, 2rem);
    --button-group-gap: var(--vds-space-1-5, 0.375rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }

  /* md — default, inherits base tokens */

  .vds-button-group[data-size="lg"] {
    --button-group-height: var(--vds-size-lg, 2.5rem);
    --button-group-gap: var(--vds-space-2, 0.5rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }

  .vds-button-group[data-size="xl"] {
    --button-group-height: var(--vds-size-xl, 2.75rem);
    --button-group-gap: var(--vds-space-2, 0.5rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }

  .vds-button-group[data-size="2xl"] {
    --button-group-height: var(--vds-size-2xl, 3.25rem);
    --button-group-gap: var(--vds-space-2-5, 0.625rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }

  .vds-button-group[data-size="3xl"] {
    --button-group-height: var(--vds-size-3xl, 4rem);
    --button-group-gap: var(--vds-space-3, 0.75rem);
    --button-group-radius: var(--vds-radius-button-group, var(--vds-radius-element, 0.375rem));
  }
}

import { cn } from "@virtari-packages/utils";
import {
  forwardRef,
  useMemo,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";
import {
  ButtonGroupContext,
  type ButtonColor,
  type ButtonVariant,
  type ButtonSize,
} from "@virtari-packages/react-button";

export interface ButtonGroupProps
  extends Omit<ComponentPropsWithoutRef<"div">, "color"> {
  /** Hue/intent propagated to every child Button. Each child can still override. */
  color?: ButtonColor;
  /** Visual style propagated to every child Button. Each child can still override. */
  variant?: ButtonVariant;
  /** Size propagated to every child Button. Each child can still override. */
  size?: ButtonSize;
  /** Disabled propagated to every child Button. Each child can still override. */
  disabled?: boolean;
  /** Layout axis. */
  orientation?: "horizontal" | "vertical";
  /** Segmented mode: zero gap, collapsed inner radii and shared borders. */
  attached?: boolean;
  /** Children stretch to equal flex basis, filling the container. */
  fullWidth?: boolean;
  children: ReactNode;
}

export const ButtonGroup = forwardRef<HTMLDivElement, ButtonGroupProps>(
  function ButtonGroup(
    {
      color,
      variant,
      size,
      disabled,
      orientation = "horizontal",
      attached = false,
      fullWidth = false,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const ctx = useMemo(
      () => ({ color, variant, size, disabled }),
      [color, variant, size, disabled],
    );

    return (
      <ButtonGroupContext.Provider value={ctx}>
        <div
          ref={ref}
          role="group"
          className={cn("vds-button-group", className)}
          data-orientation={orientation}
          data-attached={attached ? "" : undefined}
          data-full-width={fullWidth ? "" : undefined}
          data-size={size}
          data-variant={variant}
          data-color={color}
          {...rest}
        >
          {children}
        </div>
      </ButtonGroupContext.Provider>
    );
  },
);

ButtonGroup.displayName = "ButtonGroup";

