@import "./Carousel.tokens.css";

/*
 * Virtari Carousel — Swiper.js theme
 * --------------------------------------------------------------------------
 * We do NOT import Swiper's stock CSS. We re-implement the minimal track
 * surface Swiper needs and theme the pagination/scrollbar to match the DS.
 * Navigation buttons are <Button> components from @virtari-packages/react-button
 * — Swiper just controls their disabled state via class hooks.
 *
 * All selectors use `:where()` so consumer overrides win without !important.
 * --------------------------------------------------------------------------
 */
@layer design-system.components {
  /* =========================================================================
   * 1. Root + Swiper engine layout (minimum viable surface)
   * ========================================================================= */
  .vds-carousel {
    display: block;
    inline-size: 100%;
    max-inline-size: 100%;
    min-inline-size: 0;
    block-size: 100%;
    box-sizing: border-box;
    contain: inline-size;
    padding-block: var(--carousel-padding-block);
    padding-inline: var(--carousel-padding-inline);
  }

  /* Slot adjacency — the container owns the gap between topSlot, the track
   * and bottomSlot. Only adjacent pairs get it, so an omitted slot leaves no
   * dangling space and neither slot has to manage its own leading edge. */
  .vds-carousel > * + * {
    margin-block-start: var(--carousel-slot-gap);
  }

  /* Track wrapper — establishes the positioning anchor for nav buttons,
   * pagination, and scrollbar. Must wrap the Swiper *and* its overlays so
   * absolute positioning is anchored to the track regardless of topSlot /
   * bottomSlot height. */
  .vds-carousel :where(.vds-carousel-track) {
    position: relative;
    display: block;
    inline-size: 100%;
    max-inline-size: 100%;
    min-inline-size: 0;
    block-size: 100%;
    box-sizing: border-box;
  }

  .vds-carousel :where(.swiper) {
    position: relative;
    overflow: hidden;
    list-style: none;
    margin-inline: auto;
    padding: 0;
    z-index: 1;
    inline-size: 100%;
    max-inline-size: 100%;
    min-inline-size: 0;
    block-size: 100%;
    box-sizing: border-box;
    border-radius: var(--carousel-track-radius);
    /* Required by Swiper's RTL detection */
    direction: ltr;
  }
  .vds-carousel:dir(rtl) :where(.swiper),
  .vds-carousel[dir="rtl"] :where(.swiper) {
    direction: rtl;
  }

  .vds-carousel :where(.swiper-wrapper) {
    position: relative;
    z-index: 1;
    display: flex;
    inline-size: 100%;
    min-inline-size: 0;
    block-size: 100%;
    box-sizing: content-box;
    transition-property: transform;
    transition-timing-function: var(--carousel-transition-easing);
    will-change: transform;
  }

  .vds-carousel :where(.swiper-slide) {
    flex-shrink: 0;
    min-inline-size: 0;
    block-size: 100%;
    position: relative;
    box-sizing: border-box;
    transition-property: transform;
  }

  .vds-carousel :where(.swiper-slide-invisible-blank) {
    visibility: hidden;
  }

  /* ── Vertical orientation ── */
  .vds-carousel[data-orientation="vertical"] {
    /* Vertical track must have a deterministic block-size; consumer should
     * give the carousel a parent height (or set it on the carousel itself). */
    block-size: 100%;
    min-block-size: 1rem;
  }
  .vds-carousel[data-orientation="vertical"] :where(.swiper) {
    block-size: 100%;
  }
  .vds-carousel[data-orientation="vertical"] :where(.swiper-wrapper) {
    flex-direction: column;
  }
  .vds-carousel[data-orientation="vertical"] :where(.swiper-slide) {
    inline-size: 100%;
    /* Vertical slides need a definite height — Swiper sizes them based on
     * the track block-size minus spaceBetween. Don't override here. */
  }

  /* ── Free-mode / autoheight ── */
  .vds-carousel :where(.swiper-autoheight),
  .vds-carousel :where(.swiper-autoheight .swiper-slide) {
    block-size: auto;
  }
  .vds-carousel :where(.swiper-autoheight .swiper-wrapper) {
    align-items: flex-start;
    transition-property: transform, height;
  }

  /* =========================================================================
   * 2. Navigation buttons — these are <Button> components rendered as
   *    siblings of the .swiper inside .vds-carousel-track. Swiper toggles
   *    disabled state via class hooks we declared.
   * ========================================================================= */
  .vds-carousel .vds-carousel-nav {
    position: absolute;
    z-index: 10;
    border-radius: var(--carousel-nav-radius);
    /* Use individual transform properties so :active scale on Button doesn't
     * fight our centering translate. `translate` is honored alongside
     * `scale` independently in modern browsers. */
    transform: none;
    /* Force a square footprint regardless of Button's icon-only :has()
     * detection (which can be brittle if children change). */
    aspect-ratio: 1;
    padding-inline: 0;
    padding-block: 0;
    min-inline-size: 0;
  }

  /* Horizontal nav placement (default + inside + minimal + solid) */
  .vds-carousel:not([data-orientation="vertical"]) .vds-carousel-nav {
    inset-block-start: 50%;
    translate: 0 -50%;
  }
  .vds-carousel:not([data-orientation="vertical"]) .vds-carousel-nav--prev {
    inset-inline-start: var(--carousel-nav-offset);
  }
  .vds-carousel:not([data-orientation="vertical"]) .vds-carousel-nav--next {
    inset-inline-end: var(--carousel-nav-offset);
  }

  /* Vertical nav placement — chevron-up at top, chevron-down at bottom. */
  .vds-carousel[data-orientation="vertical"] .vds-carousel-nav {
    inset-inline-start: 50%;
    translate: -50% 0;
  }
  .vds-carousel[data-orientation="vertical"] .vds-carousel-nav--prev {
    inset-block-start: var(--carousel-nav-offset);
  }
  .vds-carousel[data-orientation="vertical"] .vds-carousel-nav--next {
    inset-block-end: var(--carousel-nav-offset);
  }

  /* Outside variant — push horizontal nav into a side gutter. */
  .vds-carousel[data-variant="outside"]:not([data-orientation="vertical"]) {
    padding-inline: calc(var(--carousel-nav-offset) * 2 + var(--carousel-nav-size));
  }
  .vds-carousel[data-variant="outside"]:not([data-orientation="vertical"]) .vds-carousel-nav--prev {
    inset-inline-start: 0;
  }
  .vds-carousel[data-variant="outside"]:not([data-orientation="vertical"]) .vds-carousel-nav--next {
    inset-inline-end: 0;
  }

  /* RTL — Swiper swaps prev/next semantically (so prev still means "back in
   * reading direction"). Logical inset-inline-* already places them on the
   * correct side. The chevron icon, however, is direction-agnostic — flip
   * it horizontally so it points the right way for the reading order. */
  .vds-carousel:dir(rtl):not([data-orientation="vertical"]) .vds-carousel-nav .vds-button-label > svg,
  .vds-carousel[dir="rtl"]:not([data-orientation="vertical"]) .vds-carousel-nav .vds-button-label > svg {
    transform: scaleX(-1);
  }

  /* Disabled / hidden / locked — managed by Swiper via classes we declared. */
  .vds-carousel :where(.vds-carousel-nav--disabled) {
    opacity: var(--carousel-nav-disabled-opacity);
    cursor: not-allowed;
    pointer-events: none;
  }
  .vds-carousel :where(.vds-carousel-nav--hidden) {
    visibility: hidden;
    opacity: 0;
  }
  .vds-carousel :where(.vds-carousel-nav--locked) {
    display: none !important;
  }

  /* =========================================================================
   * 3. Pagination — bullets / fraction / progressbar
   * ========================================================================= */
  .vds-carousel :where(.swiper-pagination) {
    position: absolute;
    inset-inline: 0;
    inset-block-end: var(--carousel-pagination-offset);
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--carousel-pagination-gap);
    pointer-events: none;
    transition: opacity var(--carousel-transition-duration) var(--carousel-transition-easing);
  }
  .vds-carousel :where(.swiper-pagination-hidden) {
    opacity: 0;
  }
  .vds-carousel :where(.swiper-pagination-lock) {
    display: none;
  }

  /* ── Bullets ── */
  .vds-carousel :where(.swiper-pagination-bullet) {
    inline-size: var(--carousel-bullet-size);
    block-size: var(--carousel-bullet-size);
    display: inline-block;
    border: 0;
    margin: 0;
    border-radius: var(--carousel-bullet-radius);
    background-color: var(--carousel-bullet-bg);
    opacity: 1;
    pointer-events: auto;
    cursor: pointer;
    transition:
      background-color var(--carousel-transition-duration) var(--carousel-transition-easing),
      inline-size      var(--carousel-transition-duration) var(--carousel-transition-easing);
  }
  .vds-carousel :where(.swiper-pagination-bullet):hover {
    background-color: var(--carousel-bullet-bg-hover);
  }
  .vds-carousel :where(.swiper-pagination-bullet):focus-visible {
    outline: var(--carousel-focus-ring-width) solid var(--carousel-focus-ring-color);
    outline-offset: var(--carousel-focus-ring-offset);
  }
  .vds-carousel :where(.swiper-pagination-bullet-active) {
    inline-size: var(--carousel-bullet-active-size);
    background-color: var(--carousel-bullet-active-bg);
  }

  /* ── Bars look (data-pagination="bars") — same anatomy, different sizes,
   * declared in tokens; rules above already pick them up. */

  /* ── Vertical pagination — switch the bar to a column on the inline edge. */
  .vds-carousel[data-orientation="vertical"] :where(.swiper-pagination) {
    inset-block: 0;
    inset-inline-start: auto;
    inset-inline-end: var(--carousel-pagination-offset);
    inline-size: auto;
    flex-direction: column;
  }
  .vds-carousel[data-orientation="vertical"] :where(.swiper-pagination-bullet) {
    inline-size: var(--carousel-bullet-size);
    block-size: var(--carousel-bullet-size);
  }
  .vds-carousel[data-orientation="vertical"] :where(.swiper-pagination-bullet-active) {
    block-size: var(--carousel-bullet-active-size);
    inline-size: var(--carousel-bullet-size);
  }

  /* ── Fraction ── */
  .vds-carousel :where(.swiper-pagination-fraction) {
    inline-size: max-content;
    max-inline-size: calc(100% - var(--carousel-pagination-offset) * 2);
    block-size: max-content;
    margin: auto;
    box-sizing: border-box;
    color: var(--carousel-fraction-fg);
    font-family: var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    font-size: var(--carousel-fraction-font-size);
    font-variant-numeric: tabular-nums;
    pointer-events: auto;
    padding-inline: var(--vds-space-2-5, 0.625rem);
    padding-block: var(--vds-space-1, 0.25rem);
    background-color: color-mix(in oklch, var(--vds-color-surface, #fff) 80%, transparent);
    border-radius: var(--vds-radius-full, 9999px);
    backdrop-filter: blur(8px);
  }

  /* ── Progressbar ── */
  .vds-carousel :where(.swiper-pagination-progressbar) {
    position: absolute;
    inset-inline: 0;
    inset-block-start: 0;
    inset-block-end: auto;
    z-index: 10;
    inline-size: 100%;
    block-size: var(--carousel-progress-thickness);
    background-color: var(--carousel-progress-track);
    border-radius: 0;
    pointer-events: none;
    overflow: hidden;
  }
  .vds-carousel :where(.swiper-pagination-progressbar .swiper-pagination-progressbar-fill) {
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    inline-size: 100%;
    block-size: 100%;
    background-color: var(--carousel-progress-fill);
    transform-origin: 0 50%;
    transform: scaleX(0);
    border-radius: var(--carousel-progress-radius);
  }
  .vds-carousel:dir(rtl) :where(.swiper-pagination-progressbar .swiper-pagination-progressbar-fill),
  .vds-carousel[dir="rtl"] :where(.swiper-pagination-progressbar .swiper-pagination-progressbar-fill) {
    transform-origin: 100% 50%;
  }
  .vds-carousel :where(.swiper-pagination-progressbar.swiper-pagination-progressbar-opposite) {
    inset-block-start: auto;
    inset-block-end: 0;
  }

  /* Pagination position modifier (top vs outside) */
  .vds-carousel[data-pagination-position="top"] :where(.swiper-pagination) {
    inset-block-start: var(--carousel-pagination-offset);
    inset-block-end: auto;
  }
  .vds-carousel[data-pagination-position="outside"] {
    padding-block-end: calc(var(--carousel-bullet-active-size) + var(--carousel-pagination-offset) * 2);
  }
  .vds-carousel[data-pagination-position="outside"] :where(.swiper-pagination) {
    inset-block-end: 0;
  }

  /* =========================================================================
   * 4. Scrollbar (opt-in via the scrollbar prop)
   * ========================================================================= */
  .vds-carousel :where(.swiper-scrollbar) {
    position: absolute;
    z-index: 10;
    background-color: var(--carousel-scrollbar-track);
    border-radius: var(--carousel-scrollbar-radius);
  }

  .vds-carousel:not([data-orientation="vertical"]) :where(.swiper-scrollbar) {
    inset-inline: 1%;
    inset-block-end: var(--carousel-pagination-offset);
    inline-size: 98%;
    block-size: var(--carousel-scrollbar-thickness);
  }
  .vds-carousel[data-orientation="vertical"] :where(.swiper-scrollbar) {
    inset-block: 1%;
    inset-inline-end: var(--carousel-pagination-offset);
    inline-size: var(--carousel-scrollbar-thickness);
    block-size: 98%;
  }

  .vds-carousel :where(.swiper-scrollbar-drag) {
    position: relative;
    inline-size: 100%;
    block-size: 100%;
    background-color: var(--carousel-scrollbar-thumb);
    border-radius: var(--carousel-scrollbar-radius);
    cursor: grab;
  }
  .vds-carousel :where(.swiper-scrollbar-drag):active {
    cursor: grabbing;
  }
  .vds-carousel :where(.swiper-scrollbar-cursor-drag) {
    cursor: grabbing;
  }
  .vds-carousel :where(.swiper-scrollbar-lock) {
    display: none;
  }

  /* =========================================================================
   * 5. Lazy loading + zoom helpers
   * ========================================================================= */
  .vds-carousel :where(.swiper-lazy-preloader) {
    --carousel-preloader-size: var(--vds-size-lg, 2.5rem);
    inline-size: var(--carousel-preloader-size);
    block-size: var(--carousel-preloader-size);
    position: absolute;
    inset-inline-start: 50%;
    inset-block-start: 50%;
    /* Half the spinner box, so centering follows the size token. */
    margin-inline-start: calc(var(--carousel-preloader-size) / -2);
    margin-block-start: calc(var(--carousel-preloader-size) / -2);
    z-index: 10;
    transform-origin: 50%;
    box-sizing: border-box;
    border: 4px solid var(--carousel-progress-track);
    border-radius: 50%;
    border-block-start-color: transparent;
    animation: vds-carousel-spin 1s linear infinite;
  }
  @keyframes vds-carousel-spin {
    to { transform: rotate(360deg); }
  }

  .vds-carousel :where(.swiper-zoom-container) {
    inline-size: 100%;
    block-size: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;
  }
  .vds-carousel :where(.swiper-zoom-container > img),
  .vds-carousel :where(.swiper-zoom-container > svg),
  .vds-carousel :where(.swiper-zoom-container > canvas) {
    max-inline-size: 100%;
    max-block-size: 100%;
    object-fit: contain;
  }

  /* =========================================================================
   * 6. Fade effect — cleaner cross-fade for effect="fade"
   * ========================================================================= */
  .vds-carousel :where(.swiper-fade.swiper-free-mode .swiper-slide) {
    transition-timing-function: ease-out;
  }
  .vds-carousel :where(.swiper-fade .swiper-slide) {
    pointer-events: none;
    transition-property: opacity;
  }
  .vds-carousel :where(.swiper-fade .swiper-slide .swiper-slide) {
    pointer-events: none;
  }
  .vds-carousel :where(.swiper-fade .swiper-slide-active),
  .vds-carousel :where(.swiper-fade .swiper-slide-active .swiper-slide-active) {
    pointer-events: auto;
  }

  /* =========================================================================
   * 7. Reduced motion
   * ========================================================================= */
  @media (prefers-reduced-motion: reduce) {
    .vds-carousel :where(.swiper-wrapper),
    .vds-carousel :where(.swiper-pagination-bullet),
    .vds-carousel :where(.vds-carousel-nav) {
      transition-duration: 0.01ms !important;
    }
    .vds-carousel :where(.swiper-lazy-preloader) {
      animation-duration: 1.5s;
    }
  }
}

