@layer design-system.components {
  /* =========================================================================
   * 1. Base component tokens
   *    Layout / motion / focus — orthogonal to color & size.
   *    Defaults resolve to: color=primary, variant=default, size=md.
   *    Fallbacks keep the package usable without @virtari-packages/tokens.
   * ========================================================================= */
  .vds-carousel {
    /* ── Layout ── */
    --carousel-padding-block: var(--vds-space-0, 0);
    --carousel-padding-inline: var(--vds-space-0, 0);
    /* Gap between topSlot / track / bottomSlot. The container owns it, so a
     * slot never has to zero or add its own leading edge. */
    --carousel-slot-gap: var(--vds-space-3, 0.75rem);
    --carousel-radius: var(--vds-radius-card, 0.75rem);
    --carousel-track-radius: var(--carousel-radius);

    /* ── Navigation buttons ──
     * The button itself is a <Button> component; we only own its absolute
     * positioning offset and corner-radius.
     *
     * `shape="pill"` is the default and the nav has `aspect-ratio: 1`, so the
     * default corner is fully round — a circle. It used to read
     * `var(--button-radius, …)`, but --button-radius is declared on
     * `.vds-button`, which is a *descendant* of the element this token is
     * declared on, never an ancestor; the var never resolved and every
     * carousel fell through to the same finite corner as `shape="square"`,
     * making that modifier a no-op. */
    --carousel-nav-radius: var(--vds-radius-full, 9999px);
    --carousel-nav-offset: var(--vds-space-3, 0.75rem);
    /* Mirrors the height the nav <Button> resolves to at this carousel size.
     * The "outside" gutter reserves this much, so the two must stay in step. */
    --carousel-nav-size: var(--vds-size-md, 2.25rem);
    --carousel-nav-disabled-opacity: var(--vds-opacity-disabled, 0.5);

    /* ── Pagination (bullets / fraction / progress) ── */
    --carousel-pagination-gap: var(--vds-space-1-5, 0.375rem);
    --carousel-pagination-offset: var(--vds-space-3, 0.75rem);
    --carousel-bullet-size: 0.5rem; /* 8px */
    --carousel-bullet-active-size: 1.25rem; /* 20px — pill expansion */
    --carousel-bullet-radius: var(--vds-radius-full, 9999px);
    --carousel-fraction-font-size: var(--vds-text-sm, 0.875rem);
    --carousel-progress-thickness: 2px;
    --carousel-progress-radius: var(--vds-radius-full, 9999px);

    /* ── Scrollbar ── */
    --carousel-scrollbar-thickness: 4px;
    --carousel-scrollbar-radius: var(--vds-radius-full, 9999px);

    /* ── Motion ── */
    --carousel-transition-duration: var(--vds-duration-fast, 180ms);
    --carousel-transition-easing: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* ── Focus ── */
    --carousel-focus-ring-color: var(--vds-color-ring, var(--carousel-color-solid));
    --carousel-focus-ring-width: 2px;
    --carousel-focus-ring-offset: 2px;

    /* =====================================================================
     * Intent palette — default: primary
     * Used for pagination / progressbar accents only — nav buttons consume
     * Button's own palette via the color/variant prop pass-through.
     * ===================================================================== */
    --carousel-color-solid:        var(--vds-color-primary-solid, #4f46e5);

    --carousel-bullet-bg:        var(--vds-color-border, color-mix(in oklch, currentColor 25%, transparent));
    --carousel-bullet-bg-hover:  var(--vds-color-border-interactive, color-mix(in oklch, currentColor 45%, transparent));
    --carousel-bullet-active-bg: var(--carousel-color-solid);

    --carousel-progress-track:   var(--vds-color-bg-muted, color-mix(in oklch, currentColor 12%, transparent));
    --carousel-progress-fill:    var(--carousel-color-solid);

    --carousel-scrollbar-track:  var(--vds-color-surface-active, color-mix(in oklch, currentColor 8%, transparent));
    --carousel-scrollbar-thumb:  var(--vds-color-border-interactive, color-mix(in oklch, currentColor 45%, transparent));

    --carousel-fraction-fg:      var(--vds-color-text, #171717);
  }

  /* =========================================================================
   * 2. Color palettes — only the *accent* color drives pagination/progress.
   *    Nav buttons take their color directly from <Button color> via
   *    the prop pass-through; we don't need to re-declare it here.
   * ========================================================================= */
  .vds-carousel[data-color="success"] { --carousel-color-solid: var(--vds-color-success-solid, #16a34a); }
  .vds-carousel[data-color="warning"] { --carousel-color-solid: var(--vds-color-warning-solid, #f59e0b); }
  .vds-carousel[data-color="danger"]  { --carousel-color-solid: var(--vds-color-danger-solid,  #dc2626); }
  .vds-carousel[data-color="info"]    { --carousel-color-solid: var(--vds-color-info-solid,    #0891b2); }
  .vds-carousel[data-color="accent"]  { --carousel-color-solid: var(--vds-color-accent-solid,  var(--vds-color-accent-emphasis, #f97316)); }
  .vds-carousel[data-color="neutral"] { --carousel-color-solid: var(--vds-color-text, #171717); }

  /* =========================================================================
   * 3. Sizes — control bullet dimensions + spacing.
   *    Nav button size flows through to <Button size> directly.
   *    4 slots: xs · sm · md · lg.
   * ========================================================================= */
  .vds-carousel[data-size="xs"] {
    --carousel-nav-offset:         var(--vds-space-2, 0.5rem);
    --carousel-nav-size:           var(--vds-size-xs, 1.75rem);
    --carousel-bullet-size:        0.375rem; /* 6px */
    --carousel-bullet-active-size: 0.875rem;
    --carousel-pagination-gap:     var(--vds-space-1, 0.25rem);
    --carousel-pagination-offset:  var(--vds-space-2, 0.5rem);
  }
  .vds-carousel[data-size="sm"] {
    --carousel-nav-offset:         var(--vds-space-2-5, 0.625rem);
    --carousel-nav-size:           var(--vds-size-sm, 2rem);
    --carousel-bullet-size:        0.4375rem; /* 7px */
    --carousel-bullet-active-size: 1rem;
    --carousel-pagination-gap:     var(--vds-space-1, 0.25rem);
    --carousel-pagination-offset:  var(--vds-space-2-5, 0.625rem);
  }
  /* md — default, inherits base tokens (8px bullet, 20px active) */
  .vds-carousel[data-size="lg"] {
    --carousel-nav-offset:         var(--vds-space-4, 1rem);
    --carousel-nav-size:           var(--vds-size-lg, 2.5rem);
    --carousel-bullet-size:        0.625rem; /* 10px */
    --carousel-bullet-active-size: 1.5rem;
    --carousel-pagination-gap:     var(--vds-space-2, 0.5rem);
    --carousel-pagination-offset:  var(--vds-space-4, 1rem);
  }

  /* =========================================================================
   * 4. Pagination "bars" modifier — turn bullets into elongated bars.
   * ========================================================================= */
  .vds-carousel[data-pagination="bars"] {
    --carousel-bullet-size:        1.25rem; /* width */
    --carousel-bullet-active-size: 2rem;
    --carousel-bullet-radius:      var(--vds-radius-full, 9999px);
  }

  /* =========================================================================
   * 5. Shape modifier — square nav buttons (override Button's own radius).
   *    --vds-radius-control-action, not --vds-radius-action: the latter is
   *    remapped to --vds-radius-full under `data-radius="pill"`, which would
   *    turn the opt-out back into the circle it exists to opt out of. The
   *    control-action token is capped at 8px in every mode.
   * ========================================================================= */
  .vds-carousel[data-shape="square"] {
    --carousel-nav-radius: var(--vds-radius-control-action, var(--vds-radius-element, 0.5rem));
  }
}

