  id: idProp,
  ...rest
}: CheckboxGroupProps) {
  const reactId = useId();
  const groupId = idProp ?? `vds-checkbox-group-${reactId}`;
  const labelId = `${groupId}-label`;
  const descriptionId = `${groupId}-description`;
  const errorId = `${groupId}-error`;

  const hasError = Boolean(error);

  const describedBy =
    [description ? descriptionId : null, hasError ? errorId : null]
      .filter(Boolean)
      .join(" ") || undefined;

  const contextValue = useMemo(
    () => ({ disabled, error: hasError, name, describedBy }),
    [disabled, hasError, name, describedBy],
  );

  return (
    <CheckboxGroupContext.Provider value={contextValue}>
      <div
        ref={ref}
        id={groupId}
        role="group"
        aria-labelledby={label ? labelId : undefined}
        aria-describedby={describedBy}
        aria-invalid={hasError || undefined}
        aria-required={required || undefined}
        aria-disabled={disabled || undefined}
        data-orientation={orientation}
        data-error={hasError ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        className={cn("vds-checkbox-group", className)}
        {...rest}
      >
        {(label || description) && (
          <div className="vds-checkbox-group-header">
            {label && (
              <span id={labelId} className="vds-checkbox-group-label">
                {label}
                {required ? (
                  <span
                    aria-hidden="true"
                    className="vds-checkbox-group-required"
                  >
                    *
                  </span>
                ) : null}
              </span>
            )}
            {description && (
              <span
                id={descriptionId}
                className="vds-checkbox-group-description"
              >
                {description}
              </span>
            )}
          </div>
        )}

        <div className="vds-checkbox-group-items">{children}</div>

        <p
          id={errorId}
          role={hasError ? "alert" : undefined}
          aria-hidden={hasError ? undefined : true}
          data-visible={hasError ? "" : undefined}
          data-empty={hasError ? undefined : ""}
          className="vds-checkbox-group-error"
        >
          <span className="vds-checkbox-group-error-body">
            <IconAlertCircle
              size={14}
              stroke={2}
              aria-hidden
              focusable={false}
              className="vds-checkbox-group-error-icon"
            />
            <span>{error}</span>
          </span>
        </p>
      </div>
    </CheckboxGroupContext.Provider>
  );
}

