@import "./Code.tokens.css";
@import "../../react-copy-button/src/CopyButton.css";

@layer design-system.components {
  /* =========================================================================
   * Root container — wraps the CM6 editor and chrome (header/caption).
   * Uses high enough specificity to win against generic resets, but stays
   * within the design-system.components layer.
   * ========================================================================= */
  .vds-code {
    min-inline-size: 0;
    max-inline-size: 100%;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    background-color: var(--vds-code-bg);
    color: var(--vds-code-text);
    border: var(--vds-code-border-width) solid var(--vds-code-border);
    border-radius: var(--vds-code-radius);
    box-shadow: var(--vds-code-shadow);
    font-family: var(--vds-code-font-family);
    font-size: var(--vds-code-font-size);
    line-height: var(--vds-code-line-height);
    letter-spacing: var(--vds-code-letter-spacing);

    /* Concentricity channel. Header / body / caption sit flush against the
     * shell's inner edge — there is no padding between the shell and its
     * slots — so a flush child's corner is the shell's radius minus its
     * border. Follows --vds-code-radius, so `data-radius` modes and the
     * `embedded` variant (radius 0) carry through automatically. */
    --vds-radius-host-r: var(--vds-code-radius);
    --vds-radius-host-b: var(--vds-code-border-width);
    --vds-radius-host-p: 0px;

    /* Kept, deliberately. CodeMirror paints surfaces we cannot round from
     * here — the scroller's overflowing content, the gutter background, the
     * search panel, selection layers — and they are grandchildren, past the
     * one level the channel reaches. This is the only element that can mask
     * them against the shell's corner. */
    overflow: hidden;
    transition:
      background-color var(--vds-code-transition-duration) var(--vds-code-transition-easing),
      border-color var(--vds-code-transition-duration) var(--vds-code-transition-easing);
  }

  /* =========================================================================
   * Header — filename / language label + actions (copy)
   * ========================================================================= */
  .vds-code-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--vds-space-2, 0.5rem);
    padding-block: var(--vds-code-header-padding-block);
    padding-inline: var(--vds-code-header-padding-inline);
    background-color: var(--vds-code-header-bg);
    color: var(--vds-code-header-text);
    border-block-end: var(--vds-code-border-width) solid var(--vds-code-header-border);
    font-family: var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-medium, 500);
    line-height: 1.4;
    user-select: none;
  }

  .vds-code-header-info {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-2, 0.5rem);
    min-inline-size: 0;
  }

  .vds-code-header-icon {
    display: inline-flex;
    flex-shrink: 0;
    inline-size: 0.875rem;
    block-size: 0.875rem;
    color: var(--vds-color-text-subtle, currentColor);
  }

  .vds-code-header-icon > svg {
    inline-size: 100%;
    block-size: 100%;
  }

  .vds-code-header-filename {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--vds-code-header-text);
  }

  .vds-code-header-language {
    text-transform: uppercase;
    letter-spacing: 0.04em;
    font-size: 0.6875rem;
    color: var(--vds-code-header-text);
  }

  .vds-code-header-actions {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
    flex-shrink: 0;
  }

  /* =========================================================================
   * Body — the CodeMirror surface lives here. CM6 manages its own internal
   * scrolling; the body itself only enforces an outer max-height when given.
   * ========================================================================= */
  .vds-code-body {
    min-inline-size: 0;
    position: relative;
    flex: 1 1 auto;
    min-block-size: 0;
    background-color: var(--vds-code-bg);

    /* Squared against whichever of header / caption abuts it, flush where it
     * meets the shell. The CodeMirror wrapper reads this back with
     * `border-radius: inherit` so the focus ring follows the same corner
     * instead of drawing a square one inside a rounded shell. */
    border-radius: 0;
  }

  .vds-code-body:first-child {
    border-start-start-radius: var(--vds-radius-flush);
    border-start-end-radius: var(--vds-radius-flush);
  }

  .vds-code-body:last-child {
    border-end-start-radius: var(--vds-radius-flush);
    border-end-end-radius: var(--vds-radius-flush);
  }

  /* =========================================================================
   * Caption — figcaption-like description below body
   * ========================================================================= */
  .vds-code-caption {
    padding-block: var(--vds-space-2, 0.5rem);
    padding-inline: var(--vds-code-padding-inline);
    background-color: var(--vds-code-header-bg);
    color: var(--vds-code-caption-color);
    border-block-start: var(--vds-code-border-width) solid var(--vds-code-header-border);
    font-family: var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    font-size: var(--vds-code-caption-font-size);
    line-height: 1.5;
  }

  /* =========================================================================
   * Inline code — pure HTML <code> usage in prose
   * ========================================================================= */
  .vds-code-inline {
    display: inline;
    padding-block: var(--vds-code-inline-padding-block);
    padding-inline: var(--vds-code-inline-padding-inline);
    background-color: var(--vds-code-inline-bg);
    color: var(--vds-code-inline-text);
    border: var(--vds-code-inline-border-width) solid var(--vds-code-inline-border);
    border-radius: var(--vds-code-inline-radius);
    font-family: var(--vds-code-inline-font-family);
    font-size: var(--vds-code-inline-font-size);
    line-height: 1.4;
    white-space: break-spaces;
    overflow-wrap: anywhere;
  }

  .vds-code-static {
    margin: 0;
    padding: 0;
    max-block-size: inherit;
    overflow: auto;
    overscroll-behavior: contain;
    font: inherit;
    color: var(--vds-code-text);
    background: transparent;
    text-align: start;
    tab-size: 2;
    outline: none;
  }

  .vds-code-static-content {
    display: block;
    inline-size: max-content;
    min-inline-size: 100%;
    box-sizing: border-box;
    padding-block: var(--vds-code-padding-block);
    font: inherit;
    color: inherit;
    white-space: pre;
  }

  .vds-code-static-line {
    display: flex;
    padding-inline: var(--vds-code-padding-inline);
    min-block-size: 1lh;
  }

  .vds-code-static-number {
    flex: 0 0 calc(var(--vds-code-line-digits) * 1ch);
    padding-inline-end: var(--vds-code-gutter-padding-inline);
    color: var(--vds-code-gutter-text);
    text-align: end;
    user-select: none;
  }

  .vds-code-static-text { min-inline-size: 0; }
  .vds-code[data-wrap] .vds-code-static-content { inline-size: 100%; white-space: pre-wrap; }
  .vds-code[data-wrap] .vds-code-static-text { overflow-wrap: anywhere; }
  .vds-code-static-line[data-highlighted] { background: var(--vds-code-line-highlight-bg); }
  .vds-code-static-line[data-diff="add"] { background: var(--vds-code-diff-add-bg); box-shadow: inset 3px 0 var(--vds-code-diff-add-marker); }
  .vds-code-static-line[data-diff="remove"] { background: var(--vds-code-diff-remove-bg); box-shadow: inset 3px 0 var(--vds-code-diff-remove-marker); }
  .vds-code-static ::selection { background: var(--vds-code-selection-bg); }
}

/* =========================================================================
 * CodeMirror surface tweaks — kept OUTSIDE @layer because CM6 injects its
 * own theme rules unlayered, which always beat layered rules. We only keep
 * here what theme.ts cannot reach cleanly: pseudo-element scrollbar styling
 * and the focus ring around the wrapper. All other CM6 surface properties
 * are set in theme.ts via EditorView.theme().
 * ========================================================================= */

.vds-code {
  transition: box-shadow 180ms ease-out;

  @media (prefers-reduced-motion: reduce) {
    transition-duration: 0s;
  }
}

.vds-code .cm-editor.cm-focused {
  outline: none;
}

.vds-code:has(.cm-focused),
.vds-code:has(.vds-code-static:focus-visible) {
  outline: none;
  box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
  @media (forced-colors: active) {
    outline: 2px solid Highlight;
    outline-offset: 2px;
    box-shadow: none;
  }
}

.vds-code .cm-scroller::-webkit-scrollbar {
  inline-size: 0.625rem;
  block-size: 0.625rem;
}
.vds-code .cm-scroller::-webkit-scrollbar-track {
  background: transparent;
}
.vds-code .cm-scroller::-webkit-scrollbar-thumb {
  background-color: var(--vds-code-scrollbar-thumb);
  border-radius: var(--vds-radius-full, 9999px);
  border: 2px solid transparent;
  background-clip: padding-box;
}
.vds-code .cm-scroller::-webkit-scrollbar-thumb:hover {
  background-color: var(--vds-code-scrollbar-thumb-hover);
}

.vds-code .cm-scroller {
  scrollbar-color: var(--vds-code-scrollbar-thumb) transparent;
  scrollbar-width: thin;
}

.vds-code-body[data-max-height] > div,
.vds-code-body[data-max-height] .cm-editor,
.vds-code-body[data-max-height] .cm-scroller { max-height: inherit; }

.vds-code-static { scrollbar-width: thin; scrollbar-color: var(--vds-code-scrollbar-thumb) transparent; }

@media (hover: hover) and (pointer: fine) {
  .vds-code-static, .vds-code .cm-scroller { scrollbar-color: transparent transparent; }
  .vds-code-static:hover, .vds-code-static:focus-visible,
  .vds-code .cm-scroller:hover, .vds-code .cm-scroller:focus-within {
    scrollbar-color: var(--vds-code-scrollbar-thumb) transparent;
  }
  .vds-code .cm-scroller:not(:hover):not(:focus-within)::-webkit-scrollbar-thumb { background-color: transparent; }
}

@media (forced-colors: active), (prefers-contrast: more) {
  .vds-code-static, .vds-code .cm-scroller { scrollbar-color: auto; }
}

/* RTL: diff marker accent */
[dir="rtl"] .vds-code .cm-line-diff-add,
[dir="rtl"] .vds-code .cm-line-diff-remove {
  box-shadow: inset -3px 0 0 0 var(--vds-code-diff-add-marker);
}
[dir="rtl"] .vds-code .cm-line-diff-remove {
  box-shadow: inset -3px 0 0 0 var(--vds-code-diff-remove-marker);
}
.vds-code .cm-line-diff-add {
  box-shadow: inset 3px 0 0 0 var(--vds-code-diff-add-marker);
}
.vds-code .cm-line-diff-remove {
  box-shadow: inset 3px 0 0 0 var(--vds-code-diff-remove-marker);
}

packages/react-code/src/Code.tokens.css:
@layer design-system.components {
  /* =========================================================================
   * 1. Structural tokens (root .vds-code)
   *    Layout, typography, motion. Orthogonal to syntax palette.
   *    Defaults resolve to: variant=card, size=md.
   *    Fallbacks keep the package usable without @virtari-packages/tokens.
   * ========================================================================= */
  .vds-code {
    /* ── Typography ── */
    --vds-code-font-family: var(--vds-font-mono, "JetBrains Mono", ui-monospace, "Cascadia Code", "Source Code Pro", monospace);
    --vds-code-font-size: var(--vds-text-sm, 0.875rem);
    --vds-code-line-height: 1.6;
    --vds-code-letter-spacing: 0;

    /* ── Layout ── */
    --vds-code-padding-block: var(--vds-space-3, 0.75rem);
    --vds-code-padding-inline: var(--vds-space-4, 1rem);
    --vds-code-radius: var(--vds-radius-code, 0.5rem);
    --vds-code-border-width: 1px;
    --vds-code-gutter-padding-inline: var(--vds-space-3, 0.75rem);

    /* ── Surfaces ── */
    --vds-code-bg: var(--vds-color-surface-container, var(--vds-color-bg-subtle, #f8f8f8));
    --vds-code-text: var(--vds-color-text, #171717);
    --vds-code-border: var(--vds-surface-border, var(--vds-color-border-subtle, #e5e5e5));
    --vds-code-shadow: var(--vds-surface-shadow, none);

    /* ── Header / chrome ── */
    --vds-code-header-bg: var(--vds-color-neutral-a2, #f3f3f3);
    --vds-code-header-text: var(--vds-color-text-muted, #525252);
    --vds-code-header-border: var(--vds-code-border);
    --vds-code-header-padding-block: var(--vds-space-2, 0.5rem);
    --vds-code-header-padding-inline: var(--vds-space-3, 0.75rem);

    /* ── Caption ── */
    --vds-code-caption-color: var(--vds-color-text-muted, #525252);
    --vds-code-caption-font-size: var(--vds-text-xs, 0.75rem);

    /* ── Gutter (line numbers) ── */
    --vds-code-gutter-bg: transparent;
    --vds-code-gutter-text: var(--vds-color-text-muted, #525252);
    --vds-code-gutter-active-bg: transparent;
    --vds-code-gutter-active-text: var(--vds-color-text, #171717);

    /* ── Line states ── */
    --vds-code-line-active-bg: var(--vds-color-surface-hover, color-mix(in oklch, var(--vds-code-bg) 70%, currentColor 6%));
    --vds-code-line-highlight-bg: var(--vds-color-primary-bg, color-mix(in oklch, var(--vds-code-bg) 80%, var(--vds-color-primary-solid, #4f46e5) 20%));

    /* ── Diff lines ── */
    --vds-code-diff-add-bg: var(--vds-color-success-bg, color-mix(in oklch, var(--vds-code-bg) 80%, var(--vds-color-success-solid, #16a34a) 20%));
    --vds-code-diff-add-text: var(--vds-color-success-text, var(--vds-code-text));
    --vds-code-diff-add-marker: var(--vds-color-success-solid, #16a34a);
    --vds-code-diff-remove-bg: var(--vds-color-danger-bg, color-mix(in oklch, var(--vds-code-bg) 80%, var(--vds-color-danger-solid, #dc2626) 20%));
    --vds-code-diff-remove-text: var(--vds-color-danger-text, var(--vds-code-text));
    --vds-code-diff-remove-marker: var(--vds-color-danger-solid, #dc2626);

    /* ── Selection / cursor ── */
    --vds-code-selection-bg: var(--vds-color-primary-bg, color-mix(in oklch, var(--vds-code-bg) 70%, var(--vds-color-primary-solid, #4f46e5) 30%));
    --vds-code-caret-color: var(--vds-color-primary-solid, #4f46e5);

    /* ── Focus ring ── */
    --vds-code-focus-ring-color: var(--vds-color-ring, var(--vds-color-primary-solid, #4f46e5));
    --vds-code-focus-ring-width: var(--vds-focus-ring-width, 2px);
    --vds-code-focus-ring-offset: var(--vds-focus-ring-offset, 2px);

    /* ── Motion ── */
    --vds-code-transition-duration: var(--vds-duration-fast, 120ms);
    --vds-code-transition-easing: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* ── Scrollbar ── */
    --vds-code-scrollbar-thumb: var(--vds-color-border-muted, #d4d4d4);
    --vds-code-scrollbar-thumb-hover: var(--vds-color-border-subtle, #a3a3a3);

    /* =====================================================================
     * 2. Syntax palette — mapped to readable semantic text roles.
     *    Theme scopes resolve their own foreground/background pairs.
     * ===================================================================== */
    --vds-code-token-keyword:     var(--vds-color-primary-text, #3730a3);
    --vds-code-token-control:     var(--vds-color-primary-text, #3730a3);
    --vds-code-token-string:      var(--vds-color-success-text, #166534);
    --vds-code-token-string-special: var(--vds-color-success-text, #166534);
    --vds-code-token-number:      var(--vds-color-warning-text, #78350f);
    --vds-code-token-bool:        var(--vds-color-warning-text, #78350f);
    --vds-code-token-null:        var(--vds-color-warning-text, #78350f);
    --vds-code-token-comment:     var(--vds-color-text-muted, #525252);
    --vds-code-token-doc:         var(--vds-color-text-muted, #525252);
    --vds-code-token-function:    var(--vds-color-info-text, #155e75);
    --vds-code-token-method:      var(--vds-color-info-text, #155e75);
    --vds-code-token-operator:    var(--vds-color-text-muted, #525252);
    --vds-code-token-punctuation: var(--vds-color-text-muted, #525252);
    --vds-code-token-bracket:     var(--vds-color-text-muted, #525252);
    --vds-code-token-tag:         var(--vds-color-danger-text, #991b1b);
    --vds-code-token-attribute:   var(--vds-color-warning-text, #78350f);
    --vds-code-token-attr-value:  var(--vds-color-success-text, #166534);
    --vds-code-token-regex:       var(--vds-color-accent-text, #7c2d12);
    --vds-code-token-escape:      var(--vds-color-accent-text, #7c2d12);
    --vds-code-token-variable:    var(--vds-color-text, #171717);
    --vds-code-token-property:    var(--vds-color-info-text, #155e75);
    --vds-code-token-type:        var(--vds-color-accent-text, #7c2d12);
    --vds-code-token-class:       var(--vds-color-accent-text, #7c2d12);
    --vds-code-token-namespace:   var(--vds-color-accent-text, #7c2d12);
    --vds-code-token-constant:    var(--vds-color-warning-text, #78350f);
    --vds-code-token-builtin:     var(--vds-color-info-text, #155e75);
    --vds-code-token-link:        var(--vds-color-text-link, var(--vds-color-primary-text, #3730a3));
    --vds-code-token-heading:     var(--vds-color-primary-text, #3730a3);
    --vds-code-token-emphasis-style: italic;
    --vds-code-token-strong-weight: var(--vds-font-weight-semibold, 600);
  }

  /* =========================================================================
   * 3. Variants — re-map chrome tokens.
   *    "card" is baked into the base above (border + bg + radius).
   * ========================================================================= */

  /* `0px`, not `0`: --vds-code-border-width and --vds-code-radius feed the
   * <length>-typed nesting channel (--vds-radius-host-b / -r), and a unitless
   * zero is a <number> there — invalid at computed-value time. */
  .vds-code[data-variant="minimal"] {
    --vds-code-shadow: none;
    --vds-code-bg: transparent;
    --vds-code-border-width: 0px;
    --vds-code-padding-block: 0px;
    --vds-code-padding-inline: 0px;
    --vds-code-header-bg: transparent;
    --vds-code-header-border: transparent;
  }

  .vds-code[data-variant="embedded"] {
    --vds-code-shadow: none;
    --vds-code-radius: 0px;
    --vds-code-border-width: 0px;
  }

  /* =========================================================================
   * 4. Sizes — adjust typography + padding proportionally.
   *    md is default (inherits base).
   * ========================================================================= */

  .vds-code[data-size="sm"] {
    --vds-code-font-size: var(--vds-text-xs, 0.75rem);
    --vds-code-line-height: 1.55;
    --vds-code-padding-block: var(--vds-space-2, 0.5rem);
    --vds-code-padding-inline: var(--vds-space-3, 0.75rem);
    --vds-code-gutter-padding-inline: var(--vds-space-2, 0.5rem);
    --vds-code-header-padding-block: var(--vds-space-1-5, 0.375rem);
  }

  .vds-code[data-size="lg"] {
    --vds-code-font-size: var(--vds-text-base, 1rem);
    --vds-code-line-height: 1.65;
    --vds-code-padding-block: var(--vds-space-4, 1rem);
    --vds-code-padding-inline: var(--vds-space-5, 1.25rem);
    --vds-code-gutter-padding-inline: var(--vds-space-4, 1rem);
    --vds-code-header-padding-block: var(--vds-space-3, 0.75rem);
    --vds-code-header-padding-inline: var(--vds-space-4, 1rem);
  }

  /* =========================================================================
   * 5. Inline code — distinct token set, sits inside prose.
   * ========================================================================= */

  .vds-code-inline {
    --vds-code-inline-font-family: var(--vds-font-mono, ui-monospace, "Cascadia Code", monospace);
    --vds-code-inline-font-size: 0.875em;
    --vds-code-inline-padding-block: 0.125em;
    --vds-code-inline-padding-inline: 0.375em;
    --vds-code-inline-radius: var(--vds-radius-code-inline, 0.25rem);
    --vds-code-inline-border-width: 1px;

    --vds-code-inline-bg: var(--vds-color-bg-muted, #f3f3f3);
    --vds-code-inline-text: var(--vds-color-text, #171717);
    --vds-code-inline-border: var(--vds-surface-border, var(--vds-color-border-subtle, #e5e5e5));
  }

  .vds-code-inline[data-color="primary"] {
    --vds-code-inline-bg: var(--vds-color-primary-bg, #e0e7ff);
    --vds-code-inline-text: var(--vds-color-primary-text, #3730a3);
    --vds-code-inline-border: transparent;
  }

  .vds-code-inline[data-color="accent"] {
    --vds-code-inline-bg: var(--vds-color-accent-bg, #ffedd5);
    --vds-code-inline-text: var(--vds-color-accent-text, #7c2d12);
    --vds-code-inline-border: transparent;
  }
}

