@import "./ColorPicker.tokens.css";

@layer design-system.components {
  .vds-color-picker {
    box-sizing: border-box;
    container-type: inline-size;
    display: grid;
    gap: var(--color-picker-gap);
    inline-size: min(100%, var(--color-picker-max-width));
    max-inline-size: 100%;
    min-inline-size: 0;
    padding: var(--color-picker-padding);
    border: 1px solid var(--color-picker-border);
    border-radius: var(--color-picker-radius);
    background: var(--color-picker-bg);
    color: var(--color-picker-text);
    font-family: var(--color-picker-font-family);
    font-size: var(--color-picker-text-size);
    line-height: 1.3;
  }

  .vds-color-picker,
  .vds-color-picker * {
    min-inline-size: 0;
    box-sizing: border-box;
  }

  .vds-color-picker[data-disabled="true"] {
    opacity: var(--vds-opacity-disabled, 0.5);
    pointer-events: none;
  }

  /* ── Header ────────────────────────────────────────────── */
  .vds-color-picker-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--color-picker-gap-xs);
  }

  .vds-color-picker-mode-strip {
    display: inline-flex;
    align-items: center;
    gap: 0.125rem;
    padding: var(--vds-space-1, 0.25rem);
    border-radius: var(--color-picker-panel-radius);
    background: var(--color-picker-sunken-bg);

    /* ── Radius nesting host ──
       A sunken segmented track: the mode buttons fill it and their corners have
       to follow its own. Publishes radius / border / padding — all three,
       zeroes included, so the strip cannot inherit the picker shell's border
       and padding and subtract the wrong distance. The buttons were pinned to
       --color-picker-field-radius, which happens to equal the concentric answer
       in round and pill mode and is 2px too round in soft and sharp. */
    --vds-radius-host-r: var(--color-picker-panel-radius);
    --vds-radius-host-b: 0px;
    --vds-radius-host-p: var(--vds-space-1, 0.25rem);
  }

  .vds-color-picker-header-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.125rem;
    margin-inline-start: auto;
  }

  /* ── Buttons (compact icon-first) ──────────────────────── */
  .vds-color-picker-button.vds-button,
  .vds-color-picker-text-button.vds-button {
    --button-height: var(--color-picker-control-height);
    --button-padding-inline: var(--vds-space-2, 0.5rem);
    --button-radius: var(--color-picker-field-radius);
    --button-gap: 0.25rem;
    --button-font-size: var(--color-picker-text-size);
    --button-focus-ring-color: var(--color-picker-focus);
    box-shadow: none;
  }

  .vds-color-picker-button--icon.vds-button {
    --button-padding-inline: 0;
    inline-size: var(--color-picker-control-height);
    block-size: var(--color-picker-control-height);
    aspect-ratio: 1;
  }

  .vds-color-picker-button svg,
  .vds-color-picker-text-button svg {
    inline-size: var(--color-picker-icon-size);
    block-size: var(--color-picker-icon-size);
  }

  .vds-color-picker-mode-button.vds-button,
  .vds-color-picker-header-button.vds-button,
  .vds-color-picker-stop-add.vds-button,
  .vds-color-picker-stop-row-action.vds-button {
    --button-color-ghost: var(--color-picker-text-muted);
    --button-color-ghost-hover: var(--color-picker-text);
    --button-bg-soft: var(--color-picker-row-bg);
    --button-color-soft: var(--color-picker-text);
    --button-bg-soft-hover: var(--color-picker-row-bg-hover);
  }

  /* Concentric with the mode strip — see the host block above. Must come after
     the --button-radius declaration in .vds-color-picker-button.vds-button:
     both selectors are (0,2,0), so source order decides. Matched on
     `> .vds-button` rather than a modifier class because PickerButton emits
     .vds-color-picker-button, not a strip-specific one. */
  .vds-color-picker-mode-strip > .vds-button {
    --button-radius: var(--vds-radius-inset);
  }

  /* ── Solid editor ──────────────────────────────────────── */
  .vds-color-picker-solid-editor {
    display: grid;
    gap: var(--color-picker-gap-sm);
  }

  /* ── Gradient topbar (Linear select + actions) ────────── */
  .vds-color-picker-gradient-section {
    display: grid;
    gap: var(--color-picker-gap-sm);
  }

  .vds-color-picker-gradient-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--color-picker-gap-xs);
  }

  .vds-color-picker-gradient-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.125rem;
  }

  .vds-color-picker-select-trigger.vds-select-trigger,
  .vds-color-picker-format-select.vds-select-trigger {
    --select-trigger-height: var(--color-picker-control-height);
    --select-trigger-padding-inline: 0.5rem;
    --select-trigger-font-size: var(--color-picker-text-size);
    --select-trigger-radius: var(--color-picker-field-radius);
    --select-trigger-border-color: transparent;
    --select-trigger-border-color-hover: var(--color-picker-border);
    --select-trigger-bg: var(--color-picker-row-bg);
    --select-trigger-bg-hover: var(--color-picker-row-bg-hover);
    --select-trigger-focus-ring-color: var(--color-picker-focus);
    color: var(--color-picker-text);
    min-inline-size: 5rem;
  }

  .vds-color-picker-select-trigger.vds-select-trigger {
    inline-size: auto;
  }

  /* ── Saturation square ──────────────────────────────────── */
  .vds-color-picker-saturation {
    position: relative;
    inline-size: 100%;
    block-size: var(--color-picker-saturation-block);
    border-radius: var(--color-picker-panel-radius);
    overflow: hidden;
    cursor: crosshair;
    background:
      linear-gradient(180deg, transparent, #000),
      linear-gradient(90deg, #fff, transparent),
      hsl(var(--color-picker-hue, 0deg) 100% 50%);
    touch-action: none;
  }

  .vds-color-picker-solid-editor--compact .vds-color-picker-saturation {
    block-size: calc(var(--color-picker-saturation-block) - 2rem);
  }

  .vds-color-picker-saturation-thumb {
    position: absolute;
    inline-size: var(--color-picker-thumb-size);
    block-size: var(--color-picker-thumb-size);
    border-radius: 9999px;
    border: 2px solid #fff;
    box-shadow:
      0 0 0 1px rgba(0, 0, 0, 0.45),
      0 1px 3px rgba(0, 0, 0, 0.35);
    transform: translate(-50%, -50%);
    pointer-events: none;
  }

  /* ── Slider rows (hue + alpha) ─────────────────────────── */
  .vds-color-picker-slider-stack {
    display: grid;
    gap: var(--color-picker-gap-xs);
  }

  .vds-color-picker-slider-row {
    display: flex;
    align-items: center;
    gap: var(--color-picker-gap-sm);
  }

  .vds-color-picker-slider-action.vds-button {
    --button-height: var(--color-picker-control-height-lg);
    --button-padding-inline: 0;
    --button-color-ghost: var(--color-picker-text-muted);
    --button-color-ghost-hover: var(--color-picker-text);
    inline-size: var(--color-picker-control-height-lg);
    block-size: var(--color-picker-control-height-lg);
    aspect-ratio: 1;
    flex: 0 0 auto;
  }

  .vds-color-picker-slider-action svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

  .vds-color-picker-slider-spacer {
    inline-size: var(--color-picker-control-height-lg);
    flex: 0 0 var(--color-picker-control-height-lg);
    block-size: 1px;
  }

  .vds-color-picker-slider {
    position: relative;
    flex: 1 1 auto;
    block-size: var(--color-picker-slider-height);
    border-radius: 9999px;
    cursor: pointer;
    overflow: visible;
    touch-action: none;
    background-color: transparent;
  }

  /* Alpha-only: the slider needs a checkered pattern *behind* the
     RGB→opaque gradient so transparency is visible. The hue slider
     is fully opaque, so it doesn't need it. */
  .vds-color-picker-slider--alpha {
    background-color: #ffffff;
    background-image:
      linear-gradient(45deg, rgba(0, 0, 0, 0.55) 25%, transparent 25%),
      linear-gradient(-45deg, rgba(0, 0, 0, 0.55) 25%, transparent 25%),
      linear-gradient(45deg, transparent 75%, rgba(0, 0, 0, 0.55) 75%),
      linear-gradient(-45deg, transparent 75%, rgba(0, 0, 0, 0.55) 75%);
    background-size:
      var(--color-picker-grid-cell) var(--color-picker-grid-cell);
    background-position:
      0 0,
      0 calc(var(--color-picker-grid-cell) / 2),
      calc(var(--color-picker-grid-cell) / 2) calc(var(--color-picker-grid-cell) / -2),
      calc(var(--color-picker-grid-cell) / -2) 0;
  }

  .vds-color-picker-slider-track {
    position: absolute;
    inset: 0;
    border-radius: inherit;
  }

  .vds-color-picker-slider-thumb {
    position: absolute;
    inset-block-start: 50%;
    inline-size: var(--color-picker-thumb-size);
    block-size: var(--color-picker-thumb-size);
    border-radius: 9999px;
    border: 2px solid #fff;
    box-shadow:
      0 0 0 1px rgba(0, 0, 0, 0.45),
      0 1px 3px rgba(0, 0, 0, 0.35);
    background: transparent;
    transform: translate(-50%, -50%);
    pointer-events: none;
  }

  /* ── Gradient track + stops (BIG preview bar) ─────────── */
  .vds-color-picker-gradient-track {
    position: relative;
    block-size: var(--color-picker-gradient-track-block, 3.25rem);
    margin-block-start: 0.5rem;
    border-radius: var(--color-picker-field-radius);
    cursor: copy;
    background-color: var(--color-picker-sunken-bg);
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
    touch-action: none;
  }

  .vds-color-picker-stop {
    --color-picker-stop-color: #ffffff;
    position: absolute;
    inset-block-start: -0.4rem;
    inline-size: var(--color-picker-stop-size);
    block-size: calc(var(--color-picker-stop-size) + 0.4rem);
    padding: 0;
    border: none;
    background: transparent;
    transform: translateX(-50%);
    cursor: grab;
  }

  .vds-color-picker-stop-swatch {
    position: absolute;
    inset-inline-start: 0;
    inset-block-start: 0;
    inline-size: var(--color-picker-stop-size);
    block-size: var(--color-picker-stop-size);
    /* Chip family — see .vds-color-picker-swatch. */
    border-radius: var(--vds-radius-xs, 0.25rem);
    border: 2px solid #fff;
    background: var(--color-picker-stop-color);
    box-shadow:
      0 0 0 1px rgba(0, 0, 0, 0.45),
      0 1px 3px rgba(0, 0, 0, 0.3);
  }

  .vds-color-picker-stop::after {
    content: "";
    position: absolute;
    inset-inline-start: 50%;
    inset-block-start: var(--color-picker-stop-size);
    inline-size: 0.125rem;
    block-size: 0.4rem;
    background: rgba(255, 255, 255, 0.6);
    transform: translateX(-50%);
  }

  .vds-color-picker-stop[data-active="true"] .vds-color-picker-stop-swatch {
    border-color: var(--color-picker-accent);
    box-shadow:
      0 0 0 1px var(--color-picker-accent),
      0 0 0 3px color-mix(in oklch, var(--color-picker-accent) 30%, transparent);
  }

  /* ── Stops list ───────────────────────────────────────── */
  .vds-color-picker-stop-list {
    display: grid;
    gap: 0.25rem;
  }

  .vds-color-picker-stop-list-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-inline: 0.125rem;
    color: var(--color-picker-text-muted);
    font-size: var(--color-picker-label-size);
    font-weight: 500;
  }

  .vds-color-picker-stop-row {
    position: relative;
    display: grid;
    grid-template-columns: 0.875rem minmax(2.5rem, 0.6fr) minmax(0, 1fr) minmax(2.5rem, 0.5fr) var(--color-picker-control-height);
    align-items: center;
    gap: 0.25rem;
    padding: 0.125rem;
    padding-inline-start: 0.125rem;
    border-radius: var(--color-picker-field-radius);
    background: var(--color-picker-row-bg);
    border: 1px solid transparent;
    cursor: pointer;
    transition:
      background-color var(--color-picker-transition),
      border-color var(--color-picker-transition),
      opacity var(--color-picker-transition);
  }

  .vds-color-picker-stop-row:hover {
    background: var(--color-picker-row-bg-hover);
  }

  .vds-color-picker-stop-row[data-active="true"] {
    background: var(--color-picker-row-bg-active);
    border-color: color-mix(in oklch, var(--color-picker-accent) 50%, transparent);
  }

  /* Dragging state — fade the source row so the user knows it's "lifted". */
  .vds-color-picker-stop-row[data-dragging="true"] {
    opacity: 0.4;
    cursor: grabbing;
  }

  /* Drop indicator — a 2px accent line above or below the hovered target. */
  .vds-color-picker-stop-row[data-drop-target]::before {
    content: "";
    position: absolute;
    inset-inline: 0;
    block-size: 2px;
    background: var(--color-picker-accent);
    border-radius: 9999px;
    pointer-events: none;
  }
  .vds-color-picker-stop-row[data-drop-target="before"]::before {
    inset-block-start: -2px;
  }
  .vds-color-picker-stop-row[data-drop-target="after"]::before {
    inset-block-end: -2px;
  }

  /* Grip handle — invisible until row hover, full opacity on hover/focus.
   * The button is sized as a column cell so DOM clicks target it precisely. */
  .vds-color-picker-stop-grip {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    block-size: var(--color-picker-control-height);
    padding: 0;
    background: transparent;
    border: 0;
    color: var(--color-picker-text-subtle);
    cursor: grab;
    opacity: 0;
    transition:
      opacity var(--color-picker-transition),
      color var(--color-picker-transition);
  }

  .vds-color-picker-stop-row:hover .vds-color-picker-stop-grip,
  .vds-color-picker-stop-row[data-active="true"] .vds-color-picker-stop-grip,
  .vds-color-picker-stop-grip:focus-visible {
    opacity: 1;
  }

  .vds-color-picker-stop-grip:hover {
    color: var(--color-picker-text);
  }

  .vds-color-picker-stop-grip:active {
    cursor: grabbing;
  }

  .vds-color-picker-stop-grip:disabled {
    cursor: not-allowed;
    opacity: 0;
  }

  .vds-color-picker-stop-cell {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .vds-color-picker-stop-cell-suffix {
    margin-inline-start: 0.125rem;
    color: var(--color-picker-text-muted);
    font-size: var(--color-picker-label-size);
  }

  .vds-color-picker-stop-hex {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding-inline-start: 0.125rem;
  }

  .vds-color-picker-stop-color-chip {
    flex: 0 0 auto;
    inline-size: 1rem;
    block-size: 1rem;
    padding: 0;
    border-radius: var(--vds-radius-xs, 0.25rem);
    border: 1px solid rgba(255, 255, 255, 0.15);
    cursor: pointer;
    transition:
      transform var(--color-picker-transition),
      border-color var(--color-picker-transition),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-color-picker-stop-color-chip:hover:not(:disabled) {
    transform: scale(1.08);
    border-color: rgba(255, 255, 255, 0.4);
  }

  .vds-color-picker-stop-color-chip:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-color-picker-stop-color-chip[data-state="open"] {
    border-color: var(--color-picker-accent);
  }

  .vds-color-picker-stop-hex-input.vds-input {
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .vds-color-picker-stop-row-action.vds-button {
    --button-height: calc(var(--color-picker-control-height) - 0.125rem);
    inline-size: calc(var(--color-picker-control-height) - 0.125rem);
    block-size: calc(var(--color-picker-control-height) - 0.125rem);
    justify-self: end;
  }

  /* ── Inputs (use real Input component, override sizing) ── */
  .vds-color-picker .vds-input {
    --input-height: var(--color-picker-control-height);
    --input-padding-inline: var(--vds-space-1-5, 0.375rem);
    --input-padding-block: 0;
    --input-font-size: var(--color-picker-text-size);
    --input-radius: var(--color-picker-field-radius);
    border-color: transparent;
    background-color: var(--color-picker-row-bg);
    color: var(--color-picker-text);
    font-family: var(--color-picker-mono-family);
    text-align: center;
    transition: box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-color-picker .vds-input:hover:not(:disabled) {
    background-color: var(--color-picker-row-bg-hover);
  }

  .vds-color-picker .vds-input:focus-visible {
    border-color: var(--color-picker-focus);
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-color-picker .vds-textarea {
    border-color: transparent;
    background-color: var(--color-picker-row-bg);
    color: var(--color-picker-text);
  }

  /* ── Inline angle / center input ───────────────────────── */
  .vds-color-picker-inline-chip {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
    block-size: var(--color-picker-control-height-lg);
    padding-inline: 0.375rem;
    border-radius: var(--color-picker-field-radius);
    background: var(--color-picker-row-bg);
  }

  .vds-color-picker-inline-chip:hover {
    background: var(--color-picker-row-bg-hover);
  }

  .vds-color-picker-inline-chip .vds-input {
    --input-height: 1.25rem;
    --input-padding-inline: 0;
    background: transparent;
    inline-size: 2.25rem;
    text-align: center;
    border: none;
  }

  .vds-color-picker-inline-chip .vds-input:hover:not(:disabled),
  .vds-color-picker-inline-chip .vds-input:focus-visible {
    background: transparent;
    box-shadow: none;
  }

  .vds-color-picker-inline-label,
  .vds-color-picker-inline-unit {
    color: var(--color-picker-text-muted);
    font-size: var(--color-picker-label-size);
  }

  /* ── Format/value bar (HSL · 0 · 0 · 85 · 100%) ────────── */
  .vds-color-picker-value-bar {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding: var(--vds-space-1, 0.25rem);
    border-radius: var(--color-picker-field-radius);
    background: var(--color-picker-sunken-bg);
  }

  .vds-color-picker-format-select.vds-select-trigger {
    --select-trigger-height: calc(var(--color-picker-control-height-lg) - 0.25rem);
    --select-trigger-bg: transparent;
    --select-trigger-bg-hover: var(--color-picker-row-bg-hover);
    --select-trigger-padding-inline: 0.375rem;
    flex: 0 0 auto;
    min-inline-size: 3.5rem;
    inline-size: auto;
  }

  .vds-color-picker-value-fields {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    flex: 1 1 auto;
    gap: 0.125rem;
    align-items: center;
  }

  .vds-color-picker-value-field {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .vds-color-picker-value-field[data-wide="true"] {
    grid-column: span 3;
  }

  .vds-color-picker-field-input-wrap {
    position: relative;
    display: flex;
    align-items: center;
    inline-size: 100%;
  }

  .vds-color-picker-field-prefix,
  .vds-color-picker-field-unit {
    position: absolute;
    color: var(--color-picker-text-muted);
    font-size: var(--color-picker-label-size);
    pointer-events: none;
  }

  .vds-color-picker-field-prefix {
    inset-inline-start: 0.375rem;
  }

  .vds-color-picker-field-unit {
    inset-inline-end: 0.375rem;
  }

  /* The prefix ("#") and unit ("%") glyphs are absolutely positioned over the
   * Input, so the text needs to clear them on one side only. react-input has a
   * single symmetric `--input-padding-inline` hook, so this reserves the space
   * with a direct declaration. Once react-input exposes
   * `--input-padding-inline-start` / `-end`, set those instead. */
  .vds-color-picker-field-input-wrap[data-has-prefix="true"] .vds-input {
    padding-inline-start: var(--vds-space-4, 1rem);
    text-align: start;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .vds-color-picker-field-input-wrap:has(.vds-color-picker-field-unit) .vds-input {
    padding-inline-end: var(--vds-space-4, 1rem);
  }

  .vds-color-picker-value-input.vds-input {
    background: transparent;
  }

  .vds-color-picker-value-input.vds-input:hover:not(:disabled) {
    background: var(--color-picker-row-bg-hover);
  }

  /* ── Swatches ──────────────────────────────────────────── */
  .vds-color-picker-swatches {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(var(--color-picker-swatch-size), 1fr));
    gap: 0.25rem;
  }

  .vds-color-picker-swatch {
    aspect-ratio: 1;
    min-block-size: var(--color-picker-swatch-size);
    border: 1px solid rgba(255, 255, 255, 0.15);
    /* Same chip family as .vds-color-picker-stop-color-chip, which already
       reads this token. The literal 0.25rem here was mode-invariant, so the
       swatch grid stayed at 4px while every other corner in the picker moved
       with `data-radius`. */
    border-radius: var(--vds-radius-xs, 0.25rem);
    background-color: transparent;
    cursor: pointer;
    transition:
      transform var(--color-picker-transition),
      border-color var(--color-picker-transition);
  }

  .vds-color-picker-swatch:hover:not(:disabled) {
    transform: scale(1.06);
    border-color: var(--color-picker-accent);
  }

  /* ── Code mode ────────────────────────────────────────── */
  .vds-color-picker-code-panel {
    display: grid;
    gap: var(--color-picker-gap-xs);
    padding: var(--color-picker-gap-sm);
    border-radius: var(--color-picker-panel-radius);
    background: var(--color-picker-sunken-bg);
  }

  .vds-color-picker-code-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--color-picker-gap-xs);
  }

  .vds-color-picker-code-header > span {
    color: var(--color-picker-text-muted);
    font-size: var(--color-picker-label-size);
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  .vds-color-picker-code-actions {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
  }

  .vds-color-picker-code-input.vds-textarea {
    min-block-size: 4.5rem;
    padding: 0.5rem;
    resize: vertical;
    font-family: var(--color-picker-mono-family);
    font-size: var(--color-picker-text-size);
    line-height: 1.45;
  }

  .vds-color-picker-code-error {
    color: var(--color-picker-danger);
    font-size: var(--color-picker-label-size);
  }

  /* ── Floating popover (per-stop solid editor) ─────────── */
  .vds-popover-content.vds-color-picker-popover {
    inline-size: var(--color-picker-max-width, 17.5rem);
    min-inline-size: 0;
    max-inline-size: 92vw;
    padding: var(--color-picker-padding);
    background: var(--color-picker-bg);
    border: 1px solid var(--color-picker-border);
    border-radius: var(--color-picker-radius);
    color: var(--color-picker-text);
    font-family: var(--color-picker-font-family);
    font-size: var(--color-picker-text-size);
    line-height: 1.3;
    box-shadow: var(--color-picker-shadow);
  }

  .vds-color-picker-popover .vds-color-picker-solid-editor {
    gap: var(--color-picker-gap-sm);
  }

  /* ── Focus / a11y ─────────────────────────────────────── */
  .vds-color-picker-slider,
  .vds-color-picker-saturation,
  .vds-color-picker-stop,
  .vds-color-picker-swatch{
    transition: box-shadow 180ms ease-out;

    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-color-picker-slider:focus-visible,
  .vds-color-picker-saturation:focus-visible,
  .vds-color-picker-stop:focus-visible,
  .vds-color-picker-swatch:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-color-picker-slider[data-disabled="true"],
  .vds-color-picker-saturation[data-disabled="true"] {
    cursor: not-allowed;
  }

  .vds-color-picker-sr-only {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  /* ── Appearance: floating ──
   * Soft elevation when the picker pops out (Popover/Dialog). Border kept
   * for definition on busy backgrounds; shadow does the lifting. */
  .vds-color-picker[data-appearance="floating"] {
    box-shadow: var(--color-picker-shadow);
  }

  /* ── Appearance: flat ──
   * Removes chrome so the picker sits flush inside its parent surface.
   * Padding goes to zero so the parent owns the spacing decision. */
  .vds-color-picker[data-appearance="flat"] {
    border-color: transparent;
    padding: 0;
    background: transparent;
  }

  /* ── Code-mode preview swatch ──
   * Replaces the editor surface when the user opens code mode so they keep a
   * visual reference for the value they are editing. Background is set inline
   * to the live cssValue, falls back to a checker pattern when transparent. */
  .vds-color-picker-code-preview {
    block-size: var(--color-picker-code-preview-height);
    border-radius: var(--color-picker-panel-radius);
    border: 1px solid var(--color-picker-border);
    background-color: var(--color-picker-row-bg);
    background-image:
      linear-gradient(45deg, var(--color-picker-row-bg-hover) 25%, transparent 25%),
      linear-gradient(-45deg, var(--color-picker-row-bg-hover) 25%, transparent 25%),
      linear-gradient(45deg, transparent 75%, var(--color-picker-row-bg-hover) 75%),
      linear-gradient(-45deg, transparent 75%, var(--color-picker-row-bg-hover) 75%);
    background-size: 0.625rem 0.625rem;
    background-position: 0 0, 0 0.3125rem, 0.3125rem -0.3125rem, -0.3125rem 0;
  }

  /* The inline `style="background: …"` from React covers the checker layer
   * once the user has a real (opaque) value. Stack order puts the live value
   * on top via background-color which has higher precedence than the layered
   * background-image of the checker. */
  .vds-color-picker-code-preview[style] {
    background-image: var(--_live-bg, none);
  }

  /* ── Stop add/remove animation ──
   * Used on every freshly-mounted stop row in the list and on every newly
   * added stop handle on the gradient track. @starting-style runs the keyframe
   * once on mount only — no manual onMount logic needed. */
  @supports (transition-behavior: allow-discrete) {
    .vds-color-picker-stop-row {
      transition:
        background-color var(--color-picker-transition),
      border-color var(--color-picker-transition),
      opacity 160ms var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1)),
      transform 160ms var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
    }

    @starting-style {
      .vds-color-picker-stop-row {
        opacity: 0;
        transform: translateY(-4px);
      }

      .vds-color-picker-stop {
        opacity: 0;
        transform: translateX(-50%) scale(0.6);
      }
    }
  }

  .vds-color-picker-stop {
    transition:
      transform 140ms var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1)),
      opacity 140ms var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  .vds-color-picker-stop:active {
    cursor: grabbing;
  }

  /* ── Stop add/remove buttons ──
   * Slightly more refined hover + active feedback than the generic ghost
   * button so the +/− affordance reads quickly in the dense gradient panel. */
  .vds-color-picker-stop-add.vds-button,
  .vds-color-picker-stop-row-action.vds-button {
    transition:
      background-color var(--color-picker-transition),
      color var(--color-picker-transition),
      transform 90ms var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  .vds-color-picker-stop-add.vds-button:hover:not(:disabled),
  .vds-color-picker-stop-row-action.vds-button:hover:not(:disabled) {
    background-color: var(--color-picker-row-bg-hover);
    color: var(--color-picker-text);
  }

  .vds-color-picker-stop-add.vds-button:active:not(:disabled),
  .vds-color-picker-stop-row-action.vds-button:active:not(:disabled) {
    transform: scale(0.92);
  }

  .vds-color-picker-stop-row-action.vds-button:disabled {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
  }
}

@layer design-system.components {
  .vds-color-picker-inline-chip { transition: box-shadow 180ms ease-out; }
  .vds-color-picker-inline-chip:focus-within { outline: none; box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2); }
  @media (prefers-reduced-motion: reduce) { .vds-color-picker-inline-chip { transition-duration: 0s; } }
  @media (forced-colors: active) { .vds-color-picker-inline-chip:focus-within { outline: 2px solid Highlight; outline-offset: 2px; box-shadow: none; } }
}

@layer design-system.components {
  .vds-color-picker {
    /* — Layout — */
    --color-picker-width: 100%;
    --color-picker-max-width: 17.5rem;
    --color-picker-padding: var(--vds-space-3, 0.75rem);
    --color-picker-gap: var(--vds-space-2-5, 0.625rem);
    --color-picker-gap-sm: var(--vds-space-2, 0.5rem);
    --color-picker-gap-xs: var(--vds-space-1-5, 0.375rem);

    /* — Surfaces / borders —
     * Light-mode-friendly defaults. The semantic tokens (--vds-color-surface,
     * --vds-color-bg-subtle, etc.) flip automatically in dark mode via the
     * global [data-theme="dark"] selector, so we don't duplicate values here. */
    --color-picker-radius: var(--vds-radius-color-picker, 0.75rem);
    --color-picker-panel-radius: var(--vds-radius-color-picker-panel, 0.5rem);
    --color-picker-field-radius: var(--vds-radius-color-picker-field, 0.375rem);
    --color-picker-border: var(--vds-surface-border, var(--vds-color-border-subtle, var(--vds-color-border, #e5e7eb)));
    --color-picker-border-strong: var(--vds-color-border, #d1d5db);
    --color-picker-bg: var(--vds-surface-bg, var(--vds-color-surface, #ffffff));
    --color-picker-panel-bg: var(--vds-color-bg-subtle, #f5f5f5);
    --color-picker-sunken-bg: var(--vds-color-bg-muted, #ebebeb);
    --color-picker-row-bg: var(--vds-color-bg-subtle, #f5f5f5);
    --color-picker-row-bg-hover: var(--vds-color-surface-hover, var(--vds-color-bg-muted, #ebebeb));
    --color-picker-row-bg-active: color-mix(
      in oklch,
      var(--vds-color-primary-bg, #e0e7ff) 80%,
      var(--vds-color-surface, #ffffff)
    );

    /* — Shadow (used by floating appearance) — */
    --color-picker-shadow: var(--vds-overlay-shadow, var(--vds-shadow-lg, 0 16px 40px -8px var(--vds-color-shadow-tint, rgba(15, 23, 42, 0.18))));

    /* — Text / accent — */
    --color-picker-text: var(--vds-color-text, #171717);
    --color-picker-text-muted: var(--vds-color-text-muted, #525252);
    --color-picker-text-subtle: var(--vds-color-text-subtle, #a3a3a3);
    --color-picker-accent: var(--vds-color-primary-solid, #4f46e5);
    --color-picker-accent-bg: color-mix(
      in oklch,
      var(--vds-color-primary-solid, #4f46e5) 16%,
      transparent
    );
    --color-picker-accent-text: var(--vds-color-on-primary, #ffffff);
    --color-picker-focus: var(--vds-color-ring, var(--vds-color-primary-solid, #4f46e5));
    --color-picker-danger: var(--vds-color-danger-solid, #dc2626);

    /* — Typography / motion — */
    --color-picker-font-family: var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    --color-picker-mono-family: var(--vds-font-mono, ui-monospace, monospace);
    --color-picker-text-size: var(--vds-text-xs, 0.75rem);
    --color-picker-label-size: 0.6875rem;
    --color-picker-transition: var(--vds-duration-fast, 120ms)
      var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* — Control sizing (compact) —
     * 1.5rem matches the design-system Input "xs" preset so format Select,
     * HexField, NumberField, and add/remove buttons share one height. */
    --color-picker-control-height: 1.5rem;
    --color-picker-control-height-lg: 1.75rem;
    --color-picker-icon-size: 1rem;
    --color-picker-slider-height: 0.625rem;
    --color-picker-thumb-size: 0.875rem;
    --color-picker-stop-size: 0.875rem;
    --color-picker-grid-cell: 0.5rem;
    --color-picker-swatch-size: 1.25rem;
    --color-picker-saturation-block: 9.5rem;
    --color-picker-code-preview-height: 3.5rem;
  }

  /* ── Appearance: floating ──
   * Solid surface + soft elevation. Use when the picker pops out (e.g. inside
   * a Popover/Dialog). The shadow is subtle so it works on both light and dark. */
  .vds-color-picker[data-appearance="floating"] {
    --color-picker-bg: var(--vds-color-surface-overlay, var(--vds-color-surface, #ffffff));
    --color-picker-border: var(--vds-color-border, #d1d5db);
  }

  /* ── Appearance: flat ──
   * No background, no border, no padding — drops cleanly into a parent that
   * already supplies its own surface (e.g. a Card body). */
  .vds-color-picker[data-appearance="flat"] {
    --color-picker-bg: transparent;
    --color-picker-border: transparent;
  }
}

