@import "./CopyButton.tokens.css";

@layer design-system.components {
  .vds-copy-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    --_copy-btn-min-size: max(1.5rem, calc(max(var(--_copy-btn-icon-size), var(--_copy-btn-font-size) * 1.4) + var(--_copy-btn-padding) * 2));
    min-inline-size: var(--_copy-btn-min-size);
    min-block-size: var(--_copy-btn-min-size);
    line-height: 1.4;
    gap: var(--_copy-btn-gap);
    padding: var(--_copy-btn-padding);
    border-radius: var(--_copy-btn-radius);
    border: none;
    background: transparent;
    color: var(--vds-color-text-muted);
    font-size: var(--_copy-btn-font-size);
    font-family: var(--vds-font-sans);
    cursor: pointer;
    transition:
      color var(--vds-duration-fast) var(--vds-ease-out),
      background-color var(--vds-duration-fast) var(--vds-ease-out);

    &:focus-visible {
      outline: 2px solid var(--vds-color-ring);
      outline-offset: 1px;
    }

    &:disabled {
      opacity: var(--vds-opacity-disabled, 0.5);
      cursor: not-allowed;
    }

    /* ── Variants ── */

    &[data-variant="ghost"] {
      &:hover:not(:disabled) {
        background-color: var(--vds-color-surface-hover);
        color: var(--vds-color-text);
      }
      &:active:not(:disabled) {
        background-color: var(--vds-color-surface-active);
      }
    }

    &[data-variant="outline"] {
      border: 1px solid var(--vds-color-border);
      &:hover:not(:disabled) {
        background-color: var(--vds-color-surface-hover);
        color: var(--vds-color-text);
      }
    }

    &[data-variant="soft"] {
      background-color: var(--vds-color-bg-muted);
      color: var(--vds-color-text);
      &:hover:not(:disabled) {
        background-color: var(--vds-color-surface-active);
      }
    }

    /* ── Copied state ── */

    &[data-copied] {
      color: var(--vds-color-success-text);
    }
    &[data-error] { color: var(--vds-color-danger-text); }
  }

  .vds-copy-button__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--_copy-btn-icon-size);
    block-size: var(--_copy-btn-icon-size);
    flex-shrink: 0;

    & > svg {
      inline-size: 100%;
      block-size: 100%;
    }
  }

  .vds-copy-button__label {
    line-height: inherit;
    min-inline-size: 0;
    overflow-wrap: anywhere;
  }
  .vds-copy-button__status {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
  @media (prefers-reduced-motion: reduce) { .vds-copy-button { transition: none; } }
}

@layer design-system.components {
  /* The default size is `sm`, not `md` — a copy button is an affordance
   * riding on someone else's surface (a code block header, a table cell), so
   * it sizes below the surrounding control. The base block below therefore
   * restates `sm`; there is deliberately no `[data-size="sm"]` block. */
  .vds-copy-button {
    --_copy-btn-padding:   var(--vds-space-1-5);
    --_copy-btn-icon-size: 1rem;
    --_copy-btn-font-size: var(--vds-text-sm);
    --_copy-btn-radius:    var(--vds-radius-copy-button, var(--vds-radius-element));
    --_copy-btn-gap:       var(--vds-space-1-5);

    &[data-size="2xs"] {
      --_copy-btn-padding:   var(--vds-space-0-5);
      --_copy-btn-icon-size: 0.75rem;
      --_copy-btn-font-size: var(--vds-text-xs);
    }

    &[data-size="xs"] {
      --_copy-btn-padding:   var(--vds-space-1);
      --_copy-btn-icon-size: 0.875rem;
      --_copy-btn-font-size: var(--vds-text-xs);
    }

    &[data-size="md"] {
      --_copy-btn-padding:   var(--vds-space-2);
      --_copy-btn-icon-size: 1.125rem;
      --_copy-btn-font-size: var(--vds-text-base);
    }

    &[data-size="lg"] {
      --_copy-btn-padding:   var(--vds-space-2-5);
      --_copy-btn-icon-size: 1.25rem;
      --_copy-btn-font-size: var(--vds-text-lg);
    }
  }
}

import { cn } from "@virtari-packages/utils";
import { forwardRef, useEffect, useRef, useState } from "react";
import type { Ref } from "react";
import { IconCheck, IconCopy } from "@virtari-packages/react-icons";

export type CopyButtonVariant = "ghost" | "outline" | "soft";
export type CopyButtonSize = "2xs" | "xs" | "sm" | "md" | "lg";

export interface CopyButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  /** Text to copy to the clipboard. */
  text: string;
  /** How long the "copied" state lasts in ms. */
  feedbackMs?: number;
  variant?: CopyButtonVariant;
  copyButtonSize?: CopyButtonSize;
  /** Optional visible label next to the icon. */
  label?: string;
  /** Label shown while in the "copied" state. */
  copiedLabel?: string;
  /** Accessible idle label when no visible label is supplied. */
  copyLabel?: string;
  /** Visible/announced feedback when clipboard access fails. */
  errorLabel?: string;
  onCopied?: () => void;
  onCopyError?: (error: unknown) => void;
  ref?: Ref<HTMLButtonElement>;
}

export const CopyButton = forwardRef<HTMLButtonElement, CopyButtonProps>(function CopyButton({
  text,
  feedbackMs = 2000,
  variant = "ghost",
  copyButtonSize = "sm",
  label,
  copiedLabel = "Copied",
  copyLabel = "Copy to clipboard",
  errorLabel = "Copy failed; select and copy the text manually",
  onCopied,
  onCopyError,
  onClick,
  disabled,
  className,
  ref: suppliedRef,
  ...props
}: CopyButtonProps, forwardedRef) {
  const [status, setStatus] = useState<"idle" | "copied" | "error">("idle");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const request = useRef(0);
  useEffect(() => {
    setStatus("idle");
    return () => { request.current++; clearTimeout(timer.current); };
  }, [text]);
  const handleCopy = async (event: React.MouseEvent<HTMLButtonElement>) => {
    onClick?.(event);
    if (event.defaultPrevented || disabled) return;
    clearTimeout(timer.current);
    const currentRequest = ++request.current;
    let error: unknown;
    let failed = false;
    try {
      await navigator.clipboard.writeText(text);
    } catch (failure) {
      failed = true;
      error = failure;
    }
    if (currentRequest !== request.current) return;
    setStatus(failed ? "error" : "copied");
    timer.current = setTimeout(() => setStatus("idle"), Math.max(0, feedbackMs));
    if (failed) onCopyError?.(error); else onCopied?.();
  };
  const copied = status === "copied";
  const feedback = copied ? copiedLabel : status === "error" ? errorLabel : "";

  return (
    <button
      {...props}
      ref={forwardedRef ?? suppliedRef}
      type={props.type ?? "button"}
      className={cn("vds-copy-button", className)}
      data-variant={variant}
      data-size={copyButtonSize}
      data-copied={copied || undefined}
      data-error={status === "error" || undefined}
      disabled={disabled}
      aria-label={feedback || props["aria-label"] || label || copyLabel}
      title={status === "error" ? errorLabel : props.title}
      onClick={handleCopy}
    >
      <span className="vds-copy-button__icon" aria-hidden="true">
        {copied ? (
          <IconCheck aria-hidden focusable={false} />
        ) : (
          <IconCopy aria-hidden focusable={false} />
        )}
      </span>
      {label && (
        <span className="vds-copy-button__label">
          {feedback || label}
        </span>
      )}
      <span className="vds-copy-button__status" role="status" aria-live="polite">{feedback}</span>
    </button>
  );
});

