import { useEffect, useMemo, useState } from "react";
import {
  DndContext,
  KeyboardSensor,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import type { DragEndEvent } from "@dnd-kit/core";
import {
  SortableContext,
  arrayMove,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import {
  Drawer,
  DrawerBody,
  DrawerContent,
  DrawerHeader,
  DrawerTitle,
} from "@virtari-packages/react-drawer";
import { Input } from "@virtari-packages/react-input";
import { Switch } from "@virtari-packages/react-switch";
import { cn } from "@virtari-packages/utils";
import { IconGripVertical } from "@virtari-packages/react-icons";

export interface ColumnConfig {
  id: string;
  label: string;
  icon?: React.ReactNode;
  visible: boolean;
}

export interface DataTableCustomizeDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  columns: ColumnConfig[];
  onColumnsChange: (columns: ColumnConfig[]) => void;
  defaultColumns?: ColumnConfig[];
  title?: string;
  side?: "left" | "right" | "top" | "bottom";
}

export function DataTableCustomizeDrawer({
  open,
  onOpenChange,
  columns: external,
  onColumnsChange,
  defaultColumns,
  title = "Customize view",
  side = "right",
}: DataTableCustomizeDrawerProps) {
  const [columns, setColumns] = useState<ColumnConfig[]>(external);
  const [search, setSearch] = useState("");

  useEffect(() => {
    if (open) setColumns(external);
  }, [open, external]);

  const filtered = useMemo(() => {
    if (!search.trim()) return columns;
    const q = search.toLowerCase();
    return columns.filter(
      (c) => c.label.toLowerCase().includes(q) || c.id.toLowerCase().includes(q),
    );
  }, [columns, search]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 4 } }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    setColumns((prev) => {
      const oldIndex = prev.findIndex((c) => c.id === active.id);
      const newIndex = prev.findIndex((c) => c.id === over.id);
      if (oldIndex < 0 || newIndex < 0) return prev;
      const next = arrayMove(prev, oldIndex, newIndex);
      onColumnsChange(next);
      return next;
    });
  };

  const toggleVisibility = (id: string, visible: boolean) => {
    setColumns((prev) => {
      const next = prev.map((c) => (c.id === id ? { ...c, visible } : c));
      onColumnsChange(next);
      return next;
    });
  };

  const handleReset = () => {
    if (!defaultColumns) return;
    setColumns(defaultColumns);
    onColumnsChange(defaultColumns);
  };

  const visibleCount = columns.filter((c) => c.visible).length;

  return (
    <Drawer
      direction={side}
      open={open}
      onOpenChange={onOpenChange}
      sizeMode="fixed"
      size="min(24rem, 95vw)"
    >
      <DrawerContent
        className="vds-data-table-customize-drawer"
        aria-label={title}
      >
        <DrawerHeader>
          <div className="vds-data-table-customize-drawer-header">
            <DrawerTitle>{title}</DrawerTitle>
            <span className="vds-data-table-customize-drawer-count">
              {visibleCount} / {columns.length} shown
            </span>
          </div>
        </DrawerHeader>

        <DrawerBody>
          <div className="vds-data-table-customize-drawer-body">
            <Input
              inputSize="md"
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search columns…"
            />

            <DndContext
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext
                items={filtered.map((c) => c.id)}
                strategy={verticalListSortingStrategy}
              >
                <div className="vds-data-table-customize-drawer-list">
                  {filtered.map((column) => (
                    <SortableColumnItem
                      key={column.id}
                      column={column}
                      onToggle={toggleVisibility}
                    />
                  ))}
                </div>
              </SortableContext>
            </DndContext>

            {defaultColumns && (
              <button
                type="button"
                onClick={handleReset}
                className="vds-data-table-customize-drawer-reset"
              >
                Reset to default
              </button>
            )}
          </div>
        </DrawerBody>
      </DrawerContent>
    </Drawer>
  );
}

interface SortableColumnItemProps {
  column: ColumnConfig;
  onToggle: (id: string, visible: boolean) => void;
}

function SortableColumnItem({ column, onToggle }: SortableColumnItemProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: column.id });

  const style: React.CSSProperties = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      data-dragging={isDragging ? "" : undefined}
      className={cn("vds-data-table-customize-item")}
    >
      <button
        type="button"
        {...attributes}
        {...listeners}
        aria-label="Drag to reorder"
        className="vds-data-table-customize-item-drag"
      >
        <IconGripVertical size={14} stroke={1.75} aria-hidden focusable={false} />
      </button>
      {column.icon && (
        <span className="vds-data-table-customize-item-icon">{column.icon}</span>
      )}
      <span className="vds-data-table-customize-item-label">{column.label}</span>
      <Switch
        checked={column.visible}
        onCheckedChange={(checked) => onToggle(column.id, Boolean(checked))}
        aria-label={`Toggle ${column.label}`}
      />
    </div>
  );
}

export {
  DataTableCustomizeDrawer,
} from "./CustomizeDrawer";
export type {
  ColumnConfig,
  DataTableCustomizeDrawerProps,
} from "./CustomizeDrawer";

@import './DataTable.tokens.css';
@import '../../react-pagination/src/Pagination.css';

@layer design-system.components {
  /* ───── Root wrapper ───────────────────────────────────────── */
  .vds-data-table {
    display: flex;
    flex-direction: column;
    min-block-size: 0;
    color: var(--data-table-cell-color);
    font-family: var(--data-table-font-family);
    font-size: var(--data-table-font-size);
    line-height: var(--data-table-line-height);
    background-color: var(--data-table-bg);
    border: var(--data-table-border-width) solid var(--vds-surface-border, var(--data-table-border-color));
    border-radius: var(--data-table-radius);
    overflow: clip;
    position: relative;
    box-shadow: var(--data-table-shadow);
  }

  .vds-data-table-scroll-shell {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-inline-size: 0;
    min-block-size: 0;
  }
  .vds-data-table-sticky-header-rail {
    background-color: var(--data-table-header-bg);
  }
  .vds-data-table-sticky-header-rail[data-sticky] {
    position: sticky;
    inset-block-start: calc(
      var(--vds-sticky-top, 0px) +
        var(--vds-sticky-effective-offset-top, var(--vds-sticky-offset-top, 0px))
    );
    z-index: 7;
  }
  .vds-data-table-sticky-header-scroll {
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .vds-data-table-sticky-header-scroll::-webkit-scrollbar {
    display: none;
  }

  /* ───── Scroll area ────────────────────────────────────────── */
  /* Default: only horizontal scroll is contained here; vertical overflow
   * falls through to the page scroll so `position: sticky` on <thead>
   * pins to the same scrollport as the outer toolbar/filter-bar bands.
   * Virtualization switches vertical back to `auto` — the virtualizer
   * owns row scrolling and needs its own scrollport. */
  .vds-data-table-scroll-area {
    flex: 1 1 auto;
    min-inline-size: 0;
    min-block-size: 0;
    overflow-x: auto;
    overflow-y: clip;
    scrollbar-gutter: auto;
  }
  .vds-data-table[data-virtualized] .vds-data-table-scroll-area {
    overflow-y: auto;
    scrollbar-gutter: stable;
  }
  /* Drag-to-pan cursor: `grab` when the feature is on, `grabbing` during drag.
   * Only applied when horizontal overflow exists (so we don't hint at drag
   * when the table already fits). `:where()` keeps specificity at 0 so
   * consumers can override easily. */
  :where(.vds-data-table[data-scrolled-x]) .vds-data-table-scroll-area[data-scroll-drag] {
    cursor: grab;
  }
  .vds-data-table-scroll-area[data-scroll-dragging] {
    cursor: grabbing !important;
    user-select: none;
  }

  /* ───── Table element ──────────────────────────────────────── */
  .vds-data-table-table {
    table-layout: fixed;
    inline-size: max(100%, var(--data-table-total-width, 100%));
    border-collapse: separate;
    border-spacing: 0;
    font-size: inherit;
    color: inherit;
  }

  /* ───── Header group (sticky by default) ───────────────────── */
  .vds-data-table-header {
    background-color: var(--data-table-header-bg);
  }
  .vds-data-table[data-sticky-header] .vds-data-table-header {
    z-index: 6;
  }
  .vds-data-table[data-sticky-header] .vds-data-table-header-cell {
    position: sticky;
    inset-block-start: calc(
      var(--vds-sticky-top, 0px) +
        var(--vds-sticky-effective-offset-top, var(--vds-sticky-offset-top, 0px))
    );
    z-index: 6;
  }

  .vds-data-table-sticky-header-rail .vds-data-table-header-cell {
    position: relative;
    inset-block-start: auto;
  }
  .vds-data-table-sticky-header-rail
    .vds-data-table-header-cell[data-pinned] {
    position: sticky;
    inset-block-start: auto;
  }

  .vds-data-table [data-sticky="smart"] {
    transition: transform var(--data-table-transition-duration)
      var(--data-table-transition-easing);
  }
  .vds-data-table[data-scrolling-down]
    [data-sticky="smart"][data-sticky-axis="top"] {
    transform: translateY(
      calc(
        -100% - var(--vds-sticky-top, 0px) -
          var(
            --vds-sticky-effective-offset-top,
            var(--vds-sticky-offset-top, 0px)
          )
      )
    );
    will-change: transform;
    pointer-events: none;
  }
  .vds-data-table[data-scrolling-down]
    [data-sticky="smart"][data-sticky-axis="bottom"] {
    transform: translateY(
      calc(
        100% + var(--vds-sticky-bottom, 0px) +
          var(
            --vds-sticky-effective-offset-bottom,
            var(--vds-sticky-offset-bottom, 0px)
          )
      )
    );
    will-change: transform;
    pointer-events: none;
  }

  /* ───── Header row ─────────────────────────────────────────── */
  .vds-data-table-header-row {
    block-size: var(--data-table-header-row-height);
  }

  /* ───── Header cell ────────────────────────────────────────── */
  .vds-data-table-header-cell {
    position: relative;
    box-sizing: border-box;
    text-align: start;
    vertical-align: middle;
    inline-size: var(--col-size, var(--data-table-col-default-width));
    min-inline-size: var(--data-table-col-min-width);
    padding-inline: var(--data-table-cell-padding-inline);
    padding-block: 0;
    font-size: var(--data-table-header-font-size);
    font-weight: var(--data-table-header-font-weight);
    letter-spacing: var(--data-table-header-letter-spacing);
    text-transform: var(--data-table-header-text-transform);
    color: var(--data-table-header-color);
    background-color: var(--data-table-header-bg);
    border-block-end: var(--data-table-border-width) solid
      var(--data-table-header-divider-color);
    border-inline-end: var(--data-table-border-width) solid
      var(--data-table-border-color);
    user-select: none;
  }
  .vds-data-table-header-cell:last-child {
    border-inline-end: 0;
  }

  /* ───── Body / row / cell ──────────────────────────────────── */
  .vds-data-table-body {
    background-color: var(--data-table-bg);
  }

  .vds-data-table-row {
    block-size: var(--data-table-row-height);
    background-color: var(--data-table-row-bg);
    transition: background-color var(--data-table-transition-duration)
      var(--data-table-transition-easing);
  }

  .vds-data-table-cell {
    box-sizing: border-box;
    vertical-align: middle;
    inline-size: var(--col-size, var(--data-table-col-default-width));
    min-inline-size: var(--data-table-col-min-width);
    padding-inline: var(--data-table-cell-padding-inline);
    padding-block: var(--data-table-cell-padding-block);
    color: var(--data-table-cell-color);
    background-color: inherit;
    border-block-end: var(--data-table-border-width) solid
      var(--data-table-border-color);
    border-inline-end: var(--data-table-border-width) solid
      var(--data-table-border-color);

    /* `clip`, not `hidden`. The cell still has to contain its content to the
     * column width — `table-layout: fixed` does not do that on its own — but
     * `hidden` cut the focus rings off the interactive things that live in
     * cells (row expand / pin triggers, the actions-cell trigger, the copyable
     * button, the inline editor), all of which draw at `outline-offset: 2px`.
     * `overflow-clip-margin` widens the clip box by exactly the ring, so the
     * ring survives and the content is still contained. Browsers without
     * `overflow-clip-margin` fall back to clipping at the border box, i.e.
     * the previous behaviour. */
    overflow: clip;
    overflow-clip-margin: var(--data-table-cell-clip-margin);
  }
  .vds-data-table-row > .vds-data-table-cell:last-child {
    border-inline-end: 0;
  }

  /* Last row — drop the trailing divider (outer container owns that edge). */
  .vds-data-table-row:last-child > .vds-data-table-cell {
    border-block-end: 0;
  }

  /* Cell content — ellipsis truncation by default. */
  .vds-data-table-cell-content {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Empty cell — stretches across all columns. */
  .vds-data-table-empty-cell {
    inline-size: auto;
    min-inline-size: 0;
    padding-block: var(--vds-space-8, 2rem);
    text-align: center;
    color: var(--vds-color-text-muted, #6b7280);
  }

  /* ───── Footer ─────────────────────────────────────────────── */
  .vds-data-table-footer {
    background-color: var(--data-table-footer-bg);
  }
  .vds-data-table-footer[data-sticky] {
    z-index: 4;
    background-color: var(--data-table-sticky-bottom-bg);
    box-shadow: var(--data-table-sticky-bottom-shadow);
    isolation: isolate;
  }
  .vds-data-table-footer[data-sticky] .vds-data-table-footer-cell {
    position: sticky;
    inset-block-end: calc(
      var(--vds-sticky-bottom, 0px) +
        var(
          --vds-sticky-effective-offset-bottom,
          var(--vds-sticky-offset-bottom, 0px)
        )
    );
    z-index: 4;
    background-color: var(--data-table-sticky-bottom-bg);
  }
  .vds-data-table-footer-row {
    block-size: var(--data-table-footer-row-height);
  }
  .vds-data-table-footer-cell {
    box-sizing: border-box;
    vertical-align: middle;
    inline-size: var(--col-size, var(--data-table-col-default-width));
    min-inline-size: var(--data-table-col-min-width);
    padding-inline: var(--data-table-cell-padding-inline);
    padding-block: var(--data-table-cell-padding-block);
    color: var(--data-table-footer-color);
    font-weight: var(--data-table-header-font-weight);
    border-block-start: var(--data-table-border-width) solid
      var(--data-table-header-divider-color);
  }

  /* ───── Bordered variants ──────────────────────────────────── */
  .vds-data-table[data-bordered="none"] .vds-data-table-cell,
  .vds-data-table[data-bordered="none"] .vds-data-table-header-cell {
    border-block-end: 0;
    border-inline-end: 0;
  }
  .vds-data-table[data-bordered="grid"] .vds-data-table-cell,
  .vds-data-table[data-bordered="grid"] .vds-data-table-header-cell,
  .vds-data-table[data-bordered="grid"] .vds-data-table-footer-cell {
    border-inline-end: var(--data-table-border-width) solid
      var(--data-table-border-color);
  }
  .vds-data-table[data-bordered="grid"]
    .vds-data-table-header-row
    > .vds-data-table-header-cell:last-child,
  .vds-data-table[data-bordered="grid"]
    .vds-data-table-row
    > .vds-data-table-cell:last-child,
  .vds-data-table[data-bordered="grid"]
    .vds-data-table-footer-row
    > .vds-data-table-footer-cell:last-child {
    border-inline-end: 0;
  }

  /* ───── Grid interaction-mode focus ring ───────────────────── */
  .vds-data-table[data-interaction-mode="grid"]
    .vds-data-table-cell,
  .vds-data-table[data-interaction-mode="grid"]
    .vds-data-table-header-cell{
    transition: box-shadow 180ms ease-out;

    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table[data-interaction-mode="grid"]
    .vds-data-table-cell:focus-visible,
  .vds-data-table[data-interaction-mode="grid"]
    .vds-data-table-header-cell:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  /* ───── Empty + loading overlay ────────────────────────────── */
  .vds-data-table-empty {
    padding: var(--vds-space-8, 2rem);
    text-align: center;
    color: var(--vds-color-text-muted, #6b7280);
  }

  .vds-data-table-loading {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    background-color: var(--data-table-overlay-bg);
    backdrop-filter: blur(2px);
    z-index: 4;
    pointer-events: all;
  }
  .vds-data-table-loading-label {
    color: var(--vds-color-text, #111827);
    font-weight: var(--vds-font-weight-medium, 500);
  }

  /* ───── Toolbar ────────────────────────────────────────────── */
  .vds-data-table-toolbar {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--vds-space-1-5, 0.375rem);
    padding-inline: var(--vds-space-3, 0.75rem);
    padding-block: var(--vds-space-2, 0.5rem);
    border-block-end: var(--data-table-border-width) solid
      var(--data-table-border-color);
    background-color: var(--data-table-bg);
  }
  .vds-data-table-toolbar[data-sticky] {
    position: sticky;
    inset-block-start: calc(
      var(--vds-sticky-top, 0px) +
        var(--vds-sticky-effective-offset-top, var(--vds-sticky-offset-top, 0px))
    );
    z-index: 8;
  }
  .vds-data-table-view-toggle .vds-tabs-trigger {
    gap: var(--vds-space-1-5, 0.375rem);
  }
  .vds-data-table-view-toggle-icon,
  .vds-data-table-view-toggle-label {
    display: inline-flex;
    align-items: center;
    line-height: 1;
    flex: 0 0 auto;
  }
  .vds-data-table-view-toggle-label {
    transform: translateY(var(--data-table-view-toggle-label-offset));
  }
  @media (max-width: 640px) {
    .vds-data-table-toolbar {
      gap: var(--vds-space-1, 0.25rem);
      padding-inline: var(--vds-space-2, 0.5rem);
    }
    .vds-data-table-toolbar > [aria-hidden="true"] {
      display: none !important;
    }
    .vds-data-table-view-toggle {
      flex: 1 1 auto;
      min-inline-size: 0;
    }
    .vds-data-table-view-toggle .vds-tabs-list {
      inline-size: 100%;
    }
    .vds-data-table-search-field {
      order: 2;
      flex: 1 1 100%;
      max-inline-size: none;
      inline-size: 100%;
    }
    .vds-data-table-toolbar .vds-button[data-mobile-icon-only] {
      inline-size: var(--vds-size-md, 2.25rem);
      min-inline-size: var(--vds-size-md, 2.25rem);
      padding-inline: 0;
    }
    .vds-data-table-toolbar
      .vds-button[data-mobile-icon-only]
      .vds-data-table-toolbar-button-label,
    .vds-data-table-toolbar
      .vds-button[data-mobile-icon-only]
      .vds-data-table-toolbar-button-count,
    .vds-data-table-toolbar
      .vds-button[data-mobile-icon-only]
      .vds-button-section[data-position="end"] {
      display: none;
    }
  }

  /* ───── Global filter (search input) ───────────────────────── */
  .vds-data-table-global-filter {
    block-size: var(--data-table-filter-height);
    padding-inline: var(--data-table-filter-padding-inline);
    min-inline-size: 10rem;
    font-family: inherit;
    font-size: var(--data-table-filter-font-size);
    color: var(--data-table-cell-color);
    background-color: var(--data-table-filter-bg);
    border: 1px solid var(--data-table-filter-border);
    border-radius: var(--data-table-filter-radius);
    outline: none;
    transition: border-color var(--data-table-transition-duration)
      var(--data-table-transition-easing),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table-global-filter::placeholder {
    color: var(--data-table-filter-placeholder-color);
  }
  .vds-data-table-global-filter:focus-visible {
    border-color: var(--data-table-focus-ring-color);
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-data-table-search-field {
    position: relative;
    display: inline-flex;
    align-items: center;
    min-inline-size: 9rem;
    max-inline-size: 16rem;
  }
  .vds-data-table-search-field-icon {
    position: absolute;
    inset-inline-start: var(--vds-space-2, 0.5rem);
    display: inline-flex;
    color: var(--vds-color-text-muted, #9ca3af);
    pointer-events: none;
    z-index: 1;
  }
  .vds-data-table-search-field-input {
    /* Clears the leading search icon and the trailing clear button. Set through
       the Input's public token so no `!important` is needed to win the cascade. */
    --input-padding-inline: var(--vds-space-7, 1.75rem);
    inline-size: 100%;
    min-inline-size: 0;
    font-size: var(--data-table-filter-font-size);
  }
  .vds-data-table-search-field-clear {
    all: unset;
    position: absolute;
    inset-inline-end: var(--vds-space-1-5, 0.375rem);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.125rem;
    block-size: 1.125rem;
    color: var(--vds-color-text-muted, #9ca3af);
    border-radius: 999px;
    cursor: pointer;
  }
  .vds-data-table-search-field-clear:hover {
    color: var(--data-table-cell-color);
    background-color: var(--data-table-toolbar-button-bg-hover);
  }

  /* ───── Header cell inner content (flex wrapper) ───────────── */
  .vds-data-table-header-cell-content {
    display: inline-flex;
    align-items: center;
    gap: var(--data-table-sort-gap);
    inline-size: 100%;
    min-inline-size: 0;
  }

  /* ───── Sort trigger ───────────────────────────────────────── */
  .vds-data-table-sort-trigger {
    all: unset;
    display: inline-flex;
    align-items: center;
    gap: var(--data-table-sort-gap);
    inline-size: 100%;
    min-inline-size: 0;
    cursor: pointer;
    color: inherit;
    font: inherit;
    text-transform: inherit;
    letter-spacing: inherit;
    transition: box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table-sort-trigger:focus-visible {
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }
  .vds-data-table-sort-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    flex: 1 1 auto;
    min-inline-size: 0;
  }

  /* ───── Sort icon ──────────────────────────────────────────── */
  .vds-data-table-sort-icon {
    flex: 0 0 auto;
    color: var(--data-table-sort-icon-color);
    opacity: var(--data-table-sort-icon-opacity);
    transition:
      color var(--data-table-transition-duration)
        var(--data-table-transition-easing),
      opacity var(--data-table-transition-duration)
        var(--data-table-transition-easing);
  }

  /* ───── Resize handle ──────────────────────────────────────── */
  .vds-data-table-resize-handle {
    position: absolute;
    inset-block: 0;
    inset-inline-end: calc(var(--data-table-resize-hit-width) / -2);
    inline-size: var(--data-table-resize-hit-width);
    cursor: col-resize;
    user-select: none;
    touch-action: none;
    z-index: 2;
    /* No transition on width/background — must snap. */
  }
  .vds-data-table-resize-handle-line {
    position: absolute;
    inset-block: 25%;
    inset-inline-end: calc(var(--data-table-resize-hit-width) / 2);
    inline-size: var(--data-table-resize-line-width);
    background-color: var(--data-table-resize-line-color);
    transition:
      background-color var(--data-table-transition-duration)
        var(--data-table-transition-easing),
      inline-size var(--data-table-transition-duration)
        var(--data-table-transition-easing);
  }
  .vds-data-table-resize-handle:focus-visible {
    outline: none; /* delegate focus ring to the line below */
  }
  .vds-data-table-resize-handle
    .vds-data-table-resize-handle-line{
    transition: box-shadow 180ms ease-out;

    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table-resize-handle:focus-visible
    .vds-data-table-resize-handle-line {
    inline-size: var(--data-table-resize-line-width-active);
    background-color: var(--data-table-resize-line-color-active);
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  /* Resize guideline overlay — full-height 1px line during drag.
     Uses physical `left` anchor because the offset from TanStack
     (startOffset + deltaOffset) is a physical-pixel value paired with
     physical translateX — in RTL we still want the guideline at the
     dragged column's physical position. */
  .vds-data-table[data-resizing] .vds-data-table-resize-handle-line {
    transition: none;
  }
  .vds-data-table[data-resizing] .vds-data-table-header-cell-draggable {
    transition: none !important;
  }

  .vds-data-table-resize-guideline {
    position: absolute;
    inset-block-start: var(--data-table-guideline-top, 0px);
    block-size: var(--data-table-guideline-height, 100%);
    /* Deliberately physical: --data-table-guideline-offset is a physical
       clientX, and the translate3d below moves along the physical X axis, so
       the origin has to be the physical left edge in both directions. */
    left: 0;
    inline-size: var(--data-table-guideline-width);
    background-color: var(--data-table-guideline-color);
    pointer-events: none;
    z-index: 3;
    transform: translate3d(var(--data-table-guideline-offset, 0), 0, 0);
    will-change: transform;
  }

  /* Global cursor while any table is being resized. */
  body:has(.vds-data-table[data-resizing]) {
    cursor: col-resize;
    user-select: none;
  }

  /* ───── Column pinning (position: sticky approach) ─────────── */
  /* Pinned cells must be opaque to overlay scrolling center cells.
   * Background is re-applied explicitly because `background: inherit` fails
   * once the row background is itself set on the <tr>. */
  .vds-data-table-header-cell[data-pinned],
  .vds-data-table-cell[data-pinned],
  .vds-data-table-footer-cell[data-pinned] {
    position: sticky;
    z-index: 2;
  }
  .vds-data-table-header-cell[data-pinned] {
    z-index: 3; /* above both body pinned cells and sticky header */
    background-color: var(--data-table-pin-header-bg);
  }
  .vds-data-table[data-sticky-header] .vds-data-table-header-cell[data-pinned] {
    z-index: 7;
  }
  .vds-data-table-footer[data-sticky] .vds-data-table-footer-cell[data-pinned] {
    z-index: 5;
  }
  .vds-data-table-pagination .vds-pagination-info {
    font-variant-numeric: tabular-nums;
  }
  .vds-data-table-pagination .vds-pagination-page-size {
    gap: var(--vds-space-2, 0.5rem);
    color: var(--data-table-footer-color);
  }
  .vds-data-table-pagination .vds-pagination-page-size-label {
    font-size: var(--vds-text-sm, 0.875rem);
    font-weight: var(--vds-font-weight-medium, 500);
    color: var(--data-table-footer-color);
  }
  .vds-data-table-pagination .vds-pagination-page-size-trigger.vds-select-trigger {
    inline-size: 4.5rem;
    min-inline-size: 4.5rem;
    max-inline-size: 4.5rem;
    --select-trigger-height: calc(
      var(--data-table-pagination-button-size) + 0.25rem
    );
    --select-trigger-padding-inline: var(--vds-space-2, 0.5rem);
    --select-trigger-font-size: var(--vds-text-sm, 0.875rem);
    --select-trigger-font-weight: var(--vds-font-weight-semibold, 600);
    --select-trigger-bg: var(--vds-color-surface, #ffffff);
    --select-trigger-bg-hover: var(--vds-color-surface-hover, #f3f4f6);
    --select-trigger-border-color: var(--data-table-border-color);
    --select-trigger-border-color-hover:
      var(--vds-color-border-strong, #9ca3af);
    --select-trigger-text-color: var(--data-table-cell-color);
    --select-trigger-icon-color: var(--data-table-footer-color);
  }
  .vds-data-table-pagination
    .vds-pagination-page-size-trigger
    .vds-select-trigger-value {
    font-variant-numeric: tabular-nums;
    font-weight: var(--vds-font-weight-semibold, 600);
  }
  .vds-data-table-cell[data-pinned] {
    background-color: var(--data-table-row-bg);
  }
  .vds-data-table-footer-cell[data-pinned] {
    background-color: var(--data-table-footer-bg);
  }

  /* Scroll shadows on the LAST left-pinned and FIRST right-pinned columns.
   * Only appear when horizontal scroll is not at the corresponding edge.
   * - at "start" (scroll=0)  → no left shadow, right shadow OK
   * - at "middle"            → both shadows
   * - at "end" (maxed)       → left shadow OK, no right shadow
   * - at "none"              → no overflow, no shadows */
  .vds-data-table[data-scrolled-x="middle"]
    .vds-data-table-cell[data-pinned-last],
  .vds-data-table[data-scrolled-x="middle"]
    .vds-data-table-header-cell[data-pinned-last],
  .vds-data-table[data-scrolled-x="middle"]
    .vds-data-table-footer-cell[data-pinned-last],
  .vds-data-table[data-scrolled-x="end"]
    .vds-data-table-cell[data-pinned-last],
  .vds-data-table[data-scrolled-x="end"]
    .vds-data-table-header-cell[data-pinned-last],
  .vds-data-table[data-scrolled-x="end"]
    .vds-data-table-footer-cell[data-pinned-last] {
    box-shadow: var(--data-table-pin-shadow-left);
  }
  .vds-data-table[data-scrolled-x="middle"]
    .vds-data-table-cell[data-pinned-first],
  .vds-data-table[data-scrolled-x="middle"]
    .vds-data-table-header-cell[data-pinned-first],
  .vds-data-table[data-scrolled-x="middle"]
    .vds-data-table-footer-cell[data-pinned-first],
  .vds-data-table[data-scrolled-x="start"]
    .vds-data-table-cell[data-pinned-first],
  .vds-data-table[data-scrolled-x="start"]
    .vds-data-table-header-cell[data-pinned-first],
  .vds-data-table[data-scrolled-x="start"]
    .vds-data-table-footer-cell[data-pinned-first] {
    box-shadow: var(--data-table-pin-shadow-right);
  }

  /* RTL: flip the shadow directions — left/right physical values reversed. */
  .vds-data-table[dir="rtl"]
    .vds-data-table-cell[data-pinned-last],
  .vds-data-table[dir="rtl"]
    .vds-data-table-header-cell[data-pinned-last] {
    box-shadow: var(--data-table-pin-shadow-right);
  }
  .vds-data-table[dir="rtl"]
    .vds-data-table-cell[data-pinned-first],
  .vds-data-table[dir="rtl"]
    .vds-data-table-header-cell[data-pinned-first] {
    box-shadow: var(--data-table-pin-shadow-left);
  }

  /* ───── Per-column filters ─────────────────────────────────── */
  .vds-data-table-filter-trigger {
    all: unset;
