  }

  .vds-data-table-text-cell[data-truncate] {
    display: inline-block;
    max-inline-size: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    vertical-align: bottom;
  }
  .vds-data-table-text-cell[data-weight="medium"] {
    font-weight: var(--vds-font-weight-medium, 500);
  }
  .vds-data-table-text-cell[data-weight="semibold"] {
    font-weight: var(--vds-font-weight-semibold, 600);
  }
  .vds-data-table-text-cell[data-muted] {
    color: var(--vds-color-text-muted, #6b7280);
  }

  .vds-data-table-number-cell {
    font-variant-numeric: tabular-nums;
    display: inline-block;
    inline-size: 100%;
  }
  .vds-data-table-number-cell[data-align="start"] { text-align: start; }
  .vds-data-table-number-cell[data-align="center"] { text-align: center; }
  .vds-data-table-number-cell[data-align="end"] { text-align: end; }

  .vds-data-table-date-cell {
    font-variant-numeric: tabular-nums;
  }

  .vds-data-table-link-cell {
    color: var(--vds-color-primary-solid, #6366f1);
    text-decoration: none;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .vds-data-table-link-cell:hover {
    text-decoration: underline;
  }

  .vds-data-table-copyable-cell {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
    min-inline-size: 0;
  }
  .vds-data-table-copyable-cell-content {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .vds-data-table-copyable-cell-button {
    all: unset;
    display: inline-flex;
    padding: 2px;
    opacity: 0;
    color: var(--vds-color-text-muted, #6b7280);
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));
    cursor: pointer;
    transition: opacity var(--data-table-transition-duration)
      var(--data-table-transition-easing);
  }
  .vds-data-table-copyable-cell:hover .vds-data-table-copyable-cell-button,
  .vds-data-table-copyable-cell-button:focus-visible {
    opacity: 1;
  }
  .vds-data-table-copyable-cell[data-copied] .vds-data-table-copyable-cell-button {
    opacity: 1;
    color: var(--vds-color-success-solid, #16a34a);
  }

  .vds-data-table-row-actions {
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--vds-space-1, 0.25rem);
    inline-size: 100%;
    min-inline-size: 0;
    white-space: nowrap;
  }

  .vds-data-table-actions-cell-trigger {
    all: unset;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.75rem;
    block-size: 1.75rem;
    color: var(--vds-color-text-muted, #6b7280);
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));
    cursor: pointer;
    transition: box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table-actions-cell-trigger:hover {
    background-color: var(--data-table-pagination-button-bg-hover);
    color: var(--vds-color-text, #111827);
  }
  .vds-data-table-actions-cell-trigger:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }
  .vds-data-table-actions-cell-item-icon {
    display: inline-flex;
    margin-inline-end: var(--vds-space-2, 0.5rem);
  }

  /* ───── Filter drawer ──────────────────────────────────────── */
  .vds-data-table-filter-drawer-header {
    display: flex;
    align-items: center;
    gap: var(--vds-space-2, 0.5rem);
  }
  .vds-data-table-filter-drawer-back {
    all: unset;
    display: inline-flex;
    padding: var(--vds-space-1, 0.25rem);
    cursor: pointer;
    color: var(--vds-color-text-muted, #6b7280);
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));
  }
  .vds-data-table-filter-drawer-back:hover {
    background-color: var(--data-table-pagination-button-bg-hover);
  }
  .vds-data-table-filter-drawer-count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-inline-size: 1.25rem;
    block-size: 1.25rem;
    padding-inline: 4px;
    background-color: var(--vds-color-primary-solid, #6366f1);
    color: var(--vds-color-on-primary, #fff);
    border-radius: 999px;
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-semibold, 600);
  }
  .vds-data-table-filter-drawer-body {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-4, 1rem);
  }
  .vds-data-table-filter-drawer-active {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-2, 0.5rem);
    padding: var(--vds-space-3, 0.75rem);
    background-color: var(--vds-color-surface-raised, #f9fafb);
    border: 1px solid var(--vds-color-border-muted, #e5e7eb);
    border-radius: var(--vds-radius-card, 0.5rem);
  }
  .vds-data-table-filter-drawer-active-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: var(--vds-text-sm, 0.875rem);
    color: var(--vds-color-text-muted, #6b7280);
  }
  .vds-data-table-filter-drawer-clear {
    all: unset;
    cursor: pointer;
    color: var(--vds-color-danger-solid, #dc2626);
    font-size: var(--vds-text-xs, 0.75rem);
  }
  .vds-data-table-filter-drawer-group {
    display: flex;
    flex-wrap: wrap;
    gap: var(--vds-space-1-5, 0.375rem);
  }
  .vds-data-table-filter-drawer-operator {
    all: unset;
    padding: 2px var(--vds-space-2, 0.5rem);
    background-color: var(--vds-color-surface, #ffffff);
    border: 1px dashed var(--vds-color-border, #d1d5db);
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));
    cursor: pointer;
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-semibold, 600);
  }
  .vds-data-table-filter-drawer-chip {
    --chip-height: 1.5rem;
    --chip-padding-inline: var(--vds-space-2, 0.5rem);
    --chip-font-size: var(--vds-text-xs, 0.75rem);
  }
  .vds-data-table-filter-drawer-section {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-2, 0.5rem);
  }
  .vds-data-table-filter-drawer-section-title {
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-semibold, 600);
    color: var(--vds-color-text-muted, #6b7280);
    text-transform: uppercase;
    letter-spacing: var(--vds-tracking-wide, 0.025em);
  }
  .vds-data-table-filter-drawer-fields {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .vds-data-table-filter-drawer-field {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--vds-space-2, 0.5rem) var(--vds-space-3, 0.75rem);
    background-color: var(--vds-color-surface, #ffffff);
    border: 1px solid var(--vds-color-border-muted, #e5e7eb);
    border-radius: var(--vds-radius-nav-item, var(--vds-radius-element, 0.375rem));
    cursor: pointer;
    transition: background-color var(--data-table-transition-duration)
      var(--data-table-transition-easing);
  }
  .vds-data-table-filter-drawer-field:hover {
    background-color: var(--vds-color-surface-hover, #f3f4f6);
  }
  .vds-data-table-filter-drawer-field[data-active] {
    border-color: var(--vds-color-primary-solid, #6366f1);
  }
  .vds-data-table-filter-drawer-field-left {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-2, 0.5rem);
  }
  .vds-data-table-filter-drawer-footer {
    display: flex;
    gap: var(--vds-space-2, 0.5rem);
    justify-content: flex-end;
  }
  .vds-data-table-filter-config {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-3, 0.75rem);
  }
  .vds-data-table-filter-config-row {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-1, 0.25rem);
  }
  .vds-data-table-filter-config-label {
    font-size: var(--vds-text-xs, 0.75rem);
    color: var(--vds-color-text-muted, #6b7280);
    font-weight: var(--vds-font-weight-medium, 500);
  }
  .vds-data-table-filter-config-select {
    block-size: var(--vds-size-md, 2.25rem);
    padding-inline: var(--vds-space-2, 0.5rem);
    background-color: var(--data-table-filter-bg);
    border: 1px solid var(--data-table-filter-border);
    border-radius: var(--data-table-filter-radius);
    color: var(--data-table-cell-color);
    font: inherit;
    font-size: var(--vds-text-sm, 0.875rem);
  }
  .vds-data-table-filter-config-actions {
    display: flex;
    gap: var(--vds-space-2, 0.5rem);
    justify-content: flex-end;
    padding-block-start: var(--vds-space-2, 0.5rem);
  }

  /* ───── Customize view drawer ──────────────────────────────── */
  .vds-data-table-customize-drawer-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--vds-space-2, 0.5rem);
  }
  .vds-data-table-customize-drawer-count {
    font-size: var(--vds-text-xs, 0.75rem);
    color: var(--vds-color-text-muted, #6b7280);
  }
  .vds-data-table-customize-drawer-body {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-3, 0.75rem);
  }
  .vds-data-table-customize-drawer-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .vds-data-table-customize-drawer-reset {
    all: unset;
    align-self: flex-start;
    cursor: pointer;
    color: var(--vds-color-text-muted, #6b7280);
    font-size: var(--vds-text-xs, 0.75rem);
    padding: var(--vds-space-1, 0.25rem) var(--vds-space-2, 0.5rem);
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.375rem));
  }
  .vds-data-table-customize-drawer-reset:hover {
    background-color: var(--vds-color-surface-hover, #f3f4f6);
  }
  .vds-data-table-customize-item {
    display: flex;
    align-items: center;
    gap: var(--vds-space-3, 0.75rem);
    padding: var(--vds-space-2, 0.5rem) var(--vds-space-3, 0.75rem);
    background-color: var(--vds-color-surface, #ffffff);
    border: 1px solid var(--vds-color-border-muted, #e5e7eb);
    border-radius: var(--vds-radius-control, var(--vds-radius-element, 0.375rem));
  }
  .vds-data-table-customize-item[data-dragging] {
    box-shadow: var(--vds-shadow-md, 0 4px 8px rgba(0, 0, 0, 0.08));
  }
  .vds-data-table-customize-item-drag {
    all: unset;
    display: inline-flex;
    cursor: grab;
    color: var(--vds-color-text-subtle, #9ca3af);
    padding: 2px;
  }
  .vds-data-table-customize-item-drag:active {
    cursor: grabbing;
  }
  .vds-data-table-customize-item-icon {
    display: inline-flex;
    color: var(--vds-color-text-muted, #6b7280);
  }
  .vds-data-table-customize-item-label {
    flex: 1;
    font-size: var(--vds-text-sm, 0.875rem);
    color: var(--data-table-cell-color);
  }

  /* ───── Filter bar (chip row beneath the toolbar) ──────────── */
  .vds-data-table-filter-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--vds-space-1-5, 0.375rem);
    padding-inline: var(--vds-space-3, 0.75rem);
    padding-block: var(--vds-space-2, 0.5rem);
    background-color: var(--data-table-bg);
    border-block-end: var(--data-table-border-width) solid
      var(--data-table-border-color);
  }
  .vds-data-table-filter-bar[data-sticky] {
    position: sticky;
    inset-block-start: calc(
      var(--vds-sticky-top, 0px) +
        var(--vds-sticky-effective-offset-top, var(--vds-sticky-offset-top, 0px))
    );
    z-index: 7;
  }
  .vds-data-table-filter-bar:empty {
    display: none;
  }

  .vds-data-table-filter-chip {
    --chip-height: 1.5rem;
    --chip-padding-inline: var(--vds-space-2, 0.5rem);
    --chip-gap: var(--vds-space-1, 0.25rem);
    --chip-font-size: var(--vds-text-xs, 0.75rem);
    --chip-background: var(--data-table-toolbar-button-bg-hover);
    --chip-background-hover: color-mix(
      in oklch,
      var(--data-table-toolbar-button-bg-hover),
      var(--data-table-cell-color) 6%
    );
    --chip-border-color: var(--vds-color-border-muted, var(--vds-color-border, #d1d5db));
    --chip-text-color: var(--data-table-cell-color);
    cursor: pointer;
    transition: box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table-filter-chip:hover {
    --chip-background: var(--chip-background-hover);
  }
  .vds-data-table-filter-chip:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }
  .vds-data-table-filter-chip-label {
    color: var(--vds-color-text-muted, #9ca3af);
  }
  .vds-data-table-filter-chip-value {
    color: var(--data-table-cell-color);
    font-weight: var(--vds-font-weight-semibold, 600);
  }
  .vds-data-table-filter-chip .vds-chip-remove {
    color: var(--vds-color-text-muted, #9ca3af);
  }
  .vds-data-table-filter-chip .vds-chip-remove:hover {
    background-color: color-mix(
      in oklch,
      var(--data-table-cell-color),
      transparent 80%
    );
    color: var(--data-table-cell-color);
  }

  .vds-data-table-filter-add {
    all: unset;
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
    padding: 4px var(--vds-space-2-5, 0.625rem);
    color: var(--vds-color-text-muted, #9ca3af);
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-medium, 500);
    border-radius: 999px;
    cursor: pointer;
    transition: color var(--data-table-transition-duration)
      var(--data-table-transition-easing),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
  .vds-data-table-filter-add:hover {
    color: var(--data-table-cell-color);
    background-color: var(--data-table-toolbar-button-bg-hover);
  }
  .vds-data-table-filter-add:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  /* ───── Reduced motion ─────────────────────────────────────── */
  @media (prefers-reduced-motion: reduce) {
    .vds-data-table [data-sticky="smart"],
    .vds-data-table-row,
    .vds-data-table-sort-icon,
    .vds-pagination-button,
    .vds-pagination-page-button {
      transition: none;
    }
  }
}

@layer design-system.components {
  /*
   * Virtari DataTable — local component tokens.
   * Scoped to .vds-data-table. Every token declares a --vds-* fallback
   * plus a literal light-mode default so the package works standalone.
   *
   * State/variant redefinitions only REWRITE values — never set properties.
   */
  .vds-data-table {
    /* ── Font + layout ───────────────────────────────────────── */
    --data-table-font-family:
      var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    --data-table-font-size:            var(--vds-text-xs, 0.75rem);
    --data-table-line-height:          var(--vds-leading-tight, 1.35);
    --data-table-cell-padding-inline:  var(--vds-space-2, 0.5rem);
    --data-table-cell-padding-block:   var(--vds-space-1, 0.25rem);
    /* Density ramp (md default). The row must clear the tallest thing the
       package puts in a cell: a `sm` Avatar / `sm` Button, both 2rem, plus
       the block padding above and below. Header and footer track the body so
       the three never drift apart. */
    --data-table-row-height:           2.5rem;   /* 40px */
    --data-table-header-row-height:    var(--data-table-row-height);
    --data-table-footer-row-height:    var(--data-table-row-height);
    --data-table-col-min-width:        4rem;
    --data-table-col-default-width:    10rem;

    /* ── Surfaces ────────────────────────────────────────────── */
    --data-table-bg:                   var(--vds-color-surface, #ffffff);
    --data-table-header-bg:            var(--vds-color-surface, #ffffff);
    --data-table-row-bg:               var(--vds-color-surface, #ffffff);
    --data-table-row-bg-alt:           var(--vds-color-surface-raised, #f9fafb);
    --data-table-row-bg-hover:
      color-mix(
        in oklch,
        var(--vds-color-surface-hover, #f3f4f6),
        transparent 30%
      );
    --data-table-row-bg-selected:      var(--vds-color-primary-bg, #eef2ff);
    --data-table-row-bg-selected-hover:var(--vds-color-primary-bg, #eef2ff);
    --data-table-footer-bg:            var(--vds-color-surface-raised, #f9fafb);
    --data-table-sticky-bottom-bg:
      color-mix(
        in oklch,
        var(--data-table-footer-bg),
        var(--data-table-bg) 12%
      );
    --data-table-sticky-bottom-shadow:
      0 -1px 0 var(--data-table-border-color),
      0 -12px 24px -18px color-mix(
        in oklch,
        var(--data-table-cell-color),
        transparent 88%
      );
    --data-table-overlay-bg:           color-mix(
      in oklch,
      var(--vds-color-surface, #ffffff),
      transparent 20%
    );

    /* ── Borders ─────────────────────────────────────────────── */
    --data-table-border-width:         1px;
    --data-table-border-color:
      color-mix(
        in oklch,
        var(--vds-color-border-muted, #e5e7eb),
        transparent 35%
      );
    --data-table-border-color-strong:  var(--vds-color-border, #d1d5db);
    --data-table-header-divider-color:
      color-mix(
        in oklch,
        var(--vds-color-border-muted, #e5e7eb),
        transparent 20%
      );

    /* ── Typography ──────────────────────────────────────────── */
    --data-table-header-font-size:      var(--vds-text-xs, 0.75rem);
    --data-table-header-font-weight:    var(--vds-font-weight-medium, 500);
    --data-table-header-color:          var(--vds-color-text-muted, #6b7280);
    --data-table-header-letter-spacing: 0;
    --data-table-header-text-transform: none;
    --data-table-cell-color:            var(--vds-color-text, #111827);
    --data-table-footer-color:          var(--vds-color-text-muted, #6b7280);

    /* ── Radii ───────────────────────────────────────────────── */
    --data-table-radius: var(--vds-radius-data-table, 0.5rem);
    --data-table-shadow:
      var(--vds-surface-shadow, var(--vds-shadow-xl, 0 24px 48px -18px rgba(0, 0, 0, 0.42)));

    /* ── Motion ──────────────────────────────────────────────── */
    --data-table-transition-duration: var(--vds-duration-fast, 100ms);
    --data-table-transition-easing:
      var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* ── Focus (grid mode + sort triggers) ───────────────────── */
    --data-table-focus-ring-color:
      var(--vds-color-primary-solid, #6366f1);
    --data-table-focus-ring-width:  2px;
    --data-table-focus-ring-offset: -2px;
    /* How far past a cell's border box the clip box extends. Cell-level
     * affordances (row expand / pin, actions trigger, copy button, the inline
     * editor) draw their ring at `outline-offset: 2px`, so the clip has to
     * clear offset + ring or it slices the ring off. */
    --data-table-cell-clip-margin: calc(2px + var(--data-table-focus-ring-width));

    /* ── Sort trigger ────────────────────────────────────────── */
    --data-table-sort-icon-color:
      var(--vds-color-text-subtle, #9ca3af);
    --data-table-sort-icon-color-active:
      var(--vds-color-primary-solid, #6366f1);
    --data-table-sort-icon-opacity:        0.35;
    --data-table-sort-icon-opacity-active: 1;
    --data-table-sort-gap: var(--vds-space-1-5, 0.375rem);

    /* ── Selection cell width ────────────────────────────────── */
    --data-table-select-cell-size: 2.5rem;

    /* ── Global filter ───────────────────────────────────────── */
    --data-table-filter-bg:
      var(--vds-color-surface, #ffffff);
    --data-table-filter-border:
      var(--vds-color-border, #d1d5db);
    --data-table-filter-radius:
      var(--vds-radius-input, var(--vds-radius-element, 0.375rem));
    --data-table-filter-height: var(--vds-size-sm, 2rem);
    --data-table-filter-padding-inline: var(--vds-space-2-5, 0.625rem);
    --data-table-filter-font-size: var(--vds-text-sm, 0.875rem);
    --data-table-filter-placeholder-color:
      var(--vds-color-text-subtle, #9ca3af);

    /* ── Pinning ─────────────────────────────────────────────── */
    --data-table-pin-bg: var(--data-table-row-bg);
    --data-table-pin-header-bg: var(--data-table-header-bg);
    --data-table-pin-shadow-left: 4px 0 6px -4px color-mix(
      in oklch,
      var(--vds-color-border, #d1d5db),
      transparent 20%
    );
    --data-table-pin-shadow-right: -4px 0 6px -4px color-mix(
      in oklch,
      var(--vds-color-border, #d1d5db),
      transparent 20%
    );

    /* ── Resize ──────────────────────────────────────────────── */
    --data-table-resize-hit-width: 8px;
    --data-table-resize-line-width: 1px;
    --data-table-resize-line-width-active: 2px;
    --data-table-resize-line-color: transparent;
    --data-table-resize-line-color-hover:
      var(--vds-color-border, #d1d5db);
    --data-table-resize-line-color-active:
      var(--vds-color-primary-solid, #6366f1);
    --data-table-guideline-color:
      var(--vds-color-primary-solid, #6366f1);
    --data-table-guideline-width: 1px;
    --data-table-guideline-offset: 0px;

    /* ── v2: View mode toggle ────────────────────────────────── */
    --data-table-view-toggle-bg:
      var(--vds-color-surface-raised, #f9fafb);
    --data-table-view-toggle-border:
      var(--vds-color-border-muted, #e5e7eb);
    --data-table-view-toggle-radius:
      var(--vds-radius-segmented, var(--vds-radius-element, 0.375rem));
    --data-table-view-toggle-button-color:
      var(--vds-color-text-muted, #6b7280);
    --data-table-view-toggle-button-color-active:
      var(--vds-color-text, #111827);
    --data-table-view-toggle-button-bg-active:
      var(--vds-color-surface, #ffffff);
    --data-table-view-toggle-label-offset: 0px;

    /* ── v2: Board view ──────────────────────────────────────── */
    --data-table-board-gap: var(--vds-space-3, 0.75rem);
    --data-table-board-card-min-width: 15rem;
    --data-table-board-card-padding: var(--vds-space-3, 0.75rem);
    --data-table-board-card-bg:
