    --data-table-board-card-border:
      var(--vds-color-border-muted, #e5e7eb);
    --data-table-board-card-radius:
      var(--vds-radius-card, 0.5rem);
    --data-table-board-card-shadow:
      var(--vds-shadow-sm, 0 1px 2px rgba(0, 0, 0, 0.04));

    /* ── v2: List view ───────────────────────────────────────── */
    --data-table-list-item-padding-block: var(--vds-space-2, 0.5rem);
    --data-table-list-item-padding-inline: var(--vds-space-3, 0.75rem);
    --data-table-list-divider:
      var(--vds-color-border-muted, #e5e7eb);

    /* ── v2: BulkActions bar ─────────────────────────────────── */
    --data-table-bulk-bg:
      var(--vds-color-surface, #ffffff);
    --data-table-bulk-border:
      var(--vds-color-border-muted, #e5e7eb);
    --data-table-bulk-padding-inline:
      var(--vds-space-4, 1rem);
    --data-table-bulk-padding-block:
      var(--vds-space-3, 0.75rem);
    --data-table-bulk-gap: var(--vds-space-3, 0.75rem);
    --data-table-bulk-count-color:
      var(--vds-color-primary-solid, #6366f1);

    /* Select-all-across-pages banner */
    --data-table-select-all-bg:
      color-mix(
        in oklch,
        var(--vds-color-primary-solid, #6366f1),
        transparent 92%
      );
    --data-table-select-all-color:
      var(--vds-color-text, #111827);

    /* ── v2: Toolbar buttons ─────────────────────────────────── */
    --data-table-toolbar-button-bg: transparent;
    --data-table-toolbar-button-bg-hover:
      var(--vds-color-surface-hover, #f3f4f6);
    --data-table-toolbar-button-color:
      var(--vds-color-text, #111827);
    --data-table-toolbar-button-color-primary:
      var(--vds-color-primary-solid, #6366f1);
    --data-table-toolbar-button-color-danger:
      var(--vds-color-danger-solid, #dc2626);
    --data-table-toolbar-button-radius:
      var(--vds-radius-button, var(--vds-radius-element, 0.375rem));
    --data-table-toolbar-button-padding-inline: var(--vds-space-2-5, 0.625rem);
    --data-table-toolbar-button-height: var(--vds-size-sm, 2rem);
    --data-table-toolbar-button-font-size: var(--vds-text-sm, 0.875rem);
    --data-table-toolbar-button-gap: var(--vds-space-1-5, 0.375rem);

    /* ── Pagination ──────────────────────────────────────────── */
    --data-table-pagination-bg:
      var(--data-table-footer-bg);
    --data-table-pagination-padding-inline: var(--vds-space-4, 1rem);
    --data-table-pagination-padding-block:  var(--vds-space-2, 0.5rem);
    --data-table-pagination-gap: var(--vds-space-2, 0.5rem);
    --data-table-pagination-button-size: var(--vds-size-md, 2.25rem);
    --data-table-pagination-sticky-offset: 0px;
    --data-table-bulk-sticky-offset: 0px;
    --data-table-pagination-button-bg: transparent;
    --data-table-pagination-button-bg-hover:
      var(--vds-color-surface-hover, #f3f4f6);
    --data-table-pagination-button-bg-active:
      var(--vds-color-primary-bg, #eef2ff);
    --data-table-pagination-button-color:
      var(--vds-color-text, #111827);
    --data-table-pagination-button-color-active:
      var(--vds-color-primary-solid, #6366f1);
    --data-table-pagination-button-radius:
      var(--vds-radius-pagination-button, var(--vds-radius-element, 0.375rem));
  }

  /* ── Density ─────────────────────────────────────────────── */
  .vds-data-table[data-size="sm"] {
    --data-table-row-height:           2rem;     /* 32px */
    --data-table-cell-padding-inline:  var(--vds-space-2-5, 0.625rem);
    --data-table-cell-padding-block:   var(--vds-space-0-5, 0.125rem);
    --data-table-font-size:            var(--vds-text-xs, 0.75rem);
    --data-table-header-letter-spacing: 0;
  }
  /* No [data-size="md"] block: the base already is md (40px row height), so a
   * block here would only restate it and give the ramp a second source of
   * truth to drift from. The ramp is 32 / 40 / 48. */
  .vds-data-table[data-size="lg"] {
    --data-table-row-height:          3rem;      /* 48px */
    --data-table-cell-padding-inline: var(--vds-space-3, 0.75rem);
    --data-table-cell-padding-block:  var(--vds-space-1-5, 0.375rem);
    --data-table-font-size:           var(--vds-text-sm, 0.875rem);
  }

  /* ── Zebra opt-in ────────────────────────────────────────── */
  .vds-data-table[data-striped] .vds-data-table-row:nth-child(even) {
    --data-table-row-bg: var(--data-table-row-bg-alt);
  }

  /* ── Row states ──────────────────────────────────────────── */
  .vds-data-table-row:hover {
    --data-table-row-bg: var(--data-table-row-bg-hover);
  }
  .vds-data-table-row[aria-selected="true"] {
    --data-table-row-bg: var(--data-table-row-bg-selected);
  }
  .vds-data-table-row[aria-selected="true"]:hover {
    --data-table-row-bg: var(--data-table-row-bg-selected-hover);
  }

  /* ── Sort state: fade-in icon + accent ─────────────────────── */
  .vds-data-table-header-cell:hover .vds-data-table-sort-icon,
  .vds-data-table-header-cell[data-sorted] .vds-data-table-sort-icon {
    --data-table-sort-icon-opacity: var(--data-table-sort-icon-opacity-active);
  }
  .vds-data-table-header-cell[data-sorted] .vds-data-table-sort-icon {
    --data-table-sort-icon-color: var(--data-table-sort-icon-color-active);
  }

  /* ── Resize states ───────────────────────────────────────── */
  .vds-data-table-resize-handle:hover,
  .vds-data-table-resize-handle:focus-visible {
    --data-table-resize-line-color:
      var(--data-table-resize-line-color-hover);
  }
  .vds-data-table-resize-handle[data-resizing] {
    --data-table-resize-line-color:
      var(--data-table-resize-line-color-active);
    --data-table-resize-line-width:
      var(--data-table-resize-line-width-active);
  }

  /* Disable width transitions while dragging so it snaps frame-perfect. */
  .vds-data-table[data-resizing] {
    --data-table-transition-duration: 0ms;
  }
}

