/* ────────────────────────────────────────────────────────────
 * Root
 * ──────────────────────────────────────────────────────────── */

type DataTableRootOwnProps = {
  size?: DataTableSize;
  interactionMode?: DataTableInteractionMode;
  bordered?: DataTableBorderMode;
  striped?: boolean;
  stickyHeader?: boolean;
  /** Base top offset for top sticky bands (toolbar, filter-bar, header).
   * Useful when the page has an outer
   * fixed/sticky chrome — e.g. an app header — that sticky bands must clear.
   * In nested scroll containers the offset is normalized against the scrollport's
   * actual viewport position so it does not create an initial gap if that
   * scrollport already sits below the page chrome.
   * Individual top bands can still override with their own `stickyOffset`. */
  stickyOffset?: CSSProperties["top"];
  /** Base bottom offset for bottom sticky bands (bulk actions, pagination, footer).
   * Like `stickyOffset`, this is normalized inside nested scroll containers. */
  stickyBottomOffset?: CSSProperties["bottom"];
  mode?: DataTableMode;
  virtualization?: false | DataTableVirtualizationOptions;
  columnResizeMode?: "onChange" | "onEnd";
  rowCount?: number;
  viewMode?: DataTableViewMode;
  defaultViewMode?: DataTableViewMode;
  onViewModeChange?: (mode: DataTableViewMode) => void;
  onDataRequest?: (state: DataTableServerRequestState) => void;
  onCellEdit?: (
    row: Row<unknown>,
    columnId: string,
    nextValue: unknown,
  ) => void | Promise<void>;
  id?: string;
  className?: string;
  style?: CSSProperties;
  children?: ReactNode;
} & DataTableStatePairs;

type AdvancedProps<TData> = {
  table: Table<TData>;
  columns?: never;
  data?: never;
};

type SimpleProps<TData, TValue = unknown> = {
  table?: never;
  columns: ColumnDef<TData, TValue>[];
  data: TData[];
};

export type DataTableRootProps<TData, TValue = unknown> =
  DataTableRootOwnProps & (AdvancedProps<TData> | SimpleProps<TData, TValue>);

/* Shared renderer that takes a fully-built TanStack table instance. */
function DataTableRootRender<TData>({
  table,
  size,
  interactionMode,
  bordered,
  striped,
  stickyHeader,
  stickyOffset,
  stickyBottomOffset,
  mode,
  virtualization,
  columnResizeMode,
  rowCount,
  viewMode,
  defaultViewMode,
  onViewModeChange,
  onCellEdit,
  onDataRequest,
  id,
  className,
  style,
  children,
  forwardedRef,
}: {
  table: Table<TData>;
  size: DataTableSize;
  interactionMode: DataTableInteractionMode;
  bordered: DataTableBorderMode;
  striped: boolean;
  stickyHeader: boolean;
  stickyOffset: CSSProperties["top"] | undefined;
  stickyBottomOffset: CSSProperties["bottom"] | undefined;
  mode: DataTableMode;
  virtualization: false | DataTableVirtualizationOptions;
  columnResizeMode: "onChange" | "onEnd";
  rowCount: number | undefined;
  viewMode?: DataTableViewMode;
  defaultViewMode?: DataTableViewMode;
  onViewModeChange?: (mode: DataTableViewMode) => void;
  onCellEdit?: (
    row: Row<TData>,
    columnId: string,
    next: unknown,
  ) => void | Promise<void>;
  onDataRequest?: (state: DataTableServerRequestState) => void;
  id: string | undefined;
  className: string | undefined;
  style: CSSProperties | undefined;
  children: ReactNode;
  forwardedRef: React.Ref<HTMLDivElement>;
}) {
  const [viewModeState, setViewMode] = useControllableState<DataTableViewMode>({
    value: viewMode,
    defaultValue: defaultViewMode ?? "table",
    onChange: onViewModeChange,
  });
  /* Stage 11 — server-side mode: fire onDataRequest whenever any server-driven
   * state changes. Debounced 150ms to avoid firing on every key press. */
  useEffect(() => {
    if (mode !== "server" || !onDataRequest) return;
    const id = window.setTimeout(() => {
      const s = table.getState();
      onDataRequest({
        sorting: s.sorting,
        columnFilters: s.columnFilters,
        globalFilter: s.globalFilter ?? "",
        pagination: s.pagination,
        grouping: s.grouping,
      });
    }, 150);
    return () => window.clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    mode,
    onDataRequest,
    table.getState().sorting,
    table.getState().columnFilters,
    table.getState().globalFilter,
    table.getState().pagination,
    table.getState().grouping,
  ]);

  return (
    <DataTableProvider<TData>
      id={id}
      table={table}
      size={size}
      interactionMode={interactionMode}
      bordered={bordered}
      striped={striped}
      stickyHeader={stickyHeader}
      mode={mode}
      virtualization={virtualization}
      columnResizeMode={columnResizeMode}
      rowCount={rowCount}
      viewMode={viewModeState}
      setViewMode={setViewMode}
      onCellEdit={onCellEdit}
      onDataRequest={onDataRequest}
    >
      <DataTableRootDiv
        className={className}
        style={style}
        size={size}
        interactionMode={interactionMode}
        bordered={bordered}
        striped={striped}
        stickyHeader={stickyHeader}
        stickyOffset={stickyOffset}
        stickyBottomOffset={stickyBottomOffset}
        mode={mode}
        virtualization={virtualization}
        forwardedRef={forwardedRef}
      >
        {children}
      </DataTableRootDiv>
    </DataTableProvider>
  );
}

/** Compute sticky-offset style for a pinned column cell. Returns empty
 * object for non-pinned columns. Uses TanStack's cumulative getStart/getAfter.
 */
function pinOffsetStyle(column: Column<unknown, unknown>): CSSProperties {
  const pinned = column.getIsPinned();
  if (pinned === "left") {
    return { left: `${column.getStart("left")}px` };
  }
  if (pinned === "right") {
    return { right: `${column.getAfter("right")}px` };
  }
  return {};
}

/** Inner div split so we can read context (resizing flag) next to the DOM. */
function DataTableRootDiv({
  size,
  interactionMode,
  bordered,
  striped,
  stickyHeader,
  stickyOffset,
  stickyBottomOffset,
  mode,
  virtualization,
  className,
  style,
  children,
  forwardedRef,
}: {
  size: DataTableSize;
  interactionMode: DataTableInteractionMode;
  bordered: DataTableBorderMode;
  striped: boolean;
  stickyHeader: boolean;
  stickyOffset: CSSProperties["top"] | undefined;
  stickyBottomOffset: CSSProperties["bottom"] | undefined;
  mode: DataTableMode;
  virtualization: false | DataTableVirtualizationOptions;
  className: string | undefined;
  style: CSSProperties | undefined;
  children: ReactNode;
  forwardedRef: React.Ref<HTMLDivElement>;
}) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const { table, scrollRef } = useDataTableContext();
  const resizingId = table.getState().columnSizingInfo.isResizingColumn as
    | string
    | false;
  const scrolledX = useHorizontalScrollShadow(scrollRef);
  useDataTableStickyStack(rootRef);
  useKeyboardGridNav(interactionMode === "grid", scrollRef);
  const announcement = useSrAnnouncements(table);
  const rootStyle =
    stickyOffset === undefined && stickyBottomOffset === undefined
      ? style
      : ({
          ...(stickyOffset !== undefined
            ? { ["--vds-sticky-offset-top" as string]: stickyOffset }
            : null),
          ...(stickyBottomOffset !== undefined
            ? { ["--vds-sticky-offset-bottom" as string]: stickyBottomOffset }
            : null),
          ...style,
        } as CSSProperties);
  return (
    <div
      ref={composeRefs(rootRef, forwardedRef)}
      className={cn("vds-data-table", className)}
      data-size={size}
      data-interaction-mode={interactionMode}
      data-bordered={bordered}
      data-striped={boolAttr(striped)}
      data-sticky-header={boolAttr(stickyHeader)}
      data-mode={mode}
      data-virtualized={boolAttr(virtualization !== false)}
      data-resizing={resizingId ? "" : undefined}
      data-scrolled-x={scrolledX}
      style={rootStyle}
    >
      {children}
      {/* Stage 15: screen-reader announcements for sort/filter/selection. */}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="vds-data-table-sr-only"
      >
        {announcement}
      </div>
    </div>
  );
}

/* Simple-API branch: builds the table internally. */
function DataTableSimpleRoot<TData, TValue>({
  columns,
  data,
  size = "md",
  interactionMode = "table",
  bordered = "rows",
  striped = false,
  stickyHeader = true,
  stickyOffset,
  stickyBottomOffset,
  mode = "client",
  virtualization = false,
  columnResizeMode = "onChange",
  rowCount,
  viewMode,
  defaultViewMode,
  onViewModeChange,
  onCellEdit,
  onDataRequest,
  id,
  className,
  style,
  children,
  forwardedRef,
  ...statePairs
}: DataTableRootOwnProps &
  SimpleProps<TData, TValue> & {
    forwardedRef: React.Ref<HTMLDivElement>;
  }) {
  const table = useDataTable<TData, TValue>({
    columns,
    data,
    mode,
    columnResizeMode,
    rowCount,
    ...(statePairs as DataTableStatePairs),
  });
  return (
    <DataTableRootRender<TData>
      table={table}
      size={size}
      interactionMode={interactionMode}
      bordered={bordered}
      striped={striped}
      stickyHeader={stickyHeader}
      stickyOffset={stickyOffset}
      stickyBottomOffset={stickyBottomOffset}
      mode={mode}
      virtualization={virtualization}
      columnResizeMode={columnResizeMode}
      rowCount={rowCount}
      viewMode={viewMode}
      defaultViewMode={defaultViewMode}
      onViewModeChange={onViewModeChange}
      onCellEdit={
        onCellEdit as
          | ((row: Row<TData>, columnId: string, next: unknown) => void | Promise<void>)
          | undefined
      }
      onDataRequest={onDataRequest}
      id={id}
      className={className}
      style={style}
      forwardedRef={forwardedRef}
    >
      {children}
    </DataTableRootRender>
  );
}

/* Advanced-API branch: consumer passes the table. */
function DataTableAdvancedRoot<TData>({
  table,
  size = "md",
  interactionMode = "table",
  bordered = "rows",
  striped = false,
  stickyHeader = true,
  stickyOffset,
  stickyBottomOffset,
  mode = "client",
  virtualization = false,
  columnResizeMode = "onChange",
  rowCount,
  viewMode,
  defaultViewMode,
  onViewModeChange,
  onCellEdit,
  onDataRequest,
