import { useState } from "react";
import { Button } from "@virtari-packages/react-button";
import { Input } from "@virtari-packages/react-input";
import { cn } from "@virtari-packages/utils";

import type {
  ComparisonOperator,
  FilterCondition,
  FilterFieldDefinition,
} from "./types";

const OPERATORS_BY_TYPE: Record<
  FilterFieldDefinition["type"],
  { value: ComparisonOperator; label: string }[]
> = {
  text: [
    { value: "contains", label: "Contains" },
    { value: "notContains", label: "Does not contain" },
    { value: "equals", label: "Equals" },
    { value: "notEquals", label: "Does not equal" },
  ],
  number: [
    { value: "equals", label: "Equals" },
    { value: "notEquals", label: "Not equal" },
    { value: "greaterThan", label: "Greater than" },
    { value: "lessThan", label: "Less than" },
    { value: "between", label: "Between" },
  ],
  date: [
    { value: "equals", label: "On" },
    { value: "greaterThan", label: "After" },
    { value: "lessThan", label: "Before" },
    { value: "between", label: "Between" },
  ],
  "date-range": [{ value: "between", label: "Between" }],
  select: [
    { value: "equals", label: "Is" },
    { value: "notEquals", label: "Is not" },
  ],
  boolean: [{ value: "equals", label: "Is" }],
};

export interface FilterConfigPanelProps {
  field: FilterFieldDefinition;
  onAdd: (cond: FilterCondition) => void;
  onCancel: () => void;
}

export function FilterConfigPanel({
  field,
  onAdd,
  onCancel,
}: FilterConfigPanelProps) {
  const operators = OPERATORS_BY_TYPE[field.type];
  const [comparison, setComparison] = useState<ComparisonOperator>(
    operators[0]!.value,
  );
  const [value, setValue] = useState<string>("");
  const [value2, setValue2] = useState<string>("");

  const canAdd =
    comparison === "between"
      ? value !== "" && value2 !== ""
      : value !== "" || field.type === "boolean";

  const handleAdd = () => {
    const cond: FilterCondition = {
      id: `cond-${Date.now()}`,
      fieldId: field.id,
      fieldLabel: field.label,
      comparison,
      value:
        field.type === "number" ? Number(value) :
        field.type === "boolean" ? value === "true" :
        value,
      value2:
        comparison === "between"
          ? field.type === "number"
            ? Number(value2)
            : value2
          : undefined,
    };
    onAdd(cond);
  };

  return (
    <div className="vds-data-table-filter-config">
      <div className="vds-data-table-filter-config-row">
        <label className="vds-data-table-filter-config-label">Operator</label>
        <select
          value={comparison}
          onChange={(e) => setComparison(e.target.value as ComparisonOperator)}
          className="vds-data-table-filter-config-select"
        >
          {operators.map((op) => (
            <option key={op.value} value={op.value}>
              {op.label}
            </option>
          ))}
        </select>
      </div>

      <div className="vds-data-table-filter-config-row">
        <label className="vds-data-table-filter-config-label">Value</label>
        {field.type === "select" ? (
          <select
            value={String(value)}
            onChange={(e) => setValue(e.target.value)}
            className="vds-data-table-filter-config-select"
          >
            <option value="">—</option>
            {(field.options ?? []).map((opt) => (
              <option key={String(opt.value)} value={String(opt.value)}>
                {opt.label}
              </option>
            ))}
          </select>
        ) : field.type === "boolean" ? (
          <select
            value={value}
            onChange={(e) => setValue(e.target.value)}
            className="vds-data-table-filter-config-select"
          >
            <option value="true">True</option>
            <option value="false">False</option>
          </select>
        ) : (
          <Input
            inputSize="sm"
            type={field.type === "number" ? "number" : field.type === "date" ? "date" : "text"}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            placeholder={field.placeholder}
          />
        )}
      </div>

      {comparison === "between" && (
        <div className="vds-data-table-filter-config-row">
          <label className="vds-data-table-filter-config-label">And</label>
          <Input
            inputSize="sm"
            type={field.type === "number" ? "number" : field.type === "date" ? "date" : "text"}
            value={value2}
            onChange={(e) => setValue2(e.target.value)}
          />
        </div>
      )}

      <div className="vds-data-table-filter-config-actions">
        <Button
          onClick={onCancel}
          variant="ghost"
          color="contrast"
          size="sm"
          className={cn(
            "vds-data-table-toolbar-button",
            "vds-data-table-filter-config-cancel",
          )}
        >
          Cancel
        </Button>
        <Button
          onClick={handleAdd}
          disabled={!canAdd}
          data-intent="primary"
          variant="solid"
          color="primary"
          size="sm"
          className={cn("vds-data-table-toolbar-button")}
        >
          Add filter
        </Button>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from "react";
import {
  Drawer,
  DrawerBody,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
} from "@virtari-packages/react-drawer";
import { Button } from "@virtari-packages/react-button";
import { Chip, ChipLabel, ChipRemove } from "@virtari-packages/react-chip";
import { Input } from "@virtari-packages/react-input";
import { Switch } from "@virtari-packages/react-switch";
import { cn } from "@virtari-packages/utils";
import { IconChevronLeft } from "@virtari-packages/react-icons";

import { FilterConfigPanel } from "./FilterConfigPanel";
import type {
  FilterCondition,
  FilterFieldDefinition,
  FilterGroup,
} from "./types";
import { countConditions } from "./types";

export interface DataTableFilterDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Fields the user can add conditions against. */
  availableFilters: FilterFieldDefinition[];
  /** Currently-active filter groups (controlled). */
  filterGroups?: FilterGroup[];
  /** Fired on Apply. */
  onApplyFilters: (groups: FilterGroup[]) => void;
  title?: string;
  /** Drawer side. Default "right". */
  side?: "left" | "right" | "top" | "bottom";
}

export function DataTableFilterDrawer({
  open,
  onOpenChange,
  availableFilters,
  filterGroups: externalGroups = [],
  onApplyFilters,
  title = "Filters",
  side = "right",
}: DataTableFilterDrawerProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [groups, setGroups] = useState<FilterGroup[]>(externalGroups);
  const [configField, setConfigField] = useState<FilterFieldDefinition | null>(
    null,
  );

  /* Re-sync internal state each time the drawer opens. */
  const prevOpenRef = useRef(false);
  useEffect(() => {
    if (open && !prevOpenRef.current) {
      setGroups(externalGroups);
      setSearchQuery("");
      setConfigField(null);
    }
    prevOpenRef.current = open;
  }, [open, externalGroups]);

  const filteredFields = useMemo(() => {
    if (!searchQuery.trim()) return availableFilters;
    const q = searchQuery.toLowerCase();
    return availableFilters.filter(
      (f) => f.label.toLowerCase().includes(q) || f.id.toLowerCase().includes(q),
    );
  }, [availableFilters, searchQuery]);

  const shown = filteredFields.filter(
    (f) => f.category === "shown" || !f.category,
  );
  const popular = filteredFields.filter((f) => f.category === "popular");
  const activeCount = countConditions(groups);

  const hasActive = (fieldId: string) =>
    groups.some((g) => g.conditions.some((c) => c.fieldId === fieldId));

  const addCondition = (cond: FilterCondition) => {
    setGroups((prev) => {
      if (prev.length === 0) {
        return [
          {
            id: `group-${Date.now()}`,
            operator: "AND",
            conditions: [cond],
          },
        ];
      }
      const next = [...prev];
      next[next.length - 1]!.conditions.push(cond);
      return next;
    });
    setConfigField(null);
  };

  const removeCondition = (groupId: string, conditionId: string) => {
    setGroups((prev) =>
      prev
        .map((g) =>
          g.id === groupId
            ? {
                ...g,
                conditions: g.conditions.filter((c) => c.id !== conditionId),
              }
            : g,
        )
        .filter((g) => g.conditions.length > 0),
    );
  };

  const toggleOperator = (groupId: string) => {
    setGroups((prev) =>
      prev.map((g) =>
        g.id === groupId
          ? { ...g, operator: g.operator === "AND" ? "OR" : "AND" }
          : g,
      ),
    );
  };

  const handleApply = () => {
    onApplyFilters(groups);
    onOpenChange(false);
  };

  const handleClear = () => {
    setGroups([]);
    onApplyFilters([]);
    onOpenChange(false);
  };

  return (
    <Drawer
      direction={side}
      open={open}
      onOpenChange={onOpenChange}
      sizeMode="fixed"
      size="min(26rem, 95vw)"
    >
      <DrawerContent
        className="vds-data-table-filter-drawer"
        aria-label={title}
      >
        <DrawerHeader>
          <div className="vds-data-table-filter-drawer-header">
            {configField && (
              <button
                type="button"
                onClick={() => setConfigField(null)}
                aria-label="Back"
                className="vds-data-table-filter-drawer-back"
              >
                <IconChevronLeft size={14} stroke={1.75} aria-hidden focusable={false} />
              </button>
            )}
            <DrawerTitle>{configField ? configField.label : title}</DrawerTitle>
            {!configField && activeCount > 0 && (
              <span className="vds-data-table-filter-drawer-count">
                {activeCount}
              </span>
            )}
          </div>
        </DrawerHeader>

        <DrawerBody>
          {!configField ? (
            <div className="vds-data-table-filter-drawer-body">
              <Input
                inputSize="md"
                type="search"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search filters..."
              />

              {activeCount > 0 && (
                <div className="vds-data-table-filter-drawer-active">
                  <div className="vds-data-table-filter-drawer-active-header">
                    <span>Active ({activeCount})</span>
                    <button
                      type="button"
                      onClick={handleClear}
                      className="vds-data-table-filter-drawer-clear"
                    >
                      Clear all
                    </button>
                  </div>
                  {groups.map((group, gi) => (
                    <div key={group.id} className="vds-data-table-filter-drawer-group">
                      {gi > 0 && (
                        <button
                          type="button"
                          onClick={() => toggleOperator(group.id)}
                          className="vds-data-table-filter-drawer-operator"
                        >
                          {group.operator}
                        </button>
                      )}
                      {group.conditions.map((c) => (
                        <Chip
                          key={c.id}
                          size="sm"
                          appearance="outline"
                          variant="primary"
                          className="vds-data-table-filter-drawer-chip"
                        >
                          <ChipLabel>
                            {c.fieldLabel}: {String(c.value)}
                          </ChipLabel>
                          <ChipRemove
                            onClick={() => removeCondition(group.id, c.id)}
                            aria-label={`Remove ${c.fieldLabel} filter`}
                          />
                        </Chip>
                      ))}
                    </div>
                  ))}
                </div>
              )}

              {shown.length > 0 && (
                <FilterSection
                  title="Shown"
                  fields={shown}
                  hasActive={hasActive}
                  onPick={setConfigField}
                />
              )}
              {popular.length > 0 && (
                <FilterSection
                  title="Popular"
                  fields={popular}
                  hasActive={hasActive}
                  onPick={setConfigField}
                />
              )}
            </div>
          ) : (
            <FilterConfigPanel
              field={configField}
              onAdd={addCondition}
              onCancel={() => setConfigField(null)}
            />
          )}
        </DrawerBody>

        {!configField && (
          <DrawerFooter>
            <div className="vds-data-table-filter-drawer-footer">
              <Button
                onClick={() => onOpenChange(false)}
                variant="ghost"
                color="contrast"
                size="sm"
                className="vds-data-table-toolbar-button"
              >
                Cancel
              </Button>
              <Button
                onClick={handleApply}
                disabled={activeCount === 0}
                data-intent="primary"
                variant="solid"
                color="primary"
                size="sm"
                className="vds-data-table-toolbar-button"
              >
                Apply
              </Button>
            </div>
          </DrawerFooter>
        )}
      </DrawerContent>
    </Drawer>
  );
}

function FilterSection({
  title,
  fields,
  hasActive,
  onPick,
}: {
  title: string;
  fields: FilterFieldDefinition[];
  hasActive: (fieldId: string) => boolean;
  onPick: (f: FilterFieldDefinition) => void;
}) {
  return (
    <div className="vds-data-table-filter-drawer-section">
      <div className="vds-data-table-filter-drawer-section-title">{title}</div>
      <div className="vds-data-table-filter-drawer-fields">
        {fields.map((field) => (
          <div
            key={field.id}
            role="button"
            tabIndex={0}
            onClick={() => onPick(field)}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onPick(field);
              }
            }}
            className={cn("vds-data-table-filter-drawer-field")}
            data-active={hasActive(field.id) ? "" : undefined}
          >
            <span className="vds-data-table-filter-drawer-field-left">
              {field.icon && <span>{field.icon}</span>}
              <span>{field.label}</span>
            </span>
            <Switch
              checked={hasActive(field.id)}
              onCheckedChange={() => onPick(field)}
              aria-label={`Toggle ${field.label}`}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

