}

export type ComparisonOperator =
  | "equals"
  | "notEquals"
  | "contains"
  | "notContains"
  | "greaterThan"
  | "lessThan"
  | "between";

export interface FilterCondition {
  id: string;
  fieldId: string;
  fieldLabel: string;
  comparison: ComparisonOperator;
  value: unknown;
