  .vds-slot-counter {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-inline-size: 1ch;
    line-height: 1.1;
    overflow: hidden;
    vertical-align: baseline;
  }

  .vds-slot-counter-current,
  .vds-slot-counter-prev {
    display: inline-block;
    white-space: nowrap;
    will-change: transform, opacity;
