  .vds-slot-counter-prev {
    position: absolute;
    inset-inline-start: 0;
    inset-block-start: 0;
  }

  .vds-slot-counter[data-direction="up"] .vds-slot-counter-current {
    animation: vds-slot-in-up 260ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
  }
  .vds-slot-counter[data-direction="up"] .vds-slot-counter-prev {
    animation: vds-slot-out-up 260ms cubic-bezier(0.4, 0, 0.8, 0.4) both;
  }
  .vds-slot-counter[data-direction="down"] .vds-slot-counter-current {
    animation: vds-slot-in-down 260ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
  }
  .vds-slot-counter[data-direction="down"] .vds-slot-counter-prev {
    animation: vds-slot-out-down 260ms cubic-bezier(0.4, 0, 0.8, 0.4) both;
  }

  @keyframes vds-slot-in-up {
    from { transform: translateY(85%); opacity: 0; }
    60%  { opacity: 1; }
    to   { transform: translateY(0); opacity: 1; }
  }
  @keyframes vds-slot-out-up {
    from { transform: translateY(0); opacity: 1; }
    to   { transform: translateY(-90%); opacity: 0; }
  }
  @keyframes vds-slot-in-down {
    from { transform: translateY(-85%); opacity: 0; }
    60%  { opacity: 1; }
    to   { transform: translateY(0); opacity: 1; }
  }
  @keyframes vds-slot-out-down {
    from { transform: translateY(0); opacity: 1; }
    to   { transform: translateY(90%); opacity: 0; }
