  .vds-calendar-selector-item[data-selected="true"] {
    background: var(--calendar-cell-selected-bg);
    color: var(--calendar-cell-selected-text);
  }

  .vds-calendar-wheel-view {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-3, 0.75rem);
    inline-size: 100%;
    min-inline-size: 0;
    min-block-size: 0;
  }

  .vds-calendar-year-wheel {
    /* Hoist the wheel-geometry tokens here so they are defined regardless
     * of whether the calendar sits inside a TimeField / DatePicker scope.
     * Without these, the ::before/::after spacers on the wheel track
     * collapse to zero and the tail end of the list becomes unreachable. */
    --time-picker-wheel-height: 11rem;
    --time-picker-wheel-item-height: 2.5rem;
    /* Hoisted for the same reason as the rest of this block: the selection
       band below reads it, and a standalone <Calendar> is outside the
       DateField token scope that normally declares it. */
    --time-picker-surface-inner-radius: var(--vds-radius-time-picker-inner, 0.5rem);
    --time-picker-wheel-font-size: var(--vds-text-lg, 1.125rem);
    --time-picker-wheel-muted-text: var(--vds-color-text-muted, #6b7280);
    --time-picker-wheel-hover-text: color-mix(
      in oklab,
      var(--vds-color-text, #111827) 72%,
      var(--vds-color-text-muted, #6b7280)
    );
    --time-picker-wheel-selected-text: var(--vds-color-text, #111827);
    --time-picker-wheel-selection-bg: color-mix(
      in oklab,
      var(--vds-color-ring, var(--vds-color-primary-9, #6366f1)) 18%,
      transparent
    );
    --vds-year-wheel-height: var(--time-picker-wheel-height);
    position: relative;
    display: flex;
    justify-content: stretch;
    align-items: stretch;
    inline-size: 100%;
    block-size: var(--vds-year-wheel-height);
    padding: 0;
    background: transparent;
    overflow: hidden;
  }

  .vds-calendar-year-wheel::before {
    content: "";
    position: absolute;
    z-index: 1;
    inset-inline: var(--vds-space-1, 0.25rem);
    inset-block-start: calc(50% - (var(--time-picker-wheel-item-height) / 2));
    block-size: var(--time-picker-wheel-item-height);
    /* Same band as .vds-time-picker-wheels::before in DateField.css — see the
       note there. Uses the purpose-built token instead of a raw primitive. */
    border-radius: var(--time-picker-surface-inner-radius);
    background: var(--time-picker-wheel-selection-bg);
    pointer-events: none;
  }

  .vds-calendar-year-wheel .vds-time-wheel {
    flex: 1 1 auto;
    min-inline-size: 0;
    max-inline-size: none;
    inline-size: 100%;
  }

  .vds-calendar-year-wheel .vds-time-wheel-track {
    block-size: var(--vds-year-wheel-height);
  }

  .vds-calendar-year-wheel .vds-time-wheel-track::before,
  .vds-calendar-year-wheel .vds-time-wheel-track::after {
    flex: 0 0 calc((var(--vds-year-wheel-height) - var(--time-picker-wheel-item-height)) / 2);
  }

  .vds-calendar-year-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--vds-space-2, 0.5rem);
  }

  .vds-calendar-year-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    block-size: var(--vds-size-md, 2.25rem);
    padding-inline: var(--vds-space-3, 0.75rem);
    border: 1px solid transparent;
    border-radius: var(--vds-radius-action, var(--vds-radius-element, 0.5rem));
    font: inherit;
    font-size: var(--vds-text-sm, 0.875rem);
    font-weight: var(--vds-font-weight-medium, 500);
    cursor: pointer;
    transition:
      background-color var(--date-field-transition-duration) var(--date-field-transition-easing),
      color var(--date-field-transition-duration) var(--date-field-transition-easing),
      border-color var(--date-field-transition-duration) var(--date-field-transition-easing),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-calendar-year-action--secondary {
    background: var(--vds-color-bg-subtle, #f3f4f6);
    color: var(--vds-color-text, #111827);
  }

  .vds-calendar-year-action--secondary:hover {
    background: var(--vds-color-bg-muted, #e5e7eb);
  }

  .vds-calendar-year-action--primary {
    background: var(--vds-color-primary-10, #4f46e5);
    color: var(--vds-color-primary-contrast, #ffffff);
  }

  .vds-calendar-year-action--primary:hover {
    background: var(--vds-color-primary-11, #4338ca);
  }

  .vds-calendar-year-action:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-calendar-weekday {
    padding-block-end: var(--calendar-cell-gap);
    inline-size: var(--calendar-cell-size);
    text-align: center;
    font-size: var(--calendar-weekday-font-size);
    font-weight: var(--calendar-weekday-font-weight);
    color: var(--calendar-weekday-color);
    text-transform: uppercase;
    letter-spacing: 0.02em;
  }

  .vds-calendar-cell-td {
    padding: 0;
    text-align: center;
    vertical-align: middle;
    position: relative;
  }

  .vds-calendar-cell {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--calendar-cell-size);
    block-size: var(--calendar-cell-size);
    font-size: var(--calendar-cell-font-size);
    font-weight: var(--calendar-cell-font-weight);
    color: var(--calendar-cell-text-color);
    background: var(--calendar-cell-bg);
    border-radius: var(--calendar-cell-radius);
    cursor: pointer;
    outline: none;
    transition:
      background-color var(--calendar-transition-duration) var(--calendar-transition-easing),
      color var(--calendar-transition-duration) var(--calendar-transition-easing),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-calendar-cell[hidden] {
    display: none;
  }

  .vds-calendar-cell:hover:not([data-disabled]):not([data-unavailable]) {
    background: var(--calendar-cell-bg-hover);
  }

  .vds-calendar-cell:focus-visible {
    z-index: 1;
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-calendar-cell:not([data-selected])[data-today="true"] {
    box-shadow: inset 0 0 0 var(--calendar-cell-today-ring-width) var(--calendar-cell-today-ring-color);
  }

  .vds-calendar-cell[data-outside="true"] {
    color: var(--calendar-cell-outside-color);
    opacity: 0.5;
  }

  .vds-calendar-cell[data-disabled="true"] {
    color: var(--calendar-cell-text-disabled);
    cursor: not-allowed;
    pointer-events: none;
  }

  .vds-calendar-cell[data-unavailable="true"] {
    color: var(--calendar-cell-unavailable-color);
    background: var(--calendar-cell-unavailable-bg);
    cursor: not-allowed;
    text-decoration: line-through;
    text-decoration-thickness: 1px;
  }

  .vds-calendar:not(.vds-calendar-range) .vds-calendar-cell[data-selected="true"] {
    background: var(--calendar-cell-selected-bg);
    color: var(--calendar-cell-selected-text);
  }

  .vds-calendar:not(.vds-calendar-range) .vds-calendar-cell[data-selected="true"]:hover {
    background: var(--calendar-cell-selected-bg-hover);
  }

  /* ─────────────────────────────────────────────
   * Range selection
   * - Faded strip is painted on the <td> and grown outward with a
   *   pseudo-element so it bridges the `border-spacing` gap between tds.
   * - Start/end cells grow their button to the full td width so the solid
   *   primary pill matches the faded strip in height AND width.
   * - Hover state is overridden explicitly because the generic
   *   `.vds-calendar-cell:hover` selector has higher specificity than the
   *   single-class + attribute range rules.
   * ───────────────────────────────────────────── */

  /* Middle cell: transparent button — strip comes from td pseudo. */
  .vds-calendar-range .vds-calendar-cell[data-range-middle="true"],
  .vds-calendar-range .vds-calendar-cell[data-range-middle="true"]:hover,
  .vds-calendar-range .vds-calendar-cell[data-range-middle="true"]:focus-visible {
    background: transparent;
    color: var(--calendar-range-text);
    border-radius: 0;
  }

  /* Start/end cell: solid pill that fills the whole td (matches the
   * faded strip size the user sees underneath). */
  .vds-calendar-range .vds-calendar-cell[data-range-start="true"],
  .vds-calendar-range .vds-calendar-cell[data-range-end="true"],
  .vds-calendar-range .vds-calendar-cell[data-range-start="true"]:hover,
  .vds-calendar-range .vds-calendar-cell[data-range-end="true"]:hover,
  .vds-calendar-range .vds-calendar-cell[data-range-start="true"]:focus-visible,
  .vds-calendar-range .vds-calendar-cell[data-range-end="true"]:focus-visible {
    inline-size: 100%;
    background: var(--calendar-range-endpoint-bg);
    color: var(--calendar-range-endpoint-text);
  }

  .vds-calendar-range .vds-calendar-cell[data-range-start="true"] {
    border-start-end-radius: 0;
    border-end-end-radius: 0;
  }

  .vds-calendar-range .vds-calendar-cell[data-range-end="true"] {
    border-start-start-radius: 0;
    border-end-start-radius: 0;
  }

  .vds-calendar-range .vds-calendar-cell[data-range-start="true"][data-range-end="true"] {
    border-radius: var(--calendar-cell-radius);
  }

  /* td enablement for overflow pseudo (bridges border-spacing gap). */
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-middle="true"]),
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-start="true"]),
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-end="true"]) {
    position: relative;
    isolation: isolate;
    background: transparent;
  }

  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-middle="true"])::before,
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-start="true"])::after,
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-end="true"])::after {
    content: "";
    position: absolute;
    inset-block: 0;
    background: var(--calendar-range-bg);
    pointer-events: none;
    z-index: -1;
  }

  /* Middle strip: extend outward by half the grid gap on each side so two
   * adjacent middle tds visually fuse across the border-spacing. */
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-middle="true"])::before {
    inset-inline-start: calc(var(--calendar-cell-gap, 2px) * -1);
    inset-inline-end: calc(var(--calendar-cell-gap, 2px) * -1);
  }

  /* Start: faded strip extends from the button's inner edge out past the
   * td's inline-end, bridging to the next (middle) td. */
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-start="true"])::after {
    inset-inline-start: 50%;
    inset-inline-end: calc(var(--calendar-cell-gap, 2px) * -1);
  }

  /* End: mirror. */
  .vds-calendar-range .vds-calendar-cell-td:has(.vds-calendar-cell[data-range-end="true"])::after {
    inset-inline-start: calc(var(--calendar-cell-gap, 2px) * -1);
    inset-inline-end: 50%;
  }

  /* Single-day range: no bridging strip needed. */
  .vds-calendar-range .vds-calendar-cell-td:has(
    .vds-calendar-cell[data-range-start="true"][data-range-end="true"]
  )::after {
    content: none;
  }

  .vds-calendar-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--calendar-gap);
    padding-block-start: var(--calendar-gap);
    border-block-start: 1px solid var(--vds-color-border-muted, #e5e7eb);
  }

  @media (max-width: 42rem) {
    .vds-calendar {
      inline-size: 100%;
    }

    .vds-calendar-months {
      grid-template-columns: 1fr;
    }

    .vds-calendar-selector {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      min-inline-size: 0;
    }
  }
}

@layer design-system.components {
  /* ─────────────────────────────────────────────
   * Calendar — tokens
   * Semantic → component mapping with fallbacks
   * so the package works standalone if dropped
   * into a project without @virtari-packages/tokens.
   * ───────────────────────────────────────────── */

  .vds-calendar {
    /* Layout */
    --calendar-padding: var(--vds-space-3, 0.75rem);
    --calendar-gap: var(--vds-space-2, 0.5rem);
    --calendar-header-height: var(--vds-size-sm, 2rem);
    --calendar-nav-button-size: var(--vds-size-xs, 1.75rem);
    --calendar-nav-button-radius: var(--vds-radius-date-trigger, 0.5rem);
    --calendar-heading-font-size: var(--vds-text-sm, 0.875rem);
    --calendar-heading-font-weight: var(--vds-font-weight-semibold, 600);

    /* Grid */
    --calendar-cell-size: 2.25rem;
    --calendar-cell-gap: 2px;
    --calendar-cell-radius: var(--vds-radius-date-cell, 0.5rem);
    --calendar-cell-font-size: var(--vds-text-sm, 0.875rem);
    --calendar-cell-font-weight: var(--vds-font-weight-normal, 400);

    /* Weekday header */
    --calendar-weekday-color: var(--vds-color-text-muted, #6b7280);
    --calendar-weekday-font-size: var(--vds-text-xs, 0.75rem);
    --calendar-weekday-font-weight: var(--vds-font-weight-medium, 500);

    /* Cell states */
    --calendar-cell-bg: transparent;
    --calendar-cell-bg-hover: var(--vds-color-bg-muted, #f3f4f6);
    --calendar-cell-text-color: var(--vds-color-text, #111827);
    --calendar-cell-text-disabled: var(--vds-color-text-disabled, #9ca3af);
    --calendar-cell-outside-color: var(--vds-color-text-subtle, #9ca3af);

    --calendar-cell-selected-bg: var(--vds-color-primary-9, #6366f1);
    --calendar-cell-selected-bg-hover: var(--vds-color-primary-10, #4f46e5);
    --calendar-cell-selected-text: var(--vds-color-primary-contrast, #ffffff);

    --calendar-cell-today-ring-color: var(--vds-color-primary-9, #6366f1);
    --calendar-cell-today-ring-width: 1.5px;

    --calendar-cell-unavailable-bg: transparent;
    --calendar-cell-unavailable-color: var(--vds-color-text-disabled, #9ca3af);

    /* Range */
    --calendar-range-bg: color-mix(in oklab, var(--vds-color-primary-9, #6366f1) 15%, transparent);
    --calendar-range-text: var(--vds-color-text, #111827);
    --calendar-range-endpoint-bg: var(--vds-color-primary-9, #6366f1);
    --calendar-range-endpoint-text: var(--vds-color-primary-contrast, #ffffff);

    /* Focus */
    --calendar-cell-focus-ring-color: var(--vds-color-ring, #6366f1);
    --calendar-cell-focus-ring-width: var(--vds-focus-ring-width, 2px);

    /* Motion */
    --calendar-transition-duration: var(--vds-duration-fastest, 50ms);
    --calendar-transition-easing: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* Nav button */
    --calendar-nav-bg: transparent;
    --calendar-nav-bg-hover: var(--vds-color-bg-muted, #f3f4f6);
    --calendar-nav-color: var(--vds-color-text-muted, #6b7280);
    --calendar-nav-color-hover: var(--vds-color-text, #111827);
  }

  /* ── Size ramp ── */
  .vds-calendar[data-size="2xs"],
  .vds-calendar[data-size="xs"] {
    --calendar-cell-size: 1.75rem;
    --calendar-cell-font-size: var(--vds-text-xs, 0.75rem);
    --calendar-heading-font-size: var(--vds-text-xs, 0.75rem);
    --calendar-padding: var(--vds-space-2, 0.5rem);
  }
  .vds-calendar[data-size="sm"] {
    --calendar-cell-size: 2rem;
    --calendar-padding: var(--vds-space-2-5, 0.625rem);
  }
  /* md default */
  .vds-calendar[data-size="lg"] {
    --calendar-cell-size: 2.5rem;
    --calendar-cell-font-size: var(--vds-text-base, 1rem);
    --calendar-heading-font-size: var(--vds-text-base, 1rem);
    --calendar-padding: var(--vds-space-4, 1rem);
  }
  .vds-calendar[data-size="xl"] {
    --calendar-cell-size: 2.75rem;
    --calendar-cell-font-size: var(--vds-text-base, 1rem);
    --calendar-heading-font-size: var(--vds-text-lg, 1.125rem);
    --calendar-padding: var(--vds-space-5, 1.25rem);
  }
  .vds-calendar[data-size="2xl"] {
    --calendar-cell-size: 3rem;
    --calendar-cell-font-size: var(--vds-text-lg, 1.125rem);
    --calendar-heading-font-size: var(--vds-text-xl, 1.25rem);
    --calendar-padding: var(--vds-space-6, 1.5rem);
  }

  /* ── Appearance ── */
  .vds-calendar[data-appearance="ghost"] {
    --calendar-cell-bg-hover: color-mix(in oklab, currentColor 8%, transparent);
    --calendar-nav-bg-hover: color-mix(in oklab, currentColor 8%, transparent);
  }

  .vds-calendar[data-appearance="filled"] {
    --calendar-cell-bg-hover: var(--vds-color-bg-subtle, #e5e7eb);
  }

  /* ── Invalid ── */
  .vds-calendar[data-invalid="true"] {
    --calendar-cell-selected-bg: var(--vds-color-danger-solid, #ef4444);
    --calendar-cell-selected-bg-hover: var(--vds-color-danger-solid-hover, #dc2626);
    --calendar-range-endpoint-bg: var(--vds-color-danger-solid, #ef4444);
    --calendar-range-bg: color-mix(in oklab, var(--vds-color-danger-solid, #ef4444) 15%, transparent);
    --calendar-cell-today-ring-color: var(--vds-color-danger-solid, #ef4444);
    --calendar-cell-focus-ring-color: var(--vds-color-danger-solid, #ef4444);
  }
}

import { cn } from "@virtari-packages/utils";
import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
} from "react";
import {
  useCalendar,
  useCalendarGrid,
  useCalendarCell,
  useRangeCalendar,
} from "@react-aria/calendar";
import {
  useCalendarState,
  useRangeCalendarState,
  type CalendarState,
  type RangeCalendarState,
} from "@react-stately/calendar";
import { useLocale } from "@react-aria/i18n";
import {
  today,
  toCalendar,
  type CalendarDate,
  type DateDuration,
} from "@internationalized/date";
import { createCalendar, resolveLocale, type CalendarSystem, type DateValue } from "./date-utils";
import type { DatePickerAppearance, DatePickerSize } from "./context";
import { IconChevronLeft, IconChevronRight } from "@virtari-packages/react-icons";
import { toButtonProps } from "./aria-button";
import { ScrollWheel } from "./Wheel";

interface CalendarVisualProps {
  size?: DatePickerSize;
  appearance?: DatePickerAppearance;
  invalid?: boolean;
  calendar?: CalendarSystem;
  locale?: string;
  footer?: ReactNode;
  className?: string;
  visibleDuration?: DateDuration;
  pageBehavior?: "single" | "visible";
}

export type CalendarView = "days" | "months" | "years";

/** Imperative handle exposed via `apiRef` so a parent (e.g. DatePicker)
 * can drive the year/month draft commit from an external action bar. */
export interface CalendarHandle {
  getView: () => CalendarView;
  setView: (view: CalendarView) => void;
  hasMonthDraft: () => boolean;
  hasYearDraft: () => boolean;
  applyMonthDraft: () => void;
  applyYearDraft: () => void;
  cancelDraft: () => void;
}

function ChevronLeft() {
  return <IconChevronLeft size={12} stroke={1.5} aria-hidden focusable={false} />;
}

function ChevronRight() {
  return <IconChevronRight size={12} stroke={1.5} aria-hidden focusable={false} />;
}

export interface CalendarProps extends CalendarVisualProps {
  value?: DateValue | null;
  defaultValue?: DateValue | null;
  onChange?: (value: DateValue) => void;
  minValue?: DateValue | null;
  maxValue?: DateValue | null;
  isDateUnavailable?: (date: DateValue) => boolean;
  isDisabled?: boolean;
  isReadOnly?: boolean;
  autoFocus?: boolean;
  "aria-label"?: string;
  /** Fires when the internal view changes (days/months/years). */
  onViewChange?: (view: CalendarView) => void;
  /** Parent-supplied ref populated with year/month draft-commit methods. */
  apiRef?: { current: CalendarHandle | null };
  /** If true, Calendar hides its own Cancel/Change-Year/Month footer.
   *  Parent is expected to render an external action bar and drive
   *  commits through `apiRef`. */
  hideInternalActions?: boolean;
  ref?: Ref<HTMLDivElement>;
}

export function Calendar({
  size = "md",
  appearance = "soft",
  invalid,
  calendar,
  locale,
  footer,
  className,
  onViewChange,
  apiRef,
  hideInternalActions,
  ref,
  ...props
}: CalendarProps) {
  const { locale: detectedLocale, direction } = useLocale();
  const usedLocale = resolveLocale(locale ?? detectedLocale, calendar);
  const state = useCalendarState({
    ...props,
    locale: usedLocale,
    createCalendar,
  });
  const { calendarProps, prevButtonProps, nextButtonProps } = useCalendar(
    props,
    state,
  );

  return (
    <CalendarFrame
      ref={ref}
      calendarProps={calendarProps}
      prevButtonProps={prevButtonProps}
      nextButtonProps={nextButtonProps}
      state={state}
      direction={direction}
      locale={usedLocale}
      size={size}
      appearance={appearance}
      invalid={invalid}
      footer={footer}
      className={className}
      onViewChange={onViewChange}
      apiRef={apiRef}
      hideInternalActions={hideInternalActions}
    />
  );
}

export interface RangeCalendarProps extends CalendarVisualProps {
  value?: { start: DateValue; end: DateValue } | null;
  defaultValue?: { start: DateValue; end: DateValue } | null;
  onChange?: (value: { start: DateValue; end: DateValue }) => void;
  minValue?: DateValue | null;
  maxValue?: DateValue | null;
  isDateUnavailable?: (date: DateValue) => boolean;
  isDisabled?: boolean;
  isReadOnly?: boolean;
  allowsNonContiguousRanges?: boolean;
  autoFocus?: boolean;
  "aria-label"?: string;
  onViewChange?: (view: CalendarView) => void;
  apiRef?: { current: CalendarHandle | null };
  hideInternalActions?: boolean;
  ref?: Ref<HTMLDivElement>;
}

export function RangeCalendar({
  size = "md",
  appearance = "soft",
  invalid,
  calendar,
  locale,
  footer,
  className,
  onViewChange,
  apiRef,
  hideInternalActions,
  ref,
  ...props
}: RangeCalendarProps) {
  const { locale: detectedLocale, direction } = useLocale();
  const usedLocale = resolveLocale(locale ?? detectedLocale, calendar);
  const localRef = useRef<HTMLDivElement>(null);
  const state = useRangeCalendarState({
    ...props,
    locale: usedLocale,
    createCalendar,
  });
  const { calendarProps, prevButtonProps, nextButtonProps } = useRangeCalendar(
    props,
    state,
    localRef,
  );

  return (
    <CalendarFrame
      ref={ref ?? localRef}
      calendarProps={calendarProps}
      prevButtonProps={prevButtonProps}
      nextButtonProps={nextButtonProps}
      state={state}
      direction={direction}
      locale={usedLocale}
      size={size}
      appearance={appearance}
      invalid={invalid}
      footer={footer}
      className={cn("vds-calendar-range", className)}
      onViewChange={onViewChange}
      apiRef={apiRef}
      hideInternalActions={hideInternalActions}
    />
  );
}

interface CalendarFrameProps {
  calendarProps: HTMLAttributes<HTMLDivElement>;
  prevButtonProps: ButtonHTMLAttributes<HTMLButtonElement>;
  nextButtonProps: ButtonHTMLAttributes<HTMLButtonElement>;
  state: CalendarState | RangeCalendarState;
  direction: "ltr" | "rtl";
  locale: string;
  size: DatePickerSize;
  appearance: DatePickerAppearance;
  invalid?: boolean;
  footer?: ReactNode;
  className?: string;
  onViewChange?: (view: CalendarView) => void;
  apiRef?: { current: CalendarHandle | null };
  hideInternalActions?: boolean;
  ref?: Ref<HTMLDivElement>;
}

function CalendarFrame({
  calendarProps,
  prevButtonProps,
  nextButtonProps,
  state,
  direction,
  locale,
  size,
  appearance,
  invalid,
  footer,
  className,
  onViewChange,
  apiRef,
  hideInternalActions,
  ref,
}: CalendarFrameProps) {
  const [view, setViewInternal] = useState<CalendarView>("days");
  const [draftYear, setDraftYear] = useState<number | null>(null);
  const [draftMonth, setDraftMonth] = useState<number | null>(null);

  const setView = useCallback(
    (next: CalendarView | ((prev: CalendarView) => CalendarView)) => {
      setViewInternal((prev) => {
        const resolved = typeof next === "function" ? next(prev) : next;
        if (resolved !== prev) {
          onViewChange?.(resolved);
        }
        return resolved;
      });
    },
    [onViewChange],
  );

  // Drop drafts when we leave the wheel views.
  useEffect(() => {
    if (view !== "years") setDraftYear(null);
    if (view !== "months") setDraftMonth(null);
  }, [view]);

  // When the selection changes externally (e.g. a preset click) and the new
  // date sits in a different month/year than the focused page, re-focus so
  // the calendar visibly jumps to that month. React-stately only syncs
  // focusedDate on the FIRST render — subsequent `value` prop changes
  // leave focusedDate untouched, so the calendar looked "dead" after
  // preset clicks that land outside the current month.
  const primaryValue = getPrimaryValue(state);
  const primaryKey = primaryValue
    ? `${primaryValue.calendar.identifier}:${primaryValue.year}-${primaryValue.month}-${primaryValue.day}`
    : null;
  useEffect(() => {
    if (!primaryValue) return;
    const focused = state.focusedDate;
    if (
      focused.year !== primaryValue.year ||
      focused.month !== primaryValue.month
    ) {
      state.setFocusedDate(primaryValue);
    }
    // state.setFocusedDate / state.focusedDate are stable-ish; primaryKey
    // is the fingerprint we want to react to.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [primaryKey]);

  // Expose commit handles to parents (e.g. DatePicker) via apiRef.
  const focusedForHandle = state.focusedDate;
  const applyYearDraft = useCallback(() => {
    const picked = draftYear ?? focusedForHandle.year;
    state.setFocusedDate(focusedForHandle.set({ year: picked, day: 1 }));
    setDraftYear(null);
    setView("days");
  }, [draftYear, focusedForHandle, state, setView]);
  const applyMonthDraft = useCallback(() => {
    const picked = draftMonth ?? focusedForHandle.month;
    state.setFocusedDate(focusedForHandle.set({ month: picked, day: 1 }));
    setDraftMonth(null);
    setView("days");
  }, [draftMonth, focusedForHandle, state, setView]);
  const cancelDraft = useCallback(() => {
    setDraftYear(null);
    setDraftMonth(null);
    setView("days");
  }, [setView]);

  useLayoutEffect(() => {
    if (!apiRef) return;
    apiRef.current = {
      getView: () => view,
      setView,
      hasMonthDraft: () => draftMonth !== null,
      hasYearDraft: () => draftYear !== null,
      applyMonthDraft,
      applyYearDraft,
      cancelDraft,
    };
    return () => {
      if (apiRef.current && typeof apiRef === "object") {
        apiRef.current = null;
      }
    };
  }, [apiRef, applyMonthDraft, applyYearDraft, cancelDraft, draftMonth, draftYear, setView, view]);

  const previousButtonProps = toButtonProps(prevButtonProps);
  const followingButtonProps = toButtonProps(nextButtonProps);
  const monthFormatter = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: "long", timeZone: "UTC" }),
    [locale],
  );
  const monthCaptionFormatter = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: "long", year: "numeric", timeZone: "UTC" }),
    [locale],
  );

  const visibleMonthCount = getVisibleMonthCount(state.visibleRange);
  const monthStartDates = useMemo(
    () =>
      Array.from({ length: visibleMonthCount }, (_, index) =>
        state.visibleRange.start.add({ months: index }).set({ day: 1 }),
      ),
    [state.visibleRange.start, visibleMonthCount],
  );
  const focusedDate = state.focusedDate;
  const monthLabel = monthFormatter.format(focusedDate.toDate("UTC"));
  const monthOptions = getMonthOptions(focusedDate, monthFormatter);
  const yearOptions = useMemo(
    () => getYearWheelOptions(focusedDate),
    [focusedDate.calendar.identifier, focusedDate.year],
  );

  const handlePrevious = () => {
    if (view === "months") {
      state.setFocusedDate(focusedDate.subtract({ years: 1 }));
      return;
    }

    if (view === "years") {
      state.setFocusedDate(focusedDate.subtract({ years: 12 }));
      return;
    }

    state.focusPreviousPage();
  };

  const handleNext = () => {
    if (view === "months") {
      state.setFocusedDate(focusedDate.add({ years: 1 }));
      return;
    }

    if (view === "years") {
      state.setFocusedDate(focusedDate.add({ years: 12 }));
      return;
    }

    state.focusNextPage();
  };

  return (
    <div
      {...calendarProps}
      ref={ref}
      className={cn("vds-calendar", className)}
      data-size={size}
      data-appearance={appearance}
      data-invalid={invalid ? "true" : undefined}
      data-dir={direction}
      data-view={view}
    >
      <div className="vds-calendar-header">
        <button
          {...previousButtonProps}
          type="button"
          className="vds-calendar-nav"
          aria-label={view === "days" ? previousButtonProps["aria-label"] ?? "Previous month" : "Previous"}
          onClick={handlePrevious}
        >
          {direction === "rtl" ? <ChevronRight /> : <ChevronLeft />}
        </button>
        <div className="vds-calendar-heading" aria-live="polite">
          <button
            type="button"
            className="vds-calendar-heading-button"
            onClick={() => setView((current) => current === "months" ? "days" : "months")}
          >
            <SlotCounter value={monthLabel} />
          </button>
          <button
            type="button"
            className="vds-calendar-heading-button"
            onClick={() => setView((current) => current === "years" ? "days" : "years")}
          >
            <SlotCounter value={String(focusedDate.year)} />
          </button>
        </div>
        <button
          {...followingButtonProps}
          type="button"
          className="vds-calendar-nav"
          aria-label={view === "days" ? followingButtonProps["aria-label"] ?? "Next month" : "Next"}
          onClick={handleNext}
        >
          {direction === "rtl" ? <ChevronLeft /> : <ChevronRight />}
        </button>
      </div>

      {view === "days" ? (
        <div className="vds-calendar-months" data-month-count={monthStartDates.length}>
          {monthStartDates.map((startDate) => (
            <div key={startDate.toString()} className="vds-calendar-month">
              {monthStartDates.length > 1 ? (
                <div className="vds-calendar-month-caption">
                  {monthCaptionFormatter.format(startDate.toDate("UTC"))}
                </div>
              ) : null}
              <CalendarGrid
                state={state}
                startDate={startDate}
                isRange={"anchorDate" in state}
                hideOutsideMonth={monthStartDates.length > 1}
              />
            </div>
          ))}
        </div>
      ) : null}

      {view === "months" ? (
        <div className="vds-calendar-wheel-view">
          <div className="vds-calendar-year-wheel" data-role="month-wheel">
            <ScrollWheel
              label="Month"
              variant="year"
              showHeader={false}
              values={monthOptions.map((option) => option.value)}
              value={draftMonth ?? focusedDate.month}
              formatValue={(monthNumber) => {
                const option = monthOptions.find((item) => item.value === monthNumber);
                return option ? String(option.label) : String(monthNumber);
              }}
              onChange={(monthNumber) => setDraftMonth(monthNumber)}
            />
          </div>
          {hideInternalActions ? null : (
            <div className="vds-calendar-year-actions">
              <button
                type="button"
                className="vds-calendar-year-action vds-calendar-year-action--secondary"
                onClick={cancelDraft}
              >
                Cancel
              </button>
              <button
                type="button"
                className="vds-calendar-year-action vds-calendar-year-action--primary"
                onClick={applyMonthDraft}
              >
                Change Month
              </button>
            </div>
          )}
        </div>
      ) : null}

      {view === "years" ? (
        <div className="vds-calendar-wheel-view">
          <div className="vds-calendar-year-wheel">
            <ScrollWheel
              label="Year"
              variant="year"
              showHeader={false}
              values={yearOptions}
              value={draftYear ?? focusedDate.year}
              formatValue={(year) => String(year)}
              onChange={(year) => setDraftYear(year)}
            />
          </div>
          {hideInternalActions ? null : (
            <div className="vds-calendar-year-actions">
              <button
                type="button"
                className="vds-calendar-year-action vds-calendar-year-action--secondary"
                onClick={cancelDraft}
              >
                Cancel
              </button>
              <button
                type="button"
                className="vds-calendar-year-action vds-calendar-year-action--primary"
                onClick={applyYearDraft}
              >
                Change Year
              </button>
            </div>
          )}
        </div>
      ) : null}

      {footer ? <div className="vds-calendar-footer">{footer}</div> : null}
    </div>
  );
}

interface CalendarGridProps {
  state: CalendarState | RangeCalendarState;
  startDate: CalendarDate;
  isRange?: boolean;
  hideOutsideMonth?: boolean;
}

function CalendarGrid({ state, startDate, isRange, hideOutsideMonth }: CalendarGridProps) {
  const { gridProps, headerProps, weekDays, weeksInMonth } = useCalendarGrid(
    { startDate },
    state,
  );

  return (
    <table {...gridProps} className="vds-calendar-grid">
      <thead {...headerProps}>
        <tr>
          {weekDays.map((day, index) => (
            <th key={index} className="vds-calendar-weekday" scope="col">
              {day}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {Array.from({ length: weeksInMonth }, (_, weekIndex) => (
          <tr key={weekIndex}>
            {state.getDatesInWeek(weekIndex, startDate).map((date, index) =>
              date ? (
                <Cell
                  key={index}
                  state={state}
                  date={date}
                  isRange={isRange}
                  gridStartDate={startDate}
                  hideOutsideMonth={hideOutsideMonth}
                />
              ) : (
                <td key={index} className="vds-calendar-cell-td" />
              ),
            )}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

interface CellProps {
  state: CalendarState | RangeCalendarState;
  date: CalendarDate;
  isRange?: boolean;
  gridStartDate: CalendarDate;
  hideOutsideMonth?: boolean;
}

function Cell({ state, date, isRange, gridStartDate, hideOutsideMonth }: CellProps) {
  const ref = useRef<HTMLDivElement>(null);
  const {
    cellProps,
    buttonProps,
    isSelected,
    isOutsideVisibleRange,
    isDisabled,
    isUnavailable,
    isInvalid,
    formattedDate,
  } = useCalendarCell({ date }, state, ref);
  const todayDate = today(state.timeZone);

  // In a multi-month grid layout, cells that belong to the *other* visible
  // month would otherwise appear duplicated as leading/trailing padding in
  // each grid. Hide them from their non-owning grid.
  const isOutsideMonth =
    date.month !== gridStartDate.month || date.year !== gridStartDate.year;
  const hideAsOutsideMonth = Boolean(hideOutsideMonth) && isOutsideMonth;

  let isRangeStart = false;
  let isRangeEnd = false;
  let isRangeMiddle = false;

  if (isRange && !hideAsOutsideMonth) {
    const rangeState = state as RangeCalendarState;
    const highlightedRange = rangeState.highlightedRange;
    if (highlightedRange) {
      isRangeStart = date.compare(highlightedRange.start) === 0;
      isRangeEnd = date.compare(highlightedRange.end) === 0;
      isRangeMiddle =
        date.compare(highlightedRange.start) > 0 &&
        date.compare(highlightedRange.end) < 0;
    }
  }

  return (
    <td {...cellProps} className="vds-calendar-cell-td">
      <div
        {...buttonProps}
        ref={ref}
        className="vds-calendar-cell"
        data-today={date.compare(todayDate) === 0 ? "true" : undefined}
        data-outside={isOutsideVisibleRange ? "true" : undefined}
        data-selected={isSelected && !hideAsOutsideMonth ? "true" : undefined}
        data-disabled={isDisabled ? "true" : undefined}
        data-unavailable={isUnavailable ? "true" : undefined}
        data-invalid={isInvalid ? "true" : undefined}
        data-range-start={isRangeStart ? "true" : undefined}
        data-range-end={isRangeEnd ? "true" : undefined}
        data-range-middle={isRangeMiddle ? "true" : undefined}
        hidden={isOutsideVisibleRange || hideAsOutsideMonth}
      >
        {formattedDate}
      </div>
    </td>
  );
}

function getVisibleMonthCount(visibleRange: { start: CalendarDate; end: CalendarDate }) {
  const months =
    (visibleRange.end.year - visibleRange.start.year) * 12 +
    (visibleRange.end.month - visibleRange.start.month);
  return Math.max(1, months + 1);
}

function getMonthOptions(date: CalendarDate, formatter: Intl.DateTimeFormat) {
  const count = date.calendar.getMonthsInYear(date);
  return Array.from({ length: count }, (_, index) => {
    const month = index + 1;
    return {
      value: month,
      label: formatter.format(date.set({ month, day: 1 }).toDate("UTC")),
    };
  });
}

/** Extracts a single "primary" date from either CalendarState (single) or
 *  RangeCalendarState — used to decide when to re-focus the calendar after
 *  external value changes. */
function getPrimaryValue(
  state: CalendarState | RangeCalendarState,
): CalendarDate | null {
  if ("anchorDate" in state) {
    const range = state.value as { start?: CalendarDate; end?: CalendarDate } | null;
    return range?.start ?? range?.end ?? null;
  }
  return (state.value as CalendarDate | null) ?? null;
}

/** Slot-machine counter: when `value` changes, slides the old value up and
 *  animates the new value in from below. Returns to a static, animation-free
 *  state once the transition completes. */
function SlotCounter({ value }: { value: string }) {
  const [prev, setPrev] = useState<string | null>(null);
  const [direction, setDirection] = useState<1 | -1>(1);
  const priorValue = useRef(value);

  useLayoutEffect(() => {
    if (priorValue.current === value) return;
    const oldValue = priorValue.current;
    const a = parseNumeric(oldValue);
    const b = parseNumeric(value);
    setDirection(a !== null && b !== null && b < a ? -1 : 1);
    priorValue.current = value;
    setPrev(oldValue);
    const t = window.setTimeout(() => setPrev(null), 260);
    return () => window.clearTimeout(t);
  }, [value]);

  return (
    <span className="vds-slot-counter" data-direction={direction === -1 ? "down" : "up"}>
      {prev !== null ? (
        <span key={`out-${prev}`} className="vds-slot-counter-prev" aria-hidden="true">
          {prev}
        </span>
      ) : null}
      <span key={`in-${value}`} className="vds-slot-counter-current">
        {value}
      </span>
    </span>
  );
}

function parseNumeric(value: string): number | null {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function getYearWheelOptions(focusedDate: CalendarDate): number[] {
  // Translate today's Gregorian date into the focused calendar system so the
  // "now" year is meaningful whether it's Gregorian, Persian, Hijri, etc.
  const nowInCalendar = toCalendar(today("UTC"), focusedDate.calendar).year;
  const isGregorian = focusedDate.calendar.identifier === "gregory";
  const defaultStart = isGregorian ? 1990 : Math.max(1, nowInCalendar - 36);
  const start = Math.min(defaultStart, focusedDate.year);
  // Give headroom for future dates (20 years ahead of "now") so users can
  // pick ahead of today. If the focused date sits further out, extend.
  const end = Math.max(nowInCalendar + 20, focusedDate.year);
  const length = end - start + 1;
  return Array.from({ length }, (_, index) => start + index);
}

