@import "../../react-button/src/Button.css";
@import "../../react-dialog/src/Dialog.css";
@import "../../react-drawer/src/Drawer.css";
@import "../../react-radio-group/src/RadioGroup.css";
@import "../../react-radio-group/src/RadioField.css";
@import "./DateField.tokens.css";

@layer design-system.components {
  .vds-date-field,
  .vds-time-field {
    display: inline-flex;
    flex-direction: column;
    gap: 0;
    font-family: var(--date-field-font-family);
  }

  .vds-date-field > *,
  .vds-time-field > * {
    min-inline-size: 0;
  }

  .vds-date-field > * + *,
  .vds-time-field > * + * {
    margin-block-start: var(--vds-space-1, 0.25rem);
  }

  .vds-date-field[data-dir="rtl"],
  .vds-time-field[data-dir="rtl"] {
    direction: rtl;
  }

  .vds-date-field-label,
  .vds-time-field-label {
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-medium, 500);
    color: var(--date-field-label-color);
  }

  .vds-date-field-group,
  .vds-time-field-group,
  .vds-date-picker-group,
  .vds-date-range-picker-group {
    display: inline-flex;
    align-items: center;
    gap: var(--date-field-gap);
    inline-size: 100%;
    min-inline-size: 0;
    box-sizing: border-box;
    block-size: var(--date-field-height);
    padding-inline: var(--date-field-padding-inline);
    background: var(--date-field-bg);
    box-shadow: var(--date-field-shadow);
    border: var(--date-field-border-width) solid var(--date-field-border-color);
    border-radius: var(--date-field-radius);
    color: var(--date-field-text-color);
    font-size: var(--date-field-font-size);
    line-height: var(--date-field-line-height);
    transition:
      background-color var(--date-field-transition-duration) var(--date-field-transition-easing),
      border-color var(--date-field-transition-duration) var(--date-field-transition-easing),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-date-field-group:hover,
  .vds-time-field-group:hover,
  .vds-date-picker-group:hover,
  .vds-date-range-picker-group:hover {
    background: var(--date-field-bg-hover);
    border-color: var(--date-field-border-color-hover);
  }

  .vds-date-field-group:focus-within,
  .vds-time-field-group:focus-within,
  .vds-date-picker-group:focus-within,
  .vds-date-range-picker-group:focus-within {
    border-color: var(--date-field-focus-border-color);
    outline: none;
    box-shadow: 0 0 0 4px var(--date-field-focus-alpha), 0 0 12px 2px var(--date-field-focus-soft-alpha);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-date-field[data-disabled="true"] .vds-date-field-group,
  .vds-time-field[data-disabled="true"] .vds-time-field-group,
  .vds-date-picker[data-disabled="true"] .vds-date-picker-group,
  .vds-date-range-picker[data-disabled="true"] .vds-date-range-picker-group {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
    pointer-events: none;
  }

  .vds-time-field[data-picker="true"] .vds-time-field-group {
    cursor: pointer;
  }

  .vds-date-picker-group[data-surface-trigger="true"],
  .vds-date-range-picker-group[data-surface-trigger="true"],
  .vds-time-field-group[data-surface-trigger="true"] {
    cursor: pointer;
  }

  .vds-time-field-segments {
    display: inline-flex;
    align-items: center;
    gap: 1px;
    flex: 1 1 auto;
    min-inline-size: 0;
  }

  .vds-static-field-segments {
    display: inline-flex;
    align-items: center;
    gap: 1px;
    flex: 1 1 auto;
    min-inline-size: 0;
  }

  .vds-date-field-segment,
  .vds-time-field-segment,
  .vds-static-field-segment {
    display: inline-block;
    padding-inline: var(--date-field-segment-padding-inline);
    border-radius: var(--date-field-segment-radius);
    font-variant-numeric: tabular-nums;
    user-select: none;
    caret-color: transparent;
    outline: none;
    transition: background-color var(--date-field-transition-duration) var(--date-field-transition-easing);
  }

  .vds-date-field-segment[data-placeholder="true"],
  .vds-time-field-segment[data-placeholder="true"],
  .vds-static-field-segment[data-placeholder="true"] {
    color: var(--date-field-placeholder-color);
  }

  .vds-date-field-segment:focus,
  .vds-time-field-segment:focus {
    background: var(--date-field-segment-focus-bg);
    color: var(--date-field-segment-focus-text);
  }

  .vds-date-field-segment[data-type="literal"],
  .vds-time-field-segment[data-type="literal"],
  .vds-static-field-segment[data-type="literal"] {
    padding-inline: 0;
    color: var(--date-field-placeholder-color);
  }

  .vds-time-field-picker-trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: calc(var(--date-field-trigger-size) + 0.5rem);
    block-size: calc(var(--date-field-trigger-size) + 0.5rem);
    margin-inline-start: auto;
    padding: 0;
    border: 0;
    border-radius: var(--vds-radius-date-trigger, 0.25rem);
    background: transparent;
    color: var(--date-field-trigger-color);
    cursor: pointer;
    flex: none;
    transition:
      background-color var(--date-field-transition-duration) var(--date-field-transition-easing),
      color var(--date-field-transition-duration) var(--date-field-transition-easing),
      box-shadow 180ms ease-out;
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-time-field-picker-trigger:hover:not(:disabled) {
    background: color-mix(in oklab, currentColor 10%, transparent);
    color: var(--date-field-text-color);
  }

  .vds-time-field-picker-trigger:focus-visible {
    outline: none;
    box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-time-field-picker-trigger:disabled {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
  }

  .vds-time-field-picker-trigger svg {
    inline-size: var(--date-field-trigger-size);
    block-size: var(--date-field-trigger-size);
  }

  /*
   * Shared by both presentations of the mobile picker (Dialog and Drawer).
   * Sizing is delegated to whichever surface hosts it: Dialog resolves
   * --dialog-width / --dialog-max-width / --dialog-max-height, Drawer sizes
   * itself from [data-direction] / [data-size-mode]. Declaring inline-size or
   * max-*-size here would tie with `.vds-dialog-content` at equal specificity
   * (0,1,0) and resolve on stylesheet import order.
