    inline-size: 100%;
    block-size: var(--time-picker-wheel-item-height);
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--time-picker-wheel-muted-text);
    font: inherit;
    font-size: var(--time-picker-wheel-font-size);
    font-weight: var(--vds-font-weight-semibold, 600);
    font-variant-numeric: tabular-nums;
    letter-spacing: 0;
    scroll-snap-align: center;
    cursor: pointer;
    opacity: 0.38;
    transition:
      color var(--date-field-transition-duration) var(--date-field-transition-easing),
      transform var(--date-field-transition-duration) var(--date-field-transition-easing),
      opacity var(--date-field-transition-duration) var(--date-field-transition-easing),
      background-color var(--date-field-transition-duration) var(--date-field-transition-easing),
