  .vds-time-wheel-item[data-distance="1"] { opacity: 0.42; }
  .vds-time-wheel-item[data-distance="2"] { opacity: 0.24; }
  .vds-time-wheel-item[data-distance="3"] { opacity: 0.14; }
  .vds-time-wheel-item[data-distance="4"] { opacity: 0.07; }

