  }

  .vds-time-picker-actions {
    padding-block-start: 0;
  }

  .vds-time-picker-panel--embedded {
    inline-size: 100%;
    min-inline-size: 0;
    padding: var(--vds-space-2, 0.5rem) var(--vds-space-3, 0.75rem) 0;
    background: transparent;
    overflow-x: hidden;
  }

  @keyframes vds-time-picker-in {
