  }

  .vds-date-field-description,
  .vds-time-field-description {
    font-size: var(--vds-text-xs, 0.75rem);
    color: var(--date-field-description-color);
  }

  .vds-date-field-error,
  .vds-time-field-error {
    font-size: var(--vds-text-xs, 0.75rem);
    color: var(--date-field-error-color);
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--vds-duration-normal, 200ms)
