  }

  .vds-date-field-error[data-visible],
  .vds-time-field-error[data-visible] {
    grid-template-rows: 1fr;
  }

  .vds-date-field-error-body,
  .vds-time-field-error-body {
    min-block-size: 0;
    overflow: hidden;
    opacity: 0;
    transform: translateY(calc(var(--vds-space-1, 0.25rem) * -1));
    transition:
      opacity var(--vds-duration-normal, 200ms)
        var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1)),
      transform var(--vds-duration-normal, 200ms)
        var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  .vds-date-field-error[data-visible] .vds-date-field-error-body,
  .vds-time-field-error[data-visible] .vds-time-field-error-body {
    opacity: 1;
    transform: translateY(0);
  }

  @media (max-width: 42rem) {
    /*
     * Phone: the picker sheet goes edge to edge. Set Dialog's width tokens
     * instead of inline-size — and carry all three classes the element
     * actually has, because a media query adds no specificity and
     * `.vds-dialog-content[data-size="sm"]` (0,2,0) also sets --dialog-width.
     * The Drawer presentation needs nothing here: [data-direction] already
     * gives it `inset-inline: 0` and its own max-block-size.
     */
    .vds-dialog-content.vds-picker-mobile-surface.vds-picker-mobile-dialog {
      --dialog-width: 100vw;
      --dialog-max-width: 100vw;
      --dialog-max-height: 100dvh;
    }

    .vds-picker-mobile-body {
      max-inline-size: 100vw;
    }

    .vds-picker-action-bar {
      gap: var(--vds-space-2, 0.5rem);
    }

    .vds-time-picker-panel {
      gap: var(--vds-space-3, 0.75rem);
      padding: var(--vds-space-3, 0.75rem);
    }

    .vds-time-picker-wheels {
      --time-picker-wheel-height: 11.5rem;
      --time-picker-wheel-item-height: 2.75rem;
      --time-picker-wheel-font-size: var(--vds-text-xl, 1.25rem);
    }

    .vds-time-picker-colon {
      flex-basis: 0.5rem;
      min-inline-size: 0.5rem;
    }
  }

  @media (max-width: 22rem) {
    .vds-picker-action-bar {
      grid-template-columns: 1fr;
    }

    .vds-time-picker-wheels {
      --time-picker-wheel-height: 10rem;
      --time-picker-wheel-font-size: var(--vds-text-lg, 1.125rem);
      padding-inline: var(--vds-space-1, 0.25rem);
    }

    .vds-time-wheel[data-variant="period"] {
      flex-basis: 2.5rem;
    }
  }
}

