@layer design-system.components {
  .vds-dropdown-menu-content {
    /* An inline-size must not be drawn from the spacing scale: retuning
       spacing would silently resize every menu. 10rem is narrower than the
       smallest --vds-surface-width-* step (xs = 20rem), which is sized for
       dialog-class overlays, so the menu keeps its own local token. */
    --dropdown-menu-min-inline-size: 10rem;
    z-index: var(--vds-z-dropdown);
    background-color: var(--vds-overlay-bg, var(--vds-color-surface));
    border: 1px solid var(--vds-surface-border, var(--vds-color-border-muted));
    border-radius: var(--vds-radius-surface);
    box-shadow: var(--vds-overlay-shadow, var(--vds-shadow-lg));
    overflow: hidden;
    padding-block: var(--vds-space-1);
    min-inline-size: var(--dropdown-menu-min-inline-size);
    animation: vds-fade-in var(--vds-duration-fast) var(--vds-ease-out);

    &[data-state="closed"] {
      animation: vds-fade-out var(--vds-duration-fastest) var(--vds-ease-in);
    }

    &[data-side="bottom"] {
      animation: vds-slide-in-from-top var(--vds-duration-fast) var(--vds-ease-out);
    }

    &[data-side="top"] {
      animation: vds-slide-in-from-bottom var(--vds-duration-fast) var(--vds-ease-out);
    }

    /* Logical side animations — the menu primitive flips `data-side` under dir="rtl", and
       the logical keyframes flip their motion axis, so both combine to a
       correctly mirrored slide in Persian/Arabic. */
    &[data-side="left"] {
      animation: vds-slide-in-from-inline-end var(--vds-duration-fast) var(--vds-ease-out);
    }

    &[data-side="right"] {
      animation: vds-slide-in-from-inline-start var(--vds-duration-fast) var(--vds-ease-out);
    }
  }

  .vds-dropdown-menu-item {
    display: flex;
    align-items: center;
    gap: var(--vds-space-2);
    padding-inline: var(--vds-space-3);
    padding-block: var(--vds-space-2);
    font-size: var(--vds-text-sm);
    cursor: pointer;
    outline: none;
    user-select: none;
    transition: background-color var(--vds-duration-fastest) var(--vds-ease-out);

    &[data-highlighted] {
      background-color: var(--vds-color-bg-muted);
    }

    &[data-disabled] {
      opacity: var(--vds-opacity-disabled, 0.5);
      pointer-events: none;
    }
  }

  .vds-dropdown-menu-label {
    padding-inline: var(--vds-space-3);
    padding-block: var(--vds-space-1-5);
    font-size: var(--vds-text-xs);
    font-weight: var(--vds-font-weight-semibold);
    color: var(--vds-color-text-muted);
    text-transform: uppercase;
    letter-spacing: var(--vds-tracking-wider);
  }

  .vds-dropdown-menu-separator {
    block-size: 1px;
    margin-block: var(--vds-space-1);
    background-color: var(--vds-color-border-muted);
  }
}

import { cn, useDirection } from "@virtari-packages/utils";
import type { ComponentRef, Ref } from "react";
import * as DropdownMenuPrimitive from "@virtari-packages/primitives/dropdown-menu";
import { DirectionProvider } from "@virtari-packages/primitives/direction";

/* ── Root ──
 * Auto-threads the active text direction into the menu primitive so submenu placement,
 * focus traversal, and arrow-key navigation flip under RTL. Consumers can
 * still override by passing `dir`. */
export interface DropdownMenuProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Root> {
  /** Reading direction. Defaults to the document's active direction. */
  dir?: "ltr" | "rtl";
}

export function DropdownMenu({ dir, ...props }: DropdownMenuProps) {
  const autoDir = useDirection();
  return (
    <DirectionProvider dir={dir ?? autoDir}>
      <DropdownMenuPrimitive.Root {...props} />
    </DirectionProvider>
  );
}

export const DropdownMenuTrigger = DropdownMenuPrimitive.Trigger;
export const DropdownMenuGroup = DropdownMenuPrimitive.Group;

/* ── DropdownMenuContent ── */
export interface DropdownMenuContentProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content> {
  ref?: Ref<ComponentRef<typeof DropdownMenuPrimitive.Content>>;
}

export function DropdownMenuContent({
  className,
  sideOffset = 4,
  ref,
  ...props
}: DropdownMenuContentProps) {
  return (
    <DropdownMenuPrimitive.Portal>
      <DropdownMenuPrimitive.Content
        ref={ref}
        sideOffset={sideOffset}
        className={cn("vds-dropdown-menu-content", className)}
        {...props}
      />
    </DropdownMenuPrimitive.Portal>
  );
}

/* ── DropdownMenuItem ── */
export interface DropdownMenuItemProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> {
  ref?: Ref<ComponentRef<typeof DropdownMenuPrimitive.Item>>;
}

export function DropdownMenuItem({
  className,
  ref,
  ...props
}: DropdownMenuItemProps) {
  return (
    <DropdownMenuPrimitive.Item
      ref={ref}
      className={cn("vds-dropdown-menu-item", className)}
      {...props}
    />
  );
}

/* ── DropdownMenuSeparator ── */
export interface DropdownMenuSeparatorProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator> {
  ref?: Ref<ComponentRef<typeof DropdownMenuPrimitive.Separator>>;
}

export function DropdownMenuSeparator({
  className,
  ref,
  ...props
}: DropdownMenuSeparatorProps) {
  return (
    <DropdownMenuPrimitive.Separator
      ref={ref}
      className={cn("vds-dropdown-menu-separator", className)}
      {...props}
    />
  );
}

/* ── DropdownMenuLabel ── */
export interface DropdownMenuLabelProps
  extends React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Label> {
  ref?: Ref<ComponentRef<typeof DropdownMenuPrimitive.Label>>;
}

export function DropdownMenuLabel({
  className,
  ref,
  ...props
}: DropdownMenuLabelProps) {
  return (
    <DropdownMenuPrimitive.Label
      ref={ref}
      className={cn("vds-dropdown-menu-label", className)}
      {...props}
    />
  );
}

