  textColors: false,
  comments: false,
  shortcuts: false,
  maxIndent: 7,
  characterLimit: null,
};

export const DEFAULT_PRO_FEATURES: ResolvedEditorFeatureOptions = {
  ...DEFAULT_CORE_FEATURES,
  tables: true,
  media: true,
  horizontalRule: true,
  draggableBlocks: true,
  tabIndentation: true,
  advancedTextFormats: true,
  textAlignment: true,
