  .vds-editor-code-block {
    display: block;
    inline-size: 100%;
    min-inline-size: 0;
    margin: var(--vds-space-4, 1rem) 0;
    padding: var(--vds-space-3, 0.75rem) var(--vds-space-3-5, 0.875rem);
    overflow-x: auto;
    border: 1px solid var(--vds-editor-code-border);
    border-radius: var(--vds-editor-radius-block, 0.5rem);
    background:
      linear-gradient(
