        transparent 0.2rem
      ),
      var(--vds-editor-code-bg);
    box-shadow: var(--vds-editor-code-shadow);
    color: var(--vds-editor-code-fg);
    font-family: var(--vds-font-mono, ui-monospace, monospace);
    font-size: var(--vds-text-sm, 0.875rem);
    line-height: var(--vds-leading-relaxed, 1.625);
    tab-size: 2;
    white-space: pre;
  }

  .vds-editor-media-block {
    display: block;
    inline-size: 100%;
    min-inline-size: 0;
    margin: var(--vds-space-4, 1rem) 0;
  }

  .vds-editor-media-figure {
    display: grid;
    gap: var(--vds-space-2, 0.5rem);
    margin: 0;
    min-inline-size: 0;
