  .vds-editor-media-preview,
  .vds-editor-media-frame {
    display: block;
    inline-size: 100%;
    min-inline-size: 0;
    border: 1px solid var(--vds-editor-border);
    border-radius: var(--vds-editor-radius-block, 0.5rem);
    background: var(--vds-editor-bg-muted);
  }

  .vds-editor-media-preview {
    max-block-size: 26rem;
    object-fit: contain;
  }

  video.vds-editor-media-preview {
    aspect-ratio: 16 / 9;
    /* Letterbox behind `object-fit: contain` video. Must stay black in both
       modes: an inverting neutral step turns this near-white in dark. */
    background: var(--vds-color-black, #000000);
  }

  .vds-editor-media-frame {
    aspect-ratio: 16 / 9;
  }

  .vds-editor-media-caption {
    color: var(--vds-editor-text-subtle);
