  .vds-editor-media-dialog {
    --vds-editor-border: var(--vds-color-border, #d4d4d8);
    --vds-editor-border-strong: var(--vds-color-border-strong, #a1a1aa);
    --vds-editor-bg: var(--vds-field-bg, var(--vds-color-surface, #ffffff));
    --vds-editor-bg-muted: var(--vds-color-surface-raised, #f5f7fb);
    --vds-editor-text: var(--vds-color-text, #111827);
    --vds-editor-text-muted: var(--vds-color-text-muted, #475569);
    --vds-editor-text-subtle: var(--vds-color-text-subtle, #64748b);
    /* Resolved width. --dialog-max-width is the viewport clamp only, so the
       intended size has to be set through --dialog-width. */
    --dialog-width: 34rem;
    --dialog-title-font-size: var(--vds-text-lg, 1.125rem);
    --dialog-description-font-size: var(--vds-text-xs, 0.75rem);
    --dialog-padding-inline: var(--vds-space-4, 1rem);
    --dialog-padding-block: var(--vds-space-4, 1rem);
    /* Seam between header / body / footer. Dialog owns the slot gaps now, so
       the media dialog only retunes the one token. */
    --dialog-slot-gap: var(--vds-space-3, 0.75rem);
  }

  .vds-editor-media-dialog .vds-dialog-footer {
    flex-direction: row;
    justify-content: flex-end;
  }

  .vds-editor-media-dialog .vds-dialog-footer > * {
    inline-size: auto;
  }

  .vds-editor-media-dialog-body {
    display: grid;
    gap: var(--vds-space-2-5, 0.625rem);
