      in oklch,
      var(--vds-color-primary-solid, #2563eb) 12%,
      transparent
    );
    color: var(--vds-color-primary-text, #1d4ed8);
  }

  .vds-editor-media-file-main {
    display: grid;
    min-inline-size: 0;
    flex: 1 1 auto;
