  .vds-editor-media-code {
    --vds-code-radius: var(--vds-editor-radius-block, 0.5rem);
  }

  .vds-editor-media-source-hint,
  .vds-editor-media-error {
    border-radius: var(--vds-editor-radius-block, 0.5rem);
    padding: var(--vds-space-2, 0.5rem);
    font-size: var(--vds-text-xs, 0.75rem);
