  .vds-editor-code-token-comment {
    color: var(--vds-editor-code-token-comment);
  }

  .vds-editor-code-token-deleted {
    color: var(--vds-editor-code-token-deleted);
  }

  .vds-editor-code-token-function {
    color: var(--vds-editor-code-token-function);
  }

  .vds-editor-code-token-inserted {
    color: var(--vds-editor-code-token-inserted);
  }

  .vds-editor-code-token-operator {
    color: var(--vds-editor-code-token-operator);
  }

  .vds-editor-code-token-property {
    color: var(--vds-editor-code-token-property);
  }

  .vds-editor-code-token-punctuation {
    color: var(--vds-editor-code-token-punctuation);
  }

  .vds-editor-code-token-selector {
    color: var(--vds-editor-code-token-selector);
  }

  .vds-editor-code-token-unchanged {
    color: var(--vds-editor-code-token-unchanged);
  }

  .vds-editor-code-token-variable {
    color: var(--vds-editor-code-token-variable);
  }

  .vds-editor-divider {
    block-size: 0;
    margin: var(--vds-space-5, 1.25rem) 0;
    border: 0;
    border-block-start: 1px solid var(--vds-editor-divider-color);
  }

  .vds-editor-list {
    margin-block: var(--vds-space-3, 0.75rem);
    padding-inline-start: var(--vds-space-6, 1.5rem);
  }

  .vds-editor-list-ul {
