  }

  .vds-editor-list-ol {
    list-style: decimal;
  }

  .vds-editor-list-ul .vds-editor-list-ul {
    list-style: circle;
  }

  .vds-editor-list-ul .vds-editor-list-ul .vds-editor-list-ul {
    list-style: square;
  }

  .vds-editor-list-ol .vds-editor-list-ol {
    list-style: lower-alpha;
  }

  .vds-editor-list-ol .vds-editor-list-ol .vds-editor-list-ol {
    list-style: lower-roman;
  }

  .vds-editor-list-check {
    padding-inline-start: 0;
    list-style: none;
  }

  .vds-editor-list-nested {
    margin-block: var(--vds-space-2, 0.5rem);
  }

  .vds-editor-list-item {
    margin-block: var(--vds-space-1, 0.25rem);
    padding-inline-start: var(--vds-space-1, 0.25rem);
