  .vds-editor-list-item-checked,
  .vds-editor-list-item-unchecked {
    /* Indent is derived from the marker box plus one spacing step, so the
       checkbox and the text stay aligned if either token is retuned. */
    --vds-editor-task-marker-size: 1rem;
    position: relative;
    list-style: none;
    padding-inline-start: calc(
      var(--vds-editor-task-marker-size) + var(--vds-space-3, 0.75rem)
    );
  }

  .vds-editor-list-item-checked::before,
  .vds-editor-list-item-unchecked::before {
    content: "";
    position: absolute;
    inset-inline-start: 0;
    inset-block-start: 0.35em;
    inline-size: var(--vds-editor-task-marker-size);
    block-size: var(--vds-editor-task-marker-size);
    border: 1px solid var(--vds-editor-border-strong);
    border-radius: var(--vds-radius-checkbox, 0.375rem);
    background: var(--vds-editor-bg);
  }

  .vds-editor-list-item-checked::before {
    border-color: var(--vds-editor-border-focus);
    background: color-mix(
      in oklch,
      var(--vds-editor-border-focus) 14%,
      transparent
    );
  }

  .vds-editor-list-item-checked::after {
    content: "";
    position: absolute;
    inset-inline-start: 0.33rem;
    inset-block-start: 0.53em;
    inline-size: 0.28rem;
    block-size: 0.55rem;
    border-inline-end: 2px solid var(--vds-editor-border-focus);
    border-block-end: 2px solid var(--vds-editor-border-focus);
    transform: rotate(45deg);
  }

  /* The shell is the scrollport, so its corners are the only ones that can be
   * rounded — `border-collapse: collapse` cells cannot follow them. That is
   * exactly what --vds-radius-data-table is capped for: above 8px the cell
   * grid and the scrollbar leave visible wedges inside the arc. Same geometry
   * here as in DataTable, so the same token rather than the surface radius. */
  .vds-editor-table-scroll {
    overflow: auto;
    margin-block: var(--vds-space-4, 1rem);
    border: 1px solid var(--vds-editor-border);
    border-radius: var(--vds-radius-data-table, var(--vds-editor-radius-block, 0.5rem));
  }

  .vds-editor-table {
    inline-size: 100%;
    min-inline-size: 28rem;
    border-collapse: collapse;
    background: var(--vds-editor-bg);
  }

  .vds-editor-table-cell {
    min-inline-size: 8rem;
    padding: var(--vds-space-3, 0.75rem);
    border: 1px solid var(--vds-editor-border);
    vertical-align: top;
