    position: relative;
    box-shadow: inset 0 0 0 1px color-mix(
      in oklch,
      var(--vds-color-primary-solid, #2563eb) 58%,
      transparent
    );
    background: color-mix(
      in oklch,
      var(--vds-color-primary-bg-hover, #dbeafe) 34%,
      var(--vds-editor-bg)
    );
  }

  .vds-editor-table-hover-actions {
    position: absolute;
    inset: 0;
    z-index: 12;
    pointer-events: none;
    overflow: visible;
  }

  .vds-editor-table-hover-button {
    --button-height: 1.75rem;
    --button-padding-inline: 0;
    --button-radius: var(--vds-radius-full, 9999px);
    position: absolute;
    inline-size: 1.75rem;
    min-inline-size: 1.75rem;
    pointer-events: auto;
    box-shadow:
      0 10px 24px -18px color-mix(in oklch, black 38%, transparent),
      0 0 0 1px color-mix(
        in oklch,
        var(--vds-color-primary-8, #60a5fa) 36%,
        transparent
      );
  }

  .vds-editor-table-hover-button[data-axis="column"],
  .vds-editor-table-hover-button[data-axis="row"] {
    transform: translate(-50%, -50%);
  }

  .vds-editor-table-hover-button[data-axis="column"] {
    inset-inline-start: 50%;
    inset-block-start: 0;
  }

  .vds-editor-table-hover-button[data-axis="row"] {
    inset-inline-start: 0;
    inset-block-start: 50%;
  }

  .vds-editor-character-limit {
    background: var(--vds-editor-danger-soft);
    color: var(--vds-color-danger-text, #b91c1c);
    border-radius: var(--vds-editor-radius-control-sm, 0.25rem);
  }

  .vds-editor[data-mode="markdown"] .vds-editor-content,
  .vds-editor[data-mode="html"] .vds-editor-content {
    font-family: var(--vds-font-mono, ui-monospace, monospace);
