import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from "react";
import { createPortal } from "react-dom";

const DROPDOWN_OFFSET = 6;
const VIEWPORT_GUTTER = 8;
const OFFSCREEN_POSITION = -10000;
const EDITOR_DROPDOWN_OPEN_EVENT = "vds-editor-dropdown-open";

interface EditorDropdownRenderProps {
  buttonRef: RefObject<HTMLButtonElement | null>;
  controlsId: string;
  open: boolean;
  setOpen: (open: boolean) => void;
  toggle: () => void;
}

interface EditorDropdownProps {
  autoFocusItems?: boolean;
  children: ReactNode;
  className?: string;
  closeOnTriggerMove?: boolean;
  disabled?: boolean;
  onOpenChange?: (open: boolean) => void;
  stopCloseOnClickSelf?: boolean;
  trigger: (props: EditorDropdownRenderProps) => ReactNode;
}

interface EditorDropdownItemProps {
  children: ReactNode;
  className?: string;
  closeOnSelect?: boolean;
  onSelect?: () => void;
  title?: string;
}

interface EditorDropdownContextValue {
  close: (options?: { restoreFocus?: boolean }) => void;
  registerItem: (itemRef: RefObject<HTMLButtonElement | null>) => void;
}

const EditorDropdownContext = createContext<EditorDropdownContextValue | null>(
  null,
);

export function useEditorDropdown() {
  const context = useContext(EditorDropdownContext);

  if (!context) {
    throw new Error("useEditorDropdown must be used within EditorDropdown.");
  }

  return context;
}

export function EditorDropdownItem({
  children,
  className,
  closeOnSelect = true,
  onSelect,
  title,
}: EditorDropdownItemProps) {
  const itemRef = useRef<HTMLButtonElement | null>(null);
  const context = useContext(EditorDropdownContext);

  if (!context) {
    throw new Error("EditorDropdownItem must be used within EditorDropdown.");
  }

  const { close, registerItem } = context;

  useEffect(() => {
    registerItem(itemRef);
  }, [registerItem]);

  return (
    <button
      ref={itemRef}
      type="button"
      className={className}
      title={title}
      onMouseDown={(event) => event.preventDefault()}
      onClick={() => {
        onSelect?.();
        if (closeOnSelect) {
          close();
        }
      }}
    >
      {children}
    </button>
  );
}

export function EditorDropdownSeparator({
  className,
}: {
  className?: string;
}) {
  return <div className={className} role="separator" />;
}

export function EditorDropdown({
  autoFocusItems = true,
  children,
  className,
  closeOnTriggerMove = true,
  disabled,
  onOpenChange,
  stopCloseOnClickSelf = false,
  trigger,
}: EditorDropdownProps) {
  const panelId = useId();
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const itemsRef = useRef<Array<RefObject<HTMLButtonElement | null>>>([]);
  const [open, setOpen] = useState(false);
  const [position, setPosition] = useState<{ left: number; top: number } | null>(
    null,
  );
  const [highlightedIndex, setHighlightedIndex] = useState(0);

  const setDropdownOpen = useCallback(
    (nextOpen: boolean) => {
      if (nextOpen && disabled) {
        return;
      }

      if (nextOpen) {
        document.dispatchEvent(
          new CustomEvent(EDITOR_DROPDOWN_OPEN_EVENT, { detail: panelId }),
        );
      }

      setOpen(nextOpen);
    },
    [disabled, panelId],
  );

  const isTriggerVisible = useCallback(() => {
    const button = buttonRef.current;

    if (!button || !button.isConnected) {
      return false;
    }

    const rect = button.getBoundingClientRect();

    return (
      rect.width > 0 &&
      rect.height > 0 &&
      rect.bottom >= 0 &&
      rect.right >= 0 &&
      rect.top <= window.innerHeight &&
      rect.left <= window.innerWidth
    );
  }, []);

  const updatePosition = useCallback(() => {
    const button = buttonRef.current;
    const panel = panelRef.current;

    if (!button || !panel) {
      return;
    }

    if (!isTriggerVisible()) {
      setDropdownOpen(false);
      return;
    }

    const { top, left, bottom } = button.getBoundingClientRect();
    const panelRect = panel.getBoundingClientRect();
    const viewportHeight = window.innerHeight;
    const viewportWidth = window.innerWidth;
    const showAbove =
      bottom + panelRect.height + DROPDOWN_OFFSET > viewportHeight &&
      top > panelRect.height + DROPDOWN_OFFSET;
    const nextTop = showAbove
      ? top - panelRect.height - DROPDOWN_OFFSET
      : bottom + DROPDOWN_OFFSET;
    const nextLeft = Math.min(
      left,
      viewportWidth - panelRect.width - VIEWPORT_GUTTER,
    );

    setPosition({
      left: Math.max(VIEWPORT_GUTTER, nextLeft),
      top: Math.max(DROPDOWN_OFFSET, nextTop),
    });
  }, [isTriggerVisible, setDropdownOpen]);

  const close = useCallback(() => {
    setOpen(false);
  }, []);

  const closeWithOptions = useCallback((options?: { restoreFocus?: boolean }) => {
    setOpen(false);

    if (options?.restoreFocus) {
      buttonRef.current?.focus({ preventScroll: true });
    }
  }, []);

  const contextValue = useMemo<EditorDropdownContextValue>(
    () => ({
      close: closeWithOptions,
      registerItem(itemRef) {
        if (!itemsRef.current.includes(itemRef)) {
          itemsRef.current = [...itemsRef.current, itemRef];
        }
      },
    }),
    [closeWithOptions],
  );

  useEffect(() => {
    onOpenChange?.(open);
  }, [onOpenChange, open]);

  useEffect(() => {
    const handleDropdownOpen = (event: Event) => {
      const { detail } = event as CustomEvent<string>;

      if (detail !== panelId) {
        setOpen(false);
      }
    };

    document.addEventListener(
      EDITOR_DROPDOWN_OPEN_EVENT,
      handleDropdownOpen,
    );

    return () => {
      document.removeEventListener(
        EDITOR_DROPDOWN_OPEN_EVENT,
        handleDropdownOpen,
      );
    };
  }, [panelId]);

  useEffect(() => {
    if (!open) {
      itemsRef.current = [];
      setPosition(null);
      setHighlightedIndex(0);
      return;
    }

    const handlePointerDown = (event: MouseEvent) => {
      const target = event.target;

      if (!(target instanceof Node)) {
        return;
      }

      if (buttonRef.current?.contains(target)) {
        return;
      }

      if (stopCloseOnClickSelf && panelRef.current?.contains(target)) {
        return;
      }

      if (!panelRef.current?.contains(target)) {
        close();
      }
    };

    document.addEventListener("mousedown", handlePointerDown);

    return () => {
      document.removeEventListener("mousedown", handlePointerDown);
    };
  }, [close, open, stopCloseOnClickSelf]);

  useEffect(() => {
    if (!open || !closeOnTriggerMove) {
      return;
    }

    const handleWindowResize = () => close();
    const handleDocumentScroll = (event: Event) => {
      const target = event.target;

      if (
        target instanceof Node &&
        panelRef.current?.contains(target)
      ) {
        return;
      }

      close();
    };

    window.addEventListener("resize", handleWindowResize);
    document.addEventListener("scroll", handleDocumentScroll, true);

    return () => {
      window.removeEventListener("resize", handleWindowResize);
      document.removeEventListener("scroll", handleDocumentScroll, true);
    };
  }, [close, open]);

  useEffect(() => {
    if (!open || !closeOnTriggerMove) {
      return;
    }

    const initialRect = buttonRef.current?.getBoundingClientRect();

    if (!initialRect) {
      return;
    }

    let animationFrame = 0;

    const watchTriggerPosition = () => {
      const button = buttonRef.current;

      if (!button || !isTriggerVisible()) {
        close();
        return;
      }

      const rect = button.getBoundingClientRect();
      const moved =
        Math.abs(rect.left - initialRect.left) > 1 ||
        Math.abs(rect.top - initialRect.top) > 1 ||
        Math.abs(rect.width - initialRect.width) > 1 ||
        Math.abs(rect.height - initialRect.height) > 1;

      if (moved) {
        close();
        return;
      }

      animationFrame = window.requestAnimationFrame(watchTriggerPosition);
    };

    animationFrame = window.requestAnimationFrame(watchTriggerPosition);

    return () => {
      window.cancelAnimationFrame(animationFrame);
    };
  }, [close, closeOnTriggerMove, isTriggerVisible, open]);

  useLayoutEffect(() => {
    if (!open) {
      return;
    }

    updatePosition();
  }, [children, open, updatePosition]);

  useEffect(() => {
    if (!open || !autoFocusItems) {
      return;
    }

    const currentItem = itemsRef.current[highlightedIndex]?.current;
    currentItem?.focus();
  }, [autoFocusItems, highlightedIndex, open]);

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (itemsRef.current.length === 0) {
      if (event.key === "Escape" || event.key === "Tab") {
        event.preventDefault();
        closeWithOptions({ restoreFocus: true });
      }
      return;
    }

    if (["Escape", "ArrowUp", "ArrowDown", "Home", "End", "Tab"].includes(event.key)) {
      event.preventDefault();
    }

    if (event.key === "Escape" || event.key === "Tab") {
      closeWithOptions({ restoreFocus: true });
      return;
    }

    if (event.key === "Home") {
      setHighlightedIndex(0);
      return;
    }

    if (event.key === "End") {
      setHighlightedIndex(itemsRef.current.length - 1);
      return;
    }

    if (event.key === "ArrowUp") {
      setHighlightedIndex((current) =>
        current === 0 ? itemsRef.current.length - 1 : current - 1,
      );
      return;
    }

    if (event.key === "ArrowDown") {
      setHighlightedIndex((current) =>
        current === itemsRef.current.length - 1 ? 0 : current + 1,
      );
    }
  }

  return (
    <>
      {trigger({
        buttonRef,
        controlsId: panelId,
        open,
        setOpen: setDropdownOpen,
        toggle: () => setDropdownOpen(!open),
      })}

      {open
        ? createPortal(
            <EditorDropdownContext.Provider value={contextValue}>
              <div
                id={panelId}
                ref={panelRef}
                className={className}
                style={{
                  position: "fixed",
                  left: position?.left ?? OFFSCREEN_POSITION,
                  top: position?.top ?? OFFSCREEN_POSITION,
                }}
                onKeyDown={handleKeyDown}
              >
                {children}
              </div>
            </EditorDropdownContext.Provider>,
            document.body,
          )
        : null}
    </>
  );
}

packages/react-editor/src/EditorField.ts:
import {
  Field,
  composeFieldDescribedBy,
  type FieldProps,
} from "@virtari-packages/react-fieldset";
import { cn } from "@virtari-packages/utils";
import { useId, type CSSProperties } from "react";
import { Editor } from "./Editor";
import type { EditorProps } from "./types";

type AriaInvalidValue = EditorProps["aria-invalid"] | boolean | undefined;

function isInvalid(value: AriaInvalidValue) {
  return value !== undefined && value !== false && value !== "false";
}

export interface EditorFieldProps
  extends Omit<
      FieldProps,
      | keyof EditorProps
      | "children"
      | "controlId"
      | "disabled"
      | "invalid"
      | "required"
    >,
    Omit<EditorProps, "className" | "style"> {
  className?: string;
  style?: CSSProperties;
  editorClassName?: string;
  editorStyle?: CSSProperties;
  invalid?: boolean;
}

export function EditorField({
  label,
  description,
  error,
  counter,
  metaLayout,
  descriptionAlign,
  errorAlign,
  counterAlign,
  labelProps,
  className,
  style,
  editorClassName,
  editorStyle,
  invalid,
  id,
  readOnly,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: EditorFieldProps) {
  const generatedId = useId();
  const controlId = id ?? `vds-editor-field-${generatedId}`;
  const labelId = label ? `${controlId}-label` : undefined;
  const descriptionId = description
    ? `${controlId}-description`
    : undefined;
  const errorId = error ? `${controlId}-error` : undefined;
  const counterId = counter !== undefined ? `${controlId}-counter` : undefined;
  const describedBy = composeFieldDescribedBy(
    ariaDescribedBy,
    descriptionId,
    errorId,
    counterId,
  );
  const resolvedInvalid = invalid ?? isInvalid(ariaInvalid);

  return (
    <Field
      className={cn("vds-editor-field", className)}
      style={style}
      label={label}
      labelProps={{
        ...labelProps,
        id: labelId,
      }}
      description={description}
      error={error}
      counter={counter}
      invalid={resolvedInvalid}
      disabled={readOnly}
      descriptionId={descriptionId}
      errorId={errorId}
      counterId={counterId}
      metaLayout={metaLayout}
      descriptionAlign={descriptionAlign}
      errorAlign={errorAlign}
      counterAlign={counterAlign}
    >
      <Editor
        {...props}
        id={controlId}
        readOnly={readOnly}
        className={editorClassName}
        style={editorStyle}
        aria-labelledby={labelId}
        aria-describedby={describedBy}
        aria-invalid={resolvedInvalid || undefined}
      />
    </Field>
  );
}

packages/react-editor/src/EditorFloating:
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
} from "react";
import { createPortal } from "react-dom";
import {
  useLexicalComposerContext,
} from "@lexical/react/LexicalComposerContext";
import { mergeRegister } from "@lexical/utils";
import { Button } from "@virtari-packages/react-button";
import { Input } from "@virtari-packages/react-input";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@virtari-packages/react-tooltip";
import {
  $getSelection,
  $isRangeSelection,
  COMMAND_PRIORITY_LOW,
  type RangeSelection,
  SELECTION_CHANGE_COMMAND,
} from "lexical";
import {
  Icon,
  IconBold,
  IconCode,
  IconH1,
  IconH2,
  IconH3,
  IconH4,
  IconH5,
  IconH6,
  IconItalic,
  IconLetterCaseLower,
  IconLetterCaseToggle,
  IconLetterCaseUpper,
  IconLink,
  IconLinkOff,
  IconMessageCirclePlus,
  IconStrikethrough,
  IconSubscript,
  IconSuperscript,
  IconTypography,
  IconUnderline,
} from "@virtari-packages/react-icons";
import { cn } from "@virtari-packages/utils";
import { useEditorContext } from "./context";
import {
  applyBlockType,
  applyLink,
  clearLink,
  EMPTY_TOOLBAR_STATE,
  formatText,
  readToolbarState,
  type ToolbarState,
} from "./editor-utils";
import type { EditorBlockType } from "./types";

const FLOATING_BLOCK_OPTIONS: Array<{
  value: Extract<
    EditorBlockType,
    "paragraph" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
  >;
  label: string;
  icon: ComponentProps<typeof Icon>["icon"];
}> = [
  { value: "paragraph", label: "Normal text", icon: IconTypography },
  { value: "h1", label: "Heading 1", icon: IconH1 },
  { value: "h2", label: "Heading 2", icon: IconH2 },
  { value: "h3", label: "Heading 3", icon: IconH3 },
  { value: "h4", label: "Heading 4", icon: IconH4 },
  { value: "h5", label: "Heading 5", icon: IconH5 },
  { value: "h6", label: "Heading 6", icon: IconH6 },
];
import type { EditorFloatingToolbarProps } from "./types";

const FLOATING_TOOLBAR_ICON_SIZE: ComponentProps<typeof Icon>["size"] = "md";

interface EditorFloatingToolbarComponentProps extends EditorFloatingToolbarProps {
  anchorElement: HTMLElement | null;
}

interface FloatingToolbarButtonProps {
  active?: boolean;
  icon: ComponentProps<typeof Icon>["icon"];
  label: string;
  onClick: () => void;
  tooltipSide: "top" | "bottom";
}

function FloatingToolbarButton({
  active,
  icon,
  label,
  onClick,
  tooltipSide,
}: FloatingToolbarButtonProps) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          type="button"
          variant={active ? "soft" : "ghost"}
          color="contrast"
          size="xs"
          className="vds-editor-floating-button"
          aria-label={label}
          onMouseDown={(event) => event.preventDefault()}
          onClick={onClick}
        >
          <Icon icon={icon} size={FLOATING_TOOLBAR_ICON_SIZE} />
        </Button>
      </TooltipTrigger>
      <TooltipContent
        className="vds-editor-floating-tooltip"
        side={tooltipSide}
        size="sm"
        variant="inverted"
      >
        {label}
      </TooltipContent>
    </Tooltip>
  );
}

export function EditorFloatingToolbar({
  className,
  showLinkActions = true,
  showCommentActions = true,
  onRequestComment,
  anchorElement,
}: EditorFloatingToolbarComponentProps) {
  const [editor] = useLexicalComposerContext();
  const { features, readOnly } = useEditorContext();
  const toolbarRef = useRef<HTMLDivElement | null>(null);
  const selectionRef = useRef<RangeSelection | null>(null);
  const [state, setState] = useState<ToolbarState>(EMPTY_TOOLBAR_STATE);
  const [position, setPosition] = useState<{
    left: number;
    top: number;
    placement: "above" | "below";
  } | null>(null);
  const [selectionRect, setSelectionRect] = useState<DOMRect | null>(null);
  const [linkEditorOpen, setLinkEditorOpen] = useState(false);
  const [linkValue, setLinkValue] = useState("");
  const linkInputRef = useRef<HTMLInputElement | null>(null);
  const linkEditorOpenRef = useRef(false);

  useEffect(() => {
    linkEditorOpenRef.current = linkEditorOpen;
  }, [linkEditorOpen]);

  function updateToolbar() {
    editor.getEditorState().read(() => {
      const selection = $getSelection();
      const rootElement = editor.getRootElement();
      const nativeSelection = window.getSelection();
      const focusInsideToolbar = Boolean(
        linkEditorOpenRef.current &&
        toolbarRef.current?.contains(document.activeElement),
      );

      if (
        !anchorElement ||
        !rootElement ||
        readOnly ||
        !$isRangeSelection(selection) ||
        selection.isCollapsed() ||
        selection.getTextContent().trim().length === 0 ||
        !nativeSelection ||
        nativeSelection.rangeCount === 0 ||
        !nativeSelection.anchorNode ||
        !nativeSelection.focusNode ||
        !rootElement.contains(nativeSelection.anchorNode) ||
        !rootElement.contains(nativeSelection.focusNode)
      ) {
        if (focusInsideToolbar) {
          return;
        }

        setPosition(null);
        setSelectionRect(null);
        setLinkEditorOpen(false);
        return;
      }

      const range = nativeSelection.getRangeAt(0);
      const rect = range.getBoundingClientRect();

      if (rect.width === 0 && rect.height === 0) {
        if (focusInsideToolbar) {
          return;
        }

        setPosition(null);
        setSelectionRect(null);
        setLinkEditorOpen(false);
        return;
      }

      selectionRef.current = selection.clone();
      setState(readToolbarState());
      setSelectionRect(rect);
    });
  }

  useLayoutEffect(() => {
    if (!anchorElement || !selectionRect || !toolbarRef.current || readOnly) {
      return;
    }

    const scrollerElement = anchorElement.parentElement;
    const anchorRect = anchorElement.getBoundingClientRect();
    const scrollerRect = scrollerElement?.getBoundingClientRect() ?? anchorRect;
    const nextPlacement =
      selectionRect.top - scrollerRect.top < 72 ? "below" : "above";
    const toolbarRect = toolbarRef.current.getBoundingClientRect();
    const nextLeft = Math.min(
      Math.max(
        selectionRect.left - anchorRect.left + selectionRect.width / 2,
        toolbarRect.width / 2 + 8,
      ),
      anchorRect.width - toolbarRect.width / 2 - 8,
    );
    const nextTop =
      nextPlacement === "above"
        ? selectionRect.top - anchorRect.top
        : selectionRect.bottom - anchorRect.top;

    setPosition({
      left: nextLeft,
      top: nextTop,
      placement: nextPlacement,
    });
  }, [anchorElement, linkEditorOpen, readOnly, selectionRect, state]);

  useEffect(() => {
    if (linkEditorOpen && linkInputRef.current) {
      linkInputRef.current.focus({ preventScroll: true });
      linkInputRef.current.select();
    }
  }, [linkEditorOpen]);

  useEffect(() => {
    updateToolbar();

    return mergeRegister(
      editor.registerUpdateListener(() => {
        updateToolbar();
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          updateToolbar();
          return false;
        },
        COMMAND_PRIORITY_LOW,
      ),
    );
  }, [anchorElement, editor, readOnly]);

  useEffect(() => {
    if (!anchorElement) return;
    const scrollerElement = anchorElement.parentElement;
    const rootElement = editor.getRootElement();

    function handleSelectionChange() {
      updateToolbar();
    }

    window.addEventListener("resize", handleSelectionChange);
    document.addEventListener("selectionchange", handleSelectionChange);
    scrollerElement?.addEventListener("scroll", handleSelectionChange, {
      passive: true,
    });
    rootElement?.addEventListener("scroll", handleSelectionChange, {
      passive: true,
    });

    return () => {
      window.removeEventListener("resize", handleSelectionChange);
      document.removeEventListener("selectionchange", handleSelectionChange);
      scrollerElement?.removeEventListener("scroll", handleSelectionChange);
      rootElement?.removeEventListener("scroll", handleSelectionChange);
    };
  }, [anchorElement, editor, readOnly]);

  function closeLinkEditor() {
    setLinkEditorOpen(false);
    setLinkValue(state.linkUrl);
  }

  function rememberEditorSelection() {
    editor.getEditorState().read(() => {
      const selection = $getSelection();

      if (!$isRangeSelection(selection) || selection.isCollapsed()) {
        return;
      }

      selectionRef.current = selection.clone();
    });
  }

  function toggleLinkEditor() {
    rememberEditorSelection();
    setLinkValue(state.linkUrl);
    setLinkEditorOpen((currentOpen) => !currentOpen);
  }

  function submitLink() {
    const nextLink = linkValue.trim();

    if (!nextLink) {
      clearLink(editor, selectionRef.current);
      closeLinkEditor();
      return;
    }

    applyLink(editor, nextLink, selectionRef.current);
    closeLinkEditor();
  }

  function handleLinkKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter") {
      event.preventDefault();
      submitLink();
    }

    if (event.key === "Escape") {
      event.preventDefault();
      closeLinkEditor();
    }
  }

  if (!anchorElement || !selectionRect || readOnly) {
    return null;
  }

  const tooltipSide = position?.placement === "below" ? "bottom" : "top";

  return createPortal(
