            label="Strikethrough"
            tooltipSide={tooltipSide}
            onClick={() => formatText(editor, "strikethrough", selectionRef.current)}
          />
          {features.advancedTextFormats ? (
            <>
              <FloatingToolbarButton
                active={state.isSubscript}
                icon={IconSubscript}
