import { useEffect, useMemo, useState } from "react";
import { Button } from "@virtari-packages/react-button";
import { CodeEditor } from "@virtari-packages/react-code";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@virtari-packages/react-dialog";
import {
  FileUpload,
  type FileUploadRootProps,
} from "@virtari-packages/react-file-upload";
import {
  Icon,
  IconCode,
  IconLink,
  IconPhoto,
  IconUpload,
  IconVideo,
  IconWorld,
} from "@virtari-packages/react-icons";
import { Input } from "@virtari-packages/react-input";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@virtari-packages/react-tabs";
import type { LexicalEditor } from "lexical";
import { insertMediaBlock } from "./editor-utils";
import type { EditorMediaKind } from "./EditorMediaNode";

type MediaDialogMode = "code" | "embed" | "upload" | "url";

interface EditorMediaDialogProps {
  editor: LexicalEditor;
  kind: EditorMediaKind | null;
  onOpenChange: (open: boolean) => void;
  open: boolean;
  targetBlockElement?: HTMLElement | null;
}

const TRUSTED_EMBED_HOSTS = new Set([
  "aparat.com",
  "canva.com",
  "codepen.io",
  "codesandbox.io",
  "dailymotion.com",
  "dribbble.com",
  "figma.com",
  "instagram.com",
  "loom.com",
  "miro.com",
  "open.spotify.com",
  "player.vimeo.com",
  "soundcloud.com",
  "tiktok.com",
  "twitter.com",
  "vimeo.com",
  "x.com",
  "youtube.com",
  "youtu.be",
]);

function getDefaultMode(kind: EditorMediaKind | null): MediaDialogMode {
  if (kind === "embed") return "embed";
  return "upload";
}

function getDialogCopy(kind: EditorMediaKind | null) {
  if (kind === "video") {
    return {
      description: "Upload a local video or embed from YouTube, Vimeo, Aparat, Loom, and other trusted platforms.",
      title: "Insert video",
    };
  }

  if (kind === "embed") {
    return {
      description: "Paste a direct URL or iframe embed code for docs, maps, prototypes, posts, audio, and other embeds.",
      title: "Insert embed",
    };
  }

  return {
    description: "Upload an image or paste a direct image URL.",
    title: "Insert image",
  };
}

function readFileAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader();

    reader.addEventListener("load", () => {
      if (typeof reader.result === "string") resolve(reader.result);
      else reject(new Error("File could not be read."));
    });
    reader.addEventListener("error", () => reject(reader.error));
    reader.readAsDataURL(file);
  });
}

function getYouTubeId(url: URL) {
  if (url.hostname.includes("youtu.be")) {
    return url.pathname.split("/").filter(Boolean)[0] ?? "";
  }

  if (url.pathname.startsWith("/shorts/")) {
    return url.pathname.split("/").filter(Boolean)[1] ?? "";
  }

  if (url.pathname.startsWith("/embed/")) {
    return url.pathname.split("/").filter(Boolean)[1] ?? "";
  }

  return url.searchParams.get("v") ?? "";
}

function getFirstUrl(value: string) {
  const iframeSrc = value.match(/<iframe[^>]+src=["']([^"']+)["']/i)?.[1];
  if (iframeSrc) return iframeSrc;

  return value.match(/https?:\/\/[^\s"'<>]+/i)?.[0] ?? "";
}

function normalizeEmbedUrl(value: string) {
  const candidate = getFirstUrl(value.trim());
  if (!candidate) return "";

  let url: URL;

  try {
    url = new URL(candidate);
  } catch {
    return candidate;
  }

  const hostname = url.hostname.replace(/^www\./, "").toLowerCase();

  if (hostname === "youtu.be" || hostname.endsWith("youtube.com")) {
    const id = getYouTubeId(url);
    return id ? `https://www.youtube.com/embed/${id}` : candidate;
  }

  if (hostname === "vimeo.com") {
    const id = url.pathname.split("/").filter(Boolean)[0];
    return id ? `https://player.vimeo.com/video/${id}` : candidate;
  }

  if (hostname === "dailymotion.com") {
    const id = url.pathname.split("/").filter(Boolean).at(-1);
    return id ? `https://www.dailymotion.com/embed/video/${id}` : candidate;
  }

  if (hostname === "aparat.com") {
    const id = url.pathname.split("/").filter(Boolean).at(-1);
    return id ? `https://www.aparat.com/video/video/embed/videohash/${id}/vt/frame` : candidate;
  }

  if (hostname === "open.spotify.com") {
    const path = url.pathname.replace(/^\/embed\//, "/");
    return `https://open.spotify.com/embed${path}`;
  }

  if (hostname === "soundcloud.com") {
    return `https://w.soundcloud.com/player/?url=${encodeURIComponent(candidate)}`;
  }

  if (hostname === "figma.com") {
    return `https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(candidate)}`;
  }

  if (hostname === "tiktok.com" || hostname.endsWith(".tiktok.com")) {
    const id = url.pathname.match(/\/video\/(\d+)/)?.[1];
    return id ? `https://www.tiktok.com/embed/v2/${id}` : candidate;
  }

  return candidate;
}

function isTrustedEmbedSource(value: string) {
  try {
    const hostname = new URL(value).hostname.replace(/^www\./, "").toLowerCase();
    return (
      TRUSTED_EMBED_HOSTS.has(hostname) ||
      Array.from(TRUSTED_EMBED_HOSTS).some((host) => hostname.endsWith(`.${host}`))
    );
  } catch {
    return false;
  }
}

export function EditorMediaDialog({
  editor,
  kind,
  onOpenChange,
  open,
  targetBlockElement,
}: EditorMediaDialogProps) {
  const [mode, setMode] = useState<MediaDialogMode>(() => getDefaultMode(kind));
  const [files, setFiles] = useState<File[]>([]);
  const [url, setUrl] = useState("");
  const [embedCode, setEmbedCode] = useState("");
  const [title, setTitle] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const copy = useMemo(() => getDialogCopy(kind), [kind]);
  const accept = useMemo<FileUploadRootProps["accept"]>(
    () => {
      if (kind === "video") {
        return { "video/*": [] } as NonNullable<
          FileUploadRootProps["accept"]
        >;
      }

      return { "image/*": [] } as NonNullable<
        FileUploadRootProps["accept"]
      >;
    },
    [kind],
  );
  const normalizedEmbed = useMemo(
    () => normalizeEmbedUrl(mode === "code" ? embedCode : url),
    [embedCode, mode, url],
  );
  const showUpload = kind === "image" || kind === "video";
  const showCode = kind === "embed";

  useEffect(() => {
    if (!open) return;

    setMode(getDefaultMode(kind));
    setFiles([]);
    setUrl("");
    setEmbedCode("");
    setTitle("");
    setError("");
    setSubmitting(false);
  }, [kind, open]);

  async function handleInsert() {
    if (!kind) return;

    setError("");
    setSubmitting(true);

    try {
      let src = "";

      if (mode === "upload") {
        const [file] = files;

        if (!file) {
          setError("Select a file first.");
          return;
        }

        src = await readFileAsDataUrl(file);
      } else if (mode === "url") {
        src = url.trim();
      } else {
        src = normalizedEmbed;
      }

      if (!src) {
        setError("Add a valid source.");
        return;
      }

      insertMediaBlock(
        editor,
        kind,
        {
          alt: title.trim(),
          src,
        },
        targetBlockElement,
      );
      onOpenChange(false);
    } catch (insertError) {
      setError(
        insertError instanceof Error
          ? insertError.message
          : "Could not insert this media.",
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        size="lg"
        animation="scale"
        backdrop="blur"
        responsive
        showCloseButton
        className="vds-editor-media-dialog"
      >
        <DialogHeader variant="bordered">
          <DialogTitle>{copy.title}</DialogTitle>
          <DialogDescription>{copy.description}</DialogDescription>
        </DialogHeader>

        <DialogBody className="vds-editor-media-dialog-body">
          <Tabs
            value={mode}
            onValueChange={(nextMode) => {
              setMode(nextMode as MediaDialogMode);
              setError("");
            }}
          >
            <TabsList
              variant="segmented"
              size="sm"
              fullWidth
              className="vds-editor-media-mode-list"
            >
              {showUpload ? (
                <TabsTrigger value="upload">
                  <Icon icon={IconUpload} size="xs" />
                  Upload
                </TabsTrigger>
              ) : null}
              {kind === "image" ? (
                <TabsTrigger value="url">
                  <Icon icon={IconLink} size="xs" />
                  URL
                </TabsTrigger>
              ) : null}
              {kind === "video" ? (
                <TabsTrigger value="embed">
                  <Icon icon={IconVideo} size="xs" />
                  Embed
                </TabsTrigger>
              ) : null}
              {kind === "embed" ? (
                <TabsTrigger value="embed">
                  <Icon icon={IconWorld} size="xs" />
                  URL
                </TabsTrigger>
              ) : null}
              {showCode ? (
                <TabsTrigger value="code">
                  <Icon icon={IconCode} size="xs" />
                  Code
                </TabsTrigger>
              ) : null}
            </TabsList>

            {showUpload ? (
              <TabsContent value="upload" className="vds-editor-media-pane">
                <FileUpload.Root
                  accept={accept}
                  files={files}
                  maxFiles={1}
                  multiple={false}
                  onFilesChange={setFiles}
                >
                  <FileUpload.Dropzone className="vds-editor-media-upload">
                    <Icon
                      icon={kind === "video" ? IconVideo : IconPhoto}
                      size="lg"
                    />
                    <div className="vds-editor-media-upload-copy">
                      <span className="vds-editor-media-upload-title">
                        Drop file here
                      </span>
                      <span className="vds-editor-media-upload-description">
                        {kind === "video"
                          ? "MP4, WebM, OGV, or any browser-supported video file."
                          : "PNG, JPG, GIF, WebP, or SVG image file."}
                      </span>
                    </div>
                    <FileUpload.Trigger asChild>
                      <Button type="button" variant="soft" size="sm">
                        Browse
                      </Button>
                    </FileUpload.Trigger>
                  </FileUpload.Dropzone>

                  {files.length > 0 ? (
                    <FileUpload.List className="vds-editor-media-file-list">
                      {files.map((file) => (
                        <FileUpload.Item key={file.name} file={file}>
                          <FileUpload.Preview
                            file={file}
                            className="vds-editor-media-file-preview"
                            render={() => (
                              <span className="vds-editor-media-file-fallback">
                                <Icon icon={IconVideo} size="sm" />
                              </span>
                            )}
                          />
                          <span className="vds-editor-media-file-main">
                            <FileUpload.Item.Name />
                            <FileUpload.Item.Size />
                          </span>
                          <FileUpload.Item.Remove />
                        </FileUpload.Item>
                      ))}
                    </FileUpload.List>
                  ) : null}
                </FileUpload.Root>
              </TabsContent>
            ) : null}

            <TabsContent value="url" className="vds-editor-media-pane">
              <Input
                inputSize="sm"
                value={url}
                onChange={(event) => setUrl(event.currentTarget.value)}
                placeholder="https://example.com/image.png"
              />
            </TabsContent>

            <TabsContent value="embed" className="vds-editor-media-pane">
              <Input
                inputSize="sm"
                value={url}
                onChange={(event) => setUrl(event.currentTarget.value)}
                placeholder="Paste a video, post, prototype, audio, map, or iframe URL"
              />
              {normalizedEmbed ? (
                <div
                  className="vds-editor-media-source-hint"
                  data-trusted={isTrustedEmbedSource(normalizedEmbed) ? "" : undefined}
                >
                  {isTrustedEmbedSource(normalizedEmbed)
                    ? "Trusted embed source"
                    : "Direct embed URL"}
                </div>
              ) : null}
            </TabsContent>

            <TabsContent value="code" className="vds-editor-media-pane">
              <CodeEditor
                className="vds-editor-media-code"
                value={embedCode}
                onValueChange={setEmbedCode}
                language="html"
                filename="embed.html"
                copyable={false}
                showLineNumbers={false}
                wrap
                minLines={4}
                maxLines={8}
                variant="embedded"
                size="sm"
                placeholder='<iframe src="https://..."></iframe>'
              />
              {normalizedEmbed ? (
                <div className="vds-editor-media-source-hint">
                  Using {normalizedEmbed}
                </div>
              ) : null}
            </TabsContent>
          </Tabs>

          <label className="vds-editor-media-field">
            <span>Title / alt text</span>
            <Input
              inputSize="sm"
              value={title}
              onChange={(event) => setTitle(event.currentTarget.value)}
              placeholder={
                kind === "image"
                  ? "Image alt text"
                  : kind === "video"
                    ? "Video title"
                    : "Embed title"
              }
            />
          </label>

          {error ? <div className="vds-editor-media-error">{error}</div> : null}
        </DialogBody>

        <DialogFooter>
          <Button
            type="button"
            variant="ghost"
            color="contrast"
            size="sm"
            onClick={() => onOpenChange(false)}
          >
            Cancel
          </Button>
          <Button
            type="button"
            color="primary"
            size="sm"
            loading={submitting}
            onClick={() => void handleInsert()}
          >
            Insert
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

packages/react-editor/src/EditorMediaNod:
import {
  $applyNodeReplacement,
  DecoratorNode,
  type DOMConversionMap,
  type DOMConversionOutput,
  type DOMExportOutput,
  type EditorConfig,
  type LexicalEditor,
  type LexicalNode,
  type NodeKey,
  type SerializedLexicalNode,
} from "lexical";
import type { ReactNode } from "react";

export type EditorMediaKind = "embed" | "image" | "video";

export interface SerializedEditorMediaNode extends SerializedLexicalNode {
  alt: string;
  kind: EditorMediaKind;
  src: string;
  type: "vds-editor-media";
  version: 1;
}

function normalizeKind(kind: string | null | undefined): EditorMediaKind {
  if (kind === "embed" || kind === "video") return kind;
  return "image";
}

function getElementLabel(element: HTMLElement, fallback = "") {
  return (
    element.getAttribute("alt") ??
    element.getAttribute("aria-label") ??
    element.getAttribute("title") ??
    fallback
  );
}

function getFigureCaption(element: HTMLElement) {
  return element.querySelector("figcaption")?.textContent?.trim() ?? "";
}

function convertImageElement(element: HTMLElement): DOMConversionOutput {
  const image = element as HTMLImageElement;

  return {
    node: $createEditorMediaNode(
      "image",
      image.getAttribute("src") ?? "",
      getElementLabel(image),
    ),
  };
}

function convertVideoElement(element: HTMLElement): DOMConversionOutput {
  const video = element as HTMLVideoElement;

  return {
    node: $createEditorMediaNode(
      "video",
      video.getAttribute("src") ?? "",
      getElementLabel(video),
    ),
  };
}

function convertIframeElement(
  element: HTMLElement,
  kind: EditorMediaKind = "embed",
): DOMConversionOutput {
  const iframe = element as HTMLIFrameElement;

  return {
    node: $createEditorMediaNode(
      kind,
      iframe.getAttribute("src") ?? "",
      getElementLabel(iframe),
    ),
  };
}

function convertFigureElement(
  element: HTMLElement,
): DOMConversionOutput | null {
  const explicitKind = element.dataset.vdsEditorMedia;
  const mediaKind = explicitKind
    ? normalizeKind(explicitKind)
    : element.querySelector("iframe")
      ? "embed"
      : element.querySelector("video")
        ? "video"
        : "image";
  const mediaElement =
    mediaKind === "image"
      ? element.querySelector("img")
      : mediaKind === "video"
        ? element.querySelector("video, iframe")
        : element.querySelector("iframe");
  const caption = getFigureCaption(element);

  if (!explicitKind && !mediaElement) {
    return null;
  }

  if (mediaElement instanceof HTMLImageElement) {
    return {
      node: $createEditorMediaNode(
        "image",
        mediaElement.getAttribute("src") ?? "",
        getElementLabel(mediaElement, caption),
      ),
    };
  }

  if (mediaElement instanceof HTMLVideoElement) {
    return {
      node: $createEditorMediaNode(
        "video",
        mediaElement.getAttribute("src") ?? "",
        getElementLabel(mediaElement, caption),
      ),
    };
  }

  if (mediaElement instanceof HTMLIFrameElement) {
    return {
      node: $createEditorMediaNode(
        mediaKind,
        mediaElement.getAttribute("src") ?? "",
        getElementLabel(mediaElement, caption),
      ),
    };
  }

  return {
    node: $createEditorMediaNode(mediaKind, "", caption),
  };
}

function isDirectVideoSource(src: string) {
  const trimmed = src.trim().toLowerCase();

  if (!trimmed) return false;
  if (trimmed.startsWith("data:video/") || trimmed.startsWith("blob:")) {
    return true;
  }

  const path = trimmed.split(/[?#]/)[0] ?? "";
  return /\.(mp4|webm|ogg|ogv|mov|m4v)$/.test(path);
}

function getSourceLabel(src: string) {
  if (!src) return "No source";
  if (src.startsWith("data:")) return "Uploaded file";
  if (src.startsWith("blob:")) return "Local file";

  try {
    return new URL(src).hostname.replace(/^www\./, "");
  } catch {
    return src;
  }
}

function applyIframeAttributes(iframe: HTMLIFrameElement) {
  iframe.loading = "lazy";
  iframe.allow =
    "accelerometer; autoplay; clipboard-write; encrypted-media; fullscreen; gyroscope; picture-in-picture; web-share";
  iframe.referrerPolicy = "strict-origin-when-cross-origin";
  iframe.setAttribute("allowfullscreen", "true");
}

export class EditorMediaNode extends DecoratorNode<ReactNode> {
  __alt: string;
  __kind: EditorMediaKind;
  __src: string;

  static getType() {
    return "vds-editor-media";
  }

  static clone(node: EditorMediaNode) {
    return new EditorMediaNode(node.__kind, node.__src, node.__alt, node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      figure: () => ({
        conversion: convertFigureElement,
        priority: 2,
      }),
      iframe: () => ({
        conversion: convertIframeElement,
        priority: 2,
      }),
      img: () => ({
        conversion: convertImageElement,
        priority: 2,
      }),
      video: () => ({
        conversion: convertVideoElement,
        priority: 2,
      }),
    };
  }

  static importJSON(serializedNode: SerializedLexicalNode): EditorMediaNode {
    const media = serializedNode as SerializedEditorMediaNode;

    return $createEditorMediaNode(media.kind, media.src, media.alt);
  }

  constructor(kind: EditorMediaKind, src = "", alt = "", key?: NodeKey) {
    super(key);
    this.__kind = kind;
    this.__src = src;
    this.__alt = alt;
  }

  createDOM(_config: EditorConfig): HTMLElement {
    const element = document.createElement("div");

    element.className = "vds-editor-media-block";
    element.dataset.kind = this.__kind;
    return element;
  }

  updateDOM(): false {
    return false;
  }

  exportDOM(): DOMExportOutput {
    const figure = document.createElement("figure");
    const caption = document.createElement("figcaption");

    figure.dataset.vdsEditorMedia = this.__kind;

    if (this.__kind === "image") {
      const image = document.createElement("img");

      if (this.__src) {
        image.src = this.__src;
      }
      image.alt = this.__alt;
      figure.append(image);
      caption.textContent = this.__alt || "Image";
    } else if (this.__kind === "video" && isDirectVideoSource(this.__src)) {
      const video = document.createElement("video");

      video.controls = true;
      if (this.__src) {
        video.src = this.__src;
      }
      if (this.__alt) {
        video.setAttribute("aria-label", this.__alt);
      }
      figure.append(video);
      caption.textContent = this.__alt || "Video";
    } else {
      const iframe = document.createElement("iframe");

      if (this.__src) {
        iframe.src = this.__src;
      }
      iframe.title = this.__alt || (this.__kind === "video" ? "Video" : "Embed");
      applyIframeAttributes(iframe);
      figure.append(iframe);
      caption.textContent = this.__alt || (this.__kind === "video" ? "Video" : "Embed");
    }

    figure.append(caption);

    return { element: figure };
  }

  exportJSON(): SerializedEditorMediaNode {
    return {
      ...super.exportJSON(),
      alt: this.__alt,
      kind: this.__kind,
      src: this.__src,
      type: "vds-editor-media",
      version: 1,
    };
  }

  getTextContent() {
    if (this.__alt) return this.__alt;
    if (this.__kind === "video") return "Video";
    if (this.__kind === "embed") return "Embed";
    return "Image";
  }

  isInline() {
    return false;
  }

  isIsolated() {
    return true;
  }

  isKeyboardSelectable() {
    return true;
  }

  decorate(_editor: LexicalEditor, _config: EditorConfig): ReactNode {
    const label =
      this.__kind === "video"
        ? "Video"
        : this.__kind === "embed"
          ? "Embed"
          : "Image";
    const detail = this.__alt || getSourceLabel(this.__src);

    if (this.__kind === "image" && this.__src) {
      return (
        <figure className="vds-editor-media-figure" data-kind={this.__kind}>
          <img
            className="vds-editor-media-preview"
            src={this.__src}
            alt={this.__alt}
          />
          {this.__alt ? (
            <figcaption className="vds-editor-media-caption">
              {this.__alt}
            </figcaption>
          ) : null}
        </figure>
      );
    }

    if (this.__kind === "video" && this.__src && isDirectVideoSource(this.__src)) {
      return (
        <figure className="vds-editor-media-figure" data-kind={this.__kind}>
          <video
            className="vds-editor-media-preview"
            src={this.__src}
            aria-label={this.__alt || undefined}
            controls
          />
          {this.__alt ? (
            <figcaption className="vds-editor-media-caption">
              {this.__alt}
            </figcaption>
          ) : null}
        </figure>
      );
    }

    if (this.__src && (this.__kind === "embed" || this.__kind === "video")) {
      return (
        <figure className="vds-editor-media-figure" data-kind={this.__kind}>
          <iframe
            className="vds-editor-media-frame"
            src={this.__src}
            title={this.__alt || label}
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; fullscreen; gyroscope; picture-in-picture; web-share"
            allowFullScreen
            loading="lazy"
            referrerPolicy="strict-origin-when-cross-origin"
          />
          {this.__alt ? (
            <figcaption className="vds-editor-media-caption">
              {this.__alt}
            </figcaption>
          ) : null}
        </figure>
      );
    }

    return (
      <div className="vds-editor-media-card" data-kind={this.__kind}>
        <span className="vds-editor-media-kind">{label}</span>
        <span className="vds-editor-media-detail">{detail}</span>
      </div>
    );
  }
}

export function $createEditorMediaNode(
  kind: EditorMediaKind,
  src = "",
  alt = "",
) {
  return $applyNodeReplacement(
    new EditorMediaNode(normalizeKind(kind), src, alt),
  );
}

export function $isEditorMediaNode(
  node: LexicalNode | null | undefined,
): node is EditorMediaNode {
  return node instanceof EditorMediaNode;
}

