import {
  Tabs,
  TabsList,
  TabsTrigger,
} from "@virtari-packages/react-tabs";
import {
  Icon,
  IconFileCode2,
  IconMarkdown,
  IconSourceCode,
} from "@virtari-packages/react-icons";
import { cn } from "@virtari-packages/utils";
import type {
  EditorMode,
  EditorModeSwitcherProps,
} from "./types";

const DEFAULT_LABELS: Record<EditorMode, string> = {
  "rich-text": "Rich",
  markdown: "Markdown",
  html: "HTML",
};

const MODE_ICONS = {
  "rich-text": IconSourceCode,
  markdown: IconMarkdown,
  html: IconFileCode2,
} as const;

interface EditorModeSwitcherControlProps extends EditorModeSwitcherProps {
  value: EditorMode;
  onChange: (mode: EditorMode) => void;
}

export function EditorModeSwitcher({
  className,
  modes = ["rich-text", "markdown", "html"],
  labels,
  value,
  onChange,
}: EditorModeSwitcherControlProps) {
  return (
    <Tabs
      className={cn("vds-editor-mode-switcher", className)}
      value={value}
      onValueChange={(nextValue) => {
        if (modes.includes(nextValue as EditorMode)) {
          onChange(nextValue as EditorMode);
        }
      }}
    >
      <TabsList
        className="vds-editor-mode-list"
        variant="segmented"
        size="sm"
        aria-label="Editor mode"
      >
      {modes.map((mode) => {
        const label = labels?.[mode] ?? DEFAULT_LABELS[mode];

        return (
          <TabsTrigger
            key={mode}
            value={mode}
            className="vds-editor-mode-trigger"
            aria-label={`${label} mode`}
          >
            <Icon icon={MODE_ICONS[mode]} size="sm" />
            <span>{label}</span>
          </TabsTrigger>
        );
      })}
      </TabsList>
    </Tabs>
  );
}

packages/react-editor/src/EditorShortcut:
import { useEffect } from "react";
import {
  useLexicalComposerContext,
} from "@lexical/react/LexicalComposerContext";
import {
  COMMAND_PRIORITY_HIGH,
  KEY_DOWN_COMMAND,
} from "lexical";
import { useEditorConfig } from "./context";
import { hasPrimaryModifier } from "./editor-shortcuts";
import {
  applyBlockType,
  formatElement,
  indentContent,
  outdentContent,
  toggleBulletList,
  toggleCheckList,
  toggleNumberList,
} from "./editor-utils";

function isToolbarTarget(target: EventTarget | null) {
  return (
    target instanceof HTMLElement &&
    Boolean(target.closest("input, textarea, select, button, [role='menu']"))
  );
}

export function EditorShortcutsPlugin() {
  const [editor] = useLexicalComposerContext();
  const { features, readOnly } = useEditorConfig();

  useEffect(() => {
    if (readOnly || !features.shortcuts) {
      return;
    }

    return editor.registerCommand(
      KEY_DOWN_COMMAND,
      (event) => {
        const rootElement = editor.getRootElement();

        if (
          editor.isComposing() ||
          !rootElement ||
          isToolbarTarget(event.target) ||
          !hasPrimaryModifier(event)
        ) {
          return false;
        }

        const target = event.target;

        if (!(target instanceof Node) || !rootElement.contains(target)) {
          return false;
        }

        const key = event.key.toLowerCase();

        if (event.altKey && !event.shiftKey) {
          switch (key) {
            case "0":
              event.preventDefault();
              applyBlockType(editor, "paragraph");
              return true;
            case "1":
              event.preventDefault();
              applyBlockType(editor, "h1");
              return true;
            case "2":
              event.preventDefault();
              applyBlockType(editor, "h2");
              return true;
            case "3":
              event.preventDefault();
              applyBlockType(editor, "h3");
              return true;
            case "4":
              event.preventDefault();
              applyBlockType(editor, "h4");
              return true;
            case "5":
              event.preventDefault();
              applyBlockType(editor, "h5");
              return true;
            case "6":
              event.preventDefault();
              applyBlockType(editor, "h6");
              return true;
            case "c":
              if (!features.codeBlocks) return false;
              event.preventDefault();
              applyBlockType(editor, "code");
              return true;
            default:
              return false;
          }
        }

        if (event.shiftKey) {
          switch (key) {
            case "7":
              if (!features.lists) return false;
              event.preventDefault();
              toggleNumberList(editor, "paragraph");
              return true;
            case "8":
              if (!features.lists) return false;
              event.preventDefault();
              toggleBulletList(editor, "paragraph");
              return true;
            case "9":
              if (!features.checklists) return false;
              event.preventDefault();
              toggleCheckList(editor, "paragraph");
              return true;
            case "q":
              event.preventDefault();
              applyBlockType(editor, "quote");
              return true;
            case "l":
              if (!features.textAlignment) return false;
              event.preventDefault();
              formatElement(editor, "left");
              return true;
            case "e":
              if (!features.textAlignment) return false;
              event.preventDefault();
              formatElement(editor, "center");
              return true;
            case "r":
              if (!features.textAlignment) return false;
              event.preventDefault();
              formatElement(editor, "right");
              return true;
            case "j":
              if (!features.textAlignment) return false;
              event.preventDefault();
              formatElement(editor, "justify");
              return true;
            default:
              return false;
          }
        }

        switch (event.key) {
          case "[":
            event.preventDefault();
            outdentContent(editor);
            return true;
          case "]":
            event.preventDefault();
            indentContent(editor);
            return true;
          default:
            return false;
        }
      },
      COMMAND_PRIORITY_HIGH,
    );
  }, [editor, features, readOnly]);

  return null;
}

