      }}
      trigger={({ buttonRef, controlsId, open, toggle }) => (
        <Button
          ref={buttonRef}
          type="button"
          variant={open || value !== resetValue ? "soft" : "ghost"}
          color="contrast"
          size="sm"
          className="vds-editor-toolbar-trigger vds-editor-toolbar-color-trigger"
          aria-label={label}
          aria-controls={controlsId}
          aria-expanded={open}
