packages/react-flow/src/FlowBadgeEdge.ts:
import { EdgeLabelRenderer, getSmoothStepPath, type Edge, type EdgeProps } from "@xyflow/react";
import type { CSSProperties } from "react";
import type { FlowTone } from "./FlowCanvas";

export interface FlowBadgeEdgeData extends Record<string, unknown> {
  label?: string;
  tone?: FlowTone;
}

export type FlowBadgeEdgeDefinition = Edge<FlowBadgeEdgeData, "badge">;
export type FlowBadgeEdgeProps = EdgeProps<FlowBadgeEdgeDefinition>;

const interactionStrokeStyle: CSSProperties = {
  fill: "none",
  stroke: "transparent",
  strokeWidth: 22,
};

function resolveToneStroke(tone?: FlowTone) {
  switch (tone) {
    case "success":
      return "#22c55e";
    case "warning":
      return "#f59e0b";
    case "danger":
      return "#ef4444";
    case "info":
      return "#38bdf8";
    case "accent":
      return "#fb7185";
    case "neutral":
      return "#94a3b8";
    case "primary":
    default:
      return "#818cf8";
  }
}

export function FlowBadgeEdge({
  animated,
  data,
  markerEnd,
  markerStart,
  selected,
  sourceX,
  sourceY,
  sourcePosition,
  targetX,
  targetY,
  targetPosition,
}: FlowBadgeEdgeProps) {
  const tone = selected ? "primary" : (data?.tone ?? "primary");
  const stroke = resolveToneStroke(tone);
  const [edgePath, labelX, labelY] = getSmoothStepPath({
    borderRadius: 18,
    offset: 28,
    sourceX,
    sourceY,
    sourcePosition,
    targetX,
    targetY,
    targetPosition,
  });

  return (
    <>
      <path
        d={edgePath}
        className="vds-flow-edge-halo"
        markerEnd={markerEnd}
        markerStart={markerStart}
        style={{
          fill: "none",
          stroke,
          opacity: 0.18,
          strokeWidth: 10,
          strokeLinecap: "round",
          strokeLinejoin: "round",
        }}
      />
      <path
        d={edgePath}
        className="react-flow__edge-path vds-flow-edge-path"
        data-active={selected || undefined}
        data-animated={animated || undefined}
        markerEnd={markerEnd}
        markerStart={markerStart}
        style={{
          fill: "none",
          stroke,
          opacity: 0.98,
          strokeWidth: 4.5,
          strokeLinecap: "round",
          strokeLinejoin: "round",
        }}
      />
      <path d={edgePath} className="react-flow__edge-interaction" style={interactionStrokeStyle} />
      {data?.label ? (
        <EdgeLabelRenderer>
          <div
            className="nodrag nopan"
            style={{
              position: "absolute",
              transform: `translate(-50%, -50%) translate(${labelX}px, ${labelY - 22}px)`,
              pointerEvents: "all",
            }}
          >
            <span className="vds-flow-edge-label" data-tone={data.tone ?? "neutral"}>
              <span className="vds-flow-edge-dot" aria-hidden="true" />
              {data.label}
            </span>
          </div>
        </EdgeLabelRenderer>
      ) : null}
    </>
  );
}

packages/react-flow/src/FlowCanvas.tsx:
import { cn } from "@virtari-packages/utils";
import {
  Background,
  BackgroundVariant,
  ConnectionLineType,
  Controls,
  MarkerType,
  MiniMap,
  ReactFlow,
  type ColorMode,
  type DefaultEdgeOptions,
  type Edge,
  type ReactFlowProps,
  type Node,
} from "@xyflow/react";
import {
  useEffect,
  useMemo,
  useState,
  type HTMLAttributes,
  type ReactNode,
} from "react";

export type FlowTone =
  | "neutral"
  | "primary"
  | "success"
  | "warning"
  | "danger"
  | "info"
  | "accent";

function useDocumentColorMode(explicitColorMode?: ColorMode): ColorMode {
  const [mode, setMode] = useState<ColorMode>(explicitColorMode ?? "dark");

  useEffect(() => {
    if (explicitColorMode) {
      setMode(explicitColorMode);
      return;
    }

    const readTheme = () => {
      if (typeof document === "undefined") return "dark" as const;
      return document.documentElement.getAttribute("data-theme") === "light"
        ? "light"
        : "dark";
    };

    setMode(readTheme());

    if (typeof MutationObserver === "undefined") return;
    const observer = new MutationObserver(() => {
      setMode(readTheme());
    });
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["data-theme"],
    });
    return () => observer.disconnect();
  }, [explicitColorMode]);

  return mode;
}

function mergeEdgeOptions(
  base: DefaultEdgeOptions,
  override?: DefaultEdgeOptions,
): DefaultEdgeOptions {
  if (!override) return base;

  return {
    ...base,
    ...override,
    markerEnd: override.markerEnd ?? base.markerEnd,
    style: {
      ...(base.style ?? {}),
      ...(override.style ?? {}),
    },
  };
}

export interface FlowCanvasProps<
  NodeType extends Node = Node,
  EdgeType extends Edge = Edge,
> extends ReactFlowProps<NodeType, EdgeType> {
  backgroundGap?: number;
  backgroundSize?: number;
  backgroundVariant?: BackgroundVariant;
  colorMode?: ColorMode;
  showBackground?: boolean;
  showControls?: boolean;
  showMiniMap?: boolean;
}

export function FlowCanvas<
  NodeType extends Node = Node,
  EdgeType extends Edge = Edge,
>({
  backgroundGap = 24,
  backgroundSize = 1,
  backgroundVariant = BackgroundVariant.Dots,
  className,
  colorMode,
  connectionLineType = ConnectionLineType.SmoothStep,
  defaultEdgeOptions,
  fitView = true,
  fitViewOptions,
  maxZoom = 1.2,
  minZoom = 0.72,
  showBackground = true,
  showControls = true,
  showMiniMap = false,
  snapGrid = [24, 24],
  snapToGrid = true,
  zoomOnDoubleClick = false,
  zoomOnScroll = false,
  children,
  ...props
}: FlowCanvasProps<NodeType, EdgeType>) {
  const resolvedColorMode = useDocumentColorMode(colorMode);

  const mergedEdgeOptions = useMemo<DefaultEdgeOptions>(
    () =>
      mergeEdgeOptions(
        {
          type: "smoothstep",
          markerEnd: {
            type: MarkerType.ArrowClosed,
            width: 18,
            height: 18,
          },
          style: {
            strokeWidth: 2,
          },
        },
        defaultEdgeOptions,
      ),
    [defaultEdgeOptions],
  );

  return (
    <ReactFlow<NodeType, EdgeType>
      className={cn("vds-flow", className)}
      colorMode={resolvedColorMode}
      connectionLineType={connectionLineType}
      defaultEdgeOptions={mergedEdgeOptions}
      fitView={fitView}
      fitViewOptions={{ padding: 0.18, ...(fitViewOptions ?? {}) }}
      maxZoom={maxZoom}
      minZoom={minZoom}
      snapGrid={snapGrid}
      snapToGrid={snapToGrid}
      zoomOnDoubleClick={zoomOnDoubleClick}
      zoomOnScroll={zoomOnScroll}
      {...props}
    >
      {showBackground ? (
        <Background
          color="var(--flow-grid-color)"
          gap={backgroundGap}
          size={backgroundSize}
          variant={backgroundVariant}
        />
      ) : null}
      {showMiniMap ? (
        <MiniMap
          bgColor="color-mix(in oklab, var(--vds-color-surface) 88%, transparent)"
          maskColor="color-mix(in oklab, var(--vds-color-bg-subtle) 74%, transparent)"
          pannable
          zoomable
        />
      ) : null}
      {showControls ? <Controls showInteractive={false} /> : null}
      {children}
    </ReactFlow>
  );
}

export interface FlowNodeShellProps extends HTMLAttributes<HTMLDivElement> {
  selected?: boolean;
  tone?: FlowTone;
}

export function FlowNodeShell({
  className,
  selected,
  tone = "primary",
  ...props
}: FlowNodeShellProps) {
  return (
    <div
      className={cn("vds-flow-node", className)}
      data-selected={selected || undefined}
      data-tone={tone}
      {...props}
    />
  );
}

