    stroke-linejoin: round;
  }

  .vds-flow-edge-path {
    stroke: var(--flow-edge-color);
    stroke-width: var(--flow-edge-width);
    stroke-linecap: round;
    stroke-linejoin: round;
    filter: drop-shadow(0 0 0.45rem color-mix(in oklab, var(--flow-edge-color) 20%, transparent));
  }

  .vds-flow-edge-path[data-active] {
    stroke: var(--flow-edge-active);
  }

  .vds-flow-edge-path[data-animated] {
    stroke-dasharray: 10 8;
    animation: vds-flow-edge-dash 0.95s linear infinite;
  }

  .vds-flow-edge-label {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1-5);
    padding: 0.35rem 0.55rem;
    border: 1px solid var(--flow-label-border);
    border-radius: var(--vds-radius-full);
    background: var(--flow-label-bg);
    color: var(--vds-color-text);
    font-size: var(--vds-text-xs);
    font-weight: var(--vds-font-weight-semibold);
    box-shadow: var(--flow-label-shadow);
    backdrop-filter: blur(10px);
  }

  .vds-flow-edge-label[data-tone="success"] {
    color: var(--vds-color-success-text);
  }

  .vds-flow-edge-label[data-tone="warning"] {
    color: var(--vds-color-warning-text);
  }

  .vds-flow-edge-label[data-tone="danger"] {
    color: var(--vds-color-danger-text);
  }

  .vds-flow-edge-label[data-tone="info"] {
    color: var(--vds-color-info-text);
  }

  .vds-flow-edge-label[data-tone="accent"] {
    color: var(--vds-color-accent-text);
  }

  .vds-flow-edge-dot {
    inline-size: 0.5rem;
    block-size: 0.5rem;
    border-radius: 999px;
    background: currentColor;
    flex: none;
  }

  @keyframes vds-flow-edge-dash {
    to {
      stroke-dashoffset: -18;
    }
  }
}

