import { forwardRef } from "react";
import {
  Field,
  composeFieldDescribedBy,
  hasFieldContent,
  type FieldProps,
} from "@virtari-packages/react-fieldset";
import {
  IconEye,
  IconEyeOff,
} from "@virtari-packages/react-icons";
import { cn, useComposedRefs, useFormReset } from "@virtari-packages/utils";
import { useId, useState, useRef } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import { Input, type InputProps } from "./Input";
import { getPasswordStrength } from "./passwordStrength";

type AriaInvalidValue = InputProps["aria-invalid"] | boolean | undefined;

export interface InputFieldProps
  extends Omit<
      FieldProps,
      | keyof InputProps
      | "afterControl"
      | "children"
      | "controlId"
      | "counter"
      | "disabled"
      | "invalid"
      | "ref"
      | "required"
    >,
    Omit<InputProps, "className" | "ref" | "style"> {
  counter?: ReactNode;
  className?: string;
  style?: CSSProperties;
  inputClassName?: string;
  inputStyle?: CSSProperties;
  showCounter?: boolean;
  counterFormatter?: (current: number, maxLength?: number) => ReactNode;
  revealable?: boolean;
  showStrengthMeter?: boolean;
  strengthFormatter?: (score: number, value: string) => ReactNode;
  afterControl?: ReactNode;
  invalid?: boolean;
  ref?: Ref<HTMLInputElement>;
}

function isInvalid(value: AriaInvalidValue) {
  return value !== undefined && value !== false && value !== "false";
}

function resolveTextValue(value: unknown) {
  if (typeof value === "string") return value;
  if (typeof value === "number") return String(value);
  return "";
}

function defaultCounterFormatter(current: number, maxLength?: number) {
  return maxLength !== undefined ? `${current}/${maxLength}` : current;
}

function defaultStrengthFormatter(score: number) {
  const labels = ["Very weak", "Weak", "Fair", "Strong", "Excellent"];
  return labels[score] ?? labels[0];
}

export const InputField = forwardRef<HTMLInputElement, InputFieldProps>(function InputField({
  label,
  description,
  error,
  counter,
  metaLayout,
  descriptionAlign,
  errorAlign,
  counterAlign,
  labelProps,
  className,
  style,
  inputClassName,
  inputStyle,
  showCounter,
  counterFormatter = defaultCounterFormatter,
  revealable = false,
  showStrengthMeter = false,
  strengthFormatter = defaultStrengthFormatter,
  afterControl,
  invalid,
  id,
  value,
  defaultValue,
  onChange,
  type = "text",
  required,
  disabled,
  maxLength,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}, ref) {
  const localRef = useRef<HTMLInputElement>(null);
  const mergedRef = useComposedRefs(localRef, ref);
  const generatedId = useId();
  const controlId = id ?? `vds-input-field-${generatedId}`;
  const descriptionId = hasFieldContent(description)
    ? `${controlId}-description`
    : undefined;
  const errorId = hasFieldContent(error) ? `${controlId}-error` : undefined;
  const resolvedInvalid = invalid ?? (ariaInvalid !== undefined ? isInvalid(ariaInvalid) : hasFieldContent(error));
  const [revealed, setRevealed] = useState(false);
  const [pwAnim, setPwAnim] = useState<"reveal" | "hide" | null>(null);
  const [uncontrolledValue, setUncontrolledValue] = useState(
    resolveTextValue(defaultValue),
  );
  useFormReset(localRef, () => setUncontrolledValue(resolveTextValue(defaultValue)), props.form);
  const isControlled = value !== undefined;
  const currentValue = isControlled
    ? resolveTextValue(value)
    : uncontrolledValue;
  const currentLength = currentValue.length;
  const resolvedCounter =
    counter ??
    (showCounter ? counterFormatter(currentLength, maxLength) : undefined);
  const counterId = hasFieldContent(resolvedCounter) ? `${controlId}-counter` : undefined;
  const describedBy = composeFieldDescribedBy(
    ariaDescribedBy,
    descriptionId,
    errorId,
    counterId,
  );

  const canReveal = revealable && type === "password";
  const resolvedType = canReveal && revealed ? "text" : type;
  const strengthScore =
    showStrengthMeter && type === "password"
      ? getPasswordStrength(currentValue)
      : 0;
  const resolvedAfterControl =
    showStrengthMeter && type === "password" && currentValue ? (
      <>
        <div
          className="vds-input-field-strength"
          data-score={strengthScore}
          style={
            {
              "--vds-input-strength-score": strengthScore,
            } as CSSProperties
          }
        >
          <div
            className="vds-input-field-strength-bar"
            aria-hidden="true"
          >
            <span className="vds-input-field-strength-fill" />
          </div>
          <span className="vds-input-field-strength-label">
            {strengthFormatter(strengthScore, currentValue)}
          </span>
        </div>
        {afterControl}
      </>
    ) : (
      afterControl
    );

  return (
    <Field
      className={cn("vds-input-field", className)}
      style={style}
      label={label}
      labelProps={labelProps}
      description={description}
      error={error}
      counter={resolvedCounter}
      invalid={resolvedInvalid}
      required={required}
      disabled={disabled}
      controlId={controlId}
      descriptionId={descriptionId}
      errorId={errorId}
      counterId={counterId}
      metaLayout={metaLayout}
      descriptionAlign={descriptionAlign}
      errorAlign={errorAlign}
      counterAlign={counterAlign}
      afterControl={resolvedAfterControl}
    >
      <div
        className="vds-input-field-control"
        data-has-action={canReveal || undefined}
        data-pw-anim={pwAnim ?? undefined}
        onAnimationEnd={() => setPwAnim(null)}
      >
        <Input
          {...props}
          ref={mergedRef}
          id={controlId}
          value={value}
          defaultValue={defaultValue}
          onChange={(event) => {
            if (!isControlled) setUncontrolledValue(event.target.value);
            onChange?.(event);
          }}
          type={resolvedType}
          required={required}
          disabled={disabled}
          maxLength={maxLength}
          aria-describedby={describedBy}
          aria-invalid={invalid !== undefined ? invalid : ariaInvalid ?? (resolvedInvalid || undefined)}
          className={inputClassName}
          style={inputStyle}
        />

        {canReveal ? (
          <button
            type="button"
            className="vds-input-field-action"
            aria-label={revealed ? "Hide password" : "Show password"}
            aria-pressed={revealed}
            disabled={disabled}
            onClick={() => {
              const next = !revealed;
              setRevealed(next);
              setPwAnim(next ? "reveal" : "hide");
            }}
          >
            {revealed ? (
              <IconEyeOff size={16} stroke={1.75} aria-hidden />
            ) : (
              <IconEye size={16} stroke={1.75} aria-hidden />
            )}
          </button>
        ) : null}
      </div>
    </Field>
  );
});

packages/react-input/src/PasswordInput.t:
import { forwardRef } from "react";
import { composeFieldDescribedBy } from "@virtari-packages/react-fieldset";
import {
  IconCheck,
  IconEye,
  IconEyeOff,
} from "@virtari-packages/react-icons";
import { cn, useComposedRefs, useFormReset } from "@virtari-packages/utils";
import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import type {
  CSSProperties,
  ChangeEvent,
  HTMLAttributes,
  ReactNode,
  Ref,
} from "react";
import { Input, type InputProps } from "./Input";
import {
  analyzePasswordStrength,
  type PasswordStrengthAnalysis,
  type PasswordStrengthOptions,
  type PasswordStrengthStandard,
  type PasswordRequirementConfig,
} from "./passwordStrength";

type PasswordInputValue = InputProps["value"] | InputProps["defaultValue"];

export interface PasswordStrengthMeterProps
  extends HTMLAttributes<HTMLDivElement> {
  analysis: PasswordStrengthAnalysis;
  label?: ReactNode;
  strengthFormatter?: (analysis: PasswordStrengthAnalysis) => ReactNode;
  showStrengthBar?: boolean;
  showRequirements?: boolean;
  showFeedback?: boolean;
  requirementsLabel?: ReactNode;
  ref?: Ref<HTMLDivElement>;
}

export interface PasswordInputProps
  extends Omit<InputProps, "type"> {
  rootClassName?: string;
  rootStyle?: CSSProperties;
  revealable?: boolean;
  revealed?: boolean;
  defaultRevealed?: boolean;
  onRevealedChange?: (revealed: boolean) => void;
  showStrengthMeter?: boolean;
  showStrengthBar?: boolean;
  showRequirements?: boolean;
  showFeedback?: boolean;
  requirements?: PasswordRequirementConfig[];
  requirementsLabel?: ReactNode;
  strengthStandard?: PasswordStrengthStandard;
  strongLength?: number;
  strengthOptions?: PasswordStrengthOptions;
  strengthFormatter?: (analysis: PasswordStrengthAnalysis) => ReactNode;
  onStrengthChange?: (analysis: PasswordStrengthAnalysis) => void;
  strengthId?: string;
  strengthClassName?: string;
  strengthStyle?: CSSProperties;
  strengthLabel?: ReactNode;
  showPasswordLabel?: string;
  hidePasswordLabel?: string;
  ref?: Ref<HTMLInputElement>;
}

function resolveTextValue(value: PasswordInputValue) {
  if (typeof value === "string") return value;
  if (typeof value === "number") return String(value);
  if (Array.isArray(value)) return value.join("");
  return "";
}

export function PasswordStrengthMeter({
  analysis,
  label = "Password strength",
  strengthFormatter,
  showStrengthBar = true,
  showRequirements = false,
  showFeedback = false,
  requirementsLabel,
  className,
  style,
  ref,
  ...props
}: PasswordStrengthMeterProps) {
  const resolvedLabel = strengthFormatter
    ? strengthFormatter(analysis)
    : analysis.label;
  const segmentCount = 5;
  const activeSegments =
    analysis.length === 0
      ? 0
      : Math.max(1, Math.min(segmentCount, Math.ceil(analysis.percent / 20)));

  return (
    <div
      ref={ref}
      className={cn("vds-password-strength", className)}
      data-score={analysis.score}
      data-level={analysis.level}
      data-color={analysis.color}
      data-has-requirements={showRequirements || undefined}
      style={
        {
          "--vds-password-strength-percent": `${analysis.percent}%`,
          ...style,
        } as CSSProperties
      }
      {...props}
    >
      {showRequirements ? (
        <>
          {requirementsLabel ? (
            <div className="vds-password-requirements-label">
              {requirementsLabel}
            </div>
          ) : null}
          <ul className="vds-password-requirements">
            {analysis.requirements.map((requirement) => (
              <li
                key={requirement.id}
                className="vds-password-requirement"
                data-met={requirement.met || undefined}
              >
                <span className="vds-password-requirement-icon" aria-hidden>
                  <IconCheck size={9} stroke={3} />
                </span>
                <span>{requirement.label}</span>
              </li>
            ))}
          </ul>
        </>
      ) : null}

      {showStrengthBar ? (
        <div className="vds-password-strength-meter">
          <div className="vds-password-strength-header">
            <span className="vds-password-strength-title">{label}</span>
            <span className="vds-password-strength-value" aria-live="polite">
              {resolvedLabel}
            </span>
          </div>

          <div
            className="vds-password-strength-track"
            role="progressbar"
            aria-label={typeof label === "string" ? label : "Password strength"}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={analysis.percent}
            aria-valuetext={
              typeof resolvedLabel === "string"
                ? resolvedLabel
                : `${analysis.percent}%`
            }
          >
            {Array.from({ length: segmentCount }, (_, index) => (
              <span
                key={index}
                className="vds-password-strength-segment"
                data-active={index < activeSegments || undefined}
              />
            ))}
          </div>
        </div>
      ) : null}

      {showFeedback ? (
        <p className="vds-password-strength-feedback">
          {analysis.feedback}
        </p>
      ) : null}
    </div>
  );
}

export const PasswordInput = forwardRef<HTMLInputElement, PasswordInputProps>(function PasswordInput({
  rootClassName,
  rootStyle,
  className,
  style,
  revealable = true,
  revealed,
  defaultRevealed = false,
  onRevealedChange,
  showStrengthMeter = true,
  showStrengthBar = true,
  showRequirements = false,
  showFeedback = false,
  requirements,
  requirementsLabel,
  strengthStandard,
  strongLength,
  strengthOptions,
  strengthFormatter,
  onStrengthChange,
  strengthId,
  strengthClassName,
  strengthStyle,
  strengthLabel,
  showPasswordLabel = "Show password",
  hidePasswordLabel = "Hide password",
  id,
  value,
  defaultValue,
  onChange,
  minLength,
  disabled,
  readOnly,
  "aria-describedby": ariaDescribedBy,
  ...props
}, ref) {
  const generatedId = useId();
  const localRef = useRef<HTMLInputElement>(null);
  const controlId = id ?? `vds-password-input-${generatedId}`;
  const meterId = strengthId ?? `${controlId}-strength`;
  const [internalRevealed, setInternalRevealed] = useState(defaultRevealed);
  const [pwAnim, setPwAnim] = useState<"reveal" | "hide" | null>(null);
  const [uncontrolledValue, setUncontrolledValue] = useState(
    resolveTextValue(defaultValue),
  );
  useFormReset(localRef, () => setUncontrolledValue(resolveTextValue(defaultValue)), props.form);
  const isValueControlled = value !== undefined;
  const isRevealedControlled = revealed !== undefined;
  const currentValue = isValueControlled
    ? resolveTextValue(value)
    : uncontrolledValue;
  const isRevealed = isRevealedControlled ? revealed : internalRevealed;
  const resolvedStrengthOptions = useMemo(
    () => ({
      ...strengthOptions,
      standard: strengthStandard ?? strengthOptions?.standard ?? "standard",
      minLength: minLength ?? strengthOptions?.minLength,
      strongLength: strongLength ?? strengthOptions?.strongLength,
      requirements: requirements ?? strengthOptions?.requirements,
    }),
    [minLength, requirements, strengthOptions, strengthStandard, strongLength],
  );
  const analysis = useMemo(
    () => analyzePasswordStrength(currentValue, resolvedStrengthOptions),
    [currentValue, resolvedStrengthOptions],
  );
  const describedBy = composeFieldDescribedBy(
    ariaDescribedBy,
    showStrengthMeter ? meterId : undefined,
  );
  const resolvedType = isRevealed ? "text" : "password";

  const mergedRef = useComposedRefs(localRef, ref);

  useEffect(() => {
    onStrengthChange?.(analysis);
  }, [onStrengthChange, analysis]);

  const setRevealState = (next: boolean) => {
    if (!isRevealedControlled) setInternalRevealed(next);
    onRevealedChange?.(next);
    setPwAnim(next ? "reveal" : "hide");
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    if (!isValueControlled) setUncontrolledValue(event.target.value);
    onChange?.(event);
  };

  return (
    <div
      className={cn("vds-password-input-root", rootClassName)}
      style={rootStyle}
      data-disabled={disabled || undefined}
    >
      <div
        className="vds-input-field-control vds-password-input-control"
        data-has-action={revealable || undefined}
        data-pw-anim={pwAnim ?? undefined}
        onAnimationEnd={() => setPwAnim(null)}
      >
        <Input
          {...props}
          ref={mergedRef}
          id={controlId}
          value={value}
          defaultValue={defaultValue}
          onChange={handleChange}
          type={resolvedType}
          minLength={minLength}
          disabled={disabled}
          readOnly={readOnly}
          aria-describedby={describedBy}
          className={className}
          style={style}
        />

        {revealable ? (
          <button
            type="button"
            className="vds-input-field-action"
            aria-label={isRevealed ? hidePasswordLabel : showPasswordLabel}
            aria-pressed={isRevealed}
            disabled={disabled}
            onClick={() => setRevealState(!isRevealed)}
          >
            {isRevealed ? (
              <IconEyeOff size={16} stroke={1.75} aria-hidden />
            ) : (
              <IconEye size={16} stroke={1.75} aria-hidden />
            )}
          </button>
        ) : null}
      </div>

      {showStrengthMeter ? (
        <PasswordStrengthMeter
          id={meterId}
          analysis={analysis}
          label={strengthLabel}
          strengthFormatter={strengthFormatter}
          showStrengthBar={showStrengthBar}
          showRequirements={showRequirements}
          showFeedback={showFeedback}
          requirementsLabel={requirementsLabel}
          className={strengthClassName}
          style={strengthStyle}
        />
      ) : null}
    </div>
  );
});

