  /* Re-export the trigger vars so the trigger (always inside the root) has them,
   * and re-export the option vars inside popover/drawer portals so CSS custom
   * properties survive the portal boundary. */
  .vds-language-picker,
  .vds-combobox-content:has(.vds-language-picker-option),
  .vds-drawer-content:has(.vds-language-picker-drawer-body) {
