    --_lp-stack-gap: 0.0625rem;
    --_lp-primary-color: var(--vds-color-text, currentColor);
    --_lp-primary-weight: var(--vds-font-weight-medium, 500);
    --_lp-subtitle-color: var(--vds-color-text-muted, #6b7280);
    --_lp-subtitle-weight: var(--vds-font-weight-normal, 400);
    --_lp-script-stack: var(--vds-font-sans, ui-sans-serif), "Noto Sans",
      "Noto Sans CJK", "Noto Sans Arabic", system-ui, -apple-system, sans-serif;
  }

  /* LanguageLabel — used standalone; sizing is set inline by `languageLabelVars`. */
  .vds-language-label {
    --_lp-gap: 0.625rem;
    --_lp-stack-gap: 0.0625rem;
    --_lp-primary-color: var(--vds-color-text, currentColor);
    --_lp-primary-weight: var(--vds-font-weight-medium, 500);
    --_lp-subtitle-color: var(--vds-color-text-muted, #6b7280);
    --_lp-subtitle-weight: var(--vds-font-weight-normal, 400);
    --_lp-script-stack: var(--vds-font-sans, ui-sans-serif), "Noto Sans",
      "Noto Sans CJK", "Noto Sans Arabic", system-ui, -apple-system, sans-serif;
  }
