packages/react-nav/src/Nav.css:
@import "./Nav.tokens.css";

@layer design-system.components {
  /* ────────────────────────────────
   * Root <nav>
   * ──────────────────────────────── */
  .vds-nav {
    display: flex;
    min-inline-size: 0;
  }

  .vds-nav[data-orientation="vertical"] {
    flex-direction: column;
    gap: var(--nav-group-gap);
    inline-size: 100%;
  }

  .vds-nav[data-orientation="horizontal"] {
    flex-direction: row;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
  }

  /* ────────────────────────────────
   * List — <ul>
   * ──────────────────────────────── */
  .vds-nav__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    min-inline-size: 0;
  }

  /* Root list mirrors the nav orientation */
  .vds-nav[data-orientation="vertical"] > .vds-nav__list,
  .vds-nav__list[data-orientation="vertical"] {
    flex-direction: column;
    gap: var(--nav-gap);
    inline-size: 100%;
  }

  .vds-nav[data-orientation="horizontal"] > .vds-nav__list,
  .vds-nav__list[data-orientation="horizontal"] {
    flex-direction: row;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
  }

  /* Group — label + list */
  .vds-nav__group {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-1-5, 0.375rem);
  }

  .vds-nav__group-label {
    display: block;
    font-size: var(--nav-group-label-font-size);
    font-weight: var(--nav-group-label-font-weight);
    letter-spacing: var(--nav-group-label-letter-spacing);
    color: var(--nav-group-label-color);
    padding-inline: var(--nav-group-label-padding-inline);
    padding-block: var(--nav-group-label-padding-block);
    text-transform: uppercase;
    user-select: none;
  }

  .vds-nav__separator {
    border: 0;
    block-size: 1px;
    background-color: var(--nav-separator-color);
    margin-block: var(--nav-separator-margin-block);
    margin-inline: 0;
  }

  /* ────────────────────────────────
   * Item — <li> wrapper
   * Structure:
   *   <li class="vds-nav__item">
   *     <a|button class="vds-nav__link|trigger">
   *       <span class="vds-nav__icon"/>
   *       <span class="vds-nav__label"/>
   *       <span class="vds-nav__badge"/> (optional)
   *       <svg  class="vds-nav__chevron"/> (when has submenu)
   *     </a|button>
   *     <div  class="vds-nav__submenu"> (when open/expanded)
   *       <ul  class="vds-nav__list"/>
   *     </div>
   *   </li>
   * ──────────────────────────────── */
  .vds-nav__item {
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    position: relative;
  }

  /* ── Link / Trigger — the clickable affordance ── */
  .vds-nav__link,
  .vds-nav__trigger {
    display: inline-flex;
    align-items: center;
    gap: var(--item-gap);
    flex: 1 1 auto;

    min-inline-size: 0;
    min-block-size: var(--item-height);
    padding-inline: calc(var(--item-padding-inline) + var(--item-indent));
    padding-block: 0;

    background-color: var(--item-background);
    border: var(--item-border-width) solid var(--item-border-color);
    border-radius: var(--item-radius);
    color: var(--item-color);

    font: inherit;
    font-size: var(--item-font-size);
    font-weight: var(--item-font-weight);
    line-height: var(--vds-control-line-height, 1.5);
    text-align: start;
    text-decoration: none;
    white-space: nowrap;

    cursor: pointer;
    user-select: none;

    transition:
      background-color var(--item-transition-duration) var(--item-transition-easing),
      border-color var(--item-transition-duration) var(--item-transition-easing),
      color var(--item-transition-duration) var(--item-transition-easing);
  }

  .vds-nav__trigger {
    appearance: none;
    inline-size: 100%;
  }

  /* Hover */
  .vds-nav__link:hover,
  .vds-nav__trigger:hover {
    background-color: var(--item-background-hover);
    color: var(--item-color-hover);
  }

  /* Active / pressed */
  .vds-nav__link:active,
  .vds-nav__trigger:active {
    background-color: var(--item-background-active);
  }

  /* Current page (aria-current="page" OR data-active="true") */
  .vds-nav__link[aria-current="page"],
  .vds-nav__link[data-active="true"],
  .vds-nav__trigger[data-active="true"] {
    background-color: var(--item-background-current);
    color: var(--item-color-current);
    border-color: var(--item-border-color-current);
  }

  /* Underline variant — bottom-border treatment; item-border-width already 2px */
  .vds-nav[data-variant="underline"] .vds-nav__link,
  .vds-nav[data-variant="underline"] .vds-nav__trigger {
    border-width: 0;
    border-block-end: 2px solid transparent;
    border-radius: 0;
    padding-inline: calc(var(--item-padding-inline) + var(--item-indent));
  }
  .vds-nav[data-variant="underline"] .vds-nav__link[aria-current="page"],
  .vds-nav[data-variant="underline"] .vds-nav__link[data-active="true"],
  .vds-nav[data-variant="underline"] .vds-nav__trigger[data-active="true"] {
    border-block-end-color: var(--vds-color-primary-solid, #6366f1);
    background-color: transparent;
  }

  /* ────────────────────────────────
   * Reveal variant — underline grows from centre on hover.
   * Built with a ::after pseudo that's 0-width by default and scales to
   * the trigger's full content-box width on hover / current. The line
   * stays out of the flex layout (position: absolute).
   * ──────────────────────────────── */
  .vds-nav[data-variant="reveal"] .vds-nav__link,
  .vds-nav[data-variant="reveal"] .vds-nav__trigger {
    position: relative;
    background-color: transparent;
    border-radius: 0;
  }
  .vds-nav[data-variant="reveal"] .vds-nav__link::after,
  .vds-nav[data-variant="reveal"] .vds-nav__trigger::after {
    content: "";
    position: absolute;
    inset-block-end: 0;
    inset-inline-start: 50%;
    inline-size: 0;
    block-size: 2px;
    background-color: var(--vds-color-primary-solid, #6366f1);
    transform: translateX(-50%);
    transition:
      inline-size var(--item-transition-duration) var(--item-transition-easing),
      opacity var(--item-transition-duration) var(--item-transition-easing);
    opacity: 0;
  }
  .vds-nav[data-variant="reveal"] .vds-nav__link:hover::after,
  .vds-nav[data-variant="reveal"] .vds-nav__trigger:hover::after {
    inline-size: calc(100% - (var(--item-padding-inline) * 2));
    opacity: 0.6;
  }
  .vds-nav[data-variant="reveal"] .vds-nav__link[aria-current="page"]::after,
  .vds-nav[data-variant="reveal"] .vds-nav__link[data-active="true"]::after,
  .vds-nav[data-variant="reveal"] .vds-nav__trigger[data-active="true"]::after {
    inline-size: calc(100% - (var(--item-padding-inline) * 2));
    opacity: 1;
  }
  .vds-nav[data-variant="reveal"] .vds-nav__link:hover,
  .vds-nav[data-variant="reveal"] .vds-nav__trigger:hover {
    background-color: transparent;
  }

  /* ────────────────────────────────
   * Outline variant — hollow border ring that fades in on hover.
   * Items stay transparent; the active state uses primary border color
   * and a subtle primary-muted wash.
   * ──────────────────────────────── */
  .vds-nav[data-variant="outline"] .vds-nav__item {
    --item-border-width: 1px;
    --item-background-hover: transparent;
    --item-background-current: transparent;
  }
  .vds-nav[data-variant="outline"] .vds-nav__link,
  .vds-nav[data-variant="outline"] .vds-nav__trigger {
    border-color: transparent;
  }
  .vds-nav[data-variant="outline"] .vds-nav__link:hover,
  .vds-nav[data-variant="outline"] .vds-nav__trigger:hover {
    border-color: var(--vds-color-border, #d1d5db);
    background-color: transparent;
  }
  .vds-nav[data-variant="outline"] .vds-nav__link[aria-current="page"],
  .vds-nav[data-variant="outline"] .vds-nav__link[data-active="true"],
  .vds-nav[data-variant="outline"] .vds-nav__trigger[data-active="true"] {
    border-color: var(--vds-color-primary-solid, #6366f1);
    /* Real semantic role. The old `--vds-color-primary-subtle` never existed,
     * so this fell through to `transparent` and the active item lost its
     * background entirely. */
    background-color: var(--vds-color-primary-bg, #e0e7ff);
  }

  /* ────────────────────────────────
   * None variant — zero chrome. No background, no border, no decoration.
   * Only the text color shifts to primary on hover / current. Quietest
   * possible treatment — good for horizontal menubars where the surrounding
   * design already provides structure and you want the nav to disappear.
   * ──────────────────────────────── */
  .vds-nav[data-variant="none"] .vds-nav__link,
  .vds-nav[data-variant="none"] .vds-nav__trigger {
    background-color: transparent;
    border-color: transparent;
    border-radius: 0;
  }
  .vds-nav[data-variant="none"] .vds-nav__link:hover,
  .vds-nav[data-variant="none"] .vds-nav__trigger:hover {
    background-color: transparent;
    color: var(--vds-color-primary-solid, #6366f1);
  }
  .vds-nav[data-variant="none"] .vds-nav__link:hover .vds-nav__icon,
  .vds-nav[data-variant="none"] .vds-nav__trigger:hover .vds-nav__icon {
    color: var(--vds-color-primary-solid, #6366f1);
  }
  .vds-nav[data-variant="none"] .vds-nav__link[aria-current="page"],
  .vds-nav[data-variant="none"] .vds-nav__link[data-active="true"],
  .vds-nav[data-variant="none"] .vds-nav__trigger[data-active="true"] {
    background-color: transparent;
    color: var(--vds-color-primary-solid, #6366f1);
  }

  /* ────────────────────────────────
   * Dot variant — a 6px primary circle fades / scales in below the label
   * on hover, pinned in on current. Needs a little extra block padding
   * so the dot has room to sit under the text.
   * ──────────────────────────────── */
  .vds-nav[data-variant="dot"] .vds-nav__item {
    --item-dot-size: 0.375rem; /* 6px */
    --item-dot-gap: 0.25rem;
  }
  .vds-nav[data-variant="dot"] .vds-nav__link,
  .vds-nav[data-variant="dot"] .vds-nav__trigger {
    position: relative;
    background-color: transparent;
    border-radius: 0;
    padding-block-end: calc(var(--item-dot-size) + var(--item-dot-gap));
  }
  .vds-nav[data-variant="dot"] .vds-nav__link::after,
  .vds-nav[data-variant="dot"] .vds-nav__trigger::after {
    content: "";
    position: absolute;
    inset-block-end: 0;
    inset-inline-start: 50%;
    inline-size: var(--item-dot-size);
    block-size: var(--item-dot-size);
    border-radius: 50%;
    background-color: var(--vds-color-primary-solid, #6366f1);
    transform: translateX(-50%) scale(0);
    opacity: 0;
    transition:
      transform var(--item-transition-duration) var(--item-transition-easing),
      opacity var(--item-transition-duration) var(--item-transition-easing);
  }
  .vds-nav[data-variant="dot"] .vds-nav__link:hover,
  .vds-nav[data-variant="dot"] .vds-nav__trigger:hover {
    background-color: transparent;
  }
  .vds-nav[data-variant="dot"] .vds-nav__link:hover::after,
  .vds-nav[data-variant="dot"] .vds-nav__trigger:hover::after {
    transform: translateX(-50%) scale(1);
    opacity: 0.55;
  }
  .vds-nav[data-variant="dot"] .vds-nav__link[aria-current="page"]::after,
  .vds-nav[data-variant="dot"] .vds-nav__link[data-active="true"]::after,
  .vds-nav[data-variant="dot"] .vds-nav__trigger[data-active="true"]::after {
    transform: translateX(-50%) scale(1);
    opacity: 1;
  }

  /* ────────────────────────────────
   * Tab variant — thick primary bar below the item, top corners rounded.
   * Reads as a tab-strip indicator (browser-tab / segmented-control style).
   * The bar scales up from 0 on hover and pins to full on current.
   * ──────────────────────────────── */
  .vds-nav[data-variant="tab"] .vds-nav__item {
    --item-tab-size: 0.25rem; /* 4px thickness */
    --item-tab-radius: var(--vds-radius-nav-item, 0.375rem);
  }
  .vds-nav[data-variant="tab"] .vds-nav__link,
  .vds-nav[data-variant="tab"] .vds-nav__trigger {
    position: relative;
    background-color: transparent;
    border-radius: 0;
  }
  .vds-nav[data-variant="tab"] .vds-nav__link::after,
  .vds-nav[data-variant="tab"] .vds-nav__trigger::after {
    content: "";
    position: absolute;
    inset-block-end: 0;
    inset-inline: var(--item-padding-inline);
    block-size: var(--item-tab-size);
    background-color: var(--vds-color-primary-solid, #6366f1);
    border-start-start-radius: var(--item-tab-radius);
    border-start-end-radius: var(--item-tab-radius);
    transform: scaleY(0);
    transform-origin: bottom;
    opacity: 0;
    transition:
      transform var(--item-transition-duration) var(--item-transition-easing),
      opacity var(--item-transition-duration) var(--item-transition-easing);
  }
  .vds-nav[data-variant="tab"] .vds-nav__link:hover,
  .vds-nav[data-variant="tab"] .vds-nav__trigger:hover {
    background-color: transparent;
  }
  .vds-nav[data-variant="tab"] .vds-nav__link:hover::after,
  .vds-nav[data-variant="tab"] .vds-nav__trigger:hover::after {
    transform: scaleY(1);
    opacity: 0.5;
  }
  .vds-nav[data-variant="tab"] .vds-nav__link[aria-current="page"]::after,
  .vds-nav[data-variant="tab"] .vds-nav__link[data-active="true"]::after,
  .vds-nav[data-variant="tab"] .vds-nav__trigger[data-active="true"]::after {
    transform: scaleY(1);
    opacity: 1;
  }
  .vds-nav[data-variant="tab"] .vds-nav__link[aria-current="page"],
  .vds-nav[data-variant="tab"] .vds-nav__link[data-active="true"],
  .vds-nav[data-variant="tab"] .vds-nav__trigger[data-active="true"] {
    color: var(--vds-color-primary-solid, #6366f1);
    background-color: transparent;
  }

  /* ────────────────────────────────
   * Lift variant — small vertical translate + shadow on hover.
   * Gives the item a light card-like bounce. Ignored under
   * prefers-reduced-motion (see reduced-motion block below).
   * ──────────────────────────────── */
  .vds-nav[data-variant="lift"] .vds-nav__link,
  .vds-nav[data-variant="lift"] .vds-nav__trigger {
    transition-property:
      background-color, border-color, color, transform, box-shadow,
      padding-inline, inline-size;
  }
  .vds-nav[data-variant="lift"] .vds-nav__link:hover,
  .vds-nav[data-variant="lift"] .vds-nav__trigger:hover {
    transform: translateY(-1px);
    box-shadow: var(--vds-shadow-sm, 0 1px 2px 0 rgb(0 0 0 / 0.05));
    background-color: var(--vds-color-surface, #fff);
  }
  .vds-nav[data-variant="lift"] .vds-nav__link[aria-current="page"],
  .vds-nav[data-variant="lift"] .vds-nav__link[data-active="true"],
  .vds-nav[data-variant="lift"] .vds-nav__trigger[data-active="true"] {
    background-color: var(--vds-color-surface, #fff);
    box-shadow: var(--vds-shadow-sm, 0 1px 2px 0 rgb(0 0 0 / 0.05));
    color: var(--vds-color-primary-solid, #6366f1);
  }

  /* Focus-visible ring */
  .vds-nav__link:focus-visible,
  .vds-nav__trigger:focus-visible {
    outline: var(--item-focus-ring-width) solid var(--item-focus-ring-color);
    outline-offset: var(--item-focus-ring-offset);
  }

  /* Disabled */
  .vds-nav__link[aria-disabled="true"],
  .vds-nav__trigger[aria-disabled="true"],
  .vds-nav__trigger:disabled {
    color: var(--item-color-disabled);
    cursor: not-allowed;
    pointer-events: none;
  }

  /* ── Icon slot ── */
  .vds-nav__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    inline-size: var(--item-icon-size);
    block-size: var(--item-icon-size);
    color: var(--item-icon-color);
  }
  .vds-nav__icon > svg,
  .vds-nav__icon > img {
    inline-size: 100%;
    block-size: 100%;
  }
  .vds-nav__link[aria-current="page"] .vds-nav__icon,
  .vds-nav__link[data-active="true"] .vds-nav__icon,
  .vds-nav__trigger[data-active="true"] .vds-nav__icon {
    color: var(--item-icon-color-current);
  }

  /* ── Label ── */
  .vds-nav__label {
    display: inline-block;
    min-inline-size: 0;
    flex: 1 1 auto;
    overflow: clip visible;
    text-overflow: ellipsis;
  }

  /* ── Badge slot ── */
  .vds-nav__badge {
    flex: none;
    display: inline-flex;
    align-items: center;
    margin-inline-start: auto;
  }

  /* ── Kbd hint ── */
  .vds-nav__kbd {
    flex: none;
    margin-inline-start: auto;
    font-size: 0.75em;
    color: var(--vds-color-text-muted, #6b7280);
  }

  /* ── Chevron ── */
  .vds-nav__chevron {
    flex: none;
    inline-size: var(--item-chevron-size);
    block-size: var(--item-chevron-size);
    margin-inline-start: auto;
    color: var(--item-chevron-color);
    transform: rotate(var(--item-chevron-rotation));
    transition: transform var(--item-transition-duration) var(--item-transition-easing);
  }
  /* Vertical / inline: chevron points down; open rotates to up-ish. */
  .vds-nav__item[data-orientation="vertical"] .vds-nav__trigger[aria-expanded="true"] > .vds-nav__chevron {
    --item-chevron-rotation: 180deg;
  }
  /* Horizontal: chevron also rotates when open. */
  .vds-nav__item[data-orientation="horizontal"] .vds-nav__trigger[aria-expanded="true"] > .vds-nav__chevron {
    --item-chevron-rotation: 180deg;
  }

  /* When chevron is present, don't absorb its space under .badge */
  .vds-nav__trigger:has(> .vds-nav__chevron) > .vds-nav__badge,
  .vds-nav__trigger:has(> .vds-nav__chevron) > .vds-nav__kbd {
    margin-inline-start: 0;
  }

  /* ────────────────────────────────
   * Submenu — inline (accordion style)
   *
   * Animate opening / closing via the `grid-template-rows: 0fr → 1fr`
   * trick — this is the only CSS-only technique that lets a container
   * transition between 0 and its natural, content-sized height without
   * hard-coding pixel values or JS measurement.
   *
   * The child `<ul>` carries `overflow: hidden; min-block-size: 0` so
   * it clips during the transition and doesn't force the grid row to
   * stay open at its min-content size.
   *
   * `visibility` is transitioned on `step-end` so the element becomes
   * hidden only after the close animation completes (blocks keyboard
   * focus and pointer events while closed) — and snaps back to `visible`
   * instantly on open so the expanding content is visible while it
   * animates in.
   * ──────────────────────────────── */
  .vds-nav__submenu[data-mode="inline"] {
    display: grid;
    grid-template-rows: 0fr;
    visibility: hidden;
    transition:
      grid-template-rows var(--submenu-open-duration, 220ms)
        var(--submenu-open-easing, cubic-bezier(0.2, 0, 0, 1)),
      visibility 0s linear var(--submenu-open-duration, 220ms);
  }

  .vds-nav__submenu[data-mode="inline"][data-state="open"] {
    grid-template-rows: 1fr;
    visibility: visible;
    transition:
      grid-template-rows var(--submenu-open-duration, 220ms)
        var(--submenu-open-easing, cubic-bezier(0.2, 0, 0, 1)),
      visibility 0s linear 0s;
  }

  .vds-nav__submenu[data-mode="inline"] > .vds-nav__list {
    overflow: hidden;
    min-block-size: 0;

    /* The clip that makes the 0fr→1fr height animation possible would also
     * trim the focus ring off every item in here — items are full-bleed, so
     * a ring drawn at `outline-offset` lands entirely outside the clip box
     * and disappears on the inline axis. `overflow` clips at the *padding*
     * box, so growing the padding by exactly the ring's reach and pulling the
     * same amount back with a negative margin buys the ring room without
     * moving anything. The block-start edge already had that much room from
     * the existing gap to the parent trigger. */
    --nav-ring-reach: calc(
      var(--item-focus-ring-offset, 2px) + var(--item-focus-ring-width, 2px)
    );
    padding-block-start: var(--vds-space-1, 0.25rem);
    padding-block-end: var(--nav-ring-reach);
    margin-block-end: calc(-1 * var(--nav-ring-reach));
    padding-inline: var(--nav-ring-reach);
    margin-inline: calc(-1 * var(--nav-ring-reach));
    inline-size: calc(100% + 2 * var(--nav-ring-reach));
  }

  /* ────────────────────────────────
   * Submenu — popover (floating)
   * position/transform set inline by Floating UI
   * ──────────────────────────────── */
  .vds-nav__submenu[data-mode="popover"] {
    inline-size: max-content;
    min-inline-size: var(--submenu-min-inline-size);
    background-color: var(--submenu-background);
    border: 1px solid var(--submenu-border-color);
    border-radius: var(--submenu-radius);
    box-shadow: var(--submenu-shadow);
    padding: var(--submenu-padding);
    z-index: var(--submenu-z-index);

    /* Enter animation */
    animation: vds-nav-enter var(--submenu-open-duration) var(--submenu-open-easing);
  }

  .vds-nav__popover-header {
    display: flex;
    align-items: center;
    min-inline-size: 0;
    padding-inline: var(--submenu-header-padding-inline);
    padding-block-end: var(--submenu-header-padding-block-end);
    margin-block-end: var(--submenu-header-margin-block-end);
    border-block-end: 1px solid var(--submenu-header-border-color);
  }

  .vds-nav__popover-title {
    display: block;
    min-inline-size: 0;
    color: var(--submenu-header-title-color);
    font-size: var(--submenu-header-title-size);
    font-weight: var(--submenu-header-title-weight);
    line-height: 1.2;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  @keyframes vds-nav-enter {
    from {
      opacity: 0;
      transform:
        var(--vds-nav-floating-transform, translate3d(0px, 0px, 0px))
        translateY(-4px) scale(0.98);
    }
    to {
      opacity: 1;
      transform:
        var(--vds-nav-floating-transform, translate3d(0px, 0px, 0px))
        translateY(0) scale(1);
    }
  }

  /* In popover submenus the child list is always vertical.
   *
   * The NavList inherits `data-orientation="horizontal"` from the parent
   * Nav's context (a menubar), which brings `align-items: center` with it.
   * That would center each <li> horizontally inside the column-flexed list,
   * producing visually centered rows — never correct for a submenu. We force
   * `align-items: stretch` here so items fill the popover width and labels
   * read from the inline-start edge (LTR or RTL as the document direction). */
  .vds-nav__submenu[data-mode="popover"] > .vds-nav__list {
    flex-direction: column;
    align-items: stretch;
    gap: var(--nav-gap, var(--vds-space-1, 0.25rem));
    inline-size: 100%;
  }

  /* Defensive: inline submenus nested inside a horizontal Nav would inherit
   * the same `align-items: center`. Same fix, applied to inline lists. */
  .vds-nav__submenu[data-mode="inline"] > .vds-nav__list {
    align-items: stretch;
  }

  /* Items inside popover submenus reset their indent */
  .vds-nav__submenu[data-mode="popover"] .vds-nav__item {
    --item-indent: 0;
  }

  .vds-nav__submenu[data-mode="popover"][data-collapsed-root="true"] {
    --submenu-padding: var(--vds-space-2-5, 0.625rem);
  }

  .vds-nav__submenu[data-mode="popover"][data-collapsed-root="true"] .vds-nav__item,
  .vds-nav__mega[data-collapsed-root="true"] .vds-nav__item {
    --item-padding-inline: var(--submenu-item-padding-inline);
  }

  /* ────────────────────────────────
   * Mega panel
   * ──────────────────────────────── */
  .vds-nav__mega {
    background-color: var(--mega-background);
    border: 1px solid var(--mega-border-color);
    border-radius: var(--mega-radius);
    box-shadow: var(--mega-shadow);
    padding: var(--mega-padding);
    z-index: var(--mega-z-index);

    animation: vds-nav-enter var(--submenu-open-duration) var(--submenu-open-easing);
  }

  .vds-nav__mega[data-columns] {
    display: grid;
    grid-template-columns: repeat(var(--mega-cols, 3), minmax(0, 1fr));
    column-gap: var(--mega-column-gap);
    row-gap: var(--mega-row-gap);
  }

  .vds-nav__mega > .vds-nav__popover-header {
    grid-column: 1 / -1;
  }

  .vds-nav__mega-section {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-1, 0.25rem);
    min-inline-size: 0;
  }

  /* Lists inside a mega panel: same reset as popover submenus — strip the
   * horizontal-Nav-inherited `align-items: center` so items sit at the
   * inline-start edge of each column. */
  .vds-nav__mega .vds-nav__list {
    flex-direction: column;
    align-items: stretch;
    gap: var(--nav-gap, var(--vds-space-1, 0.25rem));
    inline-size: 100%;
  }

  .vds-nav__mega-section-title {
    display: block;
    font-size: var(--vds-text-xs, 0.75rem);
    font-weight: var(--vds-font-weight-semibold, 600);
    letter-spacing: var(--vds-tracking-wide, 0.025em);
    text-transform: uppercase;
    color: var(--vds-color-text-muted, #6b7280);
    padding-inline: var(--vds-space-3, 0.75rem);
    padding-block: var(--vds-space-2, 0.5rem);
  }

  /* ────────────────────────────────
   * Collapsed (rail) mode
   *
   * The nav is rendered as an icon-only rail. Labels are flattened to
   * visually-hidden (but SR-readable) so the accessible name is preserved;
   * badges, keyboard hints, and chevrons are removed entirely. Items become
   * square buttons that center their icon.
   *
   * Submenus are force-switched to popover in NavItem.tsx (inline expansion
   * would be nonsensical on a narrow rail). Floating UI anchors the popover
   * to the icon button with sensible default placement (right-start).
   * ──────────────────────────────── */
  .vds-nav[data-collapsed="true"] .vds-nav__link,
  .vds-nav[data-collapsed="true"] .vds-nav__trigger {
    justify-content: center;
    padding-inline: 0;
    inline-size: var(--item-height);
    gap: 0;
  }

  /* Labels — sr-only (visually hidden, still in the a11y tree). */
  .vds-nav[data-collapsed="true"] .vds-nav__label {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  /* Non-essential chrome — hidden entirely. */
  .vds-nav[data-collapsed="true"] .vds-nav__badge,
  .vds-nav[data-collapsed="true"] .vds-nav__kbd,
  .vds-nav[data-collapsed="true"] .vds-nav__chevron {
    display: none;
  }

  /* Group labels — sr-only so `aria-labelledby` on the group stays valid. */
  .vds-nav[data-collapsed="true"] .vds-nav__group-label {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  /* Inline submenu inside a collapsed nav is impossible — NavItem forces
     popover mode. This rule is belt-and-braces for the rare case a consumer
     renders an inline submenu directly. */
  .vds-nav[data-collapsed="true"] .vds-nav__submenu[data-mode="inline"] {
    display: none;
  }

  /* Smooth-ish collapse — transition padding + size on items so the icons
     glide to center while the parent rail width animates. */
  .vds-nav__link,
  .vds-nav__trigger {
    transition-property:
      background-color,
      border-color,
      color,
      padding-inline,
      inline-size;
    transition-duration: var(--item-transition-duration);
    transition-timing-function: var(--item-transition-easing);
  }

  /* ────────────────────────────────
   * Tree mode — vertical guide lines through nested inline submenus.
   *
   * Opt-in via `tree` prop on <Nav>. Only affects inline submenus; popover
   * submenus render free-floating and don't need the visual connector.
   *
   * The line sits at the parent NavItem's icon centre — `--item-indent`
   * cascades from the parent NavItem to its NavSubmenu (since the submenu
   * is a descendant of the item `<li>`), so we can draw the line at
   * `padding-inline + indent + ~icon-centre`.
   * ──────────────────────────────── */
  .vds-nav[data-tree="true"] .vds-nav__submenu[data-mode="inline"] {
    position: relative;
  }
  .vds-nav[data-tree="true"] .vds-nav__submenu[data-mode="inline"]::before {
    content: "";
    position: absolute;
    inset-block: var(--vds-space-1, 0.25rem) 0;
    inset-inline-start: calc(
      var(--item-padding-inline) + var(--item-indent) + 0.5rem
    );
    inline-size: 1px;
    background-color: var(--vds-color-border-muted, #e5e7eb);
    pointer-events: none;
  }
  /* In tree mode nested items need a little extra inline padding so the
   * label / icon doesn't collide with the guide line directly. */
  .vds-nav[data-tree="true"] .vds-nav__submenu[data-mode="inline"] .vds-nav__link,
  .vds-nav[data-tree="true"] .vds-nav__submenu[data-mode="inline"] .vds-nav__trigger {
    padding-inline-start: calc(
      var(--item-padding-inline) + var(--item-indent) + 0.25rem
    );
  }

  /* ────────────────────────────────
   * Reduced motion
   * ──────────────────────────────── */
  @media (prefers-reduced-motion: reduce) {
    .vds-nav__submenu[data-mode="popover"],
    .vds-nav__mega {
      animation: none;
    }
    .vds-nav__submenu[data-mode="inline"],
    .vds-nav__chevron,
    .vds-nav__link,
    .vds-nav__trigger {
      transition: none;
    }
    .vds-nav[data-variant="lift"] .vds-nav__link:hover,
    .vds-nav[data-variant="lift"] .vds-nav__trigger:hover {
      transform: none;
    }
  }
}

