@layer design-system.components {
  /* ─────────────────────────────────────────────
   * 1. Nav root tokens
   * ───────────────────────────────────────────── */
  .vds-nav {
    --nav-gap: var(--vds-space-1, 0.25rem);
    --nav-group-gap: var(--vds-space-6, 1.5rem);
    --nav-group-label-color: var(--vds-color-text-muted, #6b7280);
    --nav-group-label-font-size: var(--vds-text-xs, 0.75rem);
    --nav-group-label-font-weight: var(--vds-font-weight-semibold, 600);
    --nav-group-label-letter-spacing: var(--vds-tracking-wide, 0.025em);
    --nav-group-label-padding-inline: var(--vds-space-3, 0.75rem);
    --nav-group-label-padding-block: var(--vds-space-2, 0.5rem);

    --nav-separator-color: var(--vds-color-border-muted, #e5e7eb);
    --nav-separator-margin-block: var(--vds-space-2, 0.5rem);
  }

  /* ─────────────────────────────────────────────
   * 2. Item tokens — defaults
   * ───────────────────────────────────────────── */
  .vds-nav__item {
    --item-gap: var(--vds-gap-icon, var(--vds-space-2, 0.5rem));
    --item-height: var(--vds-size-md, 2.25rem);
    --item-padding-inline: var(--vds-space-3, 0.75rem);
    --item-radius: var(--vds-radius-nav-item, 0.375rem);
    --item-font-size: var(--vds-text-sm, 0.875rem);
    --item-font-weight: var(--vds-font-weight-medium, 500);
    --item-indent: 0;

    --item-background: transparent;
    --item-background-hover: var(--vds-color-bg-muted, #f3f4f6);
    --item-background-active: var(--vds-color-bg-subtle, #f9fafb);
    --item-background-current: var(--vds-color-primary-container, #e0e7ff);

    --item-color: var(--vds-color-text, #111827);
    --item-color-hover: var(--vds-color-text, #111827);
    --item-color-current: var(--vds-color-on-primary-container, #3730a3);
    --item-color-disabled: var(--vds-color-text-disabled, #9ca3af);

    --item-border-color: transparent;
    --item-border-color-current: transparent;
    --item-border-width: 0;

    --item-icon-size: 1rem;
    --item-icon-color: var(--vds-color-text-muted, #6b7280);
    --item-icon-color-current: var(--vds-color-primary-solid, #6366f1);

    --item-chevron-size: 0.875rem;
    --item-chevron-color: var(--vds-color-text-muted, #6b7280);
    --item-chevron-rotation: 0deg;

    --item-focus-ring-color: var(--vds-color-ring, #6366f1);
    --item-focus-ring-width: 2px;
    --item-focus-ring-offset: 2px;

    --item-transition-duration: var(--vds-duration-fast, 100ms);
    --item-transition-easing: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  /* ─────────────────────────────────────────────
   * 3. Variants — visual style of items
   *    ghost (default), filled, pill, underline
   * ───────────────────────────────────────────── */

  /* filled — hover becomes a card-like block */
  .vds-nav[data-variant="filled"] .vds-nav__item {
    --item-background: transparent;
    --item-background-hover: var(--vds-color-bg-muted, #f3f4f6);
    --item-background-current: var(--vds-color-primary-container, #e0e7ff);
  }

  /* pill — fully rounded current-state */
  .vds-nav[data-variant="pill"] .vds-nav__item {
    --item-radius: var(--vds-radius-full, 9999px);
  }

  /* underline — flat with bottom-border on current (horizontal usually) */
  .vds-nav[data-variant="underline"] .vds-nav__item {
    --item-radius: 0;
    --item-background-current: transparent;
    --item-border-width: 2px;
    --item-border-color-current: var(--vds-color-primary-solid, #6366f1);
    --item-color-current: var(--vds-color-primary-solid, #6366f1);
  }

  /* ─────────────────────────────────────────────
   * 4. Sizes
   * ───────────────────────────────────────────── */
  .vds-nav[data-size="sm"] .vds-nav__item {
    --item-height: var(--vds-size-sm, 2rem);
    --item-padding-inline: var(--vds-space-2-5, 0.625rem);
    --item-font-size: var(--vds-text-xs, 0.75rem);
    --item-icon-size: 0.875rem;
    --item-gap: var(--vds-space-1-5, 0.375rem);
  }

  .vds-nav[data-size="lg"] .vds-nav__item {
    --item-height: var(--vds-size-lg, 2.5rem);
    --item-padding-inline: var(--vds-space-4, 1rem);
    --item-font-size: var(--vds-text-base, 1rem);
    --item-icon-size: 1.25rem;
    --item-gap: var(--vds-space-3, 0.75rem);
  }

  /* Portalled submenu / mega content lives outside the root `.vds-nav` DOM
   * tree, so mirror the parent nav's size tokens onto the floating panel. */
  .vds-nav__submenu[data-nav-size="sm"] .vds-nav__item,
  .vds-nav__mega[data-nav-size="sm"] .vds-nav__item {
    --item-height: var(--vds-size-sm, 2rem);
    --item-padding-inline: var(--vds-space-2-5, 0.625rem);
    --item-font-size: var(--vds-text-xs, 0.75rem);
    --item-icon-size: 0.875rem;
    --item-gap: var(--vds-space-1-5, 0.375rem);
  }

  .vds-nav__submenu[data-nav-size="lg"] .vds-nav__item,
  .vds-nav__mega[data-nav-size="lg"] .vds-nav__item {
    --item-height: var(--vds-size-lg, 2.5rem);
    --item-padding-inline: var(--vds-space-4, 1rem);
    --item-font-size: var(--vds-text-base, 1rem);
    --item-icon-size: 1.25rem;
    --item-gap: var(--vds-space-3, 0.75rem);
  }

  /* ─────────────────────────────────────────────
   * 5. Nesting indent (vertical / inline submenus)
   *
   *    Uniform 1rem step per level, so every new depth reads as a clear
   *    visual offset from its parent. Supported up to 10 levels — deeper
   *    trees fall back to the default `--item-indent: 0`.
   *
   *    At level 10 the total leading offset is ~10.75rem (indent + base
   *    padding), which fits a standard 16rem sidebar with ellipsis on long
   *    labels. Trees deeper than that should widen the sidebar or use the
   *    popover submenu mode.
   * ───────────────────────────────────────────── */
  .vds-nav__item[data-level="1"]  { --item-indent: var(--vds-space-4,  1rem);   }
  .vds-nav__item[data-level="2"]  { --item-indent: var(--vds-space-8,  2rem);   }
  .vds-nav__item[data-level="3"]  { --item-indent: var(--vds-space-12, 3rem);   }
  .vds-nav__item[data-level="4"]  { --item-indent: var(--vds-space-16, 4rem);   }
  .vds-nav__item[data-level="5"]  { --item-indent: var(--vds-space-20, 5rem);   }
  .vds-nav__item[data-level="6"]  { --item-indent: var(--vds-space-24, 6rem);   }
  .vds-nav__item[data-level="7"]  { --item-indent: 7rem;                        }
  .vds-nav__item[data-level="8"]  { --item-indent: 8rem;                        }
  .vds-nav__item[data-level="9"]  { --item-indent: 9rem;                        }
  .vds-nav__item[data-level="10"] { --item-indent: 10rem;                       }

  /* ─────────────────────────────────────────────
   * 6. Submenu tokens
   * ───────────────────────────────────────────── */
  /* Radius nesting, for the record: the popover panel is 12px-round with a
   * 1px border and 8px of padding, so the concentric target for an item is
   * 12 − 1 − 8 = 3px against the 6px an item actually draws. Deliberately not
   * reconciled. Nav's padded-panel style floats items *inside* the frame —
   * the alternative to Select's flush contract (`padding: 0` + `radius: 0`) —
   * and only the first and last item are corner-adjacent at all; flattening
   * every item to 3px to serve those two would be a redesign, and reaching
   * the element that draws the corner (panel > ul > li > link) would take
   * three chained `data-radius-host`s. */
  .vds-nav__submenu {
    --submenu-background: var(--vds-overlay-bg, var(--vds-color-surface, #ffffff));
    --submenu-border-color: var(--vds-surface-border, var(--vds-color-border-muted, #e5e7eb));
    --submenu-radius: var(--vds-radius-surface, 0.75rem);
    --submenu-shadow: var(--vds-overlay-shadow, var(--vds-shadow-lg, 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)));
    --submenu-padding: var(--vds-space-2, 0.5rem);
    --submenu-item-padding-inline: var(--vds-space-3, 0.75rem);
    --submenu-min-inline-size: 14rem;
    --submenu-z-index: 50;
    --submenu-header-padding-inline: var(--vds-space-2, 0.5rem);
    --submenu-header-padding-block-end: var(--vds-space-2, 0.5rem);
    --submenu-header-margin-block-end: var(--vds-space-1, 0.25rem);
    --submenu-header-border-color: var(--vds-color-border-muted, #e5e7eb);
    --submenu-header-title-size: var(--vds-text-sm, 0.875rem);
    --submenu-header-title-weight: var(--vds-font-weight-semibold, 600);
    --submenu-header-title-color: var(--vds-color-text, #111827);

    --submenu-open-duration: var(--vds-duration-normal, 200ms);
    --submenu-open-easing: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  /* Mega panel tokens */
  .vds-nav__mega {
    --mega-background: var(--vds-overlay-bg, var(--vds-color-surface, #ffffff));
    --mega-border-color: var(--vds-surface-border, var(--vds-color-border-muted, #e5e7eb));
    --mega-radius: var(--vds-radius-surface, 0.75rem);
    --mega-shadow: var(--vds-overlay-shadow, var(--vds-shadow-xl, 0 20px 25px -5px rgb(0 0 0 / 0.1)));
    --mega-padding: var(--vds-space-6, 1.5rem);
    --mega-column-gap: var(--vds-space-6, 1.5rem);
    --mega-row-gap: var(--vds-space-4, 1rem);
    --mega-z-index: 50;
  }
}

