@import "./OtpInput.tokens.css";

@layer design-system.components {
  .vds-otp-input {
    display: flex;
    flex-wrap: wrap;
    gap: var(--_otp-gap);
    align-items: center;
    inline-size: fit-content;
    min-inline-size: 0;
    max-inline-size: 100%;
    direction: ltr;

    &[aria-disabled="true"] {
      opacity: var(--vds-opacity-disabled, 0.5);
      pointer-events: none;
    }
  }

  .vds-otp-input__slot {
    box-shadow: var(--vds-field-shadow, none);
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    line-height: var(--vds-control-line-height, 1.5);
    inline-size: var(--_otp-slot-size);
    min-block-size: var(--_otp-slot-size);
    min-inline-size: 0;
    flex: 0 0 var(--_otp-slot-size);
    text-align: center;
    font-size: var(--_otp-font-size);
    font-weight: var(--vds-font-semibold);
    font-family: var(--vds-font-sans);
    font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum";
    color: var(--vds-color-text);
    background-color: var(--vds-field-bg, var(--vds-color-surface-field, var(--vds-color-surface)));
    border: var(--_otp-border-w) solid var(--vds-field-border, var(--vds-color-border-interactive, var(--vds-color-neutral-9)));
    border-radius: var(--_otp-radius);
    caret-color: var(--vds-color-primary-9);
    appearance: none;
    touch-action: manipulation;
    transition:
      background-color var(--vds-duration-fast) var(--vds-ease-out),
      border-color var(--vds-duration-fast) var(--vds-ease-out),
      box-shadow 180ms ease-out;
    -webkit-touch-callout: default;
    -webkit-user-select: text;
    user-select: text;

    /* hide any browser chrome */
    -moz-appearance: textfield;
    &::-webkit-inner-spin-button,
    &::-webkit-outer-spin-button {
      display: none;
    }

    &:hover:not(:disabled) {
      /* neutral-10, not border-strong (neutral-8): the resting boundary is now
         neutral-9, so border-strong would make hover *lighter* than rest. */
      border-color: var(--vds-field-border-hover, var(--vds-color-neutral-10));
      background-color: var(--vds-field-bg, var(--vds-color-surface-field, var(--vds-color-surface)));
    }

    &:focus-visible {
      /* Box-shadow ring is deliberate here: adjacent slots sit --_otp-gap
         apart and an outline would collide between them. */
      border-color: var(--vds-color-primary-9);
      outline: none;
      box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);
      @media (forced-colors: active) {
        outline: 2px solid Highlight;
        outline-offset: 2px;
        box-shadow: none;
      }
    }

    &[aria-invalid="true"] {
      border-color: var(--vds-color-danger-9);
      &:focus-visible {
        outline: none;
        box-shadow: 0 0 0 4px var(--vds-color-danger-a4), 0 0 12px 2px var(--vds-color-danger-a2);

        @media (forced-colors: active) {
          outline: 2px solid Highlight;
          outline-offset: 2px;
          box-shadow: none;
        }
      }
      transition: box-shadow 180ms ease-out;
      @media (prefers-reduced-motion: reduce) {
        transition-duration: 0s;
      }
    }

    &[data-filled]:not(:focus-visible):not([aria-invalid="true"]) {
      border-color: var(--vds-field-border-hover, var(--vds-color-neutral-10));
    }

    &[data-mask] {
      -webkit-text-security: disc;
    }

    &:disabled {
      cursor: not-allowed;
    }

    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }
}

