  }

  .vds-pagination-controls {
    display: flex;
    align-items: center;
    gap: var(--vds-pagination-gap);
    margin-inline-start: auto;
    flex: 0 1 auto;
    min-inline-size: 0;
  }

  /* Prev / Next */
  .vds-pagination-button {
    all: unset;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--vds-space-1, 0.25rem);
