    block-size: var(--vds-pagination-button-size);
    padding-inline: var(--vds-pagination-button-padding-inline);
    color: var(--vds-pagination-button-color);
    background-color: var(--vds-pagination-button-bg);
    border-radius: var(--vds-pagination-button-radius);
    cursor: pointer;
    transition:
      background-color var(--vds-pagination-transition-duration)
        var(--vds-pagination-transition-easing);
  }
  .vds-pagination-button:hover:not(:disabled) {
    background-color: var(--vds-pagination-button-bg-hover);
  }
  .vds-pagination-button:focus-visible {
    outline: var(--vds-pagination-focus-ring-width) solid
