    outline-offset: 2px;
  }
  .vds-pagination-button:disabled {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
  }

  /* Chevrons flip in RTL so visual direction matches logical Prev/Next. */
  :dir(rtl) .vds-pagination-chevron {
    transform: scaleX(-1);
  }

  /* Page size select wrapper */
  .vds-pagination-page-size {
    display: inline-flex;
