    transition:
      background-color var(--vds-pagination-transition-duration)
        var(--vds-pagination-transition-easing);
  }
  .vds-pagination-page-button:hover {
    background-color: var(--vds-pagination-button-bg-hover);
  }
  .vds-pagination-page-button[data-active] {
    background-color: var(--vds-pagination-button-bg-active);
    color: var(--vds-pagination-button-color-active);
    font-weight: var(--vds-font-weight-semibold, 600);
  }
  .vds-pagination-page-button:focus-visible {
    outline: var(--vds-pagination-focus-ring-width) solid
      var(--vds-pagination-focus-ring-color);
    outline-offset: 2px;
  }
  .vds-pagination-ellipsis {
    padding-inline: var(--vds-pagination-ellipsis-padding-inline);
    color: var(--vds-pagination-info-color);
    user-select: none;
  }

  @media (max-width: 640px) {
    .vds-pagination {
      align-items: flex-start;
    }
    .vds-pagination-controls {
      inline-size: 100%;
      margin-inline-start: 0;
      overflow-x: auto;
      /* A scrolling axis forces the other one to `auto` too, and the buttons
         sit flush against this box — so a focus ring drawn at
         `outline-offset` would be trimmed off top and bottom. `overflow`
         clips at the padding box: buy the ring room there and take the same
         amount back with a negative margin, so the row lands where it did. */
      --pagination-ring-reach: calc(
        var(--vds-pagination-focus-ring-width) + 2px
      );
      padding-block: var(--pagination-ring-reach);
      margin-block: calc(-1 * var(--pagination-ring-reach));
    }
  }
}

