@keyframes vds-control-pop {
  0%   { scale: 0.86; }
  62%  { scale: 1.12; }
  100% { scale: 1; }
}

@keyframes vds-radio-dot-spring {
  0%   { opacity: 0; scale: 0; }
  46%  { opacity: 1; scale: 1.42; }
  72%  { scale: 0.86; }
  100% { scale: 1; }
}

@media (prefers-reduced-motion: reduce) {
  @keyframes vds-control-pop        { 0% { scale: 0.86; } 100% { scale: 1; } }
  @keyframes vds-radio-dot-spring   { 0% { opacity: 0; scale: 0; } 100% { opacity: 1; scale: 1; } }
}

@layer design-system.components {
  /* =========================================================================
   * Atomic radio — circular selector with inner dot.
   * ========================================================================= */
  .vds-radio-item {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    flex-shrink: 0;
    inline-size: var(--radio-size);
    block-size: var(--radio-size);
    padding: 0;
    border: var(--radio-border-width) solid var(--radio-border-color);
    border-radius: var(--vds-radius-full, 9999px);
    background-color: var(--radio-bg);
    color: var(--radio-dot-color);
    cursor: pointer;
    transition:
      background-color var(--radio-transition-duration) var(--radio-transition-easing),
      border-color var(--radio-transition-duration) var(--radio-transition-easing),
      box-shadow 180ms ease-out,
      scale 180ms var(--vds-ease-spring);
    @media (prefers-reduced-motion: reduce) { transition-duration: 0s;
    }
  }

  /* ── Active press ── */
  .vds-radio-item:active:not(:disabled) {
    scale: 0.86;
    transition: scale 30ms linear;
  }

  /* ── Hover (unchecked) ── */
  .vds-radio-item:hover:not(:disabled):not([data-state="checked"]) {
    border-color: var(--radio-border-color-hover);
    background-color: var(--radio-bg-hover);
  }

  /* ── Checked ── */
  .vds-radio-item[data-state="checked"] {
    background-color: var(--radio-bg-checked);
    border-color: var(--radio-border-color-checked);
    animation: vds-control-pop 300ms var(--vds-ease-spring);
  }

  .vds-radio-item[data-state="checked"]:hover:not(:disabled) {
    background-color: var(--radio-bg-checked-hover);
    border-color: var(--radio-border-color-checked-hover);
  }

  /* ── Focus ring ── */
  .vds-radio-item:focus-visible { outline: var(--radio-focus-ring-width) solid var(--radio-focus-ring-color); outline-offset: var(--radio-focus-ring-offset); box-shadow: 0 0 0 4px var(--vds-color-primary-a4), 0 0 12px 2px var(--vds-color-primary-a2);

    @media (forced-colors: active) { outline: 2px solid Highlight; outline-offset: 2px; box-shadow: none;
    }
  }

  /* ── Disabled ── */
  .vds-radio-item:disabled {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
  }

  /* ── Indicator / inner dot ── */
  .vds-radio-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    inline-size: 100%;
    block-size: 100%;
  }

  .vds-radio-dot {
    display: block;
    flex-shrink: 0;
    inline-size: var(--radio-dot-size);
    block-size: var(--radio-dot-size);
    border-radius: var(--vds-radius-full, 9999px);
    background-color: var(--radio-dot-color);
    animation: vds-radio-dot-spring 360ms var(--vds-ease-spring);
  }

  /* =========================================================================
   * Group wrapper — fieldset-like container with label / description / error.
   * The primitive RadioGroup.Root IS this element; we hang label/description/error
   * as siblings next to the items, keeping keyboard roving tabindex intact.
   * ========================================================================= */
  .vds-radio-group {
    display: block;
    min-inline-size: 0;
  }

  .vds-radio-group > * {
    min-inline-size: 0;
  }

  .vds-radio-group > * + * {
    margin-block-start: var(--radio-group-gap);
  }

  .vds-radio-group-header {
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-1, 0.25rem);
  }

  .vds-radio-group-label {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1, 0.25rem);
    font-size: var(--radio-group-label-font-size);
    font-weight: var(--radio-group-label-font-weight);
    color: var(--radio-group-label-color);
    line-height: var(--vds-control-line-height, 1.5);
    overflow-wrap: anywhere;
  }

  .vds-radio-group-required {
    color: var(--radio-group-required-color);
    font-weight: var(--vds-font-weight-semibold, 600);
  }

  .vds-radio-group-description {
    font-size: var(--radio-group-description-font-size);
    color: var(--radio-group-description-color);
    line-height: var(--vds-control-line-height, 1.5);
    overflow-wrap: anywhere;
  }

  .vds-radio-group-items {
    display: flex;
    flex-direction: column;
    gap: var(--radio-group-items-gap);
    min-inline-size: 0;
  }

  .vds-radio-group[data-orientation="horizontal"] > .vds-radio-group-items {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--radio-group-items-gap);
  }

  .vds-radio-group-error {
    margin: 0;
    font-size: var(--radio-group-error-font-size);
    color: var(--radio-group-error-color);
    line-height: var(--vds-leading-snug, 1.375);
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--vds-duration-normal, 200ms)
      var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  .vds-radio-group-error[data-empty] {
    margin-block-start: 0;
  }

  .vds-radio-group-error[data-visible] {
    margin-block-start: var(--radio-group-gap);
    grid-template-rows: 1fr;
  }

  .vds-radio-group-error-body {
    display: inline-flex;
    align-items: center;
    gap: var(--radio-group-error-gap);
    min-block-size: 0;
    overflow: hidden;
    opacity: 0;
    transform: translateY(calc(var(--vds-space-1, 0.25rem) * -1));
    transition:
      opacity var(--vds-duration-normal, 200ms)
        var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1)),
      transform var(--vds-duration-normal, 200ms)
        var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  .vds-radio-group-error[data-visible] .vds-radio-group-error-body {
    opacity: 1;
    transform: translateY(0);
  }

  .vds-radio-group-error-icon {
    flex-shrink: 0;
    color: currentColor;
  }

  .vds-radio-group[data-disabled] {
    opacity: var(--vds-opacity-disabled, 0.5);
  }

  /* Dim once: a disabled group propagates `disabled` to every descendant, so
     without this the group, the field and the control would compound their
     opacities down to ~0.2. */
  .vds-radio-group[data-disabled] .vds-radio-field[data-disabled],
  .vds-radio-group[data-disabled] .vds-radio-card[data-disabled],
  .vds-radio-group[data-disabled] .vds-pill-radio-item:disabled,
  .vds-radio-group[data-disabled] .vds-segmented-radio-item:disabled,
  .vds-radio-group[data-disabled] .vds-radio-item:disabled {
    opacity: 1;
  }
}

[data-vds-no-micro] .vds-radio-item:active             { scale: 1; transition: none; }
[data-vds-no-micro] .vds-radio-item[data-state="checked"] { animation: none; }
[data-vds-no-micro] .vds-radio-dot                        { animation: none; }

@media (prefers-reduced-motion: reduce) {
  .vds-radio-item, .vds-radio-item:active:not(:disabled), .vds-radio-item[data-state="checked"], .vds-radio-dot, .vds-radio-card, .vds-radio-group-error, .vds-radio-group-error-body {
    animation: none;
    transition: none;
    scale: 1;
  }
}

@layer design-system.components {
  /* =========================================================================
