import { useEffect, type RefObject } from "react";

interface UseDragScrollOptions {
  enabled: boolean;
  axis: "x" | "y" | "both";
  /** Pixels of movement before we commit to a drag and start suppressing clicks. */
  threshold?: number;
}

/**
 * Pointer-drag-to-scroll for a scrollable element. Works with mouse, touch
 * and pen through the unified PointerEvent API. Axis-locks on first motion
 * so vertical page scroll still works inside a horizontal scroll area and
 * vice-versa. Suppresses the trailing click when the pointer moved past
 * `threshold` so children underneath don't accidentally activate.
 *
 * Skips initiation when the event originates from an interactive element
 * (button, a, input, textarea, select, role="button", or [data-no-drag])
 * so users can still click / select / copy.
 */
export function useDragScroll(
  viewportRef: RefObject<HTMLElement | null>,
  rootRef: RefObject<HTMLElement | null>,
  { enabled, axis, threshold = 6 }: UseDragScrollOptions,
) {
  useEffect(() => {
    const viewport = viewportRef.current;
    const root = rootRef.current;
    if (!viewport || !root || !enabled) return;

    let pointerId: number | null = null;
    let startX = 0;
    let startY = 0;
    let startScrollLeft = 0;
    let startScrollTop = 0;
    let axisLocked: "x" | "y" | null = null;
    let moved = false;
    let suppressClickUntil = 0;

    const isInteractive = (target: EventTarget | null): boolean => {
      if (!(target instanceof Element)) return false;
      // Only skip drag initiation on form-input surfaces where a click-drag
      // is expected to select text or manipulate a value. Buttons / anchors
      // DO allow drag — the trailing click is suppressed if movement
      // exceeds the threshold, so a plain click still works but a real
      // drag still scrolls. Opt-out explicitly via `data-no-drag`.
      return !!target.closest(
        'input, textarea, select, [contenteditable="true"], [data-no-drag]',
      );
    };

    const cleanup = () => {
      pointerId = null;
      axisLocked = null;
      moved = false;
      root.removeAttribute("data-dragging");
    };

    const onPointerDown = (e: PointerEvent) => {
      // Only primary button for mouse; touch/pen always pass.
      if (e.pointerType === "mouse" && e.button !== 0) return;
      if (isInteractive(e.target)) return;

      pointerId = e.pointerId;
      startX = e.clientX;
      startY = e.clientY;
      startScrollLeft = viewport.scrollLeft;
      startScrollTop = viewport.scrollTop;
      axisLocked = axis === "both" ? null : axis;
      moved = false;

      try {
        viewport.setPointerCapture(e.pointerId);
      } catch {
        // Some environments can throw if capture is already released; ignore.
      }
    };

    const onPointerMove = (e: PointerEvent) => {
      if (pointerId !== e.pointerId) return;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;
      const absDx = Math.abs(dx);
      const absDy = Math.abs(dy);

      if (!axisLocked) {
        if (absDx < threshold && absDy < threshold) return;
        axisLocked = absDx > absDy ? "x" : "y";
      }

      if (!moved && (absDx > threshold || absDy > threshold)) {
        moved = true;
        root.setAttribute("data-dragging", "true");
      }

      if (axisLocked === "x" && (axis === "x" || axis === "both")) {
        viewport.scrollLeft = startScrollLeft - dx;
      } else if (axisLocked === "y" && (axis === "y" || axis === "both")) {
        viewport.scrollTop = startScrollTop - dy;
      }
    };

    const onPointerEnd = (e: PointerEvent) => {
      if (pointerId !== e.pointerId) return;
      const wasMoved = moved;
      try {
        viewport.releasePointerCapture(e.pointerId);
      } catch {
        // ignore
      }
      cleanup();
      if (wasMoved) {
        // Eat the synthetic click that follows a pointerup so children
        // underneath don't activate when the user was dragging. 120ms is
        // larger than the browser's click-after-pointerup delay but small
        // enough not to block a genuine follow-up tap.
        suppressClickUntil = Date.now() + 120;
      }
    };

    const onClickCapture = (e: MouseEvent) => {
      if (Date.now() < suppressClickUntil) {
        e.stopPropagation();
        e.preventDefault();
      }
    };

    viewport.addEventListener("pointerdown", onPointerDown);
    viewport.addEventListener("pointermove", onPointerMove);
    viewport.addEventListener("pointerup", onPointerEnd);
    viewport.addEventListener("pointercancel", onPointerEnd);
    viewport.addEventListener("click", onClickCapture, { capture: true });

    return () => {
      viewport.removeEventListener("pointerdown", onPointerDown);
      viewport.removeEventListener("pointermove", onPointerMove);
      viewport.removeEventListener("pointerup", onPointerEnd);
      viewport.removeEventListener("pointercancel", onPointerEnd);
      viewport.removeEventListener("click", onClickCapture, { capture: true });
      cleanup();
    };
  }, [viewportRef, rootRef, enabled, axis, threshold]);
}

import { useEffect, type RefObject } from "react";

export interface EdgeState {
  atInlineStart: boolean;
  atInlineEnd: boolean;
  atBlockStart: boolean;
  atBlockEnd: boolean;
}

interface UseEdgeStateOptions {
  enabled: boolean;
  orientation: "vertical" | "horizontal" | "both";
  /** Threshold (px) within which an edge is considered "reached". */
  tolerance?: number;
  /** Fires whenever the edge state changes. Lets React components reflect
   *  disabled state on arrow buttons without re-reading DOM attrs. */
  onChange?: (state: EdgeState) => void;
}

/**
 * Observes a scroll viewport and reflects its edge state on the given root
 * element as logical data attributes:
 *
 *   data-at-start            → scrollLeft at inline-start edge (RTL-aware)
 *   data-at-end              → scrollLeft at inline-end   edge (RTL-aware)
 *   data-at-block-start      → scrollTop  at block-start  edge
 *   data-at-block-end        → scrollTop  at block-end    edge
 *
 * Also drives the mask CSS variables (`--scroll-area-mask-inline-start`,
 * etc.) so the gradient fades only where content continues. A `black` value
 * means "no fade" (we're at that edge); `transparent` means "fade" (more
 * content past this edge).
 *
 * Uses `scroll` + `ResizeObserver` — no rAF polling needed because the
 * browser coalesces scroll events and both properties we need
 * (scrollLeft/Top + clientSize/scrollSize) are read synchronously in the
 * handler on the same frame.
 */
export function useEdgeState(
  viewportRef: RefObject<HTMLElement | null>,
  rootRef: RefObject<HTMLElement | null>,
  { enabled, orientation, tolerance = 1, onChange }: UseEdgeStateOptions,
) {
  useEffect(() => {
    const viewport = viewportRef.current;
    const root = rootRef.current;
    if (!viewport || !root || !enabled) return;

    const isRTL = () => getComputedStyle(root).direction === "rtl";
    let prev: EdgeState | null = null;

    const update = () => {
      const {
        scrollLeft,
        scrollTop,
        clientWidth,
        clientHeight,
        scrollWidth,
        scrollHeight,
      } = viewport;

      // Horizontal (inline) — browsers differ on scrollLeft sign in RTL.
      // Chrome/Safari/FF modern all use negative-or-zero in RTL.
      // Math.abs handles both. A single overflow value smaller than
      // `tolerance` (< 1px) is treated as "no overflow".
      const horizontalOverflow = scrollWidth - clientWidth;
      const atInlineStart =
        horizontalOverflow <= tolerance
          ? true
          : isRTL()
          ? Math.abs(scrollLeft) <= tolerance
          : scrollLeft <= tolerance;
      const atInlineEnd =
        horizontalOverflow <= tolerance
          ? true
          : isRTL()
          ? Math.abs(scrollLeft) >= horizontalOverflow - tolerance
          : scrollLeft >= horizontalOverflow - tolerance;

      const verticalOverflow = scrollHeight - clientHeight;
      const atBlockStart =
        verticalOverflow <= tolerance ? true : scrollTop <= tolerance;
      const atBlockEnd =
        verticalOverflow <= tolerance
          ? true
          : scrollTop >= verticalOverflow - tolerance;

      root.toggleAttribute("data-at-start", atInlineStart);
      root.toggleAttribute("data-at-end", atInlineEnd);
      root.toggleAttribute("data-at-block-start", atBlockStart);
      root.toggleAttribute("data-at-block-end", atBlockEnd);

      // Drive mask CSS variables. `black` = opaque (no fade); `transparent` = fade.
      if (orientation === "horizontal" || orientation === "both") {
        root.style.setProperty(
          "--scroll-area-mask-inline-start",
          atInlineStart ? "black" : "transparent",
        );
        root.style.setProperty(
          "--scroll-area-mask-inline-end",
          atInlineEnd ? "black" : "transparent",
        );
      }
      if (orientation === "vertical" || orientation === "both") {
        root.style.setProperty(
          "--scroll-area-mask-block-start",
          atBlockStart ? "black" : "transparent",
        );
        root.style.setProperty(
          "--scroll-area-mask-block-end",
          atBlockEnd ? "black" : "transparent",
        );
      }

      if (onChange) {
        if (
          !prev ||
          prev.atInlineStart !== atInlineStart ||
          prev.atInlineEnd !== atInlineEnd ||
          prev.atBlockStart !== atBlockStart ||
          prev.atBlockEnd !== atBlockEnd
        ) {
          prev = { atInlineStart, atInlineEnd, atBlockStart, atBlockEnd };
          onChange(prev);
        }
      }
    };

    update();

    viewport.addEventListener("scroll", update, { passive: true });
    const resizeObserver = new ResizeObserver(update);
    resizeObserver.observe(viewport);
    // Also observe the content to catch cases where children resize/load.
    const content = viewport.firstElementChild;
    if (content) resizeObserver.observe(content);

    return () => {
      viewport.removeEventListener("scroll", update);
      resizeObserver.disconnect();
    };
  }, [viewportRef, rootRef, enabled, orientation, tolerance, onChange]);
}

import { useEffect, type RefObject } from "react";

interface UseInfiniteScrollOptions {
  enabled: boolean;
  orientation: "vertical" | "horizontal" | "both";
  /** Distance from the end (px) at which to fire the callback. */
  threshold: number;
  onEndReached: (() => void) | undefined;
}

/**
 * IntersectionObserver-based end-of-viewport detection. Cheaper and
 * smoother than scroll-event polling because the browser batches
 * intersection computations off the main thread. The caller places a
 * sentinel element at the end of the scrollable content; this hook
 * observes that sentinel with `root = viewport` and a negative
 * root-margin that equals the threshold, so the sentinel is considered
 * intersecting *before* it physically enters the viewport.
 *
 * Re-arms only after the sentinel leaves the intersection again, so
 * `onEndReached` fires once per "reach the end" event, not continuously
 * while the user idles at the bottom.
 */
export function useInfiniteScroll(
  viewportRef: RefObject<HTMLElement | null>,
  sentinelRef: RefObject<HTMLElement | null>,
  { enabled, orientation, threshold, onEndReached }: UseInfiniteScrollOptions,
) {
  useEffect(() => {
    const viewport = viewportRef.current;
    const sentinel = sentinelRef.current;
    if (!viewport || !sentinel || !enabled || !onEndReached) return;

    let armed = true;

    // Build rootMargin that pushes the intersection boundary outward
    // in the direction of scroll travel, so the callback fires `threshold`
    // px before the sentinel is actually visible.
    const m = `${threshold}px`;
    const rootMargin =
      orientation === "horizontal"
        ? `0px ${m} 0px ${m}`
        : orientation === "both"
        ? `${m} ${m} ${m} ${m}`
        : `${m} 0px ${m} 0px`;

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            if (armed) {
              armed = false;
              onEndReached();
            }
          } else {
            // Left the intersection — ready to fire again next time we enter.
            armed = true;
          }
        }
      },
      { root: viewport, rootMargin, threshold: 0 },
    );

    observer.observe(sentinel);
    return () => {
      observer.disconnect();
    };
  }, [viewportRef, sentinelRef, enabled, orientation, threshold, onEndReached]);
}

import { useEffect, type RefObject } from "react";

interface UseWheelHorizontalOptions {
  enabled: boolean;
}

/**
 * Converts vertical mouse-wheel deltas into horizontal scroll on the
 * viewport. Honours trackpad two-finger horizontal gestures by checking
 * which delta dominates, and respects Shift (native "scroll sideways")
 * and Ctrl (zoom) so user intent is preserved.
 *
 * Must use `{ passive: false }` so we can call `preventDefault()` and
 * stop the wheel event from scrolling the page vertically.
 */
export function useWheelHorizontal(
  viewportRef: RefObject<HTMLElement | null>,
  { enabled }: UseWheelHorizontalOptions,
) {
  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport || !enabled) return;

    const onWheel = (e: WheelEvent) => {
      // Ctrl = pinch zoom on trackpads — never intercept.
      if (e.ctrlKey) return;
      // Shift = user's explicit request for horizontal; browsers already
      // translate it. Let native behaviour handle it.
      if (e.shiftKey) return;

      const absX = Math.abs(e.deltaX);
      const absY = Math.abs(e.deltaY);

      // Trackpad horizontal gesture — pass through untouched.
      if (absX > absY) return;
      if (absY === 0) return;

      // Only intercept if there's actually horizontal room to scroll.
      const overflow = viewport.scrollWidth - viewport.clientWidth;
      if (overflow <= 0) return;
      const atStart = viewport.scrollLeft <= 0;
      const atEnd = viewport.scrollLeft >= overflow;
      // If we'd just eat the event without scrolling further in that
      // direction, release it to the page so the outer scroll can take over.
      if ((e.deltaY < 0 && atStart) || (e.deltaY > 0 && atEnd)) return;

      e.preventDefault();
      viewport.scrollLeft += e.deltaY;
    };

    viewport.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      viewport.removeEventListener("wheel", onWheel);
    };
  }, [viewportRef, enabled]);
}

