  .vds-scroll-area-root[data-drag="true"] .vds-scrollbar,
  .vds-scroll-area-root[data-arrows="true"] .vds-scrollbar,
  .vds-scroll-area-root[data-marquee="true"] .vds-scrollbar,
  .vds-scroll-area-root[data-hide-scrollbar="true"] .vds-scrollbar {
    display: none;
  }

  .vds-scrollbar-thumb {
    position: relative;
    flex: 1;
    border-radius: var(--scroll-area-thumb-radius);
    background-color: var(--scroll-area-thumb-bg);
    transition: background-color var(--scroll-area-transition-duration)
      var(--scroll-area-transition-ease);
  }
  .vds-scrollbar-thumb:hover {
    background-color: var(--scroll-area-thumb-bg-hover);
  }
  .vds-scrollbar-thumb[data-state="visible"]:active {
    background-color: var(--scroll-area-thumb-bg-active);
  }
  .vds-scrollbar-thumb::before {
    content: "";
    position: absolute;
    inset: -6px;
    min-inline-size: 44px;
    min-block-size: 44px;
  }

  .vds-scroll-area-corner {
    background-color: var(--scroll-area-track-bg);
  }

  /* ─────────────────────────────────────────────
   * Arrow buttons
   * ───────────────────────────────────────────── */
  .vds-scroll-area-arrow {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--scroll-area-arrow-size);
    block-size: var(--scroll-area-arrow-size);
    padding: 0;
    color: var(--scroll-area-arrow-color);
    background-color: var(--scroll-area-arrow-bg);
    border: 1px solid var(--scroll-area-arrow-border-color);
    border-radius: var(--scroll-area-arrow-radius);
    box-shadow: var(--scroll-area-arrow-shadow);
    cursor: pointer;
    appearance: none;
    align-self: center;
    transition:
      background-color var(--scroll-area-transition-duration)
        var(--scroll-area-transition-ease),
      color var(--scroll-area-transition-duration)
        var(--scroll-area-transition-ease),
      opacity var(--scroll-area-transition-duration)
        var(--scroll-area-transition-ease),
      transform var(--scroll-area-transition-duration)
        var(--scroll-area-transition-ease);
  }
  .vds-scroll-area-arrow:hover:not(:disabled) {
    background-color: var(--scroll-area-arrow-bg-hover);
  }
  .vds-scroll-area-arrow:active:not(:disabled) {
    background-color: var(--scroll-area-arrow-bg-active);
  }
  .vds-scroll-area-arrow:disabled {
    color: var(--scroll-area-arrow-color-disabled);
    cursor: not-allowed;
    opacity: var(--vds-opacity-disabled, 0.5);
  }
  .vds-scroll-area-arrow:focus-visible {
    outline: 2px solid var(--vds-color-ring, #6366f1);
    outline-offset: 2px;
  }
  .vds-scroll-area-arrow svg {
    inline-size: var(--scroll-area-arrow-icon-size);
    block-size: var(--scroll-area-arrow-icon-size);
    display: block;
  }

  /* Inner placement: overlay the arrows on top of the scroll area.
     For horizontal orientation they anchor to inline-start / inline-end
     and centre vertically; for vertical they anchor block-start / block-end
     and centre horizontally. */
  .vds-scroll-area-root[data-arrow-placement="inner"] .vds-scroll-area-arrow {
    position: absolute;
    z-index: 2;
  }
  .vds-scroll-area-root[data-arrow-placement="inner"][data-orientation="horizontal"]
    .vds-scroll-area-arrow {
    inset-block-start: 50%;
    transform: translateY(-50%);
  }
  .vds-scroll-area-root[data-arrow-placement="inner"][data-orientation="horizontal"]
    .vds-scroll-area-arrow[data-side="start"] {
    inset-inline-start: var(--scroll-area-arrow-inset, 0.5rem);
  }
  .vds-scroll-area-root[data-arrow-placement="inner"][data-orientation="horizontal"]
    .vds-scroll-area-arrow[data-side="end"] {
    inset-inline-end: var(--scroll-area-arrow-inset, 0.5rem);
  }
  .vds-scroll-area-root[data-arrow-placement="inner"][data-orientation="vertical"]
    .vds-scroll-area-arrow {
    inset-inline-start: 50%;
    transform: translateX(-50%);
  }
  .vds-scroll-area-root[data-arrow-placement="inner"][data-orientation="vertical"]
    .vds-scroll-area-arrow[data-side="start"] {
    inset-block-start: var(--scroll-area-arrow-inset, 0.5rem);
  }
  .vds-scroll-area-root[data-arrow-placement="inner"][data-orientation="vertical"]
    .vds-scroll-area-arrow[data-side="end"] {
    inset-block-end: var(--scroll-area-arrow-inset, 0.5rem);
  }

  /* Hover-appearance: fade arrows in/out on root hover / focus-within.
     When an arrow is at-edge (disabled) we fade it further so it doesn't
     draw attention once it's no longer useful. */
  .vds-scroll-area-root[data-arrow-appearance="hover"] .vds-scroll-area-arrow {
    opacity: 0;
    pointer-events: none;
  }
  .vds-scroll-area-root[data-arrow-appearance="hover"]:hover
    .vds-scroll-area-arrow,
  .vds-scroll-area-root[data-arrow-appearance="hover"]:focus-within
    .vds-scroll-area-arrow {
    opacity: 1;
    pointer-events: auto;
  }

  /* RTL chevron flip for horizontal arrows. */
  :dir(rtl) .vds-scroll-area-arrow[data-side="start"] svg,
  :dir(rtl) .vds-scroll-area-arrow[data-side="end"] svg {
    transform: scaleX(-1);
  }
  .vds-scroll-area-root[data-orientation="vertical"]
    .vds-scroll-area-arrow svg {
    transform: none !important;
  }

  /* ─────────────────────────────────────────────
   * Marquee (infinite autoplay scroll animation)
   *
   * Children are flattened (via React.Children) and
   * each one wrapped in `.vds-scroll-area-marquee-item`
   * so the marquee itself owns the layout — the user's
   * own padding/margin doesn't create a "double-gap" at
   * the junction between the two copies.
   *
   * Seamless-loop math: with N items per copy, flex-gap
   * G and padding-inline-end G, the track width is
   *   2N × item + 2N × G
   * so translateX(-50%) = -(N × item + N × G) which is
   * exactly "one copy + one gap" — the second copy lands
   * precisely where the first started. Without the
   * trailing padding, we'd be off by ½G and the gap at
   * the seam would look different from the internal gaps.
   * ───────────────────────────────────────────── */
  .vds-scroll-area-marquee {
    display: flex;
    /* Centre mixed-height children (text next to dot separators, logos of
       different sizes) on the cross axis. Also applies to the vertical
       variant below, where the cross axis is inline. */
    align-items: center;
    inline-size: max-content;
    gap: var(--scroll-area-marquee-gap);
    padding-inline-end: var(--scroll-area-marquee-gap);
    animation: vds-scroll-area-marquee-x
      var(--scroll-area-marquee-duration, 30s) linear infinite;
    animation-direction: var(--scroll-area-marquee-direction, normal);
    will-change: transform;
  }
  .vds-scroll-area-marquee-item {
    /* Flex (not block) so inline-level children are centred too, instead of
       sitting on the text baseline with descender space hanging below. */
    display: flex;
    align-items: center;
    flex: 0 0 auto;
  }
  .vds-scroll-area-root[data-orientation="vertical"] .vds-scroll-area-marquee {
    flex-direction: column;
    inline-size: 100%;
    block-size: max-content;
    padding-inline-end: 0;
    padding-block-end: var(--scroll-area-marquee-gap);
    animation-name: vds-scroll-area-marquee-y;
  }
  /* In RTL the animation runs the other way so the visual motion matches the
     inline-start→inline-end reading direction. */
  :dir(rtl) .vds-scroll-area-root[data-orientation="horizontal"]
    .vds-scroll-area-marquee {
    animation-direction: reverse;
  }

  .vds-scroll-area-root[data-marquee="true"][data-marquee-pause-on-hover="true"]:hover
    .vds-scroll-area-marquee,
  .vds-scroll-area-root[data-marquee="true"][data-marquee-pause-on-hover="true"]:focus-within
    .vds-scroll-area-marquee {
    animation-play-state: paused;
  }

  @keyframes vds-scroll-area-marquee-x {
    from {
      transform: translate3d(0, 0, 0);
    }
    to {
      transform: translate3d(-50%, 0, 0);
    }
  }
  @keyframes vds-scroll-area-marquee-y {
    from {
      transform: translate3d(0, 0, 0);
    }
    to {
      transform: translate3d(0, -50%, 0);
    }
  }

  /* ─────────────────────────────────────────────
   * Infinite-scroll sentinel
   * ───────────────────────────────────────────── */
  .vds-scroll-area-sentinel {
    flex: 0 0 auto;
    inline-size: 1px;
    block-size: 1px;
    pointer-events: none;
    opacity: 0;
  }

  /* ─────────────────────────────────────────────
   * Reduced motion
   * ───────────────────────────────────────────── */
  @media (prefers-reduced-motion: reduce) {
    .vds-scroll-area-arrow,
    .vds-scrollbar,
    .vds-scrollbar-thumb {
      transition: none;
    }
    .vds-scroll-area-marquee {
      animation: none;
    }
  }
}

@layer design-system.components {
  /* ─────────────────────────────────────────────
   * ScrollArea — tokens
   * Semantic CSS variables with fallbacks so the
   * package works standalone if dropped into a
   * project without @virtari-packages/tokens.
   * ───────────────────────────────────────────── */
  .vds-scroll-area-root {
    /* ── Scrollbar track / thumb ── */
    --scroll-area-scrollbar-size: var(--vds-space-2-5, 0.625rem); /* md default (10px) */
    --scroll-area-scrollbar-padding: 2px;
    --scroll-area-track-inset: var(--vds-space-1, 4px);
    --scroll-area-track-bg: transparent;
    --scroll-area-track-bg-hover: var(--vds-color-bg-subtle, rgba(0, 0, 0, 0.04));
    --scroll-area-thumb-bg: var(--vds-color-border-muted, #d4d4d8);
    --scroll-area-thumb-bg-hover: var(--vds-color-border-strong, #a1a1aa);
    --scroll-area-thumb-bg-active: var(--vds-color-border-interactive, #71717a);
    --scroll-area-thumb-radius: var(--vds-radius-scrollbar-thumb, 6px);
    --scroll-area-transition-duration: var(--vds-duration-fast, 150ms);
    --scroll-area-transition-ease: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* ── Edge mask (gradient fade) ── */
    --scroll-area-mask-size: 40px;
    --scroll-area-mask-inline-start: transparent;
    --scroll-area-mask-inline-end: transparent;
    --scroll-area-mask-block-start: transparent;
    --scroll-area-mask-block-end: transparent;

    /* ── Marquee (infinite autoplay) ── */
    --scroll-area-marquee-duration: 30s;
    --scroll-area-marquee-direction: normal;
    --scroll-area-marquee-gap: var(--vds-space-3, 0.75rem);

    /* ── Arrow buttons ── */
    --scroll-area-arrow-size: var(--vds-size-sm, 2rem);
    --scroll-area-arrow-icon-size: 1rem;
    --scroll-area-arrow-bg: var(--vds-color-surface, #ffffff);
    --scroll-area-arrow-bg-hover: var(--vds-color-surface-hover, #f9fafb);
    --scroll-area-arrow-bg-active: var(--vds-color-bg-muted, #f3f4f6);
    --scroll-area-arrow-color: var(--vds-color-text, #111827);
    --scroll-area-arrow-color-disabled: var(--vds-color-text-muted, #9ca3af);
    --scroll-area-arrow-border-color: var(--vds-color-border, #d1d5db);
    --scroll-area-arrow-radius: var(--vds-radius-action, var(--vds-radius-element, 0.5rem));
    --scroll-area-arrow-shadow: var(--vds-shadow-sm, 0 1px 2px 0 rgb(0 0 0 / 0.05));
    --scroll-area-arrow-gap: var(--vds-space-1, 0.25rem);

    /* ── Drag cursor ── */
    --scroll-area-drag-cursor: grab;
    --scroll-area-drag-cursor-active: grabbing;
  }

  /* ─────────────────────────────────────────────
   * Size ramp (scrollbar thickness only)
   * Matches Button/Input/Select size vocabulary.
   * ───────────────────────────────────────────── */
  .vds-scroll-area-root[data-size="sm"] {
    --scroll-area-scrollbar-size: var(--vds-space-2, 0.5rem); /* 8px */
  }
  /* No [data-size="md"] block: the base above already is md, so restating it
   * here would only be a second place to keep in sync. */
  .vds-scroll-area-root[data-size="lg"] {
    --scroll-area-scrollbar-size: var(--vds-space-3, 0.75rem); /* 12px */
  }
}

import {
  Children,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type ComponentRef,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from "react";
import * as ScrollAreaPrimitive from "@virtari-packages/primitives/scroll-area";
import { cn, useComposedRefs, useDirection } from "@virtari-packages/utils";
import { ScrollAreaArrow } from "./ScrollAreaArrow";
import { useDragScroll } from "./hooks/use-drag-scroll";
import { useEdgeState, type EdgeState } from "./hooks/use-edge-state";
import { useWheelHorizontal } from "./hooks/use-wheel-horizontal";
import { useInfiniteScroll } from "./hooks/use-infinite-scroll";

type Orientation = "vertical" | "horizontal" | "both";
type Size = "sm" | "md" | "lg";
type ArrowPlacement = "outer" | "inner";
type ArrowAppearance = "always" | "hover";
type MarqueeDirection = "normal" | "reverse";

/* ── ScrollArea ───────────────────────────────────────── */
export interface ScrollAreaProps
  extends Omit<
    ComponentPropsWithoutRef<typeof ScrollAreaPrimitive.Root>,
    "children" | "dir" | "type"
  > {
  children?: ReactNode;

  /** Which axis overflows. "both" enables both scrollbars and 2-axis drag. */
  orientation?: Orientation;
  /** Scrollbar thickness ramp — matches Button/Input size vocabulary. */
  size?: Size;
  /** Smart shows overflowing scrollbars on scroll, hover, or keyboard focus. */
  type?: "smart" | "auto" | "always" | "scroll" | "hover";
  /** Access the native scrolling element for scroll restoration and measurement. */
  viewportRef?: Ref<HTMLDivElement>;
  /** Native viewport attributes/events; keyboard scrolling remains available. */
  viewportProps?: Omit<ComponentPropsWithoutRef<typeof ScrollAreaPrimitive.Viewport>, "children" | "asChild">;

  /** Enable pointer-drag-to-scroll (mouse, touch, pen). */
  drag?: boolean;

  /** Edge-gradient fade. `true` uses the default width; number = px. */
  mask?: boolean | number;

  /** Arrow buttons on either end of the scrollable axis. Ignored for "both". */
  arrows?: boolean;
  /** Where to put the arrows — outside the scroll area or overlayed inside. Default "outer". */
  arrowPlacement?: ArrowPlacement;
  /** Whether arrows are always visible or only on hover/focus. Default "always". */
  arrowAppearance?: ArrowAppearance;
  /** How far each arrow click scrolls. "page" = 85% of viewport. Default "page". */
  arrowStep?: number | "page";

  /** Convert vertical wheel to horizontal scroll. Auto-enabled for horizontal orientation. */
  wheelToHorizontal?: boolean;

  /** Called when the user scrolls near the end of content. */
  onEndReached?: () => void;
  /** How far from the end (px) to fire `onEndReached`. Default 0. */
  endThreshold?: number;

  /** Infinite auto-play animation (marquee / ticker). Disables drag/arrows/wheel. */
  marquee?: boolean;
  /** Marquee loop duration in seconds. Default 30. */
  marqueeDuration?: number;
  /** Marquee direction. "normal" = inline-start → inline-end. */
  marqueeDirection?: MarqueeDirection;
  /** Pause marquee on hover / focus-within. Default true. */
  marqueePauseOnHover?: boolean;

  /** Force-hide the styled scrollbar even when drag/arrows/marquee aren't on. */
  hideScrollbar?: boolean;

  /** Direction. Falls back to inherited document direction. */
  dir?: "ltr" | "rtl";

  ref?: Ref<ComponentRef<typeof ScrollAreaPrimitive.Root>>;
}

/**
 * Virtari ScrollArea — customised scrollbars (via @virtari-packages/primitives/scroll-area)
 * plus a set of ergonomic behaviors that cover modern scroll UX patterns:
 *
 *   drag                 click-and-drag-to-scroll (desktop + touch)
 *   mask                 edge gradient fade that follows scroll position
 *   arrows               prev/next buttons, with inner/outer placement and
 *                        optional hover-only appearance
 *   wheelToHorizontal    vertical wheel becomes horizontal scroll
 *   onEndReached         IntersectionObserver-driven infinite-scroll hook
 *   marquee              CSS-animated auto-play loop for tickers/logos
 *
 * Everything is opt-in. The scrollbar auto-hides when drag, arrows, or
 * marquee are on, because those modes replace the scrollbar affordance.
 * All features are RTL-aware.
 */
export function ScrollArea({
  children,
  className,
  style,
  orientation = "vertical",
  size = "md",
  drag = false,
  mask = false,
  arrows = false,
  arrowPlacement = "outer",
  arrowAppearance = "always",
  arrowStep = "page",
  wheelToHorizontal,
  onEndReached,
  endThreshold = 0,
  marquee = false,
  marqueeDuration,
  marqueeDirection,
  marqueePauseOnHover = true,
  hideScrollbar,
  type = "smart",
  scrollHideDelay = 900,
  viewportRef: externalViewportRef,
  viewportProps,
  dir,
  ref,
  ...rootProps
}: ScrollAreaProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const inheritedDirection = useDirection(rootRef);
  const viewportRef = useRef<HTMLDivElement>(null);
  const mergedViewportRef = useComposedRefs(viewportRef, externalViewportRef);
  const sentinelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const viewport = viewportRef.current;
    const root = rootRef.current;
    if (!viewport || !root || type !== "smart") return;
    let timer: ReturnType<typeof setTimeout>;
    const reveal = () => {
      root.setAttribute("data-scrolling", "true");
      clearTimeout(timer);
      timer = setTimeout(() => root.removeAttribute("data-scrolling"), scrollHideDelay);
    };
    viewport.addEventListener("scroll", reveal, { passive: true });
    return () => {
      clearTimeout(timer);
      root.removeAttribute("data-scrolling");
      viewport.removeEventListener("scroll", reveal);
    };
  }, [type, scrollHideDelay]);

  const [edge, setEdge] = useState<EdgeState>({
    atInlineStart: true,
    atInlineEnd: true,
    atBlockStart: true,
    atBlockEnd: true,
  });

  // Arrows only apply to single-axis orientations — showing arrows with
  // two-axis scrolling is ambiguous. Marquee also overrides arrows.
  const showArrows = arrows && !marquee && orientation !== "both";

  // Auto-enable wheel → horizontal when the user explicitly chose horizontal
  // orientation, unless they've opted out or marquee took over.
  const wheelToH =
    marquee
      ? false
      : (wheelToHorizontal ?? (orientation === "horizontal" ? true : false));

  const dragEnabled = drag && !marquee;
  const dragAxis =
    orientation === "both" ? "both" : orientation === "vertical" ? "y" : "x";

  const maskSizePx = typeof mask === "number" ? `${mask}px` : undefined;

  // Edge state → React state (for arrow disabled) + DOM attrs / CSS vars.
  useEdgeState(viewportRef, rootRef, {
    enabled: !marquee,
    orientation,
    onChange: setEdge,
  });

  useDragScroll(viewportRef, rootRef, {
    enabled: dragEnabled,
    axis: dragAxis,
  });

  useWheelHorizontal(viewportRef, {
    enabled: wheelToH,
  });

  useInfiniteScroll(viewportRef, sentinelRef, {
    enabled: !!onEndReached && !marquee,
    orientation,
    threshold: endThreshold,
    onEndReached,
  });

  const scrollByArrow = useCallback(
    (side: "start" | "end") => {
      const viewport = viewportRef.current;
      const root = rootRef.current;
      if (!viewport || !root) return;
      const rtl = getComputedStyle(root).direction === "rtl";
      const isVertical = orientation === "vertical";
      const pageSize = isVertical
        ? viewport.clientHeight
        : viewport.clientWidth;
      const step =
        arrowStep === "page"
          ? Math.max(pageSize * 0.85, 32)
          : Math.max(arrowStep, 0);
      if (isVertical) {
        viewport.scrollBy({
          top: side === "end" ? step : -step,
          behavior: "smooth",
        });
      } else {
        // Horizontal: in LTR, "end" = +scrollLeft. In RTL (negative-scroll
        // model used by modern browsers), "end" = -scrollLeft.
        const baseSign = side === "end" ? 1 : -1;
        const sign = rtl ? -baseSign : baseSign;
        viewport.scrollBy({ left: sign * step, behavior: "smooth" });
      }
    },
    [arrowStep, orientation],
  );

  // Per-instance overrides — only set when the user passed a value so we
  // don't stomp on external stylesheet customisation.
  const rootStyle = useMemo<CSSProperties | undefined>(() => {
    const overrides: Record<string, string> = {};
    if (maskSizePx) overrides["--scroll-area-mask-size"] = maskSizePx;
    if (typeof marqueeDuration === "number") {
      overrides["--scroll-area-marquee-duration"] = `${marqueeDuration}s`;
    }
    if (marqueeDirection) {
      overrides["--scroll-area-marquee-direction"] = marqueeDirection;
    }
    if (Object.keys(overrides).length === 0) return style;
    return { ...style, ...(overrides as CSSProperties) };
  }, [style, maskSizePx, marqueeDuration, marqueeDirection]);

  return (
    <div
      ref={rootRef}
      className={cn("vds-scroll-area-root", className)}
      style={rootStyle}
      dir={dir}
      data-orientation={orientation}
      data-size={size}
      data-scrollbar-type={type}
      data-drag={dragEnabled ? "true" : undefined}
      data-mask={mask ? "true" : undefined}
      data-arrows={showArrows ? "true" : undefined}
      data-arrow-placement={showArrows ? arrowPlacement : undefined}
      data-arrow-appearance={showArrows ? arrowAppearance : undefined}
      data-marquee={marquee ? "true" : undefined}
      data-marquee-pause-on-hover={
        marquee && marqueePauseOnHover ? "true" : undefined
      }
      data-hide-scrollbar={hideScrollbar ? "true" : undefined}
    >
      {showArrows && (
        <ScrollAreaArrow
          side="start"
          orientation={orientation as "vertical" | "horizontal"}
          disabled={
            orientation === "vertical" ? edge.atBlockStart : edge.atInlineStart
          }
          onClick={() => scrollByArrow("start")}
        />
      )}

      <ScrollAreaPrimitive.Root
        ref={ref}
        type={type === "smart" ? "auto" : type}
        scrollHideDelay={scrollHideDelay}
        dir={dir ?? inheritedDirection}
        className="vds-scroll-area"
        {...rootProps}
      >
        <ScrollAreaPrimitive.Viewport
          {...viewportProps}
          ref={mergedViewportRef}
          tabIndex={viewportProps?.tabIndex ?? (marquee ? -1 : 0)}
          className={cn("vds-scroll-area-viewport", viewportProps?.className)}
        >
          {marquee ? (
            <div className="vds-scroll-area-marquee">
              {renderMarqueeItems(children)}
            </div>
          ) : (
            <>
              {children}
              {onEndReached && (
                <div
                  ref={sentinelRef}
                  className="vds-scroll-area-sentinel"
                  aria-hidden="true"
                />
              )}
            </>
          )}
        </ScrollAreaPrimitive.Viewport>

        {(orientation === "vertical" || orientation === "both") && (
          <ScrollBar orientation="vertical" />
        )}
        {(orientation === "horizontal" || orientation === "both") && (
          <ScrollBar orientation="horizontal" />
        )}
        <ScrollAreaPrimitive.Corner className="vds-scroll-area-corner" />
      </ScrollAreaPrimitive.Root>

      {showArrows && (
        <ScrollAreaArrow
          side="end"
          orientation={orientation as "vertical" | "horizontal"}
          disabled={
            orientation === "vertical" ? edge.atBlockEnd : edge.atInlineEnd
          }
          onClick={() => scrollByArrow("end")}
        />
      )}
    </div>
  );
}

/**
 * Flatten children via React.Children, wrap each in a flex item, render the
 * sequence twice (second copy aria-hidden so assistive tech only sees one).
 * The marquee's own flex gap then sits between items uniformly — including
 * between the last item of copy 1 and the first of copy 2 — which avoids the
 * "double-padding" seam you'd see if the whole children tree were duplicated
 * with its own padding/margin.
 */
function renderMarqueeItems(children: ReactNode) {
  const items = Children.toArray(children);
  return [0, 1].flatMap((copy) =>
    items.map((child, i) => (
      <div
        key={`${copy}-${i}`}
        className="vds-scroll-area-marquee-item"
        aria-hidden={copy === 1 ? "true" : undefined}
      >
        {child}
      </div>
    )),
  );
}

/* ── ScrollBar ───────────────────────────────────────── */
export interface ScrollBarProps
  extends ComponentPropsWithoutRef<
    typeof ScrollAreaPrimitive.ScrollAreaScrollbar
  > {
  ref?: Ref<ComponentRef<typeof ScrollAreaPrimitive.ScrollAreaScrollbar>>;
}

/**
 * Retained export for back-compat / advanced composition. Most consumers
 * should use <ScrollArea /> and let it render the right scrollbars.
 */
export function ScrollBar({
  className,
  orientation = "vertical",
  ref,
  ...props
}: ScrollBarProps) {
  return (
    <ScrollAreaPrimitive.ScrollAreaScrollbar
      ref={ref}
      orientation={orientation}
      className={cn("vds-scrollbar", className)}
      {...props}
    >
      <ScrollAreaPrimitive.ScrollAreaThumb className="vds-scrollbar-thumb" />
    </ScrollAreaPrimitive.ScrollAreaScrollbar>
  );
}

import type { ButtonHTMLAttributes } from "react";
import { cn } from "@virtari-packages/utils";

export interface ScrollAreaArrowProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  /**
   * Logical side the arrow scrolls toward. "start" = inline-start / block-start,
   * "end" = inline-end / block-end. RTL is handled via CSS (chevron flips).
   */
  side: "start" | "end";
  orientation: "vertical" | "horizontal";
}

export function ScrollAreaArrow({
  side,
  orientation,
  className,
  ...rest
}: ScrollAreaArrowProps) {
  return (
    <button
      type="button"
      aria-label={arrowLabel(side, orientation)}
      data-side={side}
      className={cn("vds-scroll-area-arrow", className)}
      {...rest}
    >
      <ChevronIcon side={side} orientation={orientation} />
    </button>
  );
}

function arrowLabel(
  side: "start" | "end",
  orientation: "vertical" | "horizontal",
): string {
  if (orientation === "vertical") {
    return side === "start" ? "Scroll up" : "Scroll down";
  }
  return side === "start" ? "Scroll to start" : "Scroll to end";
}

function ChevronIcon({
  side,
  orientation,
}: {
  side: "start" | "end";
  orientation: "vertical" | "horizontal";
}) {
  // For horizontal: start → left chevron, end → right chevron (CSS flips for RTL).
  // For vertical:   start → up chevron,   end → down chevron.
  const path =
    orientation === "vertical"
      ? side === "start"
        ? "M18 15 12 9 6 15"
        : "M6 9 12 15 18 9"
      : side === "start"
      ? "M15 18 9 12 15 6"
      : "M9 6 15 12 9 18";

  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d={path} />
    </svg>
  );
}

