/* Inlined into the published style entry by PostCSS, so standalone consumers
 * receive the shared track without relying on another global style import. */
@import "../../react-tabs/src/Tabs.css";

@layer design-system.components {
  /* Outer RadioGroup wrapper — inline by default, block when full-width */
  .vds-segmented-control {
    display: inline-block;
    max-inline-size: 100%;
    min-inline-size: 0;
    vertical-align: middle;
  }

  .vds-segmented-control[data-full-width="true"] {
    display: block;
  }

  /* Vertical layout: column-stack the items */
  .vds-segmented-control .vds-tabs-list[data-orientation="vertical"] {
    flex-direction: column;
    align-items: stretch;
    max-inline-size: 100%;
    overflow-x: visible;
    overflow-y: visible;
  }

  /* ── State bridge ──────────────────────────────────────────────────────────
   * RadioGroup items carry data-state="checked" (not "active").
   * Tabs CSS targets [data-state="active"] — we bridge that gap here.
   * ─────────────────────────────────────────────────────────────────────── */

  /* Map checked → active colors */
  .vds-segmented-control .vds-tabs-trigger[data-state="checked"] {
    color: var(--tabs-trigger-color-active);
    border-color: var(--tabs-trigger-border-color-active);
    background-color: var(--tabs-trigger-bg-active);
    box-shadow: var(--tabs-trigger-shadow-active);
  }

  /* When the animated indicator paints the background, suppress the trigger's own */
  .vds-segmented-control
    .vds-tabs-list[data-animated="true"]
    .vds-tabs-trigger[data-state="checked"] {
    background-color: transparent;
    box-shadow: none;
  }

  /* Tabs hover rule selects :not([data-state="active"]) — that passes through
   * to our checked items. Override so the indicator isn't painted over. */
  .vds-segmented-control
    .vds-tabs-trigger[data-state="checked"]:hover:not(:disabled):not(
      [data-disabled]
    ) {
    background-color: transparent;
    color: var(--tabs-trigger-color-active);
  }

  /* ── Disabled ─────────────────────────────────────────────────────────── */
  /* Apply opacity at list level so the track bg dims too. Reset per-item
   * opacity to 1 so it doesn't compound with Tabs' [data-disabled] rule. */
  .vds-segmented-control[data-disabled] {
    pointer-events: none;
  }
  .vds-segmented-control[data-disabled] .vds-tabs-list {
    opacity: var(--vds-opacity-disabled, 0.5);
  }
  .vds-segmented-control[data-disabled] .vds-tabs-trigger {
    opacity: 1;
  }

  /* ── Icon slot ────────────────────────────────────────────────────────── */
  .vds-segmented-control-icon {
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
    justify-content: center;
    inline-size: var(--tabs-trigger-icon-size, 1.125rem);
    block-size: var(--tabs-trigger-icon-size, 1.125rem);
    line-height: 1;
    font-size: 1em;
  }
  .vds-segmented-control-icon > svg {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    flex-shrink: 0;
  }
}

import { useRef } from "react";
import { cn, controlText, useComposedRefs, useDirection } from "@virtari-packages/utils";
import { useDirection as usePrimitiveDirection } from "@virtari-packages/primitives/direction";
import * as RadioGroupPrimitive from "@virtari-packages/primitives/radio-group";
import type { ComponentRef, Ref, ReactNode } from "react";
import { useSegmentedIndicator } from "./use-segmented-indicator";

export type SegmentedControlSize = "sm" | "md" | "lg";

type PrimitiveRootProps = React.ComponentPropsWithoutRef<
  typeof RadioGroupPrimitive.Root
>;
type PrimitiveItemProps = React.ComponentPropsWithoutRef<
  typeof RadioGroupPrimitive.Item
>;

export interface SegmentedControlProps
  extends Omit<PrimitiveRootProps, "orientation"> {
  size?: SegmentedControlSize;
  /** Expand to fill parent width. */
  fullWidth?: boolean;
  /** Vertical stacking layout. */
  orientation?: "horizontal" | "vertical";
  ref?: Ref<ComponentRef<typeof RadioGroupPrimitive.Root>>;
}

export interface SegmentedControlItemProps extends PrimitiveItemProps {
  /** Leading icon before label text. */
  icon?: ReactNode;
  ref?: Ref<ComponentRef<typeof RadioGroupPrimitive.Item>>;
}

export function SegmentedControl({
  size = "md",
  fullWidth = false,
  orientation = "horizontal",
  dir,
  disabled,
  className,
  children,
  ref,
  ...props
}: SegmentedControlProps) {
  const listRef = useRef<HTMLDivElement>(null);
  const parentRef = useRef<Element | null>(null);
  const inheritedDirection = useDirection(parentRef);
  const direction = usePrimitiveDirection(dir, inheritedDirection);
  const composedRef = useComposedRefs(ref, node => { parentRef.current = node?.parentElement ?? null; });
  useSegmentedIndicator(listRef);

  return (
    <RadioGroupPrimitive.Root
      ref={composedRef}
      dir={direction}
      orientation={orientation}
      disabled={disabled}
      data-full-width={fullWidth ? "true" : undefined}
      data-disabled={disabled || undefined}
      className={cn("vds-segmented-control", className)}
      {...props}
    >
      {/*
        This is a hand-rolled copy of Tabs' <TabsList>, because the items are
        radios rather than tabs. It has to carry the same `data-radius-host`
        the real TabsList does: the segmented trigger's radius is
        `var(--vds-radius-inset)`, and that custom property is registered
        `inherits: false`, so it is only ever given a value by the
        `[data-radius-host] > *` rule. Without the attribute every segment fell
        back to the registered initial 0px and rendered square inside the
        rounded track — while the sliding indicator, which re-derives the same
        subtraction from the inheriting --vds-radius-host-* inputs, stayed
        correctly rounded.
      */}
      <div
        ref={listRef}
        className="vds-tabs-list"
        data-radius-host=""
        data-variant="segmented"
        data-animated="true"
        data-size={size}
        data-full-width={fullWidth ? "true" : undefined}
        data-orientation={orientation}
      >
        {children}
      </div>
    </RadioGroupPrimitive.Root>
  );
}

export function SegmentedControlItem({
  icon,
  className,
  children,
  ref,
  ...props
}: SegmentedControlItemProps) {
  return (
    <RadioGroupPrimitive.Item
      ref={ref}
      className={cn("vds-tabs-trigger", className)}
      {...props}
    >
      <span className="vds-tabs-trigger-content">
        {icon && (
          <span className="vds-segmented-control-icon" aria-hidden="true">
            {icon}
          </span>
        )}
        {controlText(children)}
      </span>
    </RadioGroupPrimitive.Item>
  );
}

