@import "./Select.tokens.css";
@import "../../react-fieldset/src/Fieldset.css";

@layer design-system.components {
  /* ── Trigger ── */
  .vds-select-trigger {
    box-shadow: var(--select-trigger-shadow);
    box-sizing: border-box;
    min-inline-size: 0;
    margin: 0;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--select-trigger-gap);
    inline-size: 100%;
    min-block-size: var(--select-trigger-height);
    padding-inline: var(--select-trigger-padding-inline);
    padding-block: var(--select-trigger-padding-block);
    text-align: start;

    font-family: var(--select-trigger-font-family);
    font-size: var(--select-trigger-font-size);
    font-weight: var(--select-trigger-font-weight);
    line-height: var(--select-trigger-line-height);
    color: var(--select-trigger-text-color);

    background-color: var(--select-trigger-bg);
    border: var(--select-trigger-border-width) solid var(--select-trigger-border-color);
    border-radius: var(--select-trigger-radius);

    cursor: pointer;
    appearance: none;
    transition:
      background-color var(--select-trigger-transition-duration) var(--select-trigger-transition-easing),
      border-color var(--select-trigger-transition-duration) var(--select-trigger-transition-easing),
      box-shadow 180ms ease-out,
      color var(--select-trigger-transition-duration) var(--select-trigger-transition-easing),
      scale 140ms var(--select-trigger-transition-easing);
    @media (prefers-reduced-motion: reduce) {
      transition-duration: 0s;
    }
  }

  .vds-select-trigger:hover:not(:disabled) {
    background-color: var(--select-trigger-bg-hover);
    border-color: var(--select-trigger-border-color-hover);
  }

  .vds-select-trigger:focus-visible {
    border-color: var(--select-trigger-focus-border-color);
    outline: none;
    box-shadow: 0 0 0 4px var(--select-trigger-focus-alpha), 0 0 12px 2px var(--select-trigger-focus-soft-alpha);
    @media (forced-colors: active) {
      outline: 2px solid Highlight;
      outline-offset: 2px;
      box-shadow: none;
    }
  }

  .vds-select-trigger:active:not(:disabled):not([data-disabled]) {
    scale: 0.992;
    transition: scale 60ms var(--select-trigger-transition-easing);
