/* ── SidebarBody — main scrollable nav area ── */

export interface SidebarBodyProps extends HTMLAttributes<HTMLElement> {
  /** Override default tag. `"div"` by default; pass `"nav"` + `aria-label` when body IS the nav. */
  as?: ElementType;
