    --stepper-tone-solid: var(--vds-color-primary-solid, #4f46e5);
    --stepper-tone-text: var(--vds-color-primary-text, #3730a3);
    --stepper-tone-on: var(--vds-color-on-primary, #fff);
    --stepper-tone-ring: color-mix(in oklab, var(--stepper-tone-solid) 18%, transparent);

    /* Status: pending */
    --stepper-pending-bg: var(--vds-color-surface, #fff);
    --stepper-pending-text: var(--vds-color-text-subtle, #6b7280);
    --stepper-pending-border: var(--vds-color-border-muted, #e5e7eb);
    --stepper-pending-shadow: var(--vds-shadow-xs, 0 1px 2px rgb(0 0 0 / 0.05));

    /* Status: active */
    --stepper-active-bg: var(--stepper-tone-solid);
    --stepper-active-text: var(--stepper-tone-on);
    --stepper-active-border: var(--stepper-tone-solid);
    --stepper-active-ring: var(--stepper-tone-ring);
    --stepper-active-shadow: 0 10px 22px -14px var(--stepper-tone-solid);

    /* Status: complete */
    --stepper-complete-bg: var(--stepper-tone-solid);
    --stepper-complete-text: var(--stepper-tone-on);
    --stepper-complete-border: var(--stepper-tone-solid);
    --stepper-complete-shadow: var(--vds-shadow-xs, 0 1px 2px rgb(0 0 0 / 0.05));

    /* Status: error */
    --stepper-error-bg: var(--vds-color-danger-solid, #ef4444);
    --stepper-error-text: var(--vds-color-on-danger, #fff);
    --stepper-error-border: var(--vds-color-danger-solid, #ef4444);
    --stepper-error-ring: color-mix(in oklab, var(--vds-color-danger-solid, #ef4444) 18%, transparent);

    /* Surface */
    --stepper-card-bg: var(--vds-surface-bg, var(--vds-color-surface, #fff));
    --stepper-card-bg-hover: var(--vds-color-surface-hover, #f3f4f6);
    --stepper-card-border: var(--vds-color-border-muted, #e5e7eb);
    --stepper-card-radius: var(--vds-radius-card, 0.75rem);
    --stepper-card-shadow: var(--vds-surface-shadow, var(--vds-shadow-xs, 0 1px 2px rgb(0 0 0 / 0.05)));

    /* Text */
    --stepper-label-size: var(--vds-text-sm, 0.875rem);
    --stepper-label-weight: var(--vds-font-weight-semibold, 600);
    --stepper-label-color: var(--vds-color-text, currentColor);
    --stepper-desc-size: var(--vds-text-xs, 0.75rem);
    --stepper-desc-color: var(--vds-color-text-muted, #6b7280);

    /* Motion */
    --stepper-transition: var(--vds-transition-base, 200ms ease-out);
    --stepper-transition-spring: var(--vds-transition-spring, 300ms cubic-bezier(0.22, 1.2, 0.36, 1));
    --stepper-entrance-duration: var(--vds-duration-slow, 300ms);
    --stepper-stagger: 42ms;
  }

  .vds-stepper[data-tone="neutral"] {
    --stepper-tone-bg-subtle: var(--vds-color-bg-subtle, #f9fafb);
    --stepper-tone-bg: var(--vds-color-bg-muted, #f3f4f6);
