@layer design-system.components {
  /* =========================================================================
   * 1. Base component tokens
   *    Layout, typography, motion, focus — orthogonal to variant/size/density.
   *    Defaults: variant=surface, rows=divided, size=md, density=normal.
   *    Fallbacks keep the package usable without @virtari-packages/tokens.
   * ========================================================================= */
  .vds-table {
    /* ── Frame (outer scroll container) ── */
    --table-radius:           var(--vds-radius-data-table, 0.5rem);
    --table-border-width:     1px;
    --table-border-color:     var(--vds-color-border-muted, var(--vds-color-border, #e5e7eb));
    --table-bg:               var(--vds-color-surface, #ffffff);

    /* ── Cells (padding + row height) ── */
    --table-cell-padding-block:  var(--vds-space-3, 0.75rem);
    --table-cell-padding-inline: var(--vds-space-4, 1rem);
    --table-row-height:          2.5rem;   /* 40px */
    --table-header-row-height:   2.5rem;
    --table-footer-row-height:   2.5rem;

    /* ── Typography ── */
    --table-font-family:
      var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    --table-font-size:      var(--vds-text-sm, 0.875rem);
    --table-line-height:    var(--vds-leading-normal, 1.5);
    --table-font-weight:    var(--vds-font-weight-regular, 400);
    --table-cell-color:     var(--vds-color-text, #111827);

    /* Header (th) text treatment */
    --table-header-font-size:      var(--vds-text-xs, 0.75rem);
    --table-header-font-weight:    var(--vds-font-weight-semibold, 600);
    --table-header-color:          var(--vds-color-text-muted, #6b7280);
    --table-header-letter-spacing: var(--vds-tracking-wide, 0.025em);
    --table-header-text-transform: uppercase;
    --table-header-bg:             var(--vds-color-surface-raised, #f9fafb);

    /* Footer text treatment (tfoot) */
    --table-footer-color:  var(--vds-color-text-muted, #6b7280);
    --table-footer-bg:     var(--vds-color-surface-raised, #f9fafb);

    /* Caption */
    --table-caption-color:     var(--vds-color-text-muted, #6b7280);
    --table-caption-font-size: var(--vds-text-sm, 0.875rem);
    --table-caption-padding:   var(--vds-space-3, 0.75rem);

    /* ── Row chrome ── */
    --table-row-divider-color: color-mix(
      in oklch,
      var(--vds-color-border-muted, #e5e7eb) 80%,
      transparent
    );
    --table-row-bg:          transparent;
    --table-row-bg-alt:      var(--vds-color-surface-raised, color-mix(in oklch, var(--table-bg) 94%, var(--vds-color-text, #171717) 6%));
    --table-row-bg-hover:    var(--vds-color-surface-hover, color-mix(in oklch, var(--table-bg) 88%, var(--vds-color-text, #171717) 12%));
    --table-row-bg-selected: var(--vds-color-primary-bg, #eef2ff);
    --table-row-bg-selected-hover: color-mix(
      in oklch,
      var(--table-row-bg-selected) 80%,
      var(--vds-color-primary-solid, #4f46e5) 20%
    );

    /* ── Accent (selection stripe + sort indicator) ── */
    --table-accent-color: var(--vds-color-primary-solid, #4f46e5);

    /* ── Motion ── */
    --table-transition-duration: var(--vds-duration-fast, 120ms);
    --table-transition-easing:   var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));

    /* ── Focus (sortable headers + grid mode) ── */
    --table-focus-ring-color:  var(--vds-color-ring, var(--table-accent-color));
    --table-focus-ring-width:  2px;
    --table-focus-ring-offset: -2px;
  }

  /* =========================================================================
   * 2. Color accent — redefine --table-accent-color and the selected-row bg.
   *    Applies to selected rows and sortable-header indicator.
   * ========================================================================= */

  .vds-table[data-color="accent"] {
    --table-accent-color:    var(--vds-color-accent-solid, #f97316);
    --table-row-bg-selected: var(--vds-color-accent-bg, #ffedd5);
  }
  .vds-table[data-color="success"] {
    --table-accent-color:    var(--vds-color-success-solid, #16a34a);
    --table-row-bg-selected: var(--vds-color-success-bg, #dcfce7);
  }
  .vds-table[data-color="warning"] {
    --table-accent-color:    var(--vds-color-warning-solid, #f59e0b);
    --table-row-bg-selected: var(--vds-color-warning-bg, #fef3c7);
  }
  .vds-table[data-color="danger"] {
    --table-accent-color:    var(--vds-color-danger-solid, #dc2626);
    --table-row-bg-selected: var(--vds-color-danger-bg, #fee2e2);
  }
  .vds-table[data-color="info"] {
    --table-accent-color:    var(--vds-color-info-solid, #0891b2);
    --table-row-bg-selected: var(--vds-color-info-bg, #cffafe);
  }
  .vds-table[data-color="neutral"] {
    --table-accent-color:    var(--vds-color-text, #171717);
    --table-row-bg-selected: var(--vds-color-surface-hover, #f5f5f5);
  }

  /* =========================================================================
   * 3. Variants — frame strategy. Palette stays orthogonal.
   * ========================================================================= */

  /* surface (default) — framed on a raised surface with rounded corners.
   * Relies on the base tokens; nothing to redefine. */

  /* plain — no outer frame, transparent bg. Dividers still paint. */
  .vds-table[data-variant="plain"] {
    --table-bg:               transparent;
    --table-border-width:     0;
    --table-radius:           0;
    --table-header-bg:        transparent;
    --table-footer-bg:        transparent;
  }

  /* ghost — no frame, no dividers. For lean typographic tables. */
  .vds-table[data-variant="ghost"] {
    --table-bg:               transparent;
    --table-border-width:     0;
    --table-radius:           0;
    --table-header-bg:        transparent;
    --table-footer-bg:        transparent;
    --table-row-divider-color: transparent;
  }

  /* bordered — full grid. Every cell gets inline borders; every row gets
   * block-end border. Keeps the outer frame from `surface`. */
  .vds-table[data-variant="bordered"] .vds-table__th,
  .vds-table[data-variant="bordered"] .vds-table__td {
    border-inline-end: var(--table-border-width) solid var(--table-row-divider-color);
  }
  .vds-table[data-variant="bordered"] .vds-table__tr > :last-child {
    border-inline-end: 0;
  }

  /* =========================================================================
   * 4. Row strategies — zebra, divided, none.
   *    Divided is the default (baked into base CSS).
   * ========================================================================= */

  .vds-table[data-rows="striped"] .vds-table__tbody .vds-table__tr:nth-child(even) {
    background-color: var(--table-row-bg-alt);
  }

  .vds-table[data-rows="none"] {
    --table-row-divider-color: transparent;
  }

  /* =========================================================================
   * 5. Sizes — cell padding + font + row height.
   *    md is the default (base tokens).
   * ========================================================================= */

  .vds-table[data-size="sm"] {
    --table-font-size:            var(--vds-text-xs, 0.8125rem);
    --table-header-font-size:     0.6875rem; /* 11px */
    --table-cell-padding-block:   var(--vds-space-2, 0.5rem);
    --table-cell-padding-inline:  var(--vds-space-3, 0.75rem);
    --table-row-height:           2rem;      /* 32px */
    --table-header-row-height:    2rem;
    --table-footer-row-height:    2rem;
  }

  .vds-table[data-size="lg"] {
    --table-font-size:            var(--vds-text-base, 1rem);
    --table-header-font-size:     var(--vds-text-sm, 0.875rem);
    --table-cell-padding-block:   var(--vds-space-4, 1rem);
    --table-cell-padding-inline:  var(--vds-space-5, 1.25rem);
    --table-row-height:           3rem;      /* 48px */
    --table-header-row-height:    3rem;
    --table-footer-row-height:    3rem;
  }

  /* =========================================================================
   * 6. Density — tighter or roomier padding, independent of size.
   *    `normal` is the default. `compact` halves padding; `comfortable`
   *    bumps it. Composes with [data-size] without conflict.
   * ========================================================================= */

  .vds-table[data-density="compact"] {
    --table-cell-padding-block:   var(--vds-space-1-5, 0.375rem);
    --table-cell-padding-inline:  var(--vds-space-2-5, 0.625rem);
    --table-row-height:           2rem;      /* 32px */
    --table-header-row-height:    2rem;
    --table-footer-row-height:    2rem;
  }

  .vds-table[data-density="comfortable"] {
    --table-cell-padding-block:   var(--vds-space-5, 1.25rem);
    --table-cell-padding-inline:  var(--vds-space-6, 1.5rem);
    --table-row-height:           3.5rem;    /* 56px */
    --table-header-row-height:    3.5rem;
    --table-footer-row-height:    3.5rem;
  }

  /* =========================================================================
   * 7. Header casing modifier — opt out of the uppercase treatment for
   *    tables that need sentence-case headers (report-style).
   * ========================================================================= */
  .vds-table[data-header-case="sentence"] {
    --table-header-font-size:       var(--vds-text-sm, 0.875rem);
    --table-header-letter-spacing:  var(--vds-tracking-normal, 0);
    --table-header-text-transform:  none;
    --table-header-color:           var(--vds-color-text, #111827);
  }
}

