@import "./Tabs.tokens.css";

@layer design-system.components {
  /* ─────────────────────────────────────────────
   * Root (Tabs wrapper)
   * ───────────────────────────────────────────── */
  .vds-tabs {
    display: block;
    min-inline-size: 0;
  }

  /* Vertical layout → list and content sit side-by-side */
  .vds-tabs[data-orientation="vertical"] {
    display: flex;
    align-items: stretch;
    gap: var(--tabs-root-gap);
  }
  .vds-tabs[data-orientation="vertical"] > .vds-tabs-content {
    flex: 1 1 0;
    min-inline-size: 0;
    padding-inline-start: var(--tabs-root-gap);
    border-inline-start: 1px solid var(--tabs-root-separator-color);
  }
  .vds-tabs[data-orientation="vertical"]
    > .vds-tabs-list:is(
      [data-variant="underline"],
      [data-variant="line"],
      [data-variant="boxed"]
    )
    ~ .vds-tabs-content {
    border-inline-start: 0;
  }

  /* ─────────────────────────────────────────────
   * List
   * ───────────────────────────────────────────── */
  .vds-tabs-list {
    position: relative;
    display: inline-flex;
    align-items: stretch;
    gap: var(--tabs-list-gap);
    padding-inline: var(--tabs-list-padding-inline);
    padding-block: var(--tabs-list-padding-block);
    background-color: var(--tabs-list-bg);
    border-radius: var(--tabs-list-radius);
    border: 0 solid var(--tabs-list-border-color);
    border-block-end-width: var(--tabs-list-border-width);
    /* Keep overflow inside the list; the inset focus ring stays visible. */
    max-inline-size: 100%;
    overflow-x: auto;
    overflow-y: visible;
    scrollbar-width: none;
  }
  .vds-tabs-list::-webkit-scrollbar {
    display: none;
  }
  .vds-tabs-list::-webkit-scrollbar {
    block-size: 6px;
  }
  .vds-tabs-list > .vds-tabs-trigger {
    flex: 0 0 auto;
  }
  .vds-tabs-list[data-orientation="vertical"] {
    max-inline-size: 100%;
    overflow-x: visible;
    overflow-y: auto;
  }

  /* ─────────────────────────────────────────────
   * Trigger
   * ───────────────────────────────────────────── */
  .vds-tabs-trigger {
    position: relative;
    z-index: 1;
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    gap: var(--tabs-trigger-gap);
    min-block-size: var(--tabs-trigger-height);
    padding-inline: var(--tabs-trigger-padding-inline);
    padding-block-start: var(--tabs-trigger-padding-block);
    padding-block-end: var(--tabs-trigger-padding-block);

    font-family: var(--tabs-trigger-font-family);
    font-size: var(--tabs-trigger-font-size);
    font-weight: var(--tabs-trigger-font-weight);
    line-height: var(--tabs-trigger-line-height);
    color: var(--tabs-trigger-color);

    background-color: var(--tabs-trigger-bg);
    border: var(--tabs-trigger-border-width) solid
      var(--tabs-trigger-border-color);
    border-radius: var(--tabs-trigger-radius);

    cursor: pointer;
    appearance: none;
    white-space: nowrap;
    user-select: none;
    transition:
      color var(--tabs-trigger-transition-duration)
        var(--tabs-trigger-transition-ease),
      background-color var(--tabs-trigger-transition-duration)
        var(--tabs-trigger-transition-ease),
      border-color var(--tabs-trigger-transition-duration)
        var(--tabs-trigger-transition-ease),
      box-shadow var(--tabs-trigger-transition-duration)
        var(--tabs-trigger-transition-ease);
  }

  .vds-tabs-trigger-content {
    display: flex;
    align-items: center;
    justify-content: inherit;
    gap: inherit;
    inline-size: 100%;
    min-inline-size: 0;
    line-height: var(--vds-control-line-height, 1.5);
    transform: translateY(var(--tabs-trigger-optical-offset));
    white-space: inherit;
  }

  .vds-tabs-trigger-content > svg,
  .vds-tabs-trigger-content > :has(> svg:only-child) {
    transform: translateY(calc(var(--tabs-trigger-optical-offset) * -1));
  }

  .vds-tabs-trigger-content > svg,
  .vds-tabs-trigger-content > :has(> svg:only-child) > svg {
    display: block;
    flex-shrink: 0;
    inline-size: var(--tabs-trigger-icon-size, 1.125rem);
    block-size: var(--tabs-trigger-icon-size, 1.125rem);
  }

  .vds-tabs-trigger:hover:not(:disabled):not([data-disabled]):not(
      [data-state="active"]
    ) {
    color: var(--tabs-trigger-color-hover);
    background-color: var(--tabs-trigger-bg-hover);
    border-color: var(--tabs-trigger-border-color-hover);
  }

  .vds-tabs-trigger[data-state="active"] {
    color: var(--tabs-trigger-color-active);
    background-color: var(--tabs-trigger-bg-active);
    border-color: var(--tabs-trigger-border-color-active);
    box-shadow: var(--tabs-trigger-shadow-active);
  }

  .vds-tabs-trigger:focus-visible {
    outline: var(--tabs-trigger-focus-ring-width) solid
      var(--tabs-trigger-focus-ring-color);
    outline-offset: var(--tabs-trigger-focus-ring-offset);
  }

  .vds-tabs-trigger:disabled,
  .vds-tabs-trigger[data-disabled] {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
  }

  /* ─────────────────────────────────────────────
   * Content
   * ───────────────────────────────────────────── */
  /* Seam between the list and the panel below it. The root owns it, on a
     sibling-adjacency rule with one named token, rather than every panel
     padding its own leading edge — otherwise each container that puts a panel
     somewhere *other* than under the list (TabsPanels, or vertical
     orientation, where the list sits beside it) has to zero that padding back
     out, and the two of them disagree about which token means "the gap".
     `~` and not `+`: inactive panels stay in the DOM, so only the first panel
     would be adjacent to the list. */
  .vds-tabs:not([data-orientation="vertical"])
    > .vds-tabs-list
    ~ .vds-tabs-content {
    padding-block-start: var(--tabs-content-padding-block);
  }

  .vds-tabs-content:focus-visible {
    outline: var(--tabs-content-focus-ring-width) solid
      var(--tabs-content-focus-ring-color);
    outline-offset: var(--tabs-content-focus-ring-offset);
    border-radius: var(--tabs-content-focus-ring-radius);
  }

  /* Panel enter animation on tab change. The inline axis uses
     --tabs-content-enter-x, which is set from the physical `--tabs-content-
     enter-translate` in LTR and flipped in RTL so the enter motion always
     points inline-start-ward. */
  .vds-tabs-content {
    --tabs-content-enter-x: var(--tabs-content-enter-translate);
  }
  .vds-tabs-content:dir(rtl) {
    --tabs-content-enter-x: calc(var(--tabs-content-enter-translate) * -1);
  }
  .vds-tabs-content[data-state="active"] {
    animation: vds-tabs-content-in var(--tabs-content-enter-duration)
      var(--tabs-content-enter-ease);
  }
  @keyframes vds-tabs-content-in {
    from {
      opacity: 0;
      transform: translateX(var(--tabs-content-enter-x));
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }
  .vds-tabs[data-orientation="vertical"]
    .vds-tabs-content[data-state="active"] {
    animation-name: vds-tabs-content-in-y;
  }
  @keyframes vds-tabs-content-in-y {
    from {
      opacity: 0;
      transform: translateY(var(--tabs-content-enter-translate));
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Swipe state — inline transform wins over enter animation */
  .vds-tabs-content[data-swiping="true"] {
    animation: none !important;
    transition: none !important;
    will-change: transform;
  }

  /* ─────────────────────────────────────────────
   * Panels carousel (TabsPanels)
   * Panels are laid out side-by-side in a track. TabsPanels can force-mount
   * every panel, or only the active slide and its neighbors for heavy content.
   * The track is translated by -activeIndex * 100% via React state.
   * Touch swipe temporarily overrides the transform, then clears it so
   * the CSS transition animates to the next panel.
   * ───────────────────────────────────────────── */
  .vds-tabs-panels {
    position: relative;
    overflow: hidden;
    padding-block-start: var(--tabs-panels-padding-block);
  }
  .vds-tabs-panels-track {
    display: flex;
    inline-size: 100%;
    /* Baseline position: driven by --tabs-panels-tx which TabsPanels sets
       from activeIndex. An inline `transform` (from the swipe hook) can
       override this temporarily during a drag. When that inline transform
       is cleared, the CSS transform below reasserts — so the track always
       falls back to the correct baseline, not to translate(0).
       --tabs-panels-tx-sign flips the sign in RTL because flex-row lays
       slides out right-to-left and translateX is physical: to bring the
       same logical slide into view the track must shift the opposite way. */
    --tabs-panels-tx-sign: 1;
    transform: translateX(calc(var(--tabs-panels-tx, 0%) * var(--tabs-panels-tx-sign)));
    transition: transform var(--tabs-panels-transition-duration)
      var(--tabs-panels-transition-ease);
  }
  .vds-tabs-panels-track:dir(rtl) {
    --tabs-panels-tx-sign: -1;
  }
  .vds-tabs-panels[data-swipeable="true"] .vds-tabs-panels-track {
    touch-action: pan-y;
  }
  .vds-tabs-panels-slide {
    flex: 0 0 100%;
    min-inline-size: 0;
  }
  /* Force-mounted, non-active panels still carry `hidden` from the primitive;
     show them so they can participate in the carousel layout. */
  .vds-tabs-panels-slide > .vds-tabs-content[hidden] {
    display: block;
  }
  /* Inside the carousel the per-panel enter animation is replaced by the
     track translation; disable the default fade/slide. The panels container
     owns the seam to the list (--tabs-panels-padding-block above), and a
     panel nested in a slide is no longer a sibling of the list, so there is
     no leading padding here to cancel. */
  .vds-tabs-panels .vds-tabs-content[data-state="active"],
  .vds-tabs-panels .vds-tabs-content {
    animation: none;
  }
  /* Inactive panels inside the carousel shouldn't steal pointer events from
     the visible one (e.g., links in an adjacent panel). They stay visible
     so the neighbor can slide in during a swipe. */
  .vds-tabs-panels-slide:not([data-active="true"]) {
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .vds-tabs-panels-track {
      transition: none;
    }
  }

  /* ─────────────────────────────────────────────
   * Sliding indicator (::after)
   * Driven by CSS vars set in useTabsIndicator.
   * `--tabs-indicator-display` is block only on variants that
   * support sliding (underline / line / pills / segmented).
   * ───────────────────────────────────────────── */
  .vds-tabs-list[data-animated="true"]::after {
    content: "";
    position: absolute;
    pointer-events: none;
    z-index: 0;
    display: var(--tabs-indicator-display);
    background-color: var(--tabs-indicator-color);
    border-radius: var(--tabs-indicator-radius);
    opacity: var(--tabs-indicator-ready, 0);
    transition:
      transform var(--tabs-indicator-transition-duration)
        var(--tabs-indicator-transition-ease),
      inline-size var(--tabs-indicator-transition-duration)
        var(--tabs-indicator-transition-ease),
      block-size var(--tabs-indicator-transition-duration)
        var(--tabs-indicator-transition-ease);
  }

  /* underline: bottom line (horizontal) / end line (vertical) */
  .vds-tabs-list[data-variant="underline"][data-animated="true"]::after {
    inset-inline-start: 0;
    inset-block-end: calc(-1 * var(--tabs-list-border-width));
    inline-size: var(--tabs-indicator-w, 0);
    block-size: var(--tabs-indicator-thickness);
    transform: translateX(var(--tabs-indicator-tx, 0));
  }
  .vds-tabs-list[data-variant="underline"][data-orientation="vertical"][data-animated="true"]::after {
    inset-block-start: 0;
    inset-inline-start: auto;
    inset-inline-end: calc(-1 * var(--tabs-list-border-width));
    inset-block-end: auto;
    inline-size: var(--tabs-indicator-thickness);
    block-size: var(--tabs-indicator-h, 0);
    transform: translateY(var(--tabs-indicator-ty, 0));
  }

  /* line: top line (horizontal) / start line (vertical) */
  .vds-tabs-list[data-variant="line"][data-animated="true"]::after {
    inset-inline-start: 0;
    inset-block-start: calc(-1 * var(--tabs-list-border-width));
    inline-size: var(--tabs-indicator-w, 0);
    block-size: var(--tabs-indicator-thickness);
    transform: translateX(var(--tabs-indicator-tx, 0));
  }
  .vds-tabs-list[data-variant="line"][data-orientation="vertical"][data-animated="true"]::after {
    inset-block-start: 0;
    inset-inline-start: calc(-1 * var(--tabs-list-border-width));
    inset-block-end: auto;
    inline-size: var(--tabs-indicator-thickness);
    block-size: var(--tabs-indicator-h, 0);
    transform: translateY(var(--tabs-indicator-ty, 0));
  }

  /* pills / segmented: full-bleed indicator behind active trigger.
     Anchored at the padding-box origin (inset 0) so translate(tx, ty) from
     the hook places it on the active trigger directly. */
  .vds-tabs-list[data-variant="pills"][data-animated="true"]::after,
  .vds-tabs-list[data-variant="segmented"][data-animated="true"]::after {
    inset-block-start: 0;
    inset-inline-start: 0;
    inline-size: var(--tabs-indicator-w, 0);
    block-size: var(--tabs-indicator-h, 0);
    transform: translate(
      var(--tabs-indicator-tx, 0),
      var(--tabs-indicator-ty, 0)
    );
  }
  .vds-tabs-list[data-variant="segmented"][data-animated="true"]::after {
    box-shadow: var(--vds-shadow-sm, 0 1px 2px 0 rgb(0 0 0 / 0.05));
  }

  /* With a sliding fill (pills/segmented), the trigger mustn't
     paint its own bg/shadow — that's the indicator's job. */
  .vds-tabs-list[data-variant="pills"][data-animated="true"]
    .vds-tabs-trigger[data-state="active"],
  .vds-tabs-list[data-variant="segmented"][data-animated="true"]
    .vds-tabs-trigger[data-state="active"] {
    background-color: transparent;
    box-shadow: none;
  }

  /* ─────────────────────────────────────────────
   * Static fallback for underline/line when the
   * animated indicator is disabled.
   * ───────────────────────────────────────────── */
  .vds-tabs-list[data-variant="underline"]:not([data-animated="true"])
    .vds-tabs-trigger {
    box-shadow: inset 0 calc(-1 * var(--tabs-indicator-thickness)) 0 0
      transparent;
  }
  .vds-tabs-list[data-variant="underline"]:not([data-animated="true"])
    .vds-tabs-trigger[data-state="active"] {
    box-shadow: inset 0 calc(-1 * var(--tabs-indicator-thickness)) 0 0
      var(--tabs-indicator-color);
  }
  .vds-tabs-list[data-variant="line"]:not([data-animated="true"])
    .vds-tabs-trigger {
    box-shadow: inset 0 var(--tabs-indicator-thickness) 0 0 transparent;
  }
  .vds-tabs-list[data-variant="line"]:not([data-animated="true"])
    .vds-tabs-trigger[data-state="active"] {
    box-shadow: inset 0 var(--tabs-indicator-thickness) 0 0
      var(--tabs-indicator-color);
  }

  /* ─────────────────────────────────────────────
   * Variant: boxed — Chrome-style with inverted curves.
   * Active tab gets top+sides border matching the list's bottom border
   * (the classic browser-tab look). Curves draw the join between the
   * active tab's rounded corner and the list's horizontal border line.
   * ───────────────────────────────────────────── */
  .vds-tabs-list[data-variant="boxed"] {
    align-items: flex-end;
    /* Reserve the inverted end curves inside the horizontal scrollport. */
    padding-inline: var(--tabs-boxed-curve);
    overflow-x: auto;
  }
  .vds-tabs-list[data-variant="boxed"] .vds-tabs-trigger {
    border: 1px solid transparent;
    border-block-end: 0;
    border-start-start-radius: var(--tabs-boxed-curve);
    border-start-end-radius: var(--tabs-boxed-curve);
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    margin-block-end: calc(-1 * var(--tabs-list-border-width));
    padding-block-end: var(--tabs-list-border-width);
  }
  .vds-tabs-list[data-variant="boxed"]
    .vds-tabs-trigger[data-state="active"] {
    border-color: var(--tabs-boxed-border);
  }

  /* Inverted curves — rendered via radial-gradient for hair-thin precise */
  .vds-tabs-list[data-variant="boxed"] .vds-tabs-trigger::before,
  .vds-tabs-list[data-variant="boxed"] .vds-tabs-trigger::after {
    content: "";
    position: absolute;
    inline-size: var(--tabs-boxed-curve);
    block-size: var(--tabs-boxed-curve);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--tabs-trigger-transition-duration)
      var(--tabs-trigger-transition-ease);
  }

  /* Horizontal orientation — curves sit at the bottom of each trigger and
   * tuck under the list's horizontal border line. */
  .vds-tabs-list[data-variant="boxed"]:not([data-orientation="vertical"])
    .vds-tabs-trigger::before,
  .vds-tabs-list[data-variant="boxed"]:not([data-orientation="vertical"])
    .vds-tabs-trigger::after {
    inset-block-end: 0;
    /* Inner radius = outer radius − border width → produces a ring exactly
     * one border-width wide on the circle boundary. */
    background: radial-gradient(
      circle at var(--tabs-boxed-curve-origin-x, 0) 0,
      transparent 0 calc(var(--tabs-boxed-curve) - var(--tabs-list-border-width)),
      var(--tabs-boxed-border) calc(var(--tabs-boxed-curve) - var(--tabs-list-border-width)) var(--tabs-boxed-curve),
      var(--tabs-boxed-bg) var(--tabs-boxed-curve)
    );
  }
  .vds-tabs-list[data-variant="boxed"]:not([data-orientation="vertical"])
    .vds-tabs-trigger::before {
    inset-inline-start: calc(-1 * var(--tabs-boxed-curve));
    --tabs-boxed-curve-origin-x: 0%;
  }
  .vds-tabs-list[data-variant="boxed"]:not([data-orientation="vertical"])
    .vds-tabs-trigger::after {
    inset-inline-end: calc(-1 * var(--tabs-boxed-curve));
    --tabs-boxed-curve-origin-x: 100%;
  }

  /* RTL: logical inset flips the pseudos to the opposite physical side, so
   * the gradient's circle center must flip too (background position is
   * physical, not logical). */
  .vds-tabs-list:dir(rtl)[data-variant="boxed"]:not([data-orientation="vertical"])
    .vds-tabs-trigger::before {
    --tabs-boxed-curve-origin-x: 100%;
  }
  .vds-tabs-list:dir(rtl)[data-variant="boxed"]:not([data-orientation="vertical"])
    .vds-tabs-trigger::after {
    --tabs-boxed-curve-origin-x: 0%;
  }

  .vds-tabs-list[data-variant="boxed"]
    .vds-tabs-trigger[data-state="active"]::before,
  .vds-tabs-list[data-variant="boxed"]
    .vds-tabs-trigger[data-state="active"]::after {
    opacity: 1;
  }

  /* Boxed vertical — curves attach to inline-end side */
  .vds-tabs-list[data-variant="boxed"][data-orientation="vertical"] {
    align-items: stretch;
    padding-inline: 0;
    padding-block: var(--tabs-boxed-curve);
    --tabs-boxed-curve-shadow-x: calc(var(--tabs-boxed-curve) / 2);
  }
  .vds-tabs-list[data-variant="boxed"][data-orientation="vertical"]
    .vds-tabs-trigger {
    border-block-end-width: var(--tabs-list-border-width);
    border-block-end-style: solid;
    border-inline-end-width: 0;
    border-start-start-radius: var(--tabs-boxed-curve);
    border-end-start-radius: var(--tabs-boxed-curve);
    border-start-end-radius: 0;
    border-end-end-radius: 0;
    margin-block-end: 0;
    margin-inline-end: calc(-1 * var(--tabs-list-border-width));
    padding-block-end: var(--tabs-trigger-padding-block);
    padding-inline-end: calc(
      var(--tabs-trigger-padding-inline) + var(--tabs-list-border-width)
    );
  }
  .vds-tabs-list[data-variant="boxed"][data-orientation="vertical"]
    .vds-tabs-trigger::before {
    inset-inline-start: auto;
    inset-inline-end: calc(-1 * var(--tabs-list-border-width));
    inset-block-end: auto;
    inset-block-start: calc(-1 * var(--tabs-boxed-curve));
    border: 0;
    border-inline-end: var(--tabs-list-border-width) solid
      var(--tabs-boxed-border);
    border-block-end: var(--tabs-list-border-width) solid
      var(--tabs-boxed-border);
    border-end-end-radius: var(--tabs-boxed-curve);
    border-start-end-radius: 0;
    box-shadow: var(--tabs-boxed-curve-shadow-x)
      calc(var(--tabs-boxed-curve) / 2) 0 0 var(--tabs-boxed-bg);
  }
  .vds-tabs-list[data-variant="boxed"][data-orientation="vertical"]
    .vds-tabs-trigger::after {
    inset-inline-start: auto;
    inset-inline-end: calc(-1 * var(--tabs-list-border-width));
    inset-block-start: auto;
    inset-block-end: calc(-1 * var(--tabs-boxed-curve));
    border: 0;
    border-inline-end: var(--tabs-list-border-width) solid
      var(--tabs-boxed-border);
    border-block-start: var(--tabs-list-border-width) solid
      var(--tabs-boxed-border);
    border-end-start-radius: 0;
    border-start-end-radius: var(--tabs-boxed-curve);
    box-shadow: var(--tabs-boxed-curve-shadow-x)
      calc(-1 * var(--tabs-boxed-curve) / 2) 0 0 var(--tabs-boxed-bg);
  }
  .vds-tabs-list:dir(rtl)[data-variant="boxed"][data-orientation="vertical"] {
    --tabs-boxed-curve-shadow-x: calc(-1 * var(--tabs-boxed-curve) / 2);
  }

  /* ─────────────────────────────────────────────
   * Orientation: vertical
   * ───────────────────────────────────────────── */
  .vds-tabs-list[data-orientation="vertical"] {
    flex-direction: column;
    align-items: stretch;
    border-block-end-width: 0;
    border-inline-end-width: var(--tabs-list-border-width);
  }
  .vds-tabs-list[data-orientation="vertical"] .vds-tabs-trigger {
    justify-content: flex-start;
    /* In vertical mode, long labels wrap to the next line instead of
       forcing a horizontal scroll. Height expands to fit content. */
    white-space: normal;
    overflow-wrap: anywhere;
    min-inline-size: 0;
    text-align: start;
    block-size: auto;
    min-block-size: var(--tabs-trigger-height);
    padding-block-start: var(--vds-space-2, 0.5rem);
    padding-block-end: var(--vds-space-2, 0.5rem);
    inline-size: 100%;
  }
  .vds-tabs-list[data-orientation="vertical"] {
    max-inline-size: 100%;
    overflow-x: visible;
    overflow-y: auto;
  }
  /* line variant in vertical: swap to inline-start border */
  .vds-tabs-list[data-variant="line"][data-orientation="vertical"] {
    border-inline-end-width: 0;
    border-inline-start-width: var(--tabs-list-border-width);
  }

  /* Static fallback for vertical underline/line (animated off) */
  .vds-tabs-list[data-orientation="vertical"] {
    --tabs-static-inline-sign: 1;
  }
  .vds-tabs-list[data-orientation="vertical"]:dir(rtl) {
    --tabs-static-inline-sign: -1;
  }
  .vds-tabs-list[data-variant="underline"][data-orientation="vertical"]:not(
      [data-animated="true"]
    )
    .vds-tabs-trigger {
    box-shadow: inset calc(-1 * var(--tabs-static-inline-sign) * var(--tabs-indicator-thickness)) 0 0 0
      transparent;
  }
  .vds-tabs-list[data-variant="underline"][data-orientation="vertical"]:not(
      [data-animated="true"]
    )
    .vds-tabs-trigger[data-state="active"] {
    box-shadow: inset calc(-1 * var(--tabs-static-inline-sign) * var(--tabs-indicator-thickness)) 0 0 0
      var(--tabs-indicator-color);
  }
  .vds-tabs-list[data-variant="line"][data-orientation="vertical"]:not(
      [data-animated="true"]
    )
    .vds-tabs-trigger {
    box-shadow: inset calc(var(--tabs-static-inline-sign) * var(--tabs-indicator-thickness)) 0 0 0 transparent;
  }
  .vds-tabs-list[data-variant="line"][data-orientation="vertical"]:not(
      [data-animated="true"]
    )
    .vds-tabs-trigger[data-state="active"] {
    box-shadow: inset calc(var(--tabs-static-inline-sign) * var(--tabs-indicator-thickness)) 0 0 0
      var(--tabs-indicator-color);
  }

  /* ─────────────────────────────────────────────
   * Full-width modifier
   * ───────────────────────────────────────────── */
  .vds-tabs-list[data-full-width="true"] {
    display: flex;
    inline-size: 100%;
  }
  .vds-tabs-list[data-full-width="true"] .vds-tabs-trigger {
    flex: 1 1 0;
    min-inline-size: 0;
    white-space: normal;
    overflow-wrap: anywhere;
    padding-block: max(var(--tabs-trigger-padding-block), var(--vds-space-1, 0.25rem));
  }

  @media (forced-colors: active) {
    .vds-tabs-trigger:is([data-state="active"], [data-state="checked"]) {
      outline: 1px solid Highlight;
      outline-offset: -1px;
    }
    .vds-tabs-trigger:focus-visible {
      outline: 2px solid Highlight;
      outline-offset: -3px;
    }
  }

  /* ─────────────────────────────────────────────
   * Reduced motion
   * ───────────────────────────────────────────── */
  @media (prefers-reduced-motion: reduce) {
    .vds-tabs-list::after,
    .vds-tabs-trigger,
    .vds-tabs-list[data-variant="boxed"] .vds-tabs-trigger::before,
    .vds-tabs-list[data-variant="boxed"] .vds-tabs-trigger::after {
      transition: none;
    }
    .vds-tabs-content[data-state="active"] {
      animation: none;
    }
  }
}

