@layer design-system.components {
  /* ─────────────────────────────────────────────
   * 1. Base tokens
   *    Semantic → component mapping with fallbacks
   *    so the package works standalone if dropped
   *    into a project without @virtari-packages/tokens.
   * ───────────────────────────────────────────── */

  /* ── List ── */
  .vds-tabs-list {
    /* Layout — lengths carry units even at zero because they feed the
       registered `--vds-radius-host-*` properties below, whose `<length>`
       syntax must parse for the concentricity subtraction to stay valid. */
    --tabs-list-gap: var(--vds-space-1, 0.25rem);
    --tabs-list-padding-inline: 0px;
    --tabs-list-padding-block: 0px;
    --tabs-list-radius: 0px;

    /* Surface */
    --tabs-list-bg: transparent;
    --tabs-list-border-color: var(--vds-surface-border, var(--vds-color-border, #d1d5db));
    --tabs-list-border-width: 0px;

    /* ── Radius nesting host ──
       The list is the element that draws the track corner, so it publishes
       its radius / border / padding for its direct children (the triggers)
       to subtract from. All three are declared — including the zeroes — so a
       list dropped inside another host (a Card, a Dialog) cannot inherit the
       outer host's border/padding and subtract the wrong distance.
       `-p` uses the block padding; the segmented track is the only variant
       with padding and it is symmetric, so either axis gives the same answer. */
    --vds-radius-host-r: var(--tabs-list-radius);
    --vds-radius-host-b: var(--tabs-list-border-width);
    --vds-radius-host-p: var(--tabs-list-padding-block);

    /* Sliding indicator */
    --tabs-indicator-color: var(--vds-color-primary-solid, #6366f1);
    --tabs-indicator-thickness: 2px;
    --tabs-indicator-radius: 0px;
    --tabs-indicator-inset: 0px;
    --tabs-indicator-display: none;
    --tabs-indicator-transition-duration: var(--vds-duration-fast, 100ms);
    --tabs-indicator-transition-ease: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  /* ── Trigger ── */
  .vds-tabs-trigger {
    /* Layout — md defaults (shared ramp with Button/Select) */
    --tabs-trigger-height: var(--vds-size-md, 2.25rem);
    --tabs-trigger-gap: var(--vds-space-2, 0.5rem);
    --tabs-trigger-padding-inline: var(--vds-space-4, 1rem);
    --tabs-trigger-padding-block: 0;
    --tabs-trigger-optical-offset: var(--vds-control-optical-offset, 0px);
    --tabs-trigger-radius: 0;
    --tabs-trigger-border-width: 0;

    /* Typography */
    --tabs-trigger-font-family: var(--vds-font-sans, ui-sans-serif, system-ui, sans-serif);
    --tabs-trigger-font-size: var(--vds-text-sm, 0.875rem);
    --tabs-trigger-font-weight: var(--vds-font-weight-medium, 500);
    --tabs-trigger-line-height: var(--vds-control-line-height, 1);

    /* Colors — inactive */
    --tabs-trigger-bg: transparent;
    --tabs-trigger-color: var(--vds-color-text-muted, #6b7280);
    --tabs-trigger-border-color: transparent;

    /* Colors — hover */
    --tabs-trigger-bg-hover: transparent;
    --tabs-trigger-color-hover: var(--vds-color-text, #111827);
    --tabs-trigger-border-color-hover: transparent;

    /* Colors — active */
    --tabs-trigger-bg-active: transparent;
    --tabs-trigger-color-active: var(--vds-color-text, #111827);
    --tabs-trigger-border-color-active: transparent;
    --tabs-trigger-shadow-active: none;

    /* Focus ring */
    --tabs-trigger-focus-ring-color: var(--vds-color-ring, #6366f1);
    --tabs-trigger-focus-ring-width: 2px;
    /* Draw inside the item so a scrollable list cannot clip keyboard focus. */
    --tabs-trigger-focus-ring-offset: -2px;

    /* Motion */
    --tabs-trigger-transition-duration: var(--vds-duration-fast, 100ms);
    --tabs-trigger-transition-ease: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
  }

  /* ── Content ── */
  .vds-tabs-content {
    --tabs-content-padding-block: var(--vds-space-4, 1rem);
    --tabs-content-focus-ring-color: var(--vds-color-ring, #6366f1);
    --tabs-content-focus-ring-width: 2px;
    --tabs-content-focus-ring-offset: 2px;
    --tabs-content-focus-ring-radius: var(--vds-radius-control, var(--vds-radius-element, 0.375rem));

    /* Enter animation when a panel becomes active */
    --tabs-content-enter-duration: var(--vds-duration-fast, 100ms);
    --tabs-content-enter-ease: var(--vds-ease-out, cubic-bezier(0, 0, 0.2, 1));
    --tabs-content-enter-translate: 0.5rem;
  }

  /* ── Root (Tabs) wrapper ── */
  .vds-tabs {
    --tabs-root-gap: var(--vds-space-4, 1rem);
    --tabs-root-separator-color: var(--vds-color-border-muted, #e5e7eb);
  }

  /* ── Panels carousel ── */
  .vds-tabs-panels {
    --tabs-panels-transition-duration: 320ms;
    --tabs-panels-transition-ease: var(
      --vds-ease-out,
      cubic-bezier(0.2, 0.9, 0.25, 1)
    );
    --tabs-panels-padding-block: var(--vds-space-4, 1rem);
  }

  /* ─────────────────────────────────────────────
   * 2. Appearance variants
   *    Each variant overrides only what it needs.
   * ───────────────────────────────────────────── */

  /* ── underline (default) ── */
  .vds-tabs-list[data-variant="underline"] {
    --tabs-list-gap: var(--vds-space-4, 1rem);
    --tabs-list-border-width: 1px;
    --tabs-indicator-display: block;
    --tabs-indicator-thickness: 2px;
    --tabs-indicator-inset: 0;
  }
  .vds-tabs-list[data-variant="underline"] .vds-tabs-trigger {
    --tabs-trigger-color-active: var(--vds-color-text, #111827);
  }

  /* ── line (top) ── */
  .vds-tabs-list[data-variant="line"] {
    --tabs-list-gap: var(--vds-space-4, 1rem);
    --tabs-list-border-width: 1px;
    --tabs-indicator-display: block;
    --tabs-indicator-thickness: 2px;
    --tabs-indicator-inset: 0;
  }
  .vds-tabs-list[data-variant="line"] .vds-tabs-trigger {
    --tabs-trigger-color-active: var(--vds-color-text, #111827);
  }

  /* ── pills ── */
  .vds-tabs-list[data-variant="pills"] {
    --tabs-list-gap: var(--vds-space-1, 0.25rem);
    --tabs-indicator-display: block;
    --tabs-indicator-color: var(--vds-color-primary-solid, #6366f1);
    --tabs-indicator-radius: var(--vds-radius-badge, 9999px);
  }
  .vds-tabs-list[data-variant="pills"] .vds-tabs-trigger {
    --tabs-trigger-radius: var(--vds-radius-badge, 9999px);
    --tabs-trigger-bg-active: var(--vds-color-primary-solid, #6366f1);
    --tabs-trigger-color-active: var(--vds-color-on-primary, #ffffff);
    --tabs-trigger-bg-hover: var(--vds-color-bg-muted, #f3f4f6);
    --tabs-trigger-color-hover: var(--vds-color-text, #111827);
  }

  /* ── segmented ── */
  .vds-tabs-list[data-variant="segmented"] {
    --tabs-list-gap: 0;
    --tabs-list-bg: var(--vds-color-bg-muted, #f3f4f6);
    --tabs-list-radius: var(--vds-radius-segmented, var(--vds-radius-element, 0.375rem));
    --tabs-list-padding-inline: var(--vds-space-1, 0.25rem);
    --tabs-list-padding-block: var(--vds-space-1, 0.25rem);
    --tabs-indicator-display: block;
    --tabs-indicator-color: var(--vds-color-surface, #ffffff);
    /* The indicator is an ::after on the list, and a pseudo-element is not a
     * child — the nesting channel's `--vds-radius-inset` is registered
     * `inherits: false`, so it never reaches it. It re-runs the subtraction
     * over the same three --tabs-list-* tokens the host block publishes as
     * r / b / p, which keeps one source of truth and keeps working when the
     * package is used without @virtari-packages/tokens. */
    --tabs-indicator-radius: max(
      0px,
      calc(
        var(--tabs-list-radius) - var(--tabs-list-border-width) -
          var(--tabs-list-padding-block)
      )
    );
  }
  .vds-tabs-list[data-variant="segmented"] .vds-tabs-trigger {
    --tabs-trigger-optical-offset: var(--vds-control-optical-offset, 0px);
    /* Concentric with the track. The list carries `data-radius-host`, so a
     * trigger — a direct child — simply reads the channel's answer:
     * track radius − track border − track padding.
     *
     * The var() fallback is the standalone path, not a default. With the
     * tokens package loaded `--vds-radius-inset` is a *registered* property,
     * so it always has a value and the fallback can never fire (a trigger
     * that is not a direct child gets the registered `0px` initial — the
     * channel's deliberate fail-flat). Without the package the property does
     * not exist at all, and this keeps the tile concentric anyway. */
    --tabs-trigger-radius: var(
      --vds-radius-inset,
      max(
        0px,
        calc(
          var(--tabs-list-radius) - var(--tabs-list-border-width) -
            var(--tabs-list-padding-block)
        )
      )
    );
    --tabs-trigger-bg-active: var(--vds-color-surface, #ffffff);
    --tabs-trigger-color-active: var(--vds-color-text, #111827);
    --tabs-trigger-shadow-active: var(--vds-shadow-sm, 0 1px 2px 0 rgb(0 0 0 / 0.05));
  }

  /* A vertical track contains several short rows. Making the entire stack a
   * capsule would curve underneath the first/last labels, so it uses the
   * finite field shell even in pill mode. The tile and indicator keep deriving
   * their corners from this same track radius. */
  .vds-tabs-list[data-variant="segmented"][data-orientation="vertical"] {
    --tabs-list-radius: var(--vds-radius-control, var(--vds-radius-element, 0.375rem));
  }

  /* ── boxed (Chrome-style browser tabs with inverted curves) ── */
  .vds-tabs-list[data-variant="boxed"] {
    --tabs-list-gap: 0;
    --tabs-list-border-width: 1px;
    /* Curve radius — also used for top corners of each tab. */
    --tabs-boxed-curve: var(--vds-radius-tabs-boxed, min(var(--vds-radius-control, 0.5rem), var(--vds-radius-4, 0.5rem)));
    --tabs-boxed-bg: var(--vds-color-surface, #ffffff);
    --tabs-boxed-border: var(--vds-color-border, #d1d5db);
  }
  .vds-tabs-list[data-variant="boxed"] .vds-tabs-trigger {
    --tabs-trigger-radius: var(--tabs-boxed-curve);
    --tabs-trigger-bg-hover: var(--vds-color-surface-hover, #f9fafb);
    --tabs-trigger-bg-active: var(--tabs-boxed-bg);
    --tabs-trigger-color-active: var(--vds-color-text, #111827);
  }

  /* ── bordered ── */
  .vds-tabs-list[data-variant="bordered"] {
    --tabs-list-gap: var(--vds-space-1, 0.25rem);
  }
  .vds-tabs-list[data-variant="bordered"] .vds-tabs-trigger {
    --tabs-trigger-border-width: 1px;
    --tabs-trigger-radius: var(--vds-radius-tabs-trigger, var(--vds-radius-element, 0.375rem));
    --tabs-trigger-border-color: var(--vds-color-border, #d1d5db);
    --tabs-trigger-border-color-hover: var(--vds-color-border, #d1d5db);
    --tabs-trigger-bg-hover: var(--vds-color-surface-hover, #f9fafb);
    --tabs-trigger-bg-active: var(--vds-color-primary-solid, #6366f1);
    --tabs-trigger-border-color-active: var(--vds-color-primary-solid, #6366f1);
    --tabs-trigger-color-active: var(--vds-color-on-primary, #ffffff);
  }

  /* ── solid / filled ── */
  .vds-tabs-list[data-variant="solid"] {
    --tabs-list-gap: var(--vds-space-1, 0.25rem);
  }
  .vds-tabs-list[data-variant="solid"] .vds-tabs-trigger {
    --tabs-trigger-radius: var(--vds-radius-tabs-trigger, var(--vds-radius-element, 0.375rem));
    --tabs-trigger-bg-hover: var(--vds-color-bg-muted, #f3f4f6);
    --tabs-trigger-bg-active: var(--vds-color-primary-solid, #6366f1);
    --tabs-trigger-color-active: var(--vds-color-on-primary, #ffffff);
  }

  /* ── soft ── */
  .vds-tabs-list[data-variant="soft"] {
    --tabs-list-gap: var(--vds-space-1, 0.25rem);
  }
  .vds-tabs-list[data-variant="soft"] .vds-tabs-trigger {
    --tabs-trigger-radius: var(--vds-radius-tabs-trigger, var(--vds-radius-element, 0.375rem));
    --tabs-trigger-bg-hover: var(--vds-color-bg-muted, #f3f4f6);
    --tabs-trigger-bg-active: var(--vds-color-primary-bg, #eef2ff);
    --tabs-trigger-color-active: var(--vds-color-primary-text, #3730a3);
  }

  /* ── ghost ── */
  .vds-tabs-list[data-variant="ghost"] {
    --tabs-list-gap: var(--vds-space-1, 0.25rem);
  }
  .vds-tabs-list[data-variant="ghost"] .vds-tabs-trigger {
    --tabs-trigger-radius: var(--vds-radius-tabs-trigger, var(--vds-radius-element, 0.375rem));
    --tabs-trigger-bg-hover: var(--vds-color-bg-muted, #f3f4f6);
    --tabs-trigger-bg-active: transparent;
    --tabs-trigger-color-active: var(--vds-color-text, #111827);
  }

  /* ─────────────────────────────────────────────
   * 3. Size ramp (trigger only — layout + typography)
   *    Shared with Button / Select / Input.
   * ───────────────────────────────────────────── */

  .vds-tabs-list[data-size="2xs"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-2xs, 1.5rem);
    --tabs-trigger-padding-inline: var(--vds-space-2, 0.5rem);
    --tabs-trigger-gap: var(--vds-space-1, 0.25rem);
    --tabs-trigger-font-size: var(--vds-text-xs, 0.75rem);
  }
  .vds-tabs-list[data-size="xs"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-xs, 1.75rem);
    --tabs-trigger-padding-inline: var(--vds-space-2-5, 0.625rem);
    --tabs-trigger-gap: var(--vds-space-1, 0.25rem);
    --tabs-trigger-font-size: var(--vds-text-xs, 0.75rem);
  }
  .vds-tabs-list[data-size="sm"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-sm, 2rem);
    --tabs-trigger-padding-inline: var(--vds-space-3, 0.75rem);
    --tabs-trigger-gap: var(--vds-space-1-5, 0.375rem);
    --tabs-trigger-font-size: var(--vds-text-sm, 0.875rem);
  }
  /* md — default. The base .vds-tabs-trigger block above *is* the md step, so
     restating it here would only add a higher-specificity copy that consumer
     overrides have to fight. An unsized trigger renders md for the same
     reason. */

  .vds-tabs-list[data-size="lg"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-lg, 2.5rem);
    --tabs-trigger-padding-inline: var(--vds-space-5, 1.25rem);
    --tabs-trigger-gap: var(--vds-space-2, 0.5rem);
    --tabs-trigger-font-size: var(--vds-text-base, 1rem);
  }
  .vds-tabs-list[data-size="xl"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-xl, 2.75rem);
    --tabs-trigger-padding-inline: var(--vds-space-6, 1.5rem);
    --tabs-trigger-gap: var(--vds-space-2, 0.5rem);
    --tabs-trigger-font-size: var(--vds-text-base, 1rem);
  }
  .vds-tabs-list[data-size="2xl"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-2xl, 3.25rem);
    --tabs-trigger-padding-inline: var(--vds-space-7, 1.75rem);
    --tabs-trigger-gap: var(--vds-space-2-5, 0.625rem);
    --tabs-trigger-font-size: var(--vds-text-lg, 1.125rem);
  }
  .vds-tabs-list[data-size="3xl"] .vds-tabs-trigger {
    --tabs-trigger-height: var(--vds-size-3xl, 4rem);
    --tabs-trigger-padding-inline: var(--vds-space-8, 2rem);
    --tabs-trigger-gap: var(--vds-space-3, 0.75rem);
    --tabs-trigger-font-size: var(--vds-text-xl, 1.25rem);
  }
}

packages/react-tabs/src/Tabs.tsx:
import { cn, controlText, useDirection } from "@virtari-packages/utils";
import { useDirection as usePrimitiveDirection } from "@virtari-packages/primitives/direction";
import {
  useRef,
  type ComponentRef,
  type Ref,
  type RefObject,
} from "react";
import * as TabsPrimitive from "@virtari-packages/primitives/tabs";
import { useTabsIndicator } from "./use-tabs-indicator";
import { useTabsSwipe } from "./use-tabs-swipe";
import { useTabsAutoScroll } from "./use-tabs-auto-scroll";
import {
  useResponsiveOrientation,
  type TabsOrientation,
} from "./use-responsive-orientation";

export type TabsVariant =
  | "underline"
  | "line"
  | "pills"
  | "segmented"
  | "boxed"
  | "bordered"
  | "solid"
  | "soft"
  | "ghost";

export type TabsSize = "2xs" | "xs" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl";

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === "function") ref(node);
      else (ref as RefObject<T | null>).current = node;
    }
  };
}

/* Root */
export interface TabsProps
  extends React.ComponentPropsWithoutRef<typeof TabsPrimitive.Root> {
  /** Collapse `orientation="vertical"` back to horizontal when the Tabs
   *  container is narrower than this (in px). Pass `undefined` to disable. */
  collapseAt?: number;
  /** Enable touch swipe on the active content to switch to prev/next tab.
   *  Only active in horizontal orientation. */
  swipeable?: boolean;
  /** Minimum horizontal drag (px) to commit a swipe. Default 60. */
  swipeThreshold?: number;
  /** Max visual translation (px) while dragging. Default 80. */
  swipeMaxOffset?: number;
  ref?: Ref<ComponentRef<typeof TabsPrimitive.Root>>;
}

export function Tabs({
  className,
  orientation = "horizontal",
  dir,
  collapseAt,
  swipeable = false,
  swipeThreshold = 60,
  swipeMaxOffset = 80,
  ref,
  ...props
}: TabsProps) {
  const rootRef = useRef<ComponentRef<typeof TabsPrimitive.Root>>(null);
  const parentRef = useRef<Element | null>(null);
  const inheritedDirection = useDirection(parentRef);
  const direction = usePrimitiveDirection(dir, inheritedDirection);

  const effectiveOrientation = useResponsiveOrientation(
    rootRef,
    orientation as TabsOrientation,
    collapseAt,
  );

  useTabsSwipe(rootRef, {
    enabled: swipeable && effectiveOrientation === "horizontal",
    threshold: swipeThreshold,
    maxOffset: swipeMaxOffset,
  });

  return (
    <TabsPrimitive.Root
      ref={mergeRefs(rootRef, ref, node => { parentRef.current = node?.parentElement ?? null; })}
      dir={direction}
      orientation={effectiveOrientation}
      className={cn("vds-tabs", className)}
      {...props}
    />
  );
}

/* List */
export interface TabsListProps
  extends React.ComponentPropsWithoutRef<typeof TabsPrimitive.List> {
  variant?: TabsVariant;
  size?: TabsSize;
  fullWidth?: boolean;
  animatedIndicator?: boolean;
  /** When the list overflows, auto-scroll the active trigger into view
   *  (centered) so it's never clipped. Default `true`. */
  autoScroll?: boolean;
  ref?: Ref<ComponentRef<typeof TabsPrimitive.List>>;
}

export function TabsList({
  className,
  variant = "underline",
  size = "md",
  fullWidth,
  animatedIndicator = true,
  autoScroll = true,
  ref,
  ...props
}: TabsListProps) {
  const innerRef = useRef<ComponentRef<typeof TabsPrimitive.List>>(null);
  useTabsIndicator(innerRef, animatedIndicator);
  useTabsAutoScroll(innerRef, autoScroll);

  return (
    <TabsPrimitive.List
      ref={mergeRefs(innerRef, ref)}
      className={cn("vds-tabs-list", className)}
      data-radius-host=""
      data-variant={variant}
      data-size={size}
      data-full-width={fullWidth ? "true" : undefined}
      data-animated={animatedIndicator ? "true" : undefined}
      {...props}
    />
  );
}

/* Trigger */
export interface TabsTriggerProps
  extends React.ComponentPropsWithoutRef<typeof TabsPrimitive.Trigger> {
  ref?: Ref<ComponentRef<typeof TabsPrimitive.Trigger>>;
}

export function TabsTrigger({
  children,
  className,
  ref,
  ...props
}: TabsTriggerProps) {
  return (
    <TabsPrimitive.Trigger
      ref={ref}
      className={cn("vds-tabs-trigger", className)}
      {...props}
    >
      <span className="vds-tabs-trigger-content">{controlText(children)}</span>
    </TabsPrimitive.Trigger>
  );
}

/* Content */
export interface TabsContentProps
  extends React.ComponentPropsWithoutRef<typeof TabsPrimitive.Content> {
  ref?: Ref<ComponentRef<typeof TabsPrimitive.Content>>;
}

export function TabsContent({ className, ref, ...props }: TabsContentProps) {
  return (
    <TabsPrimitive.Content
      ref={ref}
      className={cn("vds-tabs-content", className)}
      {...props}
    />
  );
}

