import { cn } from "@virtari-packages/utils";
import {
  Children,
  cloneElement,
  isValidElement,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { useCarouselSwipe } from "./use-carousel-swipe";

export interface TabsPanelsProps {
  children: ReactNode;
  className?: string;
  /** Enable swipe/drag to navigate between panels. Default true. */
  swipeable?: boolean;
  /** Minimum pointer drag (px) to commit a tab change. Default 50. */
  swipeThreshold?: number;
  /** Restrict swipe interaction to touch-only devices (pointer: coarse).
   *  Default true — desktop users still change tabs via the list. */
  touchOnly?: boolean;
  /** Controls how many tab panels stay mounted.
   *  - `all`: preserves the previous behavior by mounting every panel.
   *  - `adjacent`: mounts only the active panel and its previous/next
   *    neighbors, keeping swipe responsive without paying the cost for
   *    distant heavy panels.
   *
   *  Default `all` to avoid changing existing behavior. */
  mountStrategy?: TabsPanelsMountStrategy;
  ref?: Ref<HTMLDivElement>;
}

export type TabsPanelsMountStrategy = "all" | "adjacent";

type TabsPanelChildProps = {
  forceMount?: true;
};

/**
 * Carousel-style container for `TabsContent`. By default it mounts all panels
 * at once (via `forceMount`), lays them out in a horizontal track, and
 * translates the track based on the active tab. Use
 * `mountStrategy="adjacent"` for heavy tab content.
 *
 * ```tsx
 * <Tabs defaultValue="a">
 *   <TabsList>...</TabsList>
 *   <TabsPanels>
 *     <TabsContent value="a">A</TabsContent>
 *     <TabsContent value="b">B</TabsContent>
 *   </TabsPanels>
 * </Tabs>
 * ```
 */
export function TabsPanels({
  children,
  className,
  swipeable = true,
  swipeThreshold = 50,
  touchOnly = true,
  mountStrategy = "all",
  ref,
}: TabsPanelsProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isTouch, setIsTouch] = useState(!touchOnly);

  /* Clone children to add `forceMount` to the panels required by the selected
     mounting strategy, and wrap each in a slide frame. */
  const slides: ReactElement[] = [];
  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;
    const idx = slides.length;
    const shouldForceMount =
      mountStrategy === "all" || Math.abs(idx - activeIndex) <= 1;
    const cloned = shouldForceMount
      ? cloneElement(child as ReactElement<TabsPanelChildProps>, {
          forceMount: true,
        })
      : (child as ReactElement);
    slides.push(cloned);
  });
  const slideCount = slides.length;

  /* Touch-only gate. Switch to "active" once a pointer-coarse media query
     matches, so desktop users still use tab clicks. */
  useLayoutEffect(() => {
    if (!touchOnly) {
      setIsTouch(true);
      return;
    }
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(pointer: coarse)");
    const apply = () => setIsTouch(mq.matches);
    apply();
    mq.addEventListener?.("change", apply);
    return () => mq.removeEventListener?.("change", apply);
  }, [touchOnly]);

  /* Track which panel is active via DOM attribute (the primitive sets
     data-state="active" on the visible panel). */
  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const update = () => {
      const activePanel = container.querySelector<HTMLElement>(
        ':scope > .vds-tabs-panels-track > .vds-tabs-panels-slide > [role="tabpanel"][data-state="active"]',
      );
      const slide = activePanel?.closest<HTMLElement>(".vds-tabs-panels-slide");
      const idx = Number(slide?.dataset.index);
      if (Number.isInteger(idx) && idx >= 0) {
        setActiveIndex((prev) => {
          if (idx === prev) return prev;
          if (mountStrategy === "adjacent" && Math.abs(idx - prev) > 1) {
            const track = trackRef.current;
            if (track) track.style.transition = "none";
          }
          return idx;
        });
      }
    };
    update();

    const mo = new MutationObserver(update);
    mo.observe(container, {
      attributes: true,
      attributeFilter: ["data-state"],
      childList: true,
      subtree: true,
    });
    return () => mo.disconnect();
  }, [slideCount, mountStrategy]);

  const activateByDirection = useCallback(
    (direction: "next" | "prev") => {
      const container = containerRef.current;
      if (!container) return false;
      const target =
        direction === "next"
          ? Math.min(activeIndex + 1, slideCount - 1)
          : Math.max(activeIndex - 1, 0);
      if (target === activeIndex) return false;

      const targetSlide = container.querySelector<HTMLElement>(
        `:scope > .vds-tabs-panels-track > .vds-tabs-panels-slide[data-index="${target}"]`,
      );
      const panel = targetSlide?.querySelector<HTMLElement>('[role="tabpanel"]');
      if (!panel) return false;
      const root = container.closest<HTMLElement>(".vds-tabs") ?? document.body;

      /* Primary: the primitive writes the owning trigger ID onto the panel
         via `aria-labelledby`, so we can hop straight to the exact trigger
         without depending on selector quirks. */
      let trigger: HTMLButtonElement | null = null;
      const triggerId = panel.getAttribute("aria-labelledby");
      if (triggerId) {
        const labelledTrigger = document.getElementById(triggerId);
        if (labelledTrigger instanceof HTMLButtonElement) {
          trigger = labelledTrigger;
        }
      }

      /* Secondary: match the trigger by `aria-controls` within the current
         tabs root. */
      if (panel.id) {
        trigger ??= root.querySelector<HTMLButtonElement>(
          `[role="tab"][aria-controls="${panel.id}"]`,
        );
      }

      /* Fallback: match by index within the nearest tablist (the primitive
         renders triggers in the same order as contents). */
      if (!trigger) {
        const tablist = root.querySelector('[role="tablist"]');
        const triggers =
          tablist?.querySelectorAll<HTMLButtonElement>('[role="tab"]');
        trigger = triggers?.[target] ?? null;
      }

      if (!trigger || trigger.disabled || trigger.hasAttribute("data-disabled")) {
        return false;
      }

      trigger.focus({ preventScroll: true });
      trigger.dispatchEvent(
        new MouseEvent("mousedown", {
          bubbles: true,
          cancelable: true,
          button: 0,
          buttons: 1,
          view: window,
        }),
      );
      trigger.dispatchEvent(
        new MouseEvent("mouseup", {
          bubbles: true,
          cancelable: true,
          button: 0,
          view: window,
        }),
      );
      return true;
    },
    [activeIndex, slideCount],
  );

  useCarouselSwipe(containerRef, trackRef, {
    enabled: swipeable && isTouch && slideCount > 1,
    activeIndex,
    slideCount,
    threshold: swipeThreshold,
    onCommit: activateByDirection,
  });

  /* After any activeIndex change (commit from swipe, or an external tab
     click), clear any inline transform/transition left on the track so the
     CSS-driven `translateX(var(--tabs-panels-tx))` baseline takes over. The
     CSS transition then animates from the drag position (if any) to the new
     baseline in one continuous movement. */
  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    track.style.transform = "";
    track.style.transition = "";
  }, [activeIndex]);

  const setRef = (node: HTMLDivElement | null) => {
    containerRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) (ref as { current: HTMLDivElement | null }).current = node;
  };

  return (
    <div
      ref={setRef}
      className={cn("vds-tabs-panels", className)}
      data-swipeable={swipeable && isTouch ? "true" : undefined}
      data-mount-strategy={mountStrategy}
    >
      <div
        ref={trackRef}
        className="vds-tabs-panels-track"
        style={
          {
            "--tabs-panels-tx": `${-activeIndex * 100}%`,
          } as CSSProperties
        }
      >
        {slides.map((slide, idx) => (
          <div
            key={(slide.key as string | number | null) ?? idx}
            className="vds-tabs-panels-slide"
            data-index={idx}
            data-active={idx === activeIndex ? "true" : undefined}
            // Set the native property because React 18 does not serialize
            // the boolean inert attribute (React 19 does).
            ref={(node) => { if (node) node.inert = idx !== activeIndex; }}
            aria-hidden={idx !== activeIndex ? true : undefined}
          >
            {slide}
          </div>
        ))}
      </div>
    </div>
  );
}

packages/react-tabs/src/use-carousel-swi:
import { useEffect, type RefObject } from "react";

interface UseCarouselSwipeOptions {
  enabled: boolean;
  activeIndex: number;
  slideCount: number;
  threshold: number;
  onCommit: (direction: "next" | "prev") => boolean;
}

/**
 * Drag/swipe a carousel track with pointer (touch + mouse for trackpads /
 * drag-capable desktops). Rubber-bands at the ends, commits past threshold.
 *
 * The track is translated by `translateX(-activeIndex * 100%)` via React
 * state; this hook only applies an *inline* transform during a drag to
 * temporarily override that, then clears it on release so React's transform
 * (with CSS transition) animates to the final position.
 */
export function useCarouselSwipe(
  containerRef: RefObject<HTMLDivElement | null>,
  trackRef: RefObject<HTMLDivElement | null>,
  {
    enabled,
    activeIndex,
    slideCount,
    threshold,
    onCommit,
  }: UseCarouselSwipeOptions,
) {
  useEffect(() => {
    const container = containerRef.current;
    const track = trackRef.current;
    if (!container || !track || !enabled || slideCount <= 1) return;

    let startX = 0;
    let startY = 0;
    let dragging = false;
    let axis: null | "x" | "y" = null;
    let pointerId = -1;

    const containerWidth = () => container.getBoundingClientRect().width;
    const rtlSign = () =>
      getComputedStyle(container).direction === "rtl" ? -1 : 1;

    const clearDragInstant = () => {
      track.style.transition = "";
      track.style.transform = "";
    };

    const animateBackToBaseline = () => {
      track.style.transition = "transform 220ms cubic-bezier(0, 0, 0.2, 1)";
      track.style.transform = "";
      window.setTimeout(() => {
        track.style.transition = "";
      }, 240);
    };

    const onPointerDown = (e: PointerEvent) => {
      if (e.pointerType === "mouse" && e.button !== 0) return;
      const target = e.target as HTMLElement;
      if (
        target.closest(
          'button, a, input, textarea, select, [role="tab"], [role="tablist"], [contenteditable="true"]',
        )
      ) {
        return;
      }
      startX = e.clientX;
      startY = e.clientY;
      dragging = true;
      axis = null;
      pointerId = e.pointerId;
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!dragging || e.pointerId !== pointerId) return;
      const dx = e.clientX - startX;
      const dy = e.clientY - startY;

      if (!axis) {
        if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
        axis = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
        if (axis === "y") {
          dragging = false;
          return;
        }
        track.style.transition = "none";
        container.setPointerCapture(e.pointerId);
      }

      if (axis === "x") {
        if (e.cancelable) e.preventDefault();
        const w = containerWidth();
        const sign = rtlSign();
        /* In RTL the flex row lays slides out physically right-to-left, so
           bringing the Nth slide into the viewport requires a positive
           translateX instead of negative. The track CSS mirrors the same
           logic for the resting transform. */
        const baseline = -sign * activeIndex * w;

        /* Rubber-band at the edges. Semantics are logical: "before start"
           means dragging back toward the inline-start of the list, which is
           physically rightward in RTL. */
        const logicalDx = sign * dx;
        let effective = dx;
        const atStart = activeIndex === 0 && logicalDx > 0;
        const atEnd = activeIndex === slideCount - 1 && logicalDx < 0;
        if (atStart || atEnd) effective = dx * 0.25;

        track.style.transform = `translateX(${baseline + effective}px)`;
      }
    };

    const onPointerUp = (e: PointerEvent) => {
      if (!dragging) {
        clearDragInstant();
        return;
      }
      if (e.pointerId !== pointerId) return;
      container.releasePointerCapture?.(e.pointerId);
      const dx = e.clientX - startX;
      dragging = false;

      if (axis === "x" && Math.abs(dx) > threshold) {
        const logicalDx = rtlSign() * dx;
        const dir = logicalDx < 0 ? "next" : "prev";
        /* Commit path: leave the inline `transform` in place (at the drag
           position) and only restore the default transition. Once React
           re-renders with the new activeIndex, a useEffect in TabsPanels
           clears the inline transform — CSS transform (driven by the
           updated --tabs-panels-tx variable) takes over and the CSS
           transition animates from the drag position to the new baseline
           in one continuous movement. */
        track.style.transition = "";
        axis = null;
        if (onCommit(dir)) return;
        animateBackToBaseline();
        return;
      }

      /* Below threshold → rubber-band back to baseline. Clearing the inline
         transform lets the CSS `translateX(var(--tabs-panels-tx))` reassert
         the current baseline, and a short inline transition animates us
         there before the CSS default transition resumes. */
      animateBackToBaseline();
      axis = null;
    };

    const onPointerCancel = () => {
      dragging = false;
      axis = null;
      clearDragInstant();
    };

    container.addEventListener("pointerdown", onPointerDown, { passive: true });
    container.addEventListener("pointermove", onPointerMove, { passive: false });
    container.addEventListener("pointerup", onPointerUp);
    container.addEventListener("pointercancel", onPointerCancel);

    return () => {
      container.removeEventListener("pointerdown", onPointerDown);
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerup", onPointerUp);
      container.removeEventListener("pointercancel", onPointerCancel);
      clearDragInstant();
    };
  }, [containerRef, trackRef, enabled, activeIndex, slideCount, threshold, onCommit]);
}

