    --timeline-connector-min-h: var(--vds-space-9, 2.25rem);

    /* Surface */
    --timeline-card-bg: var(--vds-surface-bg, var(--vds-color-surface, #fff));
    --timeline-card-border: var(--vds-color-border-muted, #e5e7eb);
