import type { ToastData, ToastOptions } from "./types";

type Listener = (snapshot: readonly ToastData[]) => void;

const DEFAULT_DURATION = 4000;

let counter = 0;
let snapshot: readonly ToastData[] = Object.freeze<ToastData[]>([]);
const listeners = new Set<Listener>();

let defaultDuration = DEFAULT_DURATION;
let maxToasts = Infinity;

export function createToastId(): string {
  return `vds-toast-${++counter}-${Date.now().toString(36)}`;
}

function resolveDuration(type: ToastData["type"], requested?: number): number {
  if (requested !== undefined) return Math.max(0, requested);
  if (type === "loading") return 0;
  return defaultDuration;
}

function commit(next: readonly ToastData[]) {
  snapshot = Object.freeze(next);
  for (const l of listeners) l(snapshot);
}

function enforceCap(list: readonly ToastData[]): readonly ToastData[] {
  if (list.length <= maxToasts) return list;
  return list.slice(list.length - maxToasts);
}

export const toastStore = {
  getSnapshot(): readonly ToastData[] {
    return snapshot;
  },

  subscribe(l: Listener): () => void {
    listeners.add(l);
    return () => {
      listeners.delete(l);
    };
  },

  setDefaultDuration(ms: number): void {
    defaultDuration = ms;
  },

  setMaxToasts(n: number | undefined): void {
    maxToasts = n ?? Infinity;
    const trimmed = enforceCap(snapshot);
    if (trimmed !== snapshot) commit(trimmed);
  },

  add(opts: ToastOptions): string {
    const id = opts.id ?? createToastId();
    const type = opts.type ?? "default";
    const toast: ToastData = {
      id,
      type,
      title: opts.title,
      description: opts.description,
      action: opts.action,
      actions: opts.actions,
      duration: resolveDuration(type, opts.duration),
      dismissible: opts.dismissible ?? true,
      icon: opts.icon,
      createdAt: Date.now(),
    };

    const existingIdx = snapshot.findIndex((t) => t.id === id);
    const next =
      existingIdx !== -1
        ? [
            ...snapshot.slice(0, existingIdx),
            toast,
            ...snapshot.slice(existingIdx + 1),
          ]
        : [...snapshot, toast];

    commit(enforceCap(next));
    return id;
  },

  update(id: string, patch: Partial<Omit<ToastOptions, "id">>): void {
    const idx = snapshot.findIndex((t) => t.id === id);
    if (idx === -1) return;

    const current = snapshot[idx];
    const nextType = patch.type ?? current.type;
    const typeChanged = patch.type !== undefined && patch.type !== current.type;
    const leavingLoading = current.type === "loading" && typeChanged;

    const duration =
      patch.duration !== undefined
        ? Math.max(0, patch.duration)
        : leavingLoading
        ? defaultDuration
        : current.duration;

    const updated: ToastData = {
      ...current,
      ...patch,
      type: nextType,
      duration,
      dismissible: patch.dismissible ?? current.dismissible,
      createdAt: Date.now(),
    };

    const next = [
      ...snapshot.slice(0, idx),
      updated,
      ...snapshot.slice(idx + 1),
    ];
    commit(next);
  },

  remove(id: string): void {
    const next = snapshot.filter((t) => t.id !== id);
    if (next.length !== snapshot.length) commit(next);
  },

  removeAll(): void {
    if (snapshot.length === 0) return;
    commit([]);
  },
};

packages/react-toast/src/Toast.css:
@import "./Toast.tokens.css";

@layer design-system.components {
  /* ------------------------------------------------------------------ */
  /*  Viewport (Toaster)                                                 */
  /* ------------------------------------------------------------------ */

  .vds-toaster {
    position: fixed;
    z-index: var(--vds-z-toast);
    display: block;
    inline-size: min(var(--toast-width), calc(100vw - var(--toast-viewport-margin)));
    margin: 0;
    padding: 0;
    list-style: none;
    outline: none;
    pointer-events: none;
  }

  /* Position variants — 6-grid */
  .vds-toaster--top-left {
    inset-block-start: calc(var(--toast-offset-block) + env(safe-area-inset-top, 0px));
    inset-inline-start: calc(var(--toast-offset-inline) + env(safe-area-inset-left, 0px));
  }
  .vds-toaster--top-right {
    inset-block-start: calc(var(--toast-offset-block) + env(safe-area-inset-top, 0px));
    inset-inline-end: calc(var(--toast-offset-inline) + env(safe-area-inset-right, 0px));
  }
  .vds-toaster--top-center {
    inset-block-start: calc(var(--toast-offset-block) + env(safe-area-inset-top, 0px));
    inset-inline-start: 50%;
    transform: translateX(-50%);
  }
  .vds-toaster--bottom-left {
    inset-block-end: calc(var(--toast-offset-block) + env(safe-area-inset-bottom, 0px));
    inset-inline-start: calc(var(--toast-offset-inline) + env(safe-area-inset-left, 0px));
  }
  .vds-toaster--bottom-right {
    inset-block-end: calc(var(--toast-offset-block) + env(safe-area-inset-bottom, 0px));
    inset-inline-end: calc(var(--toast-offset-inline) + env(safe-area-inset-right, 0px));
  }
  .vds-toaster--bottom-center {
    inset-block-end: calc(var(--toast-offset-block) + env(safe-area-inset-bottom, 0px));
    inset-inline-start: 50%;
    transform: translateX(-50%);
  }
  :dir(rtl) .vds-toaster--top-center,
  :dir(rtl) .vds-toaster--bottom-center {
    transform: translateX(50%);
  }

  /* ------------------------------------------------------------------ */
  /*  Toast (<li>)                                                       */
  /* ------------------------------------------------------------------ */

  .vds-toast {
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    background: var(--toast-surface);
    border: var(--toast-border-width) solid var(--toast-border-color);
    border-radius: var(--toast-radius);
    box-shadow: var(--toast-shadow);
    min-block-size: var(--toast-min-height);
    overflow: hidden;
    pointer-events: auto;
    user-select: none;
    cursor: grab;
    /* Allow vertical page scroll while we intercept horizontal drags */
    touch-action: pan-y;
    transform:
      translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
      scale(var(--vds-toast-scale, 1));
    opacity: var(--vds-toast-opacity, 1);
    will-change: transform, opacity;
    transition:
      transform var(--toast-duration) var(--toast-ease),
      opacity var(--vds-duration-slow) var(--vds-ease-out),
      box-shadow var(--vds-duration-slow) var(--vds-ease-out);
  }

  /* Bottom positions anchor toasts at container bottom edge; stacking offset
     is negative Y so older toasts drift upward. */
  .vds-toaster[data-position^="bottom"] .vds-toast {
    inset-block-start: auto;
    inset-block-end: 0;
  }

  /* ------------------------------------------------------------------ */
  /*  Entrance — from the anchor edge                                     */
  /* ------------------------------------------------------------------ */

  .vds-toast[data-state="open"] {
    animation: vds-toast-enter-top var(--vds-duration-slow) var(--vds-ease-ios);
  }

  .vds-toaster[data-position^="bottom"] .vds-toast[data-state="open"] {
    animation-name: vds-toast-enter-bottom;
  }

  /* Type-specific entrance flair — only for the newest toast */
  .vds-toast[data-state="open"][data-index="0"][data-type="error"] {
    animation-name: vds-toast-enter-top-shake;
  }
  .vds-toaster[data-position^="bottom"] .vds-toast[data-state="open"][data-index="0"][data-type="error"] {
    animation-name: vds-toast-enter-bottom-shake;
  }

  /* ------------------------------------------------------------------ */
  /*  Exit — back to the anchor edge                                      */
  /* ------------------------------------------------------------------ */

  .vds-toast[data-state="closed"] {
    animation: vds-toast-exit-top var(--vds-duration-normal) var(--vds-ease-in) forwards;
    pointer-events: none;
  }

  .vds-toaster[data-position^="bottom"] .vds-toast[data-state="closed"]:not([data-swipe-exit]) {
    animation-name: vds-toast-exit-bottom;
  }

  /* Swipe exit — fly horizontally (wins over position-based exit) */
  .vds-toast[data-state="closed"][data-swipe-exit="left"] {
    animation: vds-toast-swipe-out-left var(--vds-duration-normal) var(--vds-ease-out) forwards;
  }
  .vds-toast[data-state="closed"][data-swipe-exit="right"] {
    animation: vds-toast-swipe-out-right var(--vds-duration-normal) var(--vds-ease-out) forwards;
  }

  /* While dragging — no transition, snap to pointer */
  .vds-toast[data-dragging] {
    transition: none;
    cursor: grabbing;
    animation: none;
  }

  /* Stacked (behind the newest) */
  .vds-toast--stacked {
    background: var(--toast-surface-stacked);
    border-color: var(--toast-border-color-stacked);
  }

  /* Has actions — taller */
  .vds-toast--has-actions {
    min-block-size: var(--toast-min-height-with-actions);
  }

  /* Hover elevation (only on the top toast, only on hover-capable devices) */
  @media (hover: hover) {
    .vds-toast[data-index="0"]:hover {
      box-shadow: var(--toast-shadow-hover);
    }
  }

  /* When expanded (viewport hovered) — all toasts lift to full visibility */
  .vds-toaster[data-expanded] .vds-toast--stacked {
    background: var(--toast-surface);
    border-color: var(--toast-border-color);
  }

  .vds-toast:active {
    cursor: grabbing;
  }

  .vds-toast:focus-visible {
    outline: var(--toast-focus-ring-width) solid var(--toast-focus-ring-color);
    outline-offset: var(--toast-focus-ring-offset);
  }

  /* ------------------------------------------------------------------ */
  /*  Inner layout                                                        */
  /* ------------------------------------------------------------------ */

  .vds-toast__content {
    display: flex;
    align-items: flex-start;
    gap: var(--toast-content-gap);
    padding-block: var(--toast-padding-block);
    padding-inline: var(--toast-padding-inline);
    position: relative;
  }

  .vds-toast__icon {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--toast-icon-size);
    block-size: var(--toast-icon-size);
    margin-block-start: var(--toast-icon-optical-nudge);
  }

  .vds-toast__icon > svg {
    inline-size: var(--toast-icon-size);
    block-size: var(--toast-icon-size);
  }

  .vds-toast__text {
    flex: 1;
    min-inline-size: 0;
    display: flex;
    flex-direction: column;
    gap: var(--toast-text-gap);
  }

  .vds-toast__title {
    margin: 0;
    font-family: var(--vds-font-sans);
    font-size: var(--vds-text-sm);
    font-weight: var(--vds-font-weight-semibold);
    line-height: var(--vds-leading-snug);
    color: var(--vds-color-text);
    word-break: break-word;
  }

  .vds-toast__description {
    margin: 0;
    font-family: var(--vds-font-sans);
    font-size: var(--vds-text-xs);
    line-height: var(--vds-leading-normal);
    color: var(--vds-color-text-muted);
    word-break: break-word;
  }

  .vds-toast__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--toast-actions-gap);
    margin-block-start: var(--toast-actions-margin-block-start);
  }

  /* ------------------------------------------------------------------ */
  /*  Close button + progress ring                                        */
  /* ------------------------------------------------------------------ */

  .vds-toast__close-container {
    position: relative;
    flex-shrink: 0;
    inline-size: var(--toast-close-size);
    block-size: var(--toast-close-size);
  }

  .vds-toast__close {
    position: absolute;
    inset: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    block-size: 100%;
    background: transparent;
    border: 0;
    border-radius: var(--vds-radius-full);
    color: var(--vds-color-text-subtle);
    cursor: pointer;
    transition:
      background-color var(--vds-duration-fast) var(--vds-ease-out),
      color var(--vds-duration-fast) var(--vds-ease-out),
      transform var(--vds-duration-fast) var(--vds-ease-out);
    z-index: 2;
  }

  .vds-toast__close:hover {
    background-color: var(--vds-color-bg-muted);
    color: var(--vds-color-text);
    transform: scale(1.05);
  }

  .vds-toast__close:active {
    transform: scale(0.92);
  }

  .vds-toast__close:focus-visible {
    outline: var(--toast-focus-ring-width) solid var(--toast-focus-ring-color);
    outline-offset: var(--toast-focus-ring-offset);
  }

  .vds-toast__progress-ring {
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 1;
    color: currentColor;
  }

  .vds-toast__progress-ring-bg {
    stroke: currentColor;
    opacity: var(--toast-progress-track-opacity);
  }

  .vds-toast__progress-ring-progress {
    stroke: currentColor;
    opacity: var(--toast-progress-indicator-opacity);
    transition: stroke-dashoffset var(--vds-duration-fast) linear;
  }

  /* ------------------------------------------------------------------ */
  /*  Action buttons (built-in slots)                                     */
  /* ------------------------------------------------------------------ */

  .vds-toast-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--toast-action-gap);
    min-block-size: var(--toast-action-min-block-size);
    padding-inline: var(--toast-action-padding-inline);
    padding-block: var(--toast-action-padding-block);
    font-family: var(--vds-font-sans);
    font-size: var(--vds-text-xs);
    font-weight: var(--vds-font-weight-medium);
    line-height: 1;
    border: 1px solid transparent;
    border-radius: var(--toast-action-radius);
    background: transparent;
    color: var(--vds-color-text);
    cursor: pointer;
    touch-action: manipulation;
    transition:
      background-color var(--vds-duration-fast) var(--vds-ease-out),
      color var(--vds-duration-fast) var(--vds-ease-out),
      border-color var(--vds-duration-fast) var(--vds-ease-out),
      transform var(--vds-duration-fast) var(--vds-ease-out);
  }

  .vds-toast-action:hover {
    transform: translateY(-1px);
  }
  .vds-toast-action:active {
    transform: translateY(0) scale(0.97);
  }
  .vds-toast-action:focus-visible {
    outline: var(--toast-focus-ring-width) solid var(--toast-focus-ring-color);
    outline-offset: var(--toast-focus-ring-offset);
  }

  .vds-toast-action--primary {
    background: var(--vds-color-primary-solid);
    color: var(--vds-color-on-primary);
    border-color: var(--vds-color-primary-solid);
  }
  .vds-toast-action--primary:hover {
    background: var(--vds-color-primary-solid-hover, var(--vds-color-primary-solid));
  }

  .vds-toast-action--secondary {
    background: var(--vds-color-bg-muted);
    color: var(--vds-color-text);
    border-color: var(--vds-color-border);
  }
  .vds-toast-action--secondary:hover {
    background: var(--vds-color-surface-hover);
  }

  .vds-toast-action--ghost {
    background: transparent;
    color: var(--vds-color-text-muted);
  }
  .vds-toast-action--ghost:hover {
    background: var(--vds-color-bg-muted);
    color: var(--vds-color-text);
  }

  .vds-toast-action--danger {
    background: var(--vds-color-danger-solid);
    color: var(--vds-color-on-danger);
    border-color: var(--vds-color-danger-solid);
  }
  .vds-toast-action--danger:hover {
    background: var(--vds-color-danger-solid-hover, var(--vds-color-danger-solid));
  }

  .vds-toast-action--success {
    background: var(--vds-color-success-solid);
    color: var(--vds-color-on-success);
    border-color: var(--vds-color-success-solid);
  }
  .vds-toast-action--success:hover {
    background: var(--vds-color-success-solid-hover, var(--vds-color-success-solid));
  }

  /* ------------------------------------------------------------------ */
  /*  Type variants                                                       */
  /* ------------------------------------------------------------------ */

  .vds-toast--success {
    border-color: var(--vds-color-success-bg);
  }
  .vds-toast--success .vds-toast__icon {
    color: var(--vds-color-success-solid);
  }

  .vds-toast--error {
    border-color: var(--vds-color-danger-bg);
  }
  .vds-toast--error .vds-toast__icon {
    color: var(--vds-color-danger-solid);
  }

  .vds-toast--warning {
    border-color: var(--vds-color-warning-bg);
  }
  .vds-toast--warning .vds-toast__icon {
    color: var(--vds-color-warning-solid);
  }

  .vds-toast--info {
    border-color: var(--vds-color-info-bg);
  }
  .vds-toast--info .vds-toast__icon {
    color: var(--vds-color-info-solid);
  }

  .vds-toast--loading {
    border-color: var(--vds-color-primary-bg);
  }
  .vds-toast--loading .vds-toast__icon {
    color: var(--vds-color-primary-solid);
  }

  .vds-toast--default .vds-toast__icon {
    color: var(--vds-color-text-muted);
  }

  /* Type-specific progress ring color matches icon */
  .vds-toast--success .vds-toast__progress-ring {
    color: var(--vds-color-success-solid);
  }
  .vds-toast--error .vds-toast__progress-ring {
    color: var(--vds-color-danger-solid);
  }
  .vds-toast--warning .vds-toast__progress-ring {
    color: var(--vds-color-warning-solid);
  }
  .vds-toast--info .vds-toast__progress-ring {
    color: var(--vds-color-info-solid);
  }
  .vds-toast--loading .vds-toast__progress-ring {
    color: var(--vds-color-primary-solid);
  }

  /* ------------------------------------------------------------------ */
  /*  Loading spinner                                                     */
  /* ------------------------------------------------------------------ */

  /* Continuous spin for the loading icon — applies regardless of stack
     position or open/closed state. Matching the specificity of the per-type
     entrance rules below so it isn't overridden on the newest toast. */
  .vds-toast[data-type="loading"] .vds-toast__icon > svg,
  .vds-toast[data-index="0"][data-state="open"][data-type="loading"] .vds-toast__icon > svg {
    animation: vds-toast-spin 1s linear infinite;
  }

  /* ------------------------------------------------------------------ */
  /*  Icon entrance animations (per type, newest toast only)              */
  /* ------------------------------------------------------------------ */

  .vds-toast[data-index="0"][data-state="open"][data-type="success"] .vds-toast__icon > svg,
  .vds-toast[data-index="0"][data-state="open"][data-type="default"] .vds-toast__icon > svg {
    animation: vds-toast-icon-fade var(--vds-duration-normal) var(--vds-ease-out) 40ms both;
  }

  .vds-toast[data-index="0"][data-state="open"][data-type="error"] .vds-toast__icon > svg {
    animation: vds-toast-icon-shake var(--vds-duration-normal) var(--vds-ease-out) 40ms both;
  }

  .vds-toast[data-index="0"][data-state="open"][data-type="warning"] .vds-toast__icon > svg {
    animation: vds-toast-icon-pulse var(--vds-duration-normal) var(--vds-ease-out) 40ms both;
  }

  .vds-toast[data-index="0"][data-state="open"][data-type="info"] .vds-toast__icon > svg {
    animation: vds-toast-icon-slide var(--vds-duration-normal) var(--vds-ease-out) 40ms both;
  }

  :dir(rtl) .vds-toast[data-index="0"][data-state="open"][data-type="info"] .vds-toast__icon > svg {
    animation-name: vds-toast-icon-slide-rtl;
  }

  /* ------------------------------------------------------------------ */
  /*  Keyframes                                                           */
  /* ------------------------------------------------------------------ */

  @keyframes vds-toast-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
  }

  @keyframes vds-toast-enter-top {
    from {
      transform: translate3d(0, calc(-1 * var(--toast-enter-distance)), 0) scale(0.94);
      opacity: 0;
    }
    to {
      transform:
        translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
        scale(var(--vds-toast-scale, 1));
      opacity: var(--vds-toast-opacity, 1);
    }
  }

  @keyframes vds-toast-enter-bottom {
    from {
      transform: translate3d(0, var(--toast-enter-distance), 0) scale(0.94);
      opacity: 0;
    }
    to {
      transform:
        translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
        scale(var(--vds-toast-scale, 1));
      opacity: var(--vds-toast-opacity, 1);
    }
  }

  @keyframes vds-toast-enter-top-shake {
    0% {
      transform: translate3d(0, calc(-1 * var(--toast-enter-distance)), 0) scale(0.94);
      opacity: 0;
    }
    55% {
      transform: translate3d(-3px, var(--vds-toast-y, 0px), 0) scale(var(--vds-toast-scale, 1));
      opacity: 1;
    }
    100% {
      transform:
        translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
        scale(var(--vds-toast-scale, 1));
      opacity: var(--vds-toast-opacity, 1);
    }
  }

  @keyframes vds-toast-enter-bottom-shake {
    0% {
      transform: translate3d(0, var(--toast-enter-distance), 0) scale(0.94);
      opacity: 0;
    }
    55% {
      transform: translate3d(-3px, var(--vds-toast-y, 0px), 0) scale(var(--vds-toast-scale, 1));
      opacity: 1;
    }
    100% {
      transform:
        translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
        scale(var(--vds-toast-scale, 1));
      opacity: var(--vds-toast-opacity, 1);
    }
  }

  @keyframes vds-toast-exit-top {
    from {
      transform: translate3d(0, var(--vds-toast-y, 0px), 0) scale(var(--vds-toast-scale, 1));
      opacity: var(--vds-toast-opacity, 1);
    }
    to {
      transform:
        translate3d(0, calc(var(--vds-toast-y, 0px) - var(--toast-exit-distance)), 0)
        scale(0.92);
      opacity: 0;
    }
  }

  @keyframes vds-toast-exit-bottom {
    from {
      transform: translate3d(0, var(--vds-toast-y, 0px), 0) scale(var(--vds-toast-scale, 1));
      opacity: var(--vds-toast-opacity, 1);
    }
    to {
      transform:
        translate3d(0, calc(var(--vds-toast-y, 0px) + var(--toast-exit-distance)), 0)
        scale(0.92);
      opacity: 0;
    }
  }

  @keyframes vds-toast-swipe-out-left {
    from {
      transform:
        translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
        scale(var(--vds-toast-scale, 1));
      opacity: 1;
    }
    to {
      transform:
        translate3d(-120%, var(--vds-toast-y, 0px), 0)
        scale(0.9);
      opacity: 0;
    }
  }

  @keyframes vds-toast-swipe-out-right {
    from {
      transform:
        translate3d(var(--vds-toast-drag-x, 0px), var(--vds-toast-y, 0px), 0)
        scale(var(--vds-toast-scale, 1));
      opacity: 1;
    }
    to {
      transform:
        translate3d(120%, var(--vds-toast-y, 0px), 0)
        scale(0.9);
      opacity: 0;
    }
  }

  @keyframes vds-toast-icon-fade {
    from { transform: scale(0.9); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
  }

  @keyframes vds-toast-icon-shake {
    0%, 100% { transform: translateX(0); }
    25% { transform: translateX(-1.5px); }
    75% { transform: translateX(1.5px); }
  }

  @keyframes vds-toast-icon-pulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.12); opacity: 0.9; }
  }

  @keyframes vds-toast-icon-slide {
    from { transform: translateX(-5px) scale(0.95); opacity: 0; }
    to { transform: translateX(0) scale(1); opacity: 1; }
  }

  @keyframes vds-toast-icon-slide-rtl {
    from { transform: translateX(5px) scale(0.95); opacity: 0; }
    to { transform: translateX(0) scale(1); opacity: 1; }
  }

  /* ------------------------------------------------------------------ */
  /*  Responsive — tablet / small-screen                                  */
  /* ------------------------------------------------------------------ */

  @media (max-width: 48rem) {
    .vds-toaster {
      inline-size: auto;
      inset-inline: calc(var(--toast-offset-inline) + env(safe-area-inset-left, 0px))
        calc(var(--toast-offset-inline) + env(safe-area-inset-right, 0px));
    }

    /* Center positions stretch to full width on mobile */
    .vds-toaster--top-center,
    .vds-toaster--bottom-center {
      inset-inline-start: 0;
      inset-inline-end: 0;
      padding-inline: var(--toast-offset-inline);
      transform: none;
    }
  }

  /* ------------------------------------------------------------------ */
  /*  Responsive — phone                                                  */
  /* ------------------------------------------------------------------ */

  @media (max-width: 30rem) {
    .vds-toast__title {
      font-size: var(--vds-text-sm);
      line-height: var(--vds-leading-tight);
    }

    .vds-toast__description {
      font-size: var(--vds-text-xs);
      line-height: var(--vds-leading-snug);
    }

    /* Larger tap targets for actions + stack them vertically */
    .vds-toast__actions {
      flex-direction: column;
      align-items: stretch;
    }

    .vds-toast-action {
      inline-size: 100%;
      font-size: var(--vds-text-xs);
    }

    /* No hover-to-expand on small screens — let the stack auto-expand when
       there's more than one toast so users can read everything without hover. */
    .vds-toaster:not([data-expanded]) .vds-toast--stacked {
      background: var(--toast-surface);
      border-color: var(--toast-border-color);
    }
  }

  /* Touch devices — disable hover pointer blocking */
  @media (hover: none) {
    .vds-toaster:hover {
      pointer-events: none;
    }
  }

  /* Reduced motion */
  @media (prefers-reduced-motion: reduce) {
    .vds-toast,
    .vds-toast[data-state],
    .vds-toast[data-swipe-exit],
    .vds-toast__icon > svg,
    .vds-toast__progress-ring-progress {
      animation-duration: 1ms !important;
      animation-delay: 0ms !important;
      transition-duration: 1ms !important;
    }
  }
}

