@layer design-system.components {
  /* ─────────────────────────────────────────────
   * 1. Base component tokens
   *    Semantic → component mapping with fallbacks
   *    so the package works standalone if dropped
   *    into a project without @virtari-packages/tokens.
   *
   *    Backward compatibility: the older public knobs
   *    (`--vds-toast-width`, `--vds-toast-offset-*`,
   *    `--vds-toast-radius`, …) are still honoured —
   *    each `--toast-*` local reads them first and only
   *    then falls back to the design-system default.
   *
   *    `--vds-toast-y`, `-scale`, `-opacity` and
   *    `-drag-x` are NOT theming tokens: ToastItem.tsx
   *    writes them per frame. They stay untouched.
   * ───────────────────────────────────────────── */
  .vds-toaster {
    /* Viewport geometry */
    --toast-width: var(--vds-toast-width, 26.25rem);
    --toast-viewport-margin: var(--vds-space-8, 2rem);
    --toast-offset-inline: var(--vds-toast-offset-inline, var(--vds-space-6, 1.5rem));
    --toast-offset-block: var(--vds-toast-offset-block, var(--vds-space-6, 1.5rem));
    /* Stack gap between toasts. Retained as a public knob; the resting
       offsets themselves are computed in Toaster.tsx from measured heights. */
    --toast-gap: var(--vds-toast-gap, var(--vds-space-4, 1rem));

    /* Surface */
    --toast-min-height: var(--vds-toast-min-height, 4rem);
    --toast-min-height-with-actions: 5rem;
    --toast-surface: var(--vds-overlay-bg, var(--vds-color-surface, #ffffff));
    --toast-border-width: 1px;
    --toast-border-color: var(--vds-surface-border, var(--vds-color-border-muted, #e5e7eb));
    --toast-border-color-stacked: var(--vds-color-border, #d1d5db);
    --toast-surface-stacked: color-mix(
      in oklch,
      var(--toast-surface) 96%,
      var(--vds-color-bg-muted, #f3f4f6)
    );
    --toast-radius-base: var(--vds-toast-radius, var(--vds-radius-toast, 0.75rem));
    /* Phones sit the toast much closer to the viewport edge, so the corner is
       tightened one notch to stay optically matched to the reduced padding.
       Derived from `-base`, never from `--toast-radius` itself, or the phone
       override below would form a custom-property cycle. max() guards a
       themed radius of 0. */
    --toast-radius-compact: var(
      --vds-radius-toast-compact,
      max(0px, calc(var(--toast-radius-base) - 2px))
    );
    --toast-radius: var(--toast-radius-base);
    --toast-shadow: var(--vds-overlay-shadow, var(
      --vds-toast-shadow,
      0 10px 38px -10px color-mix(in oklch, black 28%, transparent),
      0 10px 20px -15px color-mix(in oklch, black 18%, transparent)
    ));
    --toast-shadow-hover: var(--vds-overlay-shadow, var(
      --vds-toast-shadow-hover,
      0 10px 38px -10px color-mix(in oklch, black 28%, transparent),
      0 10px 20px -15px color-mix(in oklch, black 18%, transparent),
      0 8px 30px -8px color-mix(in oklch, black 30%, transparent)
    ));

    /* Interior layout */
    --toast-padding-inline: var(--vds-space-5, 1.25rem);
    --toast-padding-block: var(--vds-space-4, 1rem);
    --toast-content-gap: var(--vds-cluster-gap, var(--vds-space-3, 0.75rem));
    --toast-text-gap: var(--vds-label-gap, var(--vds-space-1, 0.25rem));
    --toast-icon-size: 1.25rem;
    --toast-icon-optical-nudge: 1px;
    --toast-close-size: var(--vds-size-2xs, 1.5rem);
    --toast-actions-gap: var(--vds-cluster-gap, var(--vds-space-2, 0.5rem));
    --toast-actions-margin-block-start: var(--vds-cluster-gap, var(--vds-space-2, 0.5rem));

    /* Action buttons */
    --toast-action-gap: var(--vds-space-1-5, 0.375rem);
    --toast-action-padding-inline: var(--vds-space-3, 0.75rem);
    --toast-action-padding-block: var(--vds-space-1, 0.25rem);
    --toast-action-min-block-size: 1.75rem;
    --toast-action-radius: var(--vds-radius-toast-action, var(--vds-radius-element, 0.5rem));

    /* Progress ring */
    --toast-progress-track-opacity: 0.2;
    --toast-progress-indicator-opacity: 0.75;

    /* Focus ring — one shared width/offset across the design system */
    --toast-focus-ring-width: var(--vds-focus-ring-width, 2px);
    --toast-focus-ring-offset: var(--vds-focus-ring-offset, 2px);
    --toast-focus-ring-color: var(--vds-color-ring, #6366f1);

    /* Motion */
    --toast-ease: var(--vds-toast-ease, var(--vds-ease-ios, cubic-bezier(0.32, 0.72, 0, 1)));
    --toast-duration: var(--vds-toast-duration, var(--vds-duration-slower, 400ms));
    --toast-enter-distance: var(--vds-toast-enter-distance, 32px);
    --toast-exit-distance: var(--vds-toast-exit-distance, 48px);
  }

  /* ─────────────────────────────────────────────
   * 2. Responsive — tablet / small screen
   * ───────────────────────────────────────────── */
  @media (max-width: 48rem) {
    .vds-toaster {
      --toast-width: 100%;
      --toast-offset-inline: var(--vds-space-4, 1rem);
      --toast-offset-block: var(--vds-space-4, 1rem);
    }
  }

  /* ─────────────────────────────────────────────
   * 3. Responsive — phone
   * ───────────────────────────────────────────── */
  @media (max-width: 30rem) {
    .vds-toaster {
      --toast-offset-inline: var(--vds-space-3, 0.75rem);
      --toast-offset-block: var(--vds-space-3, 0.75rem);
      --toast-enter-distance: 24px;
      --toast-exit-distance: 36px;

      --toast-radius: var(--toast-radius-compact);
      --toast-min-height: 3.5rem;
      --toast-min-height-with-actions: auto;
      --toast-padding-inline: var(--vds-space-3-5, 0.875rem);
      --toast-padding-block: var(--vds-space-3, 0.75rem);
      --toast-content-gap: var(--vds-space-2-5, 0.625rem);
      --toast-icon-size: 1rem;
      --toast-close-size: 1.25rem;
      --toast-actions-gap: var(--vds-space-1-5, 0.375rem);
      --toast-actions-margin-block-start: var(--vds-space-2-5, 0.625rem);
      --toast-action-min-block-size: 2.25rem;
    }
  }
}

packages/react-toast/src/toast.ts:
import type { ReactNode } from "react";
import { createToastId, toastStore } from "./store";
import type {
  ToastActionConfig,
  ToastActions,
  ToastOptions,
} from "./types";

type BaseOpts = Omit<ToastOptions, "type" | "title" | "description">;

function emit(opts: ToastOptions): string {
  return toastStore.add(opts);
}

export interface ToastPromiseMessages<T> {
  loading: ReactNode;
  success: ReactNode | ((data: T) => ReactNode);
  error: ReactNode | ((error: unknown) => ReactNode);
  description?: ReactNode;
  successDescription?: ReactNode | ((data: T) => ReactNode);
  errorDescription?: ReactNode | ((error: unknown) => ReactNode);
}

export interface ToastConfirmOptions
  extends Omit<ToastOptions, "title" | "description" | "actions"> {
  confirmLabel?: ReactNode;
  cancelLabel?: ReactNode;
  confirmVariant?: ToastActionConfig["variant"];
  cancelVariant?: ToastActionConfig["variant"];
}

export interface ToastUndoOptions
  extends Omit<ToastOptions, "title" | "description" | "actions"> {
  undoLabel?: ReactNode;
}

function resolveMessage<T>(
  value: ReactNode | ((data: T) => ReactNode),
  data: T,
): ReactNode {
  return typeof value === "function"
    ? (value as (d: T) => ReactNode)(data)
    : value;
}

export const toast = Object.assign(
  (opts: ToastOptions) => emit(opts),
  {
    success(
      title: ReactNode,
      description?: ReactNode,
      opts?: BaseOpts,
    ): string {
      return emit({ ...opts, type: "success", title, description });
    },

    error(title: ReactNode, description?: ReactNode, opts?: BaseOpts): string {
      return emit({ ...opts, type: "error", title, description });
    },

    warning(
      title: ReactNode,
      description?: ReactNode,
      opts?: BaseOpts,
    ): string {
      return emit({ ...opts, type: "warning", title, description });
    },

    info(title: ReactNode, description?: ReactNode, opts?: BaseOpts): string {
      return emit({ ...opts, type: "info", title, description });
    },

    loading(
      title: ReactNode,
      description?: ReactNode,
      opts?: BaseOpts,
    ): string {
      return emit({
        ...opts,
        type: "loading",
        title,
        description,
        duration: opts?.duration ?? 0,
      });
    },

    message(
      title: ReactNode,
      description?: ReactNode,
      opts?: BaseOpts,
    ): string {
      return emit({ ...opts, type: "default", title, description });
    },

    dismiss(id?: string): void {
      if (id) toastStore.remove(id);
      else toastStore.removeAll();
    },

    promise<T>(
      promise: Promise<T> | (() => Promise<T>),
      messages: ToastPromiseMessages<T>,
      opts?: Omit<ToastOptions, "type" | "title" | "description">,
    ): Promise<T> {
      const id = emit({
        ...opts,
        type: "loading",
        title: messages.loading,
        description: messages.description,
        duration: 0,
      });
      const p = typeof promise === "function" ? promise() : promise;
      return p.then(
        (data) => {
          toastStore.update(id, {
            type: "success",
            title: resolveMessage(messages.success, data),
            description:
              messages.successDescription !== undefined
                ? resolveMessage(messages.successDescription, data)
                : undefined,
          });
          return data;
        },
        (err) => {
          toastStore.update(id, {
            type: "error",
            title: resolveMessage(messages.error, err),
            description:
              messages.errorDescription !== undefined
                ? resolveMessage(messages.errorDescription, err)
                : undefined,
          });
          throw err;
        },
      );
    },

    withAction(
      title: ReactNode,
      description: ReactNode | undefined,
      action: ToastActionConfig,
      opts?: Omit<ToastOptions, "title" | "description" | "action">,
    ): string {
      return emit({ ...opts, title, description, action });
    },

    withActions(
      title: ReactNode,
      description: ReactNode | undefined,
      actions: ToastActions,
      opts?: Omit<ToastOptions, "title" | "description" | "actions">,
    ): string {
      return emit({ ...opts, title, description, actions });
    },

    undo(
      title: ReactNode,
      description: ReactNode,
      onUndo: () => void,
      opts?: ToastUndoOptions,
    ): string {
      const id = createToastId();
      const undoLabel = opts?.undoLabel ?? "Undo";
      emit({
        type: "success",
        duration: 5000,
        ...opts,
        id,
        title,
        description,
        actions: {
          primary: {
            label: undoLabel,
            variant: "ghost",
            onClick: () => {
              onUndo();
              toastStore.remove(id);
            },
          },
        },
      });
      return id;
    },

    confirm(
      title: ReactNode,
      description: ReactNode,
      onConfirm: () => void,
      onCancel?: () => void,
      opts?: ToastConfirmOptions,
    ): string {
      const id = createToastId();
      const confirmLabel = opts?.confirmLabel ?? "Confirm";
      const cancelLabel = opts?.cancelLabel ?? "Cancel";
      emit({
        type: "warning",
        ...opts,
        id,
        title,
        description,
        duration: 0,
        actions: {
          primary: {
            label: confirmLabel,
            variant: opts?.confirmVariant ?? "primary",
            onClick: () => {
              onConfirm();
              toastStore.remove(id);
            },
          },
          secondary: {
            label: cancelLabel,
            variant: opts?.cancelVariant ?? "ghost",
            onClick: () => {
              onCancel?.();
              toastStore.remove(id);
            },
          },
        },
      });
      return id;
    },
  },
);

