@layer design-system.components {
  /* ── Root tree ── */
  .vds-tree-view,
  .vds-tree-view-group {
    list-style: none;
    margin: 0;
    padding: 0;
  }

  /* ── Item ── */
  .vds-tree-view-item {
    user-select: none;
  }

  /* ── Row (the clickable/focusable row) ── */
  .vds-tree-view-row {
    display: flex;
    align-items: center;
    gap: var(--vds-space-1-5, 0.375rem);
    block-size: var(--tree-item-height);
    padding-inline-end: var(--vds-space-2, 0.5rem);
    border-radius: var(--tree-item-radius);
    color: var(--tree-item-color);
    cursor: pointer;
    outline: none;
    transition:
      background-color var(--tree-transition),
      color var(--tree-transition);
  }

  .vds-tree-view-row:hover {
    background-color: var(--tree-item-bg-hover);
  }

  .vds-tree-view-row:active {
    background-color: var(--tree-item-bg-active);
  }

  .vds-tree-view-row:focus-visible {
    outline: var(--tree-focus-ring-width) solid var(--tree-focus-ring-color);
    outline-offset: var(--tree-focus-ring-offset);
  }

  /* ── Selected ── */
  .vds-tree-view-item[aria-selected="true"] > .vds-tree-view-row {
    background-color: var(--tree-selected-bg);
    color: var(--tree-selected-color);
  }

  .vds-tree-view-item[aria-selected="true"] > .vds-tree-view-row:hover {
    background-color: var(--tree-selected-bg-hover);
  }

  /* ── Disabled ── */
  .vds-tree-view-item[aria-disabled="true"] > .vds-tree-view-row {
    opacity: var(--vds-opacity-disabled, 0.5);
    cursor: not-allowed;
    pointer-events: none;
  }

  /* ── Toggle (expand/collapse chevron) ── */
  .vds-tree-view-toggle,
  .vds-tree-view-toggle-placeholder {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    inline-size: var(--tree-toggle-size);
    block-size: var(--tree-toggle-size);
    color: var(--tree-toggle-color);
  }

  .vds-tree-view-toggle > svg {
    inline-size: 100%;
    block-size: 100%;
    transition: rotate var(--tree-toggle-transition);
  }

  .vds-tree-view-toggle[data-expanded] > svg {
    rotate: 90deg;
  }

  :dir(rtl) .vds-tree-view-toggle > svg {
    rotate: 180deg;
  }

  :dir(rtl) .vds-tree-view-toggle[data-expanded] > svg {
    rotate: 90deg;
  }

  /* ── Icon ── */
  .vds-tree-view-icon {
    display: inline-flex;
    align-items: center;
    flex-shrink: 0;
    inline-size: var(--tree-icon-size);
    block-size: var(--tree-icon-size);
    color: var(--tree-item-color-muted);
  }

  .vds-tree-view-icon > svg {
    inline-size: 100%;
    block-size: 100%;
  }

  /* ── Label ── */
  .vds-tree-view-label {
    flex: 1;
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: var(--tree-label-size);
    font-weight: var(--tree-label-weight);
    line-height: var(--vds-leading-snug, 1.375);
  }
}

