import { useEffect, useMemo, useRef, useState } from "react";
import { useYooptaEditor, Blocks } from "@yoopta/editor";
import {
  Popover,
  PopoverAnchor,
  PopoverContent,
} from "@virtari-packages/react-popover";
import { getPluginDisplay, getPluginIcon } from "./pluginIcons";

export type ActionMenuMode = { kind: "turnInto" } | { kind: "insert"; at: number };

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  anchor: HTMLElement | null;
  placement?:
    | "top"
    | "top-start"
    | "top-end"
    | "right"
    | "right-start"
    | "right-end"
    | "bottom"
    | "bottom-start"
    | "bottom-end"
    | "left"
    | "left-start"
    | "left-end";
  mode?: ActionMenuMode;
};

function splitPlacement(p: Props["placement"]) {
  if (!p) return { side: "bottom" as const, align: "start" as const };
  const [side, align] = p.split("-") as [
    "top" | "right" | "bottom" | "left",
    "start" | "end" | undefined,
  ];
  return { side, align: (align ?? "center") as "start" | "center" | "end" };
}

export function ActionMenu({
  open,
  onOpenChange,
  anchor,
  placement = "bottom-start",
  mode = { kind: "turnInto" },
}: Props) {
  const editor = useYooptaEditor();
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  const virtualRef = useMemo(
    () => ({
      current: {
        getBoundingClientRect: () =>
          anchor?.getBoundingClientRect() ?? new DOMRect(0, 0, 0, 0),
      },
    }),
    [anchor],
  );

  const items = useMemo(() => {
    const plugins = Object.values(editor.plugins).filter(
      (p) => p && p.type !== "Mention",
    );
    const q = query.trim().toLowerCase();
    const list = plugins.map((p) => {
      const display = getPluginDisplay(p);
      return { type: p.type, ...display };
    });
    if (!q) return list;
    return list.filter(
      (it) =>
        it.title.toLowerCase().includes(q) ||
        it.type.toLowerCase().includes(q),
    );
  }, [editor.plugins, query]);

  useEffect(() => {
    if (open) {
      setQuery("");
      setActiveIndex(0);
      const t = setTimeout(() => inputRef.current?.focus(), 0);
      return () => clearTimeout(t);
    }
    return;
  }, [open]);

  useEffect(() => {
    if (!listRef.current) return;
    const el = listRef.current.querySelector<HTMLElement>(
      `[data-action-index="${activeIndex}"]`,
    );
    el?.scrollIntoView({ block: "nearest" });
  }, [activeIndex]);

  const apply = (type: string) => {
    if (mode.kind === "insert") {
      editor.insertBlock(type, { at: mode.at, focus: true });
    } else {
      const currentOrder = editor.path.current;
      if (currentOrder === null) return;
      const blockId = Object.keys(editor.children).find(
        (id) => editor.children[id]?.meta.order === currentOrder,
      );
      if (!blockId) return;
      const block = Blocks.getBlock(editor, { id: blockId });
      if (!block) return;
      editor.toggleBlock(type, { focus: true });
    }
    onOpenChange(false);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(i + 1, items.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const item = items[activeIndex];
      if (item) apply(item.type);
    } else if (e.key === "Escape") {
      e.preventDefault();
      onOpenChange(false);
    }
  };

  const { side, align } = splitPlacement(placement);

  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverAnchor virtualRef={virtualRef as never} />
      <PopoverContent
        side={side}
        align={align}
        sideOffset={6}
        className="vds-yoo-action-menu"
        onOpenAutoFocus={(e) => e.preventDefault()}
        onCloseAutoFocus={(e) => e.preventDefault()}
      >
        <div className="vds-yoo-action-menu-search">
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setActiveIndex(0);
            }}
            onKeyDown={onKeyDown}
            placeholder={mode.kind === "insert" ? "Insert block" : "Turn into"}
            className="vds-yoo-action-menu-input"
          />
        </div>
        <div ref={listRef} className="vds-yoo-action-menu-list" role="listbox">
          {items.length === 0 ? (
            <div className="vds-yoo-action-menu-empty">No blocks</div>
          ) : (
            items.map((it, i) => (
              <button
                key={it.type}
                type="button"
                role="option"
                aria-selected={i === activeIndex}
                data-action-index={i}
                data-active={i === activeIndex ? "" : undefined}
                onMouseEnter={() => setActiveIndex(i)}
                onClick={() => apply(it.type)}
                className="vds-yoo-action-menu-item"
              >
                <span className="vds-yoo-action-menu-item-icon">
                  {getPluginIcon(it.type, 18)}
                </span>
                <span className="vds-yoo-action-menu-item-text">
                  <span className="vds-yoo-action-menu-item-title">
                    {it.title}
                  </span>
                  {it.description && (
                    <span className="vds-yoo-action-menu-item-desc">
                      {it.description}
                    </span>
                  )}
                </span>
              </button>
            ))
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useYooptaEditor, Blocks } from "@yoopta/editor";
import { IconGripVertical, IconPlus } from "@virtari-packages/react-icons";

import { ActionMenu } from "./ActionMenu";
import { BlockOptions } from "./BlockOptions";

type Hover = {
  blockId: string;
  rect: DOMRect;
};

const HIDE_DELAY = 220;

export function BlockActions() {
  const editor = useYooptaEditor();
  const [hover, setHover] = useState<Hover | null>(null);
  const [insertOpen, setInsertOpen] = useState(false);
  const [insertAt, setInsertAt] = useState<number | null>(null);
  const [optionsOpen, setOptionsOpen] = useState(false);
  const [optionsBlockId, setOptionsBlockId] = useState<string | null>(null);

  const plusRef = useRef<HTMLButtonElement>(null);
  const gripRef = useRef<HTMLButtonElement>(null);
  const hideTimer = useRef<number | null>(null);
  const dragTargetRef = useRef<{ id: string; before: boolean } | null>(null);

  const frozen = insertOpen || optionsOpen;

  const findBlockUnder = useCallback((x: number, y: number) => {
    const root = editor.refElement;
    if (!root) return null;
    const blocks = root.querySelectorAll<HTMLElement>("[data-yoopta-block-id]");
    for (const el of blocks) {
      const r = el.getBoundingClientRect();
      if (y >= r.top && y <= r.bottom && x >= r.left - 80 && x <= r.right + 80) {
        const id = el.getAttribute("data-yoopta-block-id");
        if (id) return { id, rect: r };
      }
    }
    return null;
  }, [editor]);

  useEffect(() => {
    const root = editor.refElement;
    if (!root) return;

    const onMouseMove = (e: MouseEvent) => {
      if (frozen) return;
      const found = findBlockUnder(e.clientX, e.clientY);
      if (found) {
        if (hideTimer.current !== null) {
          window.clearTimeout(hideTimer.current);
          hideTimer.current = null;
        }
        setHover({ blockId: found.id, rect: found.rect });
      }
    };
    const onMouseLeave = () => {
      if (frozen) return;
      if (hideTimer.current !== null) window.clearTimeout(hideTimer.current);
      hideTimer.current = window.setTimeout(() => setHover(null), HIDE_DELAY);
    };

    root.addEventListener("mousemove", onMouseMove);
    root.addEventListener("mouseleave", onMouseLeave);
    return () => {
      root.removeEventListener("mousemove", onMouseMove);
      root.removeEventListener("mouseleave", onMouseLeave);
      if (hideTimer.current !== null) window.clearTimeout(hideTimer.current);
    };
  }, [editor, findBlockUnder, frozen]);

  useEffect(() => {
    if (!hover) return;
    const update = () => {
      const el = editor.refElement?.querySelector<HTMLElement>(
        `[data-yoopta-block-id="${hover.blockId}"]`,
      );
      if (!el) return;
      setHover({ blockId: hover.blockId, rect: el.getBoundingClientRect() });
    };
    window.addEventListener("scroll", update, true);
    window.addEventListener("resize", update);
    return () => {
      window.removeEventListener("scroll", update, true);
      window.removeEventListener("resize", update);
    };
  }, [hover, editor]);

  const onPlusClick = () => {
    if (!hover) return;
    const block = Blocks.getBlock(editor, { id: hover.blockId });
    if (!block) return;
    setInsertAt(block.meta.order + 1);
    setInsertOpen(true);
  };

  const onGripClick = () => {
    if (!hover) return;
    const block = Blocks.getBlock(editor, { id: hover.blockId });
    if (!block) return;
    editor.setPath({ current: block.meta.order });
    setOptionsBlockId(hover.blockId);
    setOptionsOpen(true);
  };

  const onDragStart = (e: React.DragEvent) => {
    if (!hover) return;
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/x-yoopta-block-id", hover.blockId);
    const el = editor.refElement?.querySelector<HTMLElement>(
      `[data-yoopta-block-id="${hover.blockId}"]`,
    );
    if (el) e.dataTransfer.setDragImage(el, 0, 0);
  };

  useEffect(() => {
    const root = editor.refElement;
    if (!root) return;

    const onDragOver = (e: DragEvent) => {
      if (!e.dataTransfer?.types.includes("text/x-yoopta-block-id")) return;
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      const found = findBlockUnder(e.clientX, e.clientY);
      if (!found) {
        dragTargetRef.current = null;
        return;
      }
      const before = e.clientY < found.rect.top + found.rect.height / 2;
      dragTargetRef.current = { id: found.id, before };
    };

    const onDrop = (e: DragEvent) => {
      const sourceId = e.dataTransfer?.getData("text/x-yoopta-block-id");
      if (!sourceId) return;
      e.preventDefault();
      const target = dragTargetRef.current;
      dragTargetRef.current = null;
      if (!target || target.id === sourceId) return;
      const targetBlock = Blocks.getBlock(editor, { id: target.id });
      if (!targetBlock) return;
      const sourceBlock = Blocks.getBlock(editor, { id: sourceId });
      if (!sourceBlock) return;
      const targetOrder = target.before
        ? targetBlock.meta.order
        : targetBlock.meta.order + 1;
      const adjusted =
        sourceBlock.meta.order < targetOrder ? targetOrder - 1 : targetOrder;
      editor.moveBlock(sourceId, adjusted);
    };

    root.addEventListener("dragover", onDragOver);
    root.addEventListener("drop", onDrop);
    return () => {
      root.removeEventListener("dragover", onDragOver);
      root.removeEventListener("drop", onDrop);
    };
  }, [editor, findBlockUnder]);

  if (typeof document === "undefined") return null;

  return (
    <>
      {hover &&
        createPortal(
          <div
            className="vds-yoo-block-actions"
            style={{
              position: "fixed",
              top: hover.rect.top + 2,
              left: hover.rect.left - 64,
            }}
            data-frozen={frozen ? "" : undefined}
            onMouseEnter={() => {
              if (hideTimer.current !== null) {
                window.clearTimeout(hideTimer.current);
                hideTimer.current = null;
              }
            }}
          >
            <button
              ref={plusRef}
              type="button"
              className="vds-yoo-block-actions-button"
              onClick={onPlusClick}
              title="Add block below"
              aria-label="Add block below"
            >
              <IconPlus size={14} />
            </button>
            <button
              ref={gripRef}
              type="button"
              className="vds-yoo-block-actions-button"
              draggable
              onDragStart={onDragStart}
              onClick={onGripClick}
              title="Drag to reorder, click to open options"
              aria-label="Block options"
            >
              <IconGripVertical size={14} />
            </button>
          </div>,
          document.body,
        )}

      <ActionMenu
        open={insertOpen}
        onOpenChange={(o) => {
          setInsertOpen(o);
          if (!o) setInsertAt(null);
        }}
        anchor={plusRef.current}
        placement="right-start"
        mode={insertAt !== null ? { kind: "insert", at: insertAt } : undefined}
      />

      <BlockOptions
        open={optionsOpen}
        onOpenChange={(o) => {
          setOptionsOpen(o);
          if (!o) setOptionsBlockId(null);
        }}
        blockId={optionsBlockId}
        anchor={gripRef.current}
      />
    </>
  );
}

import { useMemo, useRef, useState } from "react";
import { useYooptaEditor } from "@yoopta/editor";
import {
  Popover,
  PopoverAnchor,
  PopoverContent,
} from "@virtari-packages/react-popover";
import {
  IconCopy,
  IconLink,
  IconTrash,
  IconRepeat,
} from "@virtari-packages/react-icons";

import { ActionMenu } from "./ActionMenu";

type Props = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  blockId: string | null;
  anchor?: HTMLElement | null;
};

export function BlockOptions({ open, onOpenChange, blockId, anchor }: Props) {
  const editor = useYooptaEditor();
  const turnIntoRef = useRef<HTMLButtonElement>(null);
  const [actionMenuOpen, setActionMenuOpen] = useState(false);

  const virtualRef = useMemo(
    () => ({
      current: {
        getBoundingClientRect: () =>
          anchor?.getBoundingClientRect() ?? new DOMRect(0, 0, 0, 0),
      },
    }),
    [anchor],
  );

  const onDuplicate = () => {
    if (!blockId) return;
    editor.duplicateBlock({ blockId, focus: true });
    onOpenChange(false);
  };

  const onCopyLink = () => {
    if (!blockId) return;
    if (typeof window !== "undefined" && navigator?.clipboard) {
      const base = window.location.href.split("#")[0];
      navigator.clipboard.writeText(`${base}#${blockId}`).catch(() => {});
    }
    onOpenChange(false);
  };

  const onDelete = () => {
    if (!blockId) return;
    editor.deleteBlock({ blockId });
    onOpenChange(false);
  };

  const onTurnInto = () => {
    setActionMenuOpen(true);
  };

  return (
    <>
      <Popover open={open && !actionMenuOpen} onOpenChange={onOpenChange}>
        <PopoverAnchor virtualRef={virtualRef as never} />
        <PopoverContent
          side="right"
          align="end"
          sideOffset={8}
          className="vds-yoo-block-options"
          onOpenAutoFocus={(e) => e.preventDefault()}
        >
          <div className="vds-yoo-block-options-group">
            <button
              ref={turnIntoRef}
              type="button"
              onClick={onTurnInto}
              className="vds-yoo-block-options-item"
            >
              <IconRepeat size={16} />
              <span>Turn into</span>
            </button>
          </div>
          <div className="vds-yoo-block-options-separator" />
          <div className="vds-yoo-block-options-group">
            <button
              type="button"
              onClick={onDuplicate}
              className="vds-yoo-block-options-item"
            >
              <IconCopy size={16} />
              <span>Duplicate</span>
            </button>
            <button
              type="button"
              onClick={onCopyLink}
              className="vds-yoo-block-options-item"
            >
              <IconLink size={16} />
              <span>Copy link to block</span>
            </button>
            <button
              type="button"
              onClick={onDelete}
              data-variant="danger"
              className="vds-yoo-block-options-item"
            >
              <IconTrash size={16} />
              <span>Delete</span>
            </button>
          </div>
        </PopoverContent>
      </Popover>

      <ActionMenu
        open={actionMenuOpen}
        onOpenChange={(o) => {
          setActionMenuOpen(o);
          if (!o) onOpenChange(false);
        }}
        anchor={turnIntoRef.current}
        placement="right-start"
        mode={{ kind: "turnInto" }}
      />
    </>
  );
}

