import { useCallback, useState } from "react";
import { useYooptaEditor } from "@yoopta/editor";
import { useFileUpload, formatFileSize } from "@yoopta/file";
import type { PluginElementRenderProps } from "@yoopta/editor";
import { FileUpload } from "@virtari-packages/react-file-upload";
import { IconPaperclip, IconLoader2, IconAlertCircle, IconDownload } from "@virtari-packages/react-icons";
import { fileUpload } from "../uploads";

type FileProps = {
  src?: string | null;
  name?: string | null;
  size?: number | null;
  format?: string | null;
};

export function FileElement(renderProps: PluginElementRenderProps) {
  const { element, blockId, attributes, children } = renderProps;
  const editor = useYooptaEditor();
  const upload = useFileUpload(fileUpload as never);
  const [uploadError, setUploadError] = useState<string | null>(null);

  const props = (element.props ?? {}) as FileProps;
  const hasSrc = typeof props.src === "string" && props.src.length > 0;

  const onFilesChange = useCallback(
    async (files: File[]) => {
      const file = files[0];
      if (!file) return;
      setUploadError(null);
      try {
        const result = await upload.upload(file);
        editor.updateElement({
          blockId,
          type: "file",
          props: {
            src: result.src,
            name: result.name ?? file.name,
            size: result.size ?? file.size,
            format: result.format ?? file.name.split(".").pop() ?? "",
          },
        });
      } catch (err) {
        setUploadError(err instanceof Error ? err.message : "Upload failed");
      }
    },
    [upload, editor, blockId],
  );

  if (!hasSrc) {
    return (
      <div {...attributes} contentEditable={false} className="vds-yoopta-editor__upload">
        <FileUpload.Root maxFiles={1} onFilesChange={onFilesChange}>
          <FileUpload.Dropzone>
            {({ isDragActive }: { isDragActive: boolean }) => (
              <div className="vds-yoopta-editor__upload-content" data-active={isDragActive || undefined}>
                {upload.loading ? (
                  <>
                    <IconLoader2 size={20} className="vds-yoopta-editor__upload-spinner" />
                    <span>Uploading… {upload.progress?.percentage ? `${Math.round(upload.progress.percentage)}%` : ""}</span>
                  </>
                ) : uploadError ? (
                  <>
                    <IconAlertCircle size={20} />
                    <span>{uploadError}</span>
                  </>
                ) : (
                  <>
                    <IconPaperclip size={20} />
                    <span>{isDragActive ? "Drop file here…" : "Click or drop a file"}</span>
                  </>
                )}
              </div>
            )}
          </FileUpload.Dropzone>
        </FileUpload.Root>
        <span style={{ display: "none" }}>{children}</span>
      </div>
    );
  }

  return (
    <div {...attributes} className="vds-yoopta-editor__file-card">
      <a
        href={props.src ?? "#"}
        target="_blank"
        rel="noopener noreferrer"
        download={props.name ?? undefined}
        contentEditable={false}
      >
        <IconPaperclip size={18} />
        <span className="vds-yoopta-editor__file-card-info">
          <span className="vds-yoopta-editor__file-card-name">{props.name ?? "File"}</span>
          {typeof props.size === "number" && (
            <span className="vds-yoopta-editor__file-card-size">{formatFileSize(props.size)}</span>
          )}
        </span>
        <IconDownload size={16} />
      </a>
      <span style={{ display: "none" }}>{children}</span>
    </div>
  );
}

import { useCallback, useState, type CSSProperties } from "react";
import { useYooptaEditor } from "@yoopta/editor";
import { useImageUpload } from "@yoopta/image";
import type { PluginElementRenderProps } from "@yoopta/editor";
import { IconPhoto, IconLink } from "@virtari-packages/react-icons";

import { MediaPicker } from "./MediaPicker";
import { imageUpload } from "../uploads";

type ImageProps = {
  src?: string | null;
  alt?: string | null;
  sizes?: { width?: number | string; height?: number | string };
  fit?: "contain" | "cover" | "fill" | null;
  bgColor?: string | null;
};

function isLikelyImageUrl(value: string): boolean {
  try {
    const u = new URL(value);
    return u.protocol === "http:" || u.protocol === "https:";
  } catch {
    return false;
  }
}

export function ImageElement(renderProps: PluginElementRenderProps) {
  const { element, blockId, attributes, children } = renderProps;
  const editor = useYooptaEditor();
  const upload = useImageUpload(imageUpload as never);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [embedError, setEmbedError] = useState<string | null>(null);

  const props = (element.props ?? {}) as ImageProps;
  const hasSrc = typeof props.src === "string" && props.src.length > 0;

  const onFiles = useCallback(
    async (files: File[]) => {
      const file = files[0];
      if (!file) return;
      setUploadError(null);
      try {
        const result = await upload.upload(file);
        editor.updateElement({
          blockId,
          type: "image",
          props: {
            src: result.src,
            alt: result.alt ?? file.name,
            sizes: result.sizes ?? { width: 800, height: 600 },
            fit: result.fit ?? "cover",
            srcSet: result.srcSet ?? null,
            bgColor: result.bgColor ?? null,
          },
        });
      } catch (err) {
        setUploadError(err instanceof Error ? err.message : "Upload failed");
      }
    },
    [upload, editor, blockId],
  );

  const onEmbed = useCallback(
    (raw: string) => {
      setEmbedError(null);
      if (!isLikelyImageUrl(raw)) {
        setEmbedError("Enter a valid http(s) URL.");
        return;
      }
      editor.updateElement({
        blockId,
        type: "image",
        props: {
          src: raw,
          alt: raw.split("/").pop() ?? "image",
          sizes: { width: 1280, height: 720 },
          fit: "cover",
          srcSet: null,
          bgColor: null,
        },
      });
    },
    [editor, blockId],
  );

  if (!hasSrc) {
    return (
      <div {...attributes} contentEditable={false} className="vds-yoopta-editor__upload">
        <MediaPicker
          accept={{ "image/*": [] }}
          uploadIcon={<IconPhoto size={20} />}
          uploadHint="Click or drop an image"
          embedIcon={<IconLink size={14} />}
          embedHint="Paste any image URL (PNG, JPG, GIF, WebP, SVG…)."
          embedPlaceholder="https://example.com/photo.jpg"
          uploading={upload.loading}
          uploadProgress={upload.progress?.percentage ?? null}
          uploadError={uploadError}
          embedError={embedError}
          onFiles={onFiles}
          onEmbed={onEmbed}
        />
        <span style={{ display: "none" }}>{children}</span>
      </div>
    );
  }

  const sizes = props.sizes ?? {};
  const style: CSSProperties = {
    objectFit: props.fit ?? "cover",
    backgroundColor: props.bgColor ?? undefined,
    maxInlineSize: "100%",
    blockSize: "auto",
  };

  return (
    <div {...attributes} className="vds-yoopta-editor__media">
      <img
        src={props.src ?? ""}
        alt={props.alt ?? ""}
        width={typeof sizes.width === "number" ? sizes.width : undefined}
        height={typeof sizes.height === "number" ? sizes.height : undefined}
        style={style}
        draggable={false}
      />
      <span style={{ display: "none" }}>{children}</span>
    </div>
  );
}

import { useState, type ReactNode } from "react";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@virtari-packages/react-tabs";
import { Input } from "@virtari-packages/react-input";
import { Button } from "@virtari-packages/react-button";
import { FileUpload } from "@virtari-packages/react-file-upload";
import {
  IconLoader2,
  IconAlertCircle,
} from "@virtari-packages/react-icons";

export type MediaPickerProps = {
  /** File MIME accept map for the upload tab. */
  accept?: Record<string, string[]>;
  /** Idle copy + icon shown in the dropzone. */
  uploadIcon: ReactNode;
  uploadHint: string;
  /** Idle copy + icon shown in the embed input row. */
  embedIcon: ReactNode;
  embedHint: string;
  embedPlaceholder: string;
  /** Disable the embed tab entirely (e.g. file-only blocks). */
  hideEmbed?: boolean;
  /** Wired to the upload hook's loading state. */
  uploading: boolean;
  uploadProgress?: number | null;
  uploadError?: string | null;
  /** Notified when the user drops/selects a file. */
  onFiles: (files: File[]) => void;
  /** Notified when the user submits a URL via the Embed tab. */
  onEmbed: (url: string) => void | Promise<void>;
  /** Validation message when embed URL is rejected. */
  embedError?: string | null;
};

export function MediaPicker({
  accept,
  uploadIcon,
  uploadHint,
  embedIcon,
  embedHint,
  embedPlaceholder,
  hideEmbed,
  uploading,
  uploadProgress,
  uploadError,
  onFiles,
  onEmbed,
  embedError,
}: MediaPickerProps) {
  const [tab, setTab] = useState<"upload" | "embed">("upload");
  const [url, setUrl] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const handleEmbed = async () => {
    if (!url.trim()) return;
    setSubmitting(true);
    try {
      await onEmbed(url.trim());
      setUrl("");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Tabs
      value={tab}
      onValueChange={(v) => setTab(v as "upload" | "embed")}
      className="vds-yoopta-editor__picker"
    >
      <TabsList variant="segmented" size="sm">
        <TabsTrigger value="upload">Upload</TabsTrigger>
        {!hideEmbed && <TabsTrigger value="embed">Embed by URL</TabsTrigger>}
      </TabsList>

      <TabsContent value="upload">
        <FileUpload.Root accept={accept} maxFiles={1} onFilesChange={onFiles}>
          <FileUpload.Dropzone>
            {({ isDragActive }: { isDragActive: boolean }) => (
              <div
                className="vds-yoopta-editor__upload-content"
                data-active={isDragActive || undefined}
              >
                {uploading ? (
                  <>
                    <IconLoader2
                      size={20}
                      className="vds-yoopta-editor__upload-spinner"
                    />
                    <span>
                      Uploading…{" "}
                      {uploadProgress != null
                        ? `${Math.round(uploadProgress)}%`
                        : ""}
                    </span>
                  </>
                ) : uploadError ? (
                  <>
                    <IconAlertCircle size={20} />
                    <span>{uploadError}</span>
                  </>
                ) : (
                  <>
                    {uploadIcon}
                    <span>{isDragActive ? "Drop here…" : uploadHint}</span>
                  </>
                )}
              </div>
            )}
          </FileUpload.Dropzone>
        </FileUpload.Root>
      </TabsContent>

      {!hideEmbed && (
        <TabsContent value="embed">
          <div className="vds-yoopta-editor__embed-row">
            <Input
              inputSize="sm"
              placeholder={embedPlaceholder}
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  e.stopPropagation();
                  void handleEmbed();
                }
              }}
            />
            <Button
              size="sm"
              variant="solid"
              onClick={handleEmbed}
              disabled={!url.trim() || submitting}
              leftSection={embedIcon}
            >
              Embed
            </Button>
          </div>
          {embedError && (
            <div className="vds-yoopta-editor__embed-error">
              <IconAlertCircle size={14} />
              <span>{embedError}</span>
            </div>
          )}
          {!embedError && (
            <p className="vds-yoopta-editor__embed-hint">{embedHint}</p>
          )}
        </TabsContent>
      )}
    </Tabs>
  );
}

import { Tabs, TabsList, TabsTrigger, TabsContent } from "@virtari-packages/react-tabs";
import type { PluginElementRenderProps } from "@yoopta/editor";

/**
 * Yoopta tabs Slate tree:
 *   tabs-container (root, props.activeTabId)
 *     tabs-list (heading row)
 *       tabs-item-heading (each, element.id = activeTabId target)
 *     tabs-item-content (each panel, props.referenceId = matching heading.id)
 *
 * Mapped onto Virtari Tabs. Active state lives in the tabs primitive —
 * the Slate `activeTabId` is used only as `defaultValue`.
 */

export function TabsContainerElement(renderProps: PluginElementRenderProps) {
  const { attributes, children, element } = renderProps;
  const activeTabId = (element as unknown as { props?: { activeTabId?: string } }).props
    ?.activeTabId;

  return (
    <Tabs
      defaultValue={activeTabId ?? undefined}
      {...attributes}
      className="vds-yoopta-editor__tabs"
    >
      {children}
    </Tabs>
  );
}

export function TabsListElement(renderProps: PluginElementRenderProps) {
  const { attributes, children } = renderProps;
  return (
    <TabsList variant="underline" {...attributes}>
      {children}
    </TabsList>
  );
}

export function TabsItemHeadingElement(renderProps: PluginElementRenderProps) {
  const { attributes, children, element } = renderProps;
  return (
    <TabsTrigger value={element.id} {...attributes}>
      <span className="vds-yoopta-editor__tabs-heading">{children}</span>
    </TabsTrigger>
  );
}

export function TabsItemContentElement(renderProps: PluginElementRenderProps) {
  const { attributes, children, element } = renderProps;
  const referenceId = (element as unknown as { props?: { referenceId?: string } }).props
    ?.referenceId;
  if (!referenceId) {
    return <div {...attributes}>{children}</div>;
  }
  return (
    <TabsContent value={referenceId} {...attributes}>
      {children}
    </TabsContent>
  );
}

import { Transforms } from "slate";
import { ReactEditor } from "slate-react";
import { Blocks, useYooptaEditor } from "@yoopta/editor";
import type { PluginElementRenderProps } from "@yoopta/editor";
import { IconSquare, IconSquareCheckFilled } from "@virtari-packages/react-icons";

/**
 * Yoopta TodoList renders one `todo-list` element per block, with
 * `props.checked` driving the checkbox state. Default render is a bare
 * <ul><li> with no interactive control. Here we mount a Tabler-icon
 * checkbox in a contentEditable=false slot and toggle the slate prop.
 */
export function TodoListElement(renderProps: PluginElementRenderProps) {
  const { attributes, children, element, blockId } = renderProps;
  const editor = useYooptaEditor();
  const checked =
    (element as unknown as { props?: { checked?: boolean } }).props?.checked ??
    false;

  const toggle = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const slate = Blocks.getBlockSlate(editor, { id: blockId });
    if (!slate) return;
    try {
      const path = ReactEditor.findPath(slate, element as never);
      Transforms.setNodes(
        slate,
        { props: { checked: !checked } } as never,
        { at: path },
      );
    } catch {
      /* element not currently in slate tree — no-op */
    }
  };

  return (
    <ul
      {...attributes}
      className="vds-yoopta-editor__todo"
      data-checked={checked ? "" : undefined}
    >
      <li className="vds-yoopta-editor__todo-item">
        <button
          type="button"
          contentEditable={false}
          onMouseDown={(e) => e.preventDefault()}
          onClick={toggle}
          className="vds-yoopta-editor__todo-check"
          aria-checked={checked}
          aria-label={checked ? "Mark as not done" : "Mark as done"}
          role="checkbox"
        >
          {checked ? (
            <IconSquareCheckFilled size={20} />
          ) : (
            <IconSquare size={20} />
          )}
        </button>
        <span className="vds-yoopta-editor__todo-text">{children}</span>
      </li>
    </ul>
  );
}

import { useCallback, useState, type CSSProperties } from "react";
import { useYooptaEditor } from "@yoopta/editor";
import { useVideoUpload, parseVideoUrl } from "@yoopta/video";
import type { PluginElementRenderProps } from "@yoopta/editor";
import { IconVideo, IconLink } from "@virtari-packages/react-icons";

import { MediaPicker } from "./MediaPicker";
import { videoUpload } from "../uploads";

type VideoSettings = {
  controls?: boolean;
  loop?: boolean;
  muted?: boolean;
  autoPlay?: boolean;
};

type VideoProvider = {
  type: string | null;
  id: string;
  url?: string;
};

type VideoProps = {
  src?: string | null;
  poster?: string | null;
  sizes?: { width?: number | string; height?: number | string };
  fit?: "contain" | "cover" | "fill" | null;
  settings?: VideoSettings;
  provider?: VideoProvider | null;
};

const DEFAULT_SETTINGS: Required<VideoSettings> = {
  controls: true,
  loop: false,
  muted: false,
  autoPlay: false,
};

export function VideoElement(renderProps: PluginElementRenderProps) {
  const { element, blockId, attributes, children } = renderProps;
  const editor = useYooptaEditor();
  const upload = useVideoUpload(videoUpload as never);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [embedError, setEmbedError] = useState<string | null>(null);

  const props = (element.props ?? {}) as VideoProps;
  const provider = props.provider;
  const isEmbed =
    !!provider && !!provider.type && typeof props.src === "string" && props.src.length > 0;
  const hasFileSrc =
    !provider && typeof props.src === "string" && props.src.length > 0;

  const onFiles = useCallback(
    async (files: File[]) => {
      const file = files[0];
      if (!file) return;
      setUploadError(null);
      try {
        const result = await upload.upload(file);
        editor.updateElement({
          blockId,
          type: "video",
          props: {
            src: result.src,
            srcSet: null,
            bgColor: null,
            sizes: result.sizes ?? { width: 800, height: 480 },
            fit: "cover",
            poster: result.poster ?? null,
            provider: null,
            settings: { ...DEFAULT_SETTINGS },
          },
        });
      } catch (err) {
        setUploadError(err instanceof Error ? err.message : "Upload failed");
      }
    },
    [upload, editor, blockId],
  );

  const onEmbed = useCallback(
    (raw: string) => {
      setEmbedError(null);
      const parsed = parseVideoUrl(raw);
      if (!parsed.isValid) {
        setEmbedError(
          "Couldn't recognise that URL. Supported: YouTube, Vimeo, Dailymotion, Loom, Wistia.",
        );
        return;
      }
      editor.updateElement({
        blockId,
        type: "video",
        props: {
          src: parsed.embedUrl,
          srcSet: null,
          bgColor: null,
          sizes: { width: 800, height: 450 },
          fit: "cover",
          poster: parsed.thumbnailUrl ?? null,
          provider: {
            type: parsed.provider,
            id: parsed.id,
            url: parsed.originalUrl,
          },
          settings: { ...DEFAULT_SETTINGS },
        },
      });
    },
    [editor, blockId],
  );

  if (!hasFileSrc && !isEmbed) {
    return (
      <div {...attributes} contentEditable={false} className="vds-yoopta-editor__upload">
        <MediaPicker
          accept={{ "video/*": [] }}
          uploadIcon={<IconVideo size={20} />}
          uploadHint="Click or drop a video"
          embedIcon={<IconLink size={14} />}
          embedHint="Paste a YouTube, Vimeo, Dailymotion, Loom, or Wistia link."
          embedPlaceholder="https://youtube.com/watch?v=…"
          uploading={upload.loading}
          uploadProgress={upload.progress?.percentage ?? null}
          uploadError={uploadError}
          embedError={embedError}
          onFiles={onFiles}
          onEmbed={onEmbed}
        />
        <span style={{ display: "none" }}>{children}</span>
      </div>
    );
  }

  const sizes = props.sizes ?? {};
  const settings = { ...DEFAULT_SETTINGS, ...(props.settings ?? {}) };

  if (isEmbed) {
    return (
      <div {...attributes} className="vds-yoopta-editor__media">
        <iframe
          src={props.src ?? ""}
          width={typeof sizes.width === "number" ? sizes.width : "100%"}
          height={typeof sizes.height === "number" ? sizes.height : 450}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          allowFullScreen
          referrerPolicy="strict-origin-when-cross-origin"
          title={`${provider?.type ?? "video"} embed`}
        />
        <span style={{ display: "none" }}>{children}</span>
      </div>
    );
  }

  const style: CSSProperties = {
    objectFit: props.fit ?? "cover",
    maxInlineSize: "100%",
    blockSize: "auto",
  };

  return (
    <div {...attributes} className="vds-yoopta-editor__media">
      <video
        src={props.src ?? ""}
        poster={props.poster ?? undefined}
        width={typeof sizes.width === "number" ? sizes.width : undefined}
        height={typeof sizes.height === "number" ? sizes.height : undefined}
        controls={settings.controls}
        loop={settings.loop}
        muted={settings.muted}
        autoPlay={settings.autoPlay}
        playsInline
        style={style}
      />
      <span style={{ display: "none" }}>{children}</span>
    </div>
  );
}

