    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: var(--vds-text-xs);
    font-weight: var(--vds-font-weight-semibold);
  }

  /* ————————————————————————————————————————————————
     Mentions
     ———————————————————————————————————————————————— */
  .vds-yoopta-editor [data-element-type="mention"],
  .vds-yoopta-editor [data-mention] {
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1);
    padding: 0.125em 0.375em;
    border-radius: var(--vds-yoopta-radius-control);
    background: var(--vds-color-primary-bg-subtle);
    color: var(--vds-color-primary-text);
    font-weight: var(--vds-font-weight-medium);
  }

  /* ————————————————————————————————————————————————
     Mark formatting
     ———————————————————————————————————————————————— */
  .vds-yoopta-editor strong { font-weight: var(--vds-font-weight-bold); }
