  .vds-yoo-action-menu-input {
    inline-size: 100%;
    background: transparent;
    border: none;
    outline: none;
    color: inherit;
    font-family: inherit;
    font-size: var(--vds-text-sm);
    padding: var(--vds-space-1) var(--vds-space-2);
  }
  .vds-yoo-action-menu-list {
    flex: 1;
    overflow-y: auto;
    padding: var(--vds-space-1);
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .vds-yoo-action-menu-empty {
    padding: var(--vds-space-3);
    color: var(--vds-color-text-muted);
    text-align: center;
    font-size: var(--vds-text-sm);
  }
  .vds-yoo-action-menu-item {
    inline-size: 100%;
    background: transparent;
    color: inherit;
    border: none;
    text-align: start;
    padding: var(--vds-space-2);
    border-radius: var(--vds-yoopta-radius-control);
    font-family: inherit;
    font-size: var(--vds-text-sm);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: var(--vds-space-2);
    transition: background-color var(--vds-duration-fast) var(--vds-ease-out);
  }
  .vds-yoo-action-menu-item[data-active],
  .vds-yoo-action-menu-item:hover {
    background: var(--vds-color-surface-hover);
