  /* Block options popover */
  .vds-yoo-block-options {
    min-inline-size: 12rem;
    padding: var(--vds-space-1);
    background: var(--vds-color-surface-overlay);
    border: 1px solid var(--vds-yoopta-color-border);
    border-radius: var(--vds-yoopta-radius-popover);
    box-shadow: var(--vds-shadow-lg);
    color: var(--vds-color-text);
    z-index: 70;
  }
  .vds-yoo-block-options-group {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .vds-yoo-block-options-separator {
    block-size: 1px;
    background: var(--vds-yoopta-color-border);
    margin-block: var(--vds-space-1);
  }
  .vds-yoo-block-options-item {
    inline-size: 100%;
    background: transparent;
    color: inherit;
    border: none;
    text-align: start;
    padding: var(--vds-space-2);
    border-radius: var(--vds-yoopta-radius-control);
    font-family: inherit;
    font-size: var(--vds-text-sm);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: var(--vds-space-2);
    transition: background-color var(--vds-duration-fast) var(--vds-ease-out);
  }
  .vds-yoo-block-options-item:hover {
    background: var(--vds-color-surface-hover);
  }
  .vds-yoo-block-options-item[data-variant="danger"] {
    color: var(--vds-color-danger-text);
  }
  .vds-yoo-block-options-item[data-variant="danger"]:hover {
    background: var(--vds-color-danger-bg);
  }

  /* Hover plus + drag handle bar (positioned next to a block) */
  .vds-yoo-block-actions {
    z-index: 50;
    display: inline-flex;
    align-items: flex-start;
    justify-content: flex-end;
    gap: 2px;
    padding: 2px;
    background: var(--vds-color-surface-overlay);
    border: 1px solid var(--vds-yoopta-color-border);
    border-radius: var(--vds-yoopta-radius-popover);
    box-shadow: var(--vds-shadow-sm);
    color: var(--vds-color-text-muted);
    pointer-events: auto;
  }
  .vds-yoo-block-actions[data-frozen] {
    pointer-events: auto;
  }
  .vds-yoo-block-actions-button {
    background: transparent;
    border: none;
    color: inherit;
    border-radius: var(--vds-yoopta-radius-control);
    inline-size: 1.5rem;
    block-size: 1.5rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
