     cells — Yoopta's leaf placeholder fires on every empty leaf, but inside
     a table cell it crowds the layout and reads as a bug. */
  .vds-yoopta-editor table .yoopta-placeholder::before,
  .vds-yoopta-editor table [data-placeholder]::before {
    content: "" !important;
  }

  /* TodoList — checkbox + line-through when checked */
  .vds-yoopta-editor__todo {
    list-style: none;
    padding: 0;
    margin: 0;
  }
  .vds-yoopta-editor__todo-item {
    display: flex;
    align-items: flex-start;
    gap: var(--vds-space-2);
    padding-block: 0.125rem;
  }
  .vds-yoopta-editor__todo-check {
    flex-shrink: 0;
    background: transparent;
    border: none;
    padding: 0;
    margin-block-start: 2px;
    color: var(--vds-yoopta-color-text-muted);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: color var(--vds-yoopta-duration) var(--vds-yoopta-ease);
  }
  .vds-yoopta-editor__todo[data-checked] .vds-yoopta-editor__todo-check {
    color: var(--vds-color-primary-solid);
  }
  .vds-yoopta-editor__todo-check:hover {
    color: var(--vds-yoopta-color-text);
  }
  .vds-yoopta-editor__todo-text {
    flex: 1;
    min-inline-size: 0;
  }
  .vds-yoopta-editor__todo[data-checked] .vds-yoopta-editor__todo-text {
    text-decoration: line-through;
    color: var(--vds-yoopta-color-text-muted);
  }

  /* Carousel — horizontal scroll-snap rail */
  .vds-yoopta-editor__carousel {
    display: flex;
    gap: var(--vds-space-3);
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    padding-block: var(--vds-space-2);
    scrollbar-width: thin;
  }
  .vds-yoopta-editor__carousel-slide {
    flex: 0 0 auto;
    inline-size: 18rem;
    min-block-size: 9rem;
    scroll-snap-align: start;
    border: 1px solid var(--vds-yoopta-color-border);
    border-radius: var(--vds-yoopta-radius-popover);
    padding: var(--vds-space-3);
    background: var(--vds-yoopta-color-surface-raised);
  }

  /* ————————————————————————————————————————————————
     Table column/row selection (Notion-style)
     ———————————————————————————————————————————————— */

  /* Column drag handle on top of column on hover; click to select, drag to reorder */
  .vds-yoo-table-col-handle,
  .vds-yoo-table-row-handle {
    z-index: 50;
    background: var(--vds-color-surface-overlay);
    border: 1px solid var(--vds-yoopta-color-border);
    border-radius: var(--vds-yoopta-radius-control);
    color: var(--vds-color-text-muted);
    cursor: grab;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    transition: background-color var(--vds-duration-fast) var(--vds-ease-out),
      color var(--vds-duration-fast) var(--vds-ease-out);
  }
  .vds-yoo-table-col-handle {
    block-size: 1rem;
  }
  .vds-yoo-table-row-handle {
    inline-size: 1rem;
  }
  .vds-yoo-table-col-handle:hover,
  .vds-yoo-table-row-handle:hover,
  .vds-yoo-table-col-handle[data-selected],
  .vds-yoo-table-row-handle[data-selected] {
    background: var(--vds-color-primary-solid);
    color: var(--vds-color-on-solid);
    border-color: var(--vds-color-primary-solid);
  }
  .vds-yoo-table-col-handle:active,
  .vds-yoo-table-row-handle:active {
    cursor: grabbing;
  }

  /* Highlight cells when their column or row is selected */
  .vds-yoopta-editor table td[data-selected],
  .vds-yoopta-editor table th[data-selected] {
    background: color-mix(
      in oklch,
      var(--vds-color-primary-solid) 12%,
      transparent
    );
    box-shadow: inset 0 0 0 1.5px var(--vds-color-primary-solid);
  }

  /* Drop indicator line between columns/rows during drag */
  .vds-yoo-table-drop-line {
    position: fixed;
    z-index: 51;
    background: var(--vds-color-primary-solid);
    pointer-events: none;
    border-radius: var(--vds-radius-full, 9999px);
  }
  .vds-yoo-table-drop-line[data-axis="vertical"] {
    inline-size: 2px;
  }
  .vds-yoo-table-drop-line[data-axis="horizontal"] {
    block-size: 2px;
  }

  /* Highlight color popover */
  .vds-yoo-highlight-popover {
    padding: var(--vds-space-2);
    background: var(--vds-color-surface-overlay);
    border: 1px solid var(--vds-yoopta-color-border);
    border-radius: var(--vds-yoopta-radius-popover);
    box-shadow: var(--vds-shadow-lg);
    color: var(--vds-color-text);
    display: flex;
    flex-direction: column;
    gap: var(--vds-space-2);
    z-index: 70;
  }
  .vds-yoo-highlight-presets {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--vds-space-1);
  }
  .vds-yoo-highlight-swatch {
    inline-size: 1.5rem;
    block-size: 1.5rem;
    padding: 0;
    border: 1px solid var(--vds-yoopta-color-border);
    border-radius: var(--vds-yoopta-radius-control);
    cursor: pointer;
    transition: transform var(--vds-duration-fast) var(--vds-ease-out);
  }
  .vds-yoo-highlight-swatch:hover {
    transform: scale(1.08);
  }
  .vds-yoo-highlight-clear {
    background: transparent;
    color: var(--vds-color-danger-text);
    border: none;
    border-radius: var(--vds-yoopta-radius-control);
    padding: var(--vds-space-1) var(--vds-space-2);
    font-family: inherit;
    font-size: var(--vds-text-sm);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: var(--vds-space-1);
    justify-content: center;
  }
  .vds-yoo-highlight-clear:hover {
    background: var(--vds-color-danger-bg);
  }
}

