    /* ── Danger (red) — light ── */
    --vds-color-danger-1:  oklch(0.985 0.005 25);
    --vds-color-danger-2:  oklch(0.970 0.012 25);
    --vds-color-danger-3:  oklch(0.945 0.025 25);
